    private static async Task EnsureAdditionalPracticeQuestionsAsync(OralExamDbContext context, CancellationToken cancellationToken)
    {
        var existingQuestions = await context.PracticeQuestions.ToListAsync(cancellationToken);
        var existingById = existingQuestions.ToDictionary(q => q.Id);

        var questions = new List<PracticeQuestion>
        {
            // =========================================================================
            // 1. PRF192 — 36 CÂU HỎI KHO LUYỆN TẬP & THI THỬ (12 Easy, 14 Medium, 10 Hard)
            // =========================================================================
            CreatePracticeSeed("00000000-0000-0000-0003-000000000121", CoursePrf192Id, "00000000-0000-0000-0000-000000000461", RubricPrf192Id, "Cấu trúc cơ bản của chương trình C và vai trò của hàm main", "Hãy trình bày các thành phần cốt lõi trong cấu trúc của một chương trình C tiêu chuẩn. Tại sao hàm main đóng vai trò điểm vào thực thi bắt buộc và giá trị trả về bằng 0 ở cuối hàm main mang ý nghĩa gì đối với hệ điều hành?", "Một chương trình C tiêu chuẩn bao gồm năm thành phần cốt lõi phối hợp chặt chẽ với nhau. Thứ nhất là các chỉ thị tiền xử lý như chỉ thị include dùng để nạp các tệp tiêu đề chứa khai báo thư viện chuẩn vào đơn vị dịch trước khi biên dịch. Thứ hai là phần khai báo nguyên mẫu hàm, kiểu dữ liệu hoặc định nghĩa hằng số dùng chung trong phạm vi tệp. Thứ ba là hàm main, đóng vai trò điểm khởi nhập thực thi duy nhất và bắt buộc của mọi chương trình C độc lập; ngay khi tiến trình được nạp vào bộ nhớ RAM, hệ điều hành sẽ trao quyền điều khiển và kích hoạt luồng lệnh đầu tiên tại hàm main bất kể trong mã nguồn có bao nhiêu hàm phụ trợ khác. Thứ tư là thân hàm chứa các câu lệnh khai báo biến cục bộ, nhập xuất dữ liệu và xử lý giải thuật. Cuối cùng là câu lệnh trả về giá trị 0 ở cuối hàm main nhằm gửi mã trạng thái kết thúc thành công (tương đương hằng EXIT_SUCCESS) về cho hệ điều hành, trong khi các giá trị khác 0 báo hiệu tiến trình đã gặp lỗi bất thường.", "[\"Trình bày các khối thành phần chương trình C (3.0đ): Nêu đủ các phần: chỉ thị tiền xử lý, nguyên mẫu hàm, hàm main và thân lệnh thực thi.\", \"Giải thích vai trò Entry Point của hàm main (4.0đ): Phân tích rõ hàm main là điểm vào thực thi duy nhất được hệ điều hành kích hoạt khi nạp tiến trình.\", \"Ý nghĩa mã trạng thái trả về 0 ở cuối hàm main (3.0đ): Giải thích chính xác giá trị 0 báo hiệu thực thi thành công và khác 0 báo lỗi về hệ điều hành.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, "Nếu một chương trình C có nhiều hàm tự định nghĩa khác nhau thì hệ điều hành luôn bắt đầu thực thi từ hàm nào đầu tiên?"),
            CreatePracticeSeed("00000000-0000-0000-0003-000000000122", CoursePrf192Id, "00000000-0000-0000-0000-000000000461", RubricPrf192Id, "Quy trình biên dịch mã nguồn C qua 4 giai đoạn", "Từ một tệp mã nguồn C ban đầu cho đến khi tạo ra tệp thực thi nhị phân hoàn chỉnh, trình biên dịch như GCC trải qua 4 giai đoạn tuần tự nào? Hãy trình bày nhiệm vụ cốt lõi của từng giai đoạn.", "Quy trình chuyển đổi từ mã nguồn C sang tệp thực thi trải qua bốn giai đoạn tuần tự rõ rệt. Giai đoạn thứ nhất là Tiền xử lý (Preprocessing): bộ tiền xử lý đọc tệp nguồn, thực thi các chỉ thị bắt đầu bằng dấu thăng như chèn nội dung tệp tiêu đề qua include, mở rộng các hằng macro qua define và loại bỏ toàn bộ chú thích bằng cách thay mỗi chú thích bằng một khoảng trắng đơn để tạo tệp mã mở rộng trung gian. Giai đoạn thứ hai là Biên dịch (Compilation): trình biên dịch phân tích từ vựng, cú pháp và kiểm tra ngữ nghĩa kiểu dữ liệu, sau đó dịch mã C đã tiền xử lý sang mã hợp ngữ Assembly phụ thuộc kiến trúc tập lệnh của vi xử lý mục tiêu. Giai đoạn thứ ba là Hợp dịch (Assembly): trình hợp dịch chuyển đổi các chỉ thị Assembly thành mã máy nhị phân thô và đóng gói thành tệp đối tượng chứa bảng ký hiệu chưa phân giải hết. Giai đoạn thứ tư là Liên kết (Linking): trình liên kết ghép các tệp đối tượng của dự án cùng mã máy của thư viện chuẩn như libc, phân giải địa chỉ mọi lời gọi hàm ngoài như printf để xuất ra tệp thực thi hoàn chỉnh.", "[\"Liệt kê đúng tên 4 giai đoạn tuần tự (3.0đ): Nêu chính xác thứ tự: Tiền xử lý, Biên dịch, Hợp dịch và Liên kết.\", \"Nhiệm vụ của Preprocessing và Compilation (4.0đ): Mô tả rõ xử lý header, macro, loại bỏ chú thích ở tiền xử lý và dịch mã C sang hợp ngữ Assembly.\", \"Nhiệm vụ của Assembly và Linking (3.0đ): Giải thích đúng vai trò chuyển hợp ngữ sang mã máy đối tượng và trình liên kết nối thư viện tạo tệp thực thi.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Ở giai đoạn nào trong 4 giai đoạn trên thì toàn bộ chú thích trong mã nguồn bị loại bỏ?"),
            CreatePracticeSeed("00000000-0000-0000-0003-000000000123", CoursePrf192Id, "00000000-0000-0000-0000-000000000462", RubricPrf192Id, "Kiểu dữ liệu nguyên thủy, dải giá trị và kích thước bộ nhớ trong C", "Hãy liệt kê bốn kiểu dữ liệu nguyên thủy cơ bản trong ngôn ngữ C gồm char, int, float và double. Trình bày kích thước bộ nhớ thông thường cùng dải giá trị của kiểu số nguyên int có dấu và không dấu trên hệ thống 32-bit hoặc 64-bit.", "Bốn kiểu dữ liệu nguyên thủy nền tảng trong ngôn ngữ C bao gồm char, int, float và double. Kiểu char chiếm đúng 1 byte tức 8 bit bộ nhớ, dùng để lưu mã ký tự ASCII hoặc số nguyên nhỏ với dải giá trị từ âm 128 đến 127 khi có dấu và từ 0 đến 255 khi không dấu. Kiểu int trên hầu hết các kiến trúc 32-bit và 64-bit hiện đại chiếm 4 bytes tương đương 32 bit: ở dạng có dấu signed int sử dụng biểu diễn bù hai, dải giá trị trải từ âm 2 mũ 31 đến 2 mũ 31 trừ 1 (xấp xỉ âm 2,14 tỷ đến dương 2,14 tỷ); ở dạng không dấu unsigned int, toàn bộ 32 bit đều biểu diễn độ lớn nên dải giá trị mở rộng từ 0 đến 2 mũ 32 trừ 1 (khoảng 4,29 tỷ). Kiểu float chiếm 4 bytes biểu diễn số thực dấu chấm động độ chính xác đơn chuẩn IEEE 754 với khoảng 6 đến 7 chữ số thập phân có nghĩa, còn kiểu double chiếm 8 bytes đạt độ chính xác kép từ 15 đến 17 chữ số thập phân. Để tra cứu dung lượng byte chính xác trên từng nền tảng phần cứng, lập trình viên dùng toán tử sizeof được đánh giá ngay lúc biên dịch.", "[\"Liệt kê đầy đủ 4 kiểu dữ liệu nguyên thủy (3.0đ): Nêu rõ char, int, float, double cùng kích thước byte và mục đích biểu diễn của từng kiểu.\", \"Kích thước bộ nhớ và dải giá trị của int (4.0đ): Trình bày chính xác dung lượng 4 bytes, dải giá trị có dấu từ âm 2 mũ 31 đến 2 mũ 31 trừ 1 và không dấu từ 0 đến 2 mũ 32 trừ 1.\", \"Vai trò xác định kích thước của toán tử sizeof (3.0đ): Giải thích đúng cơ chế toán tử sizeof trả về số byte của kiểu dữ liệu hoặc biến lúc biên dịch.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, "Toán tử nào trong ngôn ngữ C cho phép xác định chính xác kích thước tính bằng byte của một kiểu dữ liệu hoặc một biến ngay tại thời điểm biên dịch?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000424", CoursePrf192Id, "00000000-0000-0000-0000-000000000462", RubricPrf192Id, "Phân biệt hằng số #define (Macro) và từ khóa const trong C", "Trong ngôn ngữ C, có hai cách phổ biến để định nghĩa hằng số là dùng chỉ thị tiền xử lý define và dùng từ khóa const. Hãy phân biệt sự khác nhau giữa hai cách này về cơ chế hoạt động, kiểm tra an toàn kiểu dữ liệu và cấp phát bộ nhớ.", "Chỉ thị tiền xử lý define và từ khóa const khác biệt căn bản trên ba phương diện kỹ thuật. Về cơ chế hoạt động, define được thực thi bởi bộ tiền xử lý trước khi quá trình biên dịch bắt đầu thông qua cơ chế tìm kiếm và thay thế văn bản thuần túy, do đó trình biên dịch hoàn toàn không nhìn thấy tên định danh của macro trong bảng ký hiệu. Ngược lại, hằng số dùng từ khóa const là một đối tượng dữ liệu thực sự do trình biên dịch quản lý, được khởi tạo giá trị một lần và khóa quyền ghi đè. Về an toàn kiểu dữ liệu, macro define không gắn với kiểu cụ thể nên không được kiểm tra tương thích kiểu và rất dễ gây lỗi thứ tự ưu tiên toán tử nếu biểu thức thay thế thiếu ngoặc bao vệ; trong khi biến const có kiểu tường minh giúp trình biên dịch cảnh báo chính xác mọi phép gán sai kiểu và giữ nguyên tên biến trong trình gỡ lỗi Debugger. Về bộ nhớ và phạm vi, define không chiếm ô nhớ riêng và có hiệu lực từ dòng định nghĩa đến hết tệp, còn const tuân thủ chặt chẽ phạm vi khối lệnh hoặc phạm vi tệp và thường được lưu tại phân vùng dữ liệu chỉ đọc.", "[\"So sánh cơ chế tiền xử lý và trình biên dịch (4.0đ): Phân tích rõ cơ chế thay thế văn bản thô của define so với đối tượng bất biến do trình biên dịch quản lý của const.\", \"Kiểm tra an toàn kiểu dữ liệu và hỗ trợ gỡ lỗi (3.0đ): Chỉ ra const có kiểu dữ liệu tường minh giúp bắt lỗi biên dịch và hiển thị trong Debugger, còn define không kiểm tra kiểu.\", \"Phạm vi tác dụng và cấp phát bộ nhớ (3.0đ): Giải thích đúng phạm vi khối lệnh và vùng nhớ chỉ đọc của const so với hiệu lực toàn phần còn lại của tệp ở define.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Cách nào trong hai cách trên giúp trình biên dịch phát hiện lỗi sai lệch kiểu dữ liệu tốt hơn và hỗ trợ gỡ lỗi thuận tiện hơn?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000425", CoursePrf192Id, "00000000-0000-0000-0000-000000000462", RubricPrf192Id, "Phép chia nguyên và kỹ thuật ép kiểu tường minh trong C", "Điều gì xảy ra khi thực hiện phép chia hai hằng số nguyên 5 chia cho 2 rồi gán kết quả vào một biến kiểu số thực double trong ngôn ngữ C? Giá trị biến nhận được là bao nhiêu, tại sao lại như vậy và làm thế nào để thu được kết quả chính xác 2.5 bằng kỹ thuật ép kiểu tường minh?", "Khi thực hiện phép chia 5 chia cho 2 rồi gán vào biến kiểu double, biến đích sẽ nhận giá trị là 2.0 chứ không phải 2.5. Nguyên nhân là trong ngôn ngữ C, kiểu của phép chia phụ thuộc hoàn toàn vào kiểu dữ liệu của hai toán hạng tham gia phép chia chứ không phụ thuộc vào kiểu của biến nhận kết quả ở vế trái. Vì cả 5 và 2 đều là số nguyên kiểu int, bộ xử lý thực hiện phép chia nguyên (Integer Division), lấy thương nguyên bằng 2 và cắt bỏ hoàn toàn phần thập phân 0.5 ngay lập tức; sau đó giá trị nguyên 2 mới được chuyển đổi ngầm định thành số thực 2.0 khi gán vào biến double. Để thu được kết quả chính xác 2.5, ít nhất một trong hai toán hạng phải mang kiểu số thực trước khi phép chia diễn ra: hoặc dùng hằng số thực như 5.0 chia 2, hoặc áp dụng ép kiểu tường minh bằng cách đặt kiểu double trước toán hạng đầu tiên để trình biên dịch thăng hạng toán hạng còn lại sang double rồi mới thực hiện phép chia dấu chấm động. Nếu bao ngoặc phép chia hai biến nguyên rồi mới ép kiểu bên ngoài, phép chia nguyên đã mất phần dư trước khi ép kiểu nên kết quả vẫn sai lệch.", "[\"Giải thích bản chất phép chia nguyên cắt cụt phần dư (4.0đ): Chỉ rõ toán tử chia giữa hai số nguyên luôn cắt bỏ phần thập phân trước rồi mới chuyển đổi sang kiểu double bằng 2.0.\", \"Trình bày nguyên lý ép kiểu tường minh trước phép chia (4.0đ): Giải thích đúng cách ép một toán hạng sang double hoặc dùng hằng số thực để kích hoạt phép chia số thực ra 2.5.\", \"Phân tích bẫy lỗi ép kiểu sau khi đã ngoặc phép chia nguyên (2.0đ): Cảnh báo chính xác dấu ngoặc khiến phép chia nguyên hoàn tất và mất phần thập phân trước khi ép kiểu.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Nếu hai biến a và b đều có kiểu số nguyên int, việc gom phép chia a chia b vào trong ngoặc đơn rồi mới đặt ép kiểu double ở bên ngoài có giữ được phần thập phân chính xác hay không?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000426", CoursePrf192Id, "00000000-0000-0000-0000-000000000462", RubricPrf192Id, "Toán tử tăng giảm tiền tố và hậu tố trong ngôn ngữ C", "Hãy phân biệt sự khác nhau giữa toán tử tăng tiền tố và toán tử tăng hậu tố trong ngôn ngữ C. Giải thích sự khác biệt về giá trị nhận được khi gán kết quả của tiền tố so với hậu tố vào một biến khác với giá trị khởi tạo ban đầu bằng 5.", "Cả toán tử tăng tiền tố và tăng hậu tố trong ngôn ngữ C đều có tác dụng cộng thêm 1 đơn vị vào giá trị của biến toán hạng, nhưng khác nhau hoàn toàn ở giá trị mà biểu thức trả về cho phép toán bao quanh. Với toán tử tăng tiền tố (Pre-increment), biến gốc được tăng giá trị lên 1 ngay lập tức, sau đó chính giá trị mới vừa cập nhật này được trả về để tham gia vào biểu thức gán hoặc tính toán; do đó nếu biến x khởi tạo bằng 5 và gán tiền tố của x cho biến y, x tăng lên 6 trước rồi gán cho y nên kết thúc câu lệnh cả x và y đều bằng 6. Ngược lại, với toán tử tăng hậu tố (Post-increment), trình biên dịch lưu giữ giá trị hiện hành của biến để trả về cho biểu thức sử dụng trước, đồng thời cập nhật tăng biến gốc lên 1 đơn vị; vì vậy nếu x khởi tạo bằng 5 và gán hậu tố của x cho y, biến y nhận giá trị cũ là 5 trong khi biến x tăng lên thành 6. Quy tắc thứ tự cập nhật trước hay trả giá trị cũ trước này cũng áp dụng hoàn toàn tương tự cho cặp toán tử giảm tiền tố và giảm hậu tố, đồng thời không nên đặt nhiều phép tăng giảm cùng một biến trong một biểu thức để tránh hành vi không xác định.", "[\"Giải thích cơ chế toán tử tăng tiền tố (3.5đ): Trình bày rõ biến được tăng thêm 1 đơn vị trước rồi mới trả giá trị mới cho biểu thức bao quanh.\", \"Giải thích cơ chế toán tử tăng hậu tố (3.5đ): Trình bày rõ biểu thức nhận giá trị cũ ban đầu của biến trước, còn biến gốc được tăng lên 1 đơn vị.\", \"Phân tích đúng giá trị hai biến với mốc khởi tạo bằng 5 (3.0đ): Xác định chính xác trường hợp tiền tố cho cả hai biến bằng 6, còn hậu tố cho biến nhận bằng 5 và biến gốc bằng 6.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Nếu biến x có giá trị ban đầu bằng 5 và thực hiện gán biểu thức x tăng hậu tố cho biến y, thì sau khi câu lệnh kết thúc, giá trị của x và y lần lượt là bao nhiêu?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000427", CoursePrf192Id, "00000000-0000-0000-0000-000000000463", RubricPrf192Id, "Cấu trúc điều khiển rẽ nhánh if-else và toán tử điều kiện ba ngôi", "Hãy trình bày nguyên lý đánh giá biểu thức điều kiện và luồng hoạt động của cấu trúc rẽ nhánh if-else trong ngôn ngữ C. Khi nào nên sử dụng toán tử điều kiện ba ngôi thay cho if-else và tại sao không nên lồng ghép toán tử ba ngôi quá phức tạp?", "Trong ngôn ngữ C, cấu trúc rẽ nhánh if-else điều khiển luồng thực thi dựa trên việc đánh giá giá trị chân lý của biểu thức điều kiện: mọi giá trị khác 0 đều được quy ước là đúng (True), còn giá trị bằng 0 được coi là sai (False). Khi biểu thức điều kiện khác 0, chương trình thực thi khối lệnh thuộc nhánh if và bỏ qua nhánh else; ngược lại khi điều kiện bằng 0, luồng điều khiển nhảy thẳng sang thực thi khối lệnh thuộc nhánh else nếu có. Trong khi if-else là một câu lệnh điều khiển luồng (Statement) không tự sinh ra giá trị, thì toán tử điều kiện ba ngôi gồm điều kiện chấm hỏi biểu thức một hai chấm biểu thức hai lại mang bản chất là một biểu thức (Expression) luôn đánh giá và trả về một giá trị cụ thể: trả về kết quả biểu thức thứ nhất nếu điều kiện đúng và trả về kết quả biểu thức thứ hai nếu điều kiện sai. Nhờ trả về giá trị trực tiếp, toán tử ba ngôi rất gọn gàng khi khởi tạo biến như tìm số lớn hơn giữa hai số hoặc truyền thẳng làm đối số trong hàm printf. Tuy nhiên, lập trình viên không nên lồng nhiều toán tử ba ngôi hay nhét logic nhiều bước vào đó vì sẽ làm mã nguồn rối rắm, khó đọc và khó bảo trì hơn hẳn cấu trúc if-else tường minh.", "[\"Nguyên lý đánh giá điều kiện đúng sai của if-else (3.5đ): Giải thích chuẩn quy ước giá trị khác 0 là đúng, bằng 0 là sai và cơ chế chọn nhánh thực thi loại trừ nhau.\", \"Bản chất biểu thức trả về giá trị của toán tử ba ngôi (3.5đ): Phân biệt rõ toán tử ba ngôi là biểu thức sinh ra giá trị nên dùng trực tiếp được trong phép gán hoặc đối số hàm.\", \"Tình huống áp dụng phù hợp và quy tắc giữ mã dễ đọc (3.0đ): Nêu đúng trường hợp gán điều kiện đơn giản và lý giải tác hại giảm khả năng bảo trì khi lồng ghép nhiều cấp.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Toán tử điều kiện ba ngôi có trả về một giá trị biểu thức hay không, và vì sao có thể đặt trực tiếp nó bên trong lời gọi hàm printf?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000428", CoursePrf192Id, "00000000-0000-0000-0000-000000000463", RubricPrf192Id, "Cấu trúc lựa chọn switch-case và hiện tượng fall-through khi thiếu break", "Cấu trúc lựa chọn switch-case hoạt động và ràng buộc kiểu dữ liệu của biểu thức điều khiển như thế nào trong ngôn ngữ C? Lệnh break đóng vai trò gì trong mỗi nhánh case và hiện tượng trôi lệnh fall-through xảy ra ra sao khi thiếu lệnh break?", "Cấu trúc lựa chọn switch-case trong ngôn ngữ C dùng để rẽ nhánh đa hướng dựa trên giá trị rời rạc của một biểu thức nguyên, bao gồm các kiểu int, char hoặc kiểu liệt kê enum; chuẩn C tuyệt đối không cho phép dùng kiểu số thực float, double hay chuỗi ký tự làm biểu thức switch vì các nhãn case bắt buộc phải là hằng biểu thức nguyên cố định ngay lúc biên dịch. Khi thực thi, chương trình tính giá trị biểu thức switch rồi nhảy trực tiếp đến nhãn case khớp giá trị đó, hoặc chuyển sang nhánh default nếu không có nhãn nào khớp. Các nhãn case thực chất chỉ đóng vai trò điểm nhảy vào (entry label) chứ không tự tạo ranh giới kết thúc nhánh, do đó câu lệnh break ở cuối mỗi nhánh có nhiệm vụ ngắt luồng và thoát ngay khỏi toàn bộ khối switch. Nếu lập trình viên bỏ sót lệnh break, hiện tượng trôi lệnh (Fall-through) sẽ xảy ra: CPU tiếp tục thực thi tuần tự toàn bộ câu lệnh của các nhánh case nằm kế tiếp bên dưới mà không kiểm tra lại điều kiện nữa cho tới khi gặp lệnh break hoặc hết khối switch. Dù thường gây lỗi logic nếu quên break, cơ chế fall-through vẫn hữu ích khi chủ đích gom nhiều nhãn có chung cách xử lý như các tháng cùng có 31 ngày.", "[\"Nguyên lý đối sánh nhãn và ràng buộc kiểu nguyên của switch (3.5đ): Trình bày đúng cơ chế nhảy tới nhãn hằng nguyên khớp giá trị và khẳng định cấm dùng số thực hay chuỗi ký tự.\", \"Vai trò kết thúc nhánh của câu lệnh break (3.0đ): Giải thích rõ nhãn case chỉ là điểm nhảy vào còn lệnh break mới thực sự thoát khỏi khối switch.\", \"Phân tích hiện tượng Fall-through và tình huống gom nhóm hợp lệ (3.5đ): Mô tả đúng lỗi chạy tràn xuống các nhánh dưới khi thiếu break và ví dụ gom nhiều nhãn dùng chung logic.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Biểu thức điều khiển trong lệnh switch có thể nhận kiểu số thực float hoặc chuỗi ký tự được hay không?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000429", CoursePrf192Id, "00000000-0000-0000-0000-000000000463", RubricPrf192Id, "So sánh vòng lặp while và do-while về số lần lặp tối thiểu", "Hãy so sánh sự khác nhau căn bản giữa vòng lặp while và vòng lặp do-while trong ngôn ngữ C về thời điểm kiểm tra biểu thức điều kiện và số lần thực thi thân vòng lặp tối thiểu. Nêu bài toán thực tế điển hình nên ưu tiên sử dụng vòng lặp do-while.", "Sự khác biệt cốt lõi giữa vòng lặp while và vòng lặp do-while trong ngôn ngữ C nằm ở thứ tự kiểm tra điều kiện so với việc thực thi khối lệnh thân vòng lặp. Vòng lặp while thuộc nhóm vòng lặp kiểm tra điều kiện trước (Pre-test Loop): chương trình luôn đánh giá biểu thức điều kiện ngay tại cổng vào trước mỗi chu kỳ, nếu điều kiện sai ngay từ lần đầu tiên thì toàn bộ thân vòng lặp bị bỏ qua, do đó số lần thực thi tối thiểu của while là 0 lần. Ngược lại, vòng lặp do-while thuộc nhóm vòng lặp kiểm tra điều kiện sau (Post-test Loop): luồng điều khiển đi thẳng vào thực thi trọn vẹn khối lệnh trong thân do trước, rồi mới kiểm tra biểu thức điều kiện while ở cuối chu kỳ để quyết định có quay lại lặp tiếp hay không; vì thế bất chấp điều kiện ban đầu đúng hay sai, thân vòng lặp do-while luôn được đảm bảo chạy tối thiểu 1 lần. Nhờ đặc tính này, do-while là lựa chọn tự nhiên nhất cho bài toán hiển thị menu chức năng tương tác hoặc kiểm tra tính hợp lệ dữ liệu nhập từ bàn phím, nơi chương trình bắt buộc phải nhắc và thu nhận giá trị của người dùng ít nhất một lần trước khi xét xem dữ liệu có nằm ngoài miền hợp lệ để yêu cầu nhập lại hay không.", "[\"Phân biệt thời điểm kiểm tra điều kiện trước và sau (3.5đ): Nêu rõ while kiểm tra điều kiện ở đầu chu kỳ, còn do-while thực thi thân lệnh trước rồi mới kiểm tra ở cuối chu kỳ.\", \"Xác định chính xác số lần lặp tối thiểu 0 lần và 1 lần (3.5đ): Khẳng định chuẩn xác khi điều kiện sai ngay từ đầu thì while chạy 0 lần còn do-while vẫn chạy đúng 1 lần.\", \"Phân tích tình huống ứng dụng thực tế của do-while (3.0đ): Giải thích thuyết phục ứng dụng do-while trong bài toán hiển thị menu lựa chọn hoặc xác thực dữ liệu nhập từ bàn phím.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Nếu biểu thức điều kiện của vòng lặp mang giá trị sai ngay từ đầu, vòng lặp nào sẽ không chạy lần nào và vòng lặp nào vẫn thực thi đúng một lần?"),
            CreatePracticeSeed("00000000-0000-0000-0000-00000000042a", CoursePrf192Id, "00000000-0000-0000-0000-000000000463", RubricPrf192Id, "Lệnh điều khiển vòng lặp: Phân biệt break và continue", "Bên trong thân các vòng lặp for, while và do-while của ngôn ngữ C, hai câu lệnh break và continue khác nhau như thế nào? Hãy mô tả chính xác đích nhảy của luồng điều khiển chương trình khi gặp mỗi câu lệnh này.", "Hai câu lệnh break và continue đều làm thay đổi luồng tuần tự bên trong thân vòng lặp nhưng phục vụ hai mục đích điều khiển hoàn toàn trái ngược nhau. Khi gặp lệnh break, chương trình lập tức chấm dứt vĩnh viễn vòng lặp gần nhất đang bao bọc nó, bỏ qua cả phần lệnh còn lại của chu kỳ hiện tại lẫn mọi chu kỳ kế tiếp để chuyển thẳng quyền điều khiển ra câu lệnh đầu tiên nằm ngay sau khối vòng lặp; kỹ thuật này thường dùng để dừng duyệt sớm ngay khi đã tìm thấy phần tử thỏa mãn điều kiện. Ngược lại, lệnh continue không kết thúc vòng lặp mà chỉ bỏ qua các câu lệnh phía sau nó trong duy nhất lần lặp hiện tại để chuyển sang chu kỳ kế tiếp: đối với vòng lặp for, luồng thực thi nhảy tới biểu thức cập nhật biến đếm rồi mới kiểm tra lại điều kiện lặp; còn đối với vòng lặp while và do-while, luồng thực thi nhảy thẳng tới bước đánh giá biểu thức điều kiện lặp (do đó nếu đặt lệnh tăng biến đếm phía sau continue trong vòng while sẽ gây lặp vô tận). Trong cấu trúc vòng lặp lồng nhau, cả break lẫn continue chỉ tác động lên duy nhất một tầng vòng lặp trực tiếp chứa nó chứ không thoát ra khỏi các vòng lặp bao ngoài.", "[\"Hành vi chấm dứt vòng lặp của câu lệnh break (3.5đ): Trình bày rõ break kết thúc hẳn vòng lặp gần nhất và chuyển luồng ra câu lệnh kế tiếp sau khối lặp.\", \"Hành vi chuyển chu kỳ của continue trong for và while (3.5đ): Phân biệt rõ continue bỏ qua phần còn lại của lượt hiện tại để nhảy sang biểu thức cập nhật ở for hoặc kiểm tra điều kiện ở while.\", \"Phạm vi tác động cục bộ trong vòng lặp lồng nhau (3.0đ): Khẳng định chính xác break và continue chỉ chi phối vòng lặp trong cùng trực tiếp chứa nó.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, "Trong cấu trúc gồm nhiều vòng lặp lồng nhau, câu lệnh break đặt ở vòng lặp bên trong cùng có làm thoát luôn cả vòng lặp bên ngoài hay không?"),
            CreatePracticeSeed("00000000-0000-0000-0000-00000000042b", CoursePrf192Id, "00000000-0000-0000-0000-000000000467", RubricPrf192Id, "Bản chất lưu trữ ô nhớ của mảng một chiều và đánh chỉ số trong C", "Mảng một chiều trong ngôn ngữ C được tổ chức lưu trữ trên bộ nhớ RAM theo nguyên tắc nào? Với mảng gồm N phần tử, dải chỉ số hợp lệ được xác định như thế nào và điều gì xảy ra nếu chương trình truy cập vào phần tử tại chỉ số thứ N?", "Trong ngôn ngữ C, mảng một chiều là tập hợp hữu hạn các phần tử có cùng kiểu dữ liệu được cấp phát trên một dải ô nhớ liền kề liên tục nhau hoàn toàn trong RAM (Contiguous Memory). Nhờ tính liên tục vật lý này, địa chỉ của phần tử ở chỉ số i luôn được tính trực tiếp bằng địa chỉ cơ sở của phần tử đầu tiên cộng với tích của i nhân kích thước byte một phần tử, giúp thao tác truy cập ngẫu nhiên bất kỳ vị trí nào trong mảng luôn đạt độ phức tạp thời gian hằng số O(1). Vì chỉ số mảng bản chất là độ lệch số phần tử tính từ địa chỉ gốc nên ngôn ngữ C áp dụng quy tắc đánh chỉ số bắt đầu từ 0 (Zero-based indexing); với mảng có N phần tử, dải chỉ số hợp lệ chỉ chạy từ 0 đến N trừ 1. Khác với các ngôn ngữ bậc cao có máy ảo giám sát, ngôn ngữ C ưu tiên hiệu năng tối đa nên hoàn toàn không kiểm tra ranh giới mảng lúc chạy (No Runtime Bounds Checking). Nếu chương trình truy cập vào chỉ số thứ N tức vượt ra ngoài phạm vi mảng, sẽ dẫn tới hành vi không xác định (Undefined Behavior): đọc phải dữ liệu rác, vô tình ghi đè làm hỏng các biến lân cận hoặc địa chỉ trả về trên Stack, thậm chí gây lỗi vi phạm phân đoạn bộ nhớ làm sập tiến trình.", "[\"Đặc tính lưu trữ ô nhớ liên tục và truy cập O(1) (3.5đ): Mô tả rõ các phần tử nằm liền kề trên RAM và cơ chế tính địa chỉ theo độ lệch giúp truy xuất trong thời gian hằng số.\", \"Quy tắc đánh chỉ số từ 0 và dải hợp lệ từ 0 đến N trừ 1 (3.0đ): Giải thích bản chất chỉ số là khoảng cách tính từ phần tử đầu nên mảng N phần tử có chỉ số hợp lệ từ 0 đến N trừ 1.\", \"Phân tích hành vi không xác định khi truy cập vượt biên (3.5đ): Khẳng định C không kiểm tra biên lúc chạy, chỉ rõ nguy cơ đọc rác, ghi đè biến lân cận trên Stack hoặc gây lỗi Segmentation Fault.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, "Ngôn ngữ C có tự động kiểm tra và ngăn chặn lỗi truy cập vượt quá giới hạn chỉ số mảng tại thời điểm chương trình đang chạy hay không?"),
            CreatePracticeSeed("00000000-0000-0000-0000-00000000042c", CoursePrf192Id, "00000000-0000-0000-0000-000000000468", RubricPrf192Id, "Bản chất chuỗi ký tự C và vai trò của ký tự kết thúc chuỗi null", "Trong ngôn ngữ C, chuỗi ký tự được biểu diễn và lưu trữ trong bộ nhớ như thế nào? Ký tự kết thúc chuỗi null đóng vai trò gì và điều gì sẽ xảy ra nếu một mảng ký tự không có ký tự này khi truyền vào hàm printf hoặc hàm strlen?", "Ngôn ngữ C không có kiểu dữ liệu chuỗi nguyên thủy độc lập mà biểu diễn chuỗi ký tự dưới dạng một mảng một chiều các phần tử kiểu char nằm liên tiếp nhau và bắt buộc kết thúc bằng ký tự đặc biệt null terminator. Do đó, để lưu một chuỗi văn bản gồm K ký tự hiển thị (chẳng hạn từ FPT có 3 chữ cái), mảng ký tự phải được cấp phát dung lượng tối thiểu là K cộng 1 bytes nhằm dành riêng 1 byte cuối cùng cho ký tự kết thúc chuỗi. Về bản chất nhị phân, ký tự kết thúc chuỗi null có mã ASCII bằng đúng 0 (tất cả 8 bit đều bằng 0), hoàn toàn khác với ký tự chữ số 0 in ra màn hình vốn có mã ASCII bằng 48. Vì mảng trong C không tự lưu kèm siêu dữ liệu về độ dài chuỗi, ký tự null đóng vai trò cột mốc cầm canh duy nhất báo hiệu điểm dừng cho mọi hàm thư viện chuẩn. Nếu một mảng ký tự thiếu ký tự kết thúc chuỗi null, hàm strlen sẽ tiếp tục quét tràn qua các vùng nhớ kế cận trên RAM cho đến khi tình cờ gặp một byte có giá trị bằng 0 khiến kết quả độ dài sai lệch ngẫu nhiên, còn hàm printf với đặc tả chuỗi sẽ in kèm hàng loạt ký tự rác trong bộ nhớ hoặc gây lỗi vi phạm quyền truy cập vùng nhớ.", "[\"Biểu diễn chuỗi C bằng mảng char kèm 1 byte kết thúc (3.5đ): Nêu rõ C không có kiểu string riêng mà dùng mảng char với dung lượng tối thiểu bằng số ký tự cộng thêm 1 byte cho ký tự null.\", \"Vai trò cột mốc dừng và phân biệt mã ASCII 0 với ký tự chữ số 0 (3.5đ): Giải thích ký tự null có mã ASCII bằng 0 khác với ký tự '0' mã 48, đóng vai trò điểm dừng cho các hàm xử lý chuỗi.\", \"Hậu quả đọc tràn bộ nhớ khi thiếu ký tự kết thúc chuỗi (3.0đ): Phân tích chính xác hiện tượng strlen đếm lố sang ô nhớ lân cận và printf in dữ liệu rác hoặc gây lỗi Segmentation Fault.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, "Ký tự kết thúc chuỗi null có giá trị mã ASCII bằng bao nhiêu và nó khác như thế nào so với ký tự chữ số 0 thông thường?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000113", CoursePrf192Id, "00000000-0000-0000-0000-000000000462", RubricPrf192Id, "Cơ chế đánh giá đoản mạch (Short-circuit Evaluation) của toán tử logic AND và OR", "Cơ chế đánh giá đoản mạch của hai toán tử logic AND và OR trong ngôn ngữ C hoạt động như thế nào? Hãy phân tích tình huống kết hợp điều kiện kiểm tra biến mẫu số a khác 0 ở vế trái và phép chia b chia a lớn hơn 2 ở vế phải bằng toán tử AND logic để chứng minh vai trò ngăn chặn lỗi chia cho 0 của cơ chế này.", "Trong ngôn ngữ C, hai toán tử logic AND và OR luôn đánh giá các toán hạng theo thứ tự nghiêm ngặt từ trái sang phải và áp dụng cơ chế đoản mạch (Short-circuit Evaluation), nghĩa là dừng tính toán ngay lập tức khi giá trị chân lý của toàn bộ biểu thức đã được định đoạt chắc chắn. Đối với toán tử AND logic, chỉ cần toán hạng bên trái mang giá trị sai tức bằng 0 thì kết quả chung bắt buộc bằng 0, nên trình biên dịch bỏ qua hoàn toàn toán hạng bên phải. Ngược lại, đối với toán tử OR logic, chỉ cần toán hạng bên trái mang giá trị đúng tức khác 0 thì kết quả chung chắc chắn bằng 1, nên toán hạng bên phải cũng không bao giờ được thực thi. Cơ chế này đóng vai trò lá chắn an toàn quan trọng: khi đặt điều kiện kiểm tra mẫu số a khác 0 ở vế trái trước phép chia b chia a ở vế phải của toán tử AND logic, nếu a bằng 0 thì vế trái sai nên phép chia ở vế phải bị ngắt bỏ ngay, bảo vệ tiến trình khỏi lỗi ngoại lệ chia cho 0 tại thời điểm chạy (tương tự khi kiểm tra con trỏ khác NULL trước khi giải tham chiếu). Tuy nhiên, lập trình viên cần tuyệt đối tránh đặt các phép tăng giảm biến hoặc lời gọi hàm có tác dụng phụ ở vế phải vì chúng sẽ bị bỏ qua khi xảy ra đoản mạch.", "[\"Nguyên lý đoản mạch của toán tử AND logic và OR logic (4.0đ): Giải thích rõ thứ tự từ trái sang phải và dừng đánh giá ngay khi vế trái của AND bằng 0 hoặc vế trái của OR khác 0.\", \"Phân tích tình huống bảo vệ khỏi lỗi chia cho 0 (3.5đ): Chứng minh khi mẫu số a bằng 0 thì vế trái sai khiến phép chia ở vế phải không được thực thi, ngăn chặn sập tiến trình.\", \"Cảnh báo rủi ro tác dụng phụ ở toán hạng bên phải (2.5đ): Chỉ ra nguy cơ sai lệch trạng thái nếu đặt phép thay đổi biến hoặc lời gọi hàm quan trọng ở vế phải khi đoản mạch xảy ra.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Nếu toán hạng bên trái của toán tử OR logic đã mang giá trị đúng tức khác 0, thì biểu thức ở vế bên phải có được thực thi hay không và rủi ro tác dụng phụ nào cần tránh?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000114", CoursePrf192Id, "00000000-0000-0000-0000-000000000464", RubricPrf192Id, "Nguyên mẫu hàm (Function Prototype) và vai trò trong kiểm tra kiểu dữ liệu", "Nguyên mẫu hàm trong ngôn ngữ C bao gồm những thông tin gì? Tại sao cần cung cấp nguyên mẫu hàm ở đầu tệp nguồn nếu phần định nghĩa chi tiết thân hàm được đặt ở phía dưới hàm main?", "Nguyên mẫu hàm (Function Prototype hay Forward Declaration) là lời giới thiệu giao diện của hàm với trình biên dịch trước khi hàm được gọi hoặc định nghĩa chi tiết, bao gồm ba thông tin cốt lõi: kiểu dữ liệu trả về, tên định danh của hàm và danh sách kiểu dữ liệu theo đúng thứ tự của các tham số đầu vào. Việc đặt nguyên mẫu hàm phía trên hàm main giữ vai trò sống còn do trình biên dịch C phân tích mã nguồn theo cơ chế quét một lượt từ trên xuống dưới (Single-pass parsing). Nếu hàm main gọi một hàm chưa từng xuất hiện phía trên, các trình biên dịch tuân thủ chuẩn C99 và C11 hiện đại sẽ từ chối hoặc cảnh báo lỗi gọi hàm chưa công bố; còn ở chuẩn C89 cũ, trình biên dịch tự động giả định hàm đó trả về kiểu int, gây sai lệch dữ liệu nghiêm trọng nếu thực tế hàm trả về số thực double hoặc địa chỉ con trỏ 64-bit. Hơn nữa, nguyên mẫu hàm giúp trình biên dịch kiểm tra chặt chẽ số lượng và tính tương thích kiểu của từng đối số ngay lúc biên dịch, đồng thời là nền tảng để tách giao diện hàm ra tệp tiêu đề dùng chung cho kiến trúc đa tệp.", "[\"Trình bày đầy đủ ba thành phần của Function Prototype (3.0đ): Nêu rõ nguyên mẫu hàm cung cấp tên hàm, kiểu dữ liệu trả về và danh sách kiểu của các tham số.\", \"Giải thích cơ chế quét một lượt và bẫy giả định kiểu int (4.0đ): Phân tích rõ trình biên dịch đọc từ trên xuống và rủi ro chuẩn C89 tự giả định kiểu trả về mặc định là int.\", \"Vai trò kiểm tra kiểu đối số lúc biên dịch và tách tệp tiêu đề (3.0đ): Chỉ ra lợi ích bắt lỗi sai số lượng hoặc sai kiểu đối số sớm và hỗ trợ thiết kế chương trình đa module.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Trong các trình biên dịch C cổ điển theo chuẩn C89, nếu gọi một hàm khi chưa có nguyên mẫu hàm phía trên thì trình biên dịch sẽ ngầm giả định kiểu trả về mặc định là kiểu gì?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000115", CoursePrf192Id, "00000000-0000-0000-0000-000000000464", RubricPrf192Id, "Cơ chế truyền tham trị (Pass-by-value) và Stack Frame khi gọi hàm trong C", "Trong ngôn ngữ C, cơ chế truyền tham số mặc định khi gọi hàm là gì? Hãy trình bày những gì diễn ra trên ngăn xếp lời gọi hàm Call Stack khi một hàm được kích hoạt và giải thích tại sao việc thay đổi tham số bên trong hàm con không làm biến đổi biến gốc ở hàm gọi.", "Ngôn ngữ C chỉ sử dụng duy nhất một cơ chế truyền tham số mặc định là truyền theo giá trị (Pass-by-value). Mỗi khi một hàm con được gọi từ hàm main, CPU và hệ thống quản lý bộ nhớ sẽ đẩy một khung ngăn xếp mới gọi là Stack Frame (hay Activation Record) lên đỉnh vùng nhớ Call Stack dành riêng cho lần gọi hàm đó. Khung ngăn xếp này lưu trữ địa chỉ lệnh quay về (Return Address), con trỏ khung trước đó, các biến cục bộ của hàm con và các biến tham số hình thức. Tại thời điểm gọi hàm, giá trị hiện tại của các đối số thực tế ở hàm gọi được sao chép thành những bản sao hoàn toàn độc lập đặt vào vùng nhớ tham số hình thức trên Stack Frame của hàm con. Vì vậy, mọi phép tính hay phép gán thay đổi tham số bên trong hàm con thực chất chỉ sửa đổi trên bản sao cục bộ đó mà không hề chạm tới vùng nhớ của biến gốc nằm ở Stack Frame của hàm main. Ngay khi hàm con thực hiện lệnh return, con trỏ ngăn xếp dịch chuyển thu hồi toàn bộ Stack Frame của hàm con, hủy bỏ các bản sao tạm thời và bảo toàn nguyên vẹn giá trị biến ban đầu ở hàm gọi.", "[\"Khẳng định cơ chế truyền tham trị mặc định trong C (3.0đ): Nêu rõ C truyền tham số bằng cách sao chép giá trị đối số sang vùng nhớ tham số hình thức riêng biệt.\", \"Trình bày cấu trúc và vòng đời của Stack Frame (4.0đ): Mô tả rõ quá trình cấp phát khung ngăn xếp lưu tham số, biến cục bộ và địa chỉ quay về khi gọi hàm.\", \"Giải thích tính cô lập vùng nhớ và thu hồi khung khi return (3.0đ): Chỉ rõ thao tác trong hàm con chỉ sửa bản sao và toàn bộ Stack Frame bị thu hồi ngay khi hàm kết thúc.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Ngay khi hàm con thực thi câu lệnh return để kết thúc, điều gì sẽ xảy ra đối với khung ngăn xếp Stack Frame của hàm con đó?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000116", CoursePrf192Id, "00000000-0000-0000-0000-000000000464", RubricPrf192Id, "Phân biệt biến cục bộ (Local), toàn cục (Global) và biến tĩnh cục bộ (static local)", "Hãy phân biệt biến cục bộ thông thường, biến toàn cục và biến tĩnh cục bộ có từ khóa static trong ngôn ngữ C theo ba tiêu chí: phạm vi truy cập, phân vùng bộ nhớ lưu trữ và thời gian sống.", "Ba loại biến cục bộ, toàn cục và tĩnh cục bộ trong ngôn ngữ C khác nhau rõ rệt về phạm vi hiển thị, phân vùng bộ nhớ và vòng đời tồn tại. Thứ nhất, biến cục bộ thông thường có phạm vi khối lệnh (Block scope), chỉ truy cập được bên trong hàm hoặc cặp ngoặc nhọn chứa nó; biến nằm trên vùng nhớ ngăn xếp Stack, được cấp phát tự động mỗi khi luồng thực thi đi vào hàm và bị thu hồi ngay khi hàm kết thúc, đồng thời mang giá trị rác nếu chưa khởi tạo. Thứ hai, biến toàn cục được đặt bên ngoài mọi hàm nên có phạm vi toàn tệp nguồn (File scope), nằm tại phân vùng dữ liệu tĩnh Data hoặc BSS Segment, tự động khởi tạo bằng 0 nếu không chỉ định giá trị và tồn tại xuyên suốt từ lúc nạp tiến trình đến khi chương trình kết thúc. Thứ ba, biến tĩnh cục bộ dùng từ khóa static bên trong hàm kết hợp ưu điểm của cả hai loại trên: nó vẫn giữ phạm vi khối lệnh khép kín nên các hàm bên ngoài không thể can thiệp, nhưng lại được lưu trữ ở phân vùng dữ liệu tĩnh Data hoặc BSS, chỉ khởi tạo đúng một lần duy nhất trong suốt vòng đời chương trình và giữ nguyên giá trị tích lũy qua mọi lần gọi hàm kế tiếp.", "[\"Đặc tính phạm vi, vùng nhớ và vòng đời biến cục bộ (3.0đ): Nêu rõ phạm vi khối lệnh, cấp phát trên Stack, sinh ra khi vào hàm và tự hủy ngay khi thoát hàm.\", \"Đặc tính phạm vi, vùng nhớ và vòng đời biến toàn cục (3.0đ): Nêu rõ phạm vi toàn tệp, nằm tại Data hoặc BSS Segment và tồn tại xuyên suốt thời gian chạy tiến trình.\", \"Sự kết hợp phạm vi cục bộ và thời gian sống tĩnh của static local (4.0đ): Phân tích rõ tính đóng gói trong nội bộ hàm nhưng lưu ở Data/BSS, khởi tạo duy nhất 1 lần và bảo toàn giá trị giữa các lần gọi.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Một biến tĩnh cục bộ đặt bên trong một hàm được khởi tạo giá trị ban đầu bao nhiêu lần nếu hàm đó được gọi lặp lại hàng trăm lần trong chương trình?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000117", CoursePrf192Id, "00000000-0000-0000-0000-000000000466", RubricPrf192Id, "Khai thác thư viện chuẩn math.h, time.h và cơ chế sinh số giả ngẫu nhiên trong C", "Tại sao khi gọi hàm rand trong thư viện stdlib.h mà không khởi tạo hạt giống bằng hàm srand thì chương trình luôn sinh ra cùng một dãy số giống hệt nhau ở mọi lần chạy? Hãy giải thích vai trò của việc kết hợp srand với hàm lấy thời gian hiện tại time, nguyên lý quy đổi số ngẫu nhiên về đoạn từ min đến max, và lưu ý về kiểu dữ liệu cũng như miền xác định khi dùng các hàm sqrt, pow, fabs trong math.h.", "Hàm rand trong thư viện stdlib.h thực chất là bộ sinh số giả ngẫu nhiên (PRNG) hoạt động bằng thuật toán đồng dư tuyến tính hoàn toàn tất định dựa trên một giá trị trạng thái ban đầu gọi là hạt giống (Seed), trả về số nguyên không âm từ 0 đến hằng RAND_MAX. Theo chuẩn C, nếu chương trình không gọi hàm srand thì hệ thống tự động dùng hạt giống mặc định cố định bằng 1, dẫn tới mọi lần khởi chạy đều tính ra cùng một chuỗi số y hệt nhau. Khi truyền kết quả hàm time của thư viện time.h (trả về số giây tính từ mốc Unix Epoch) vào hàm srand đúng một lần duy nhất ở đầu hàm main, hạt giống sẽ thay đổi theo từng giây thực tế nên mỗi lần chạy sinh ra dãy số khác nhau; ngược lại nếu đặt srand bên trong vòng lặp chạy hàng nghìn chu kỳ trong cùng một giây, hạt giống bị đặt lại về cùng một mốc giây khiến hàm rand trả về toàn các số trùng lặp. Để thu gọn kết quả về đoạn nguyên từ min đến max, ta lấy phần dư của phép chia kết quả rand cho tổng số phần tử của đoạn là max trừ min cộng 1, rồi cộng dịch chuyển với min. Khi dùng thư viện math.h, cần lưu ý các hàm sqrt, pow và fabs đều làm việc trên kiểu số thực double (tránh dùng nhầm hàm abs của stdlib.h vốn cắt cụt về kiểu int) và phải kiểm tra đối số không âm trước khi tính căn bậc hai sqrt để tránh lỗi miền xác định sinh giá trị NaN.", "[\"Bản chất tất định của PRNG rand và vai trò khởi tạo hạt giống srand (3.5đ): Giải thích rõ mặc định hạt giống bằng 1 gây lặp dãy số và lý do chỉ gọi srand với thời gian thực đúng 1 lần ở đầu main.\", \"Nguyên lý ánh xạ số ngẫu nhiên về đoạn từ min đến max (3.5đ): Trình bày chính xác phép chia lấy dư cho độ rộng đoạn (max trừ min cộng 1) rồi cộng với mốc đầu min.\", \"Quy tắc kiểu double và miền xác định của các hàm trong math.h (3.0đ): Phân biệt rõ fabs làm việc trên kiểu double khác với abs kiểu int, đồng thời kiểm tra điều kiện không âm trước khi gọi sqrt.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Tại sao chỉ nên khởi tạo hạt giống srand với thời gian hiện tại đúng một lần duy nhất ở đầu hàm main thay vì đặt bên trong vòng lặp mỗi khi lấy số ngẫu nhiên?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000118", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", RubricPrf192Id, "Bản chất biến con trỏ, toán tử lấy địa chỉ và toán tử giải tham chiếu trong C", "Biến con trỏ trong ngôn ngữ C có bản chất là gì? Hãy phân biệt ý nghĩa và cơ chế tác động lên bộ nhớ của hai toán tử cốt lõi đi kèm con trỏ là toán tử lấy địa chỉ và toán tử giải tham chiếu.", "Biến con trỏ (Pointer) trong ngôn ngữ C là một biến đặc biệt không lưu trữ trực tiếp giá trị dữ liệu nghiệp vụ mà lưu trữ địa chỉ ô nhớ vật lý hoặc địa chỉ ảo trên RAM của một đối tượng dữ liệu khác. Vì mọi địa chỉ bộ nhớ trên cùng một kiến trúc vi xử lý đều có độ rộng bus địa chỉ như nhau, kích thước bản thân biến con trỏ hoàn toàn độc lập với kiểu dữ liệu mà nó trỏ tới: luôn chiếm đúng 4 bytes trên kiến trúc 32-bit và 8 bytes trên kiến trúc 64-bit dù đó là con trỏ trỏ tới kiểu char 1 byte hay kiểu double 8 bytes (kiểu dữ liệu đi kèm chỉ giúp trình biên dịch biết phải đọc bao nhiêu byte khi truy xuất). Hai toán tử nền tảng của con trỏ thực hiện hai chiều tác động ngược nhau: toán tử lấy địa chỉ (ký hiệu dấu và) đặt trước một biến có lvalue để trích xuất địa chỉ vùng nhớ nơi biến đó đang cư trú nhằm gán cho con trỏ; ngược lại, toán tử giải tham chiếu (ký hiệu dấu sao trong biểu thức thực thi) đặt trước biến con trỏ hợp lệ để đi theo địa chỉ lưu bên trong tới thẳng ô nhớ đích, cho phép đọc giá trị hoặc ghi đè làm thay đổi trực tiếp biến gốc từ xa.", "[\"Bản chất lưu địa chỉ của biến con trỏ và kích thước theo kiến trúc (3.0đ): Nêu rõ con trỏ lưu địa chỉ bộ nhớ, kích thước đồng nhất 4 bytes trên 32-bit và 8 bytes trên 64-bit cho mọi kiểu trỏ tới.\", \"Cơ chế trích xuất vị trí ô nhớ của toán tử lấy địa chỉ (3.5đ): Giải thích chính xác vai trò lấy địa chỉ vùng nhớ của một biến hiện hữu để cung cấp cho biến con trỏ nắm giữ.\", \"Cơ chế truy cập gián tiếp đọc và ghi qua toán tử giải tham chiếu (3.5đ): Phân tích rõ việc lần theo địa chỉ trong con trỏ để đọc hoặc sửa đổi trực tiếp giá trị tại ô nhớ đích.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Trên cùng một hệ điều hành 64-bit, kích thước bộ nhớ của một biến con trỏ kiểu int và một biến con trỏ kiểu double có khác nhau hay không, và bằng bao nhiêu bytes?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000119", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", RubricPrf192Id, "Mô phỏng truyền tham chiếu bằng con trỏ trong bài toán hoán vị hai biến", "Tại sao một hàm hoán vị nhận vào hai tham số kiểu số nguyên thông thường lại không thể đổi chỗ giá trị của hai biến gốc nằm trong hàm main? Hãy trình bày cơ chế truyền địa chỉ kết hợp toán tử giải tham chiếu và biến trung gian để hoán đổi trực tiếp vùng nhớ của hai biến gốc một cách an toàn.", "Một hàm hoán vị nhận hai tham số kiểu số nguyên thông thường luôn thất bại trong việc đổi chỗ hai biến ở hàm main bởi ngôn ngữ C chỉ truyền tham số theo giá trị (Pass-by-value). Khi hàm được gọi, chương trình chỉ sao chép giá trị của hai biến gốc vào hai biến cục bộ nằm trên Stack Frame riêng của hàm hoán vị; mọi thao tác tráo đổi chỉ diễn ra giữa hai bản sao này và bị hủy bỏ hoàn toàn ngay khi hàm kết thúc, khiến hai biến gốc ở hàm main giữ nguyên như cũ. Để mô phỏng truyền tham chiếu trong C, hàm hoán vị phải nhận tham số đầu vào là hai con trỏ kiểu số nguyên, đồng thời phía hàm main dùng toán tử lấy địa chỉ để truyền địa chỉ ô nhớ thực sự của hai biến vào hàm. Bên trong thân hàm, sau khi kiểm tra cả hai con trỏ đều khác NULL nhằm tránh lỗi truy cập địa chỉ rỗng, thuật toán thực hiện ba bước qua toán tử giải tham chiếu: đọc giá trị tại địa chỉ con trỏ thứ nhất cất vào biến tạm kiểu nguyên, tiếp theo đọc giá trị tại địa chỉ con trỏ thứ hai ghi đè vào ô nhớ con trỏ thứ nhất trỏ tới, và cuối cùng gán giá trị từ biến tạm vào ô nhớ con trỏ thứ hai trỏ tới. Nhờ can thiệp thẳng vào địa chỉ RAM trên Stack Frame của hàm main, hai biến gốc được hoán đổi vĩnh viễn.", "[\"Giải thích nguyên nhân thất bại khi truyền tham trị thông thường (3.0đ): Chỉ rõ hàm chỉ hoán đổi trên hai bản sao cục bộ thuộc Stack Frame riêng nên biến gốc ở hàm main không đổi.\", \"Trình bày đúng quy trình 3 bước hoán đổi qua giải tham chiếu và biến tạm (4.0đ): Mô tả chính xác tham số là hai con trỏ, kiểm tra khác NULL và ba bước tráo giá trị trực tiếp trên ô nhớ đích qua biến tạm.\", \"Cơ chế truyền địa chỉ từ hàm gọi và tác động xuyên Stack Frame (3.0đ): Giải thích rõ phía hàm main phải truyền địa chỉ hai biến bằng toán tử lấy địa chỉ để hàm con truy cập đúng ô nhớ gốc.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Khi gọi hàm hoán vị sử dụng con trỏ từ bên trong hàm main, hàm gọi phải truyền đối số như thế nào và cần kiểm tra điều kiện an toàn gì trước khi giải tham chiếu?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000120", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", RubricPrf192Id, "Số học con trỏ (Pointer Arithmetic) và cơ chế dịch chuyển địa chỉ theo kích thước kiểu", "Trong ngôn ngữ C, phép cộng thêm 1 đơn vị vào một biến con trỏ khác với phép cộng số học thông thường như thế nào? Giả sử một con trỏ kiểu số nguyên int đang lưu địa chỉ hệ thập lục phân là 0x1000 và kích thước kiểu int bằng 4 bytes, thì sau khi cộng thêm 2 phần tử vào con trỏ đó, địa chỉ mới thu được là bao nhiêu?", "Số học con trỏ (Pointer Arithmetic) trong ngôn ngữ C không cộng trừ trực tiếp theo từng byte riêng lẻ như số nguyên thông thường, mà tự động co giãn bước nhảy theo kích thước của kiểu dữ liệu mà con trỏ đang trỏ tới (Memory Scaling). Cụ thể, khi cộng một số nguyên k vào con trỏ ptr, địa chỉ bộ nhớ mới bằng địa chỉ ban đầu cộng với tích của k nhân kích thước sizeof kiểu dữ liệu đích: con trỏ kiểu char tăng 1 sẽ tiến 1 byte, con trỏ kiểu int 4 bytes tăng 1 sẽ tiến 4 bytes, còn con trỏ kiểu double 8 bytes tăng 1 sẽ tiến 8 bytes để luôn trỏ trúng byte đầu tiên của phần tử kế tiếp trong mảng. Áp dụng vào tình huống đề bài, con trỏ kiểu int ban đầu ở địa chỉ 0x1000 khi cộng thêm 2 đơn vị sẽ dịch chuyển một khoảng bằng 2 nhân 4 bằng 8 bytes (tương ứng 0x8 trong hệ thập lục phân), do đó địa chỉ mới chính xác là 0x1008. Về các phép toán hợp lệ, C cho phép cộng hoặc trừ con trỏ với số nguyên và cho phép lấy hiệu hai con trỏ cùng kiểu thuộc cùng một mảng nhằm xác định khoảng cách số phần tử nằm giữa chúng; ngược lại, phép cộng, nhân hoặc chia hai địa chỉ con trỏ bị cấm hoàn toàn vì tổng của hai địa chỉ bộ nhớ tạo ra một vị trí vô nghĩa nằm ngoài vùng quản lý hợp lệ.", "[\"Nguyên lý nhân bước nhảy theo kích thước kiểu dữ liệu đích (4.0đ): Giải thích rõ cộng thêm k vào con trỏ sẽ dịch chuyển địa chỉ một lượng bằng k nhân kích thước byte của phần tử trỏ tới.\", \"Tính toán chính xác địa chỉ mới bằng 0x1008 (3.0đ): Tính đúng độ lệch 2 nhân 4 bằng 8 bytes và cộng vào địa chỉ cơ sở 0x1000 thu được kết quả 0x1008.\", \"Phân biệt phép trừ khoảng cách hai con trỏ và lệnh cấm cộng hai con trỏ (3.0đ): Nêu đúng phép trừ hai con trỏ cùng mảng trả về độ lệch số phần tử, còn cộng hai địa chỉ bị cấm vì vô nghĩa vật lý.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Trong ngôn ngữ C, phép trừ giữa hai con trỏ cùng kiểu trỏ vào cùng một mảng trả về ý nghĩa gì, và vì sao chuẩn C nghiêm cấm phép cộng giữa hai con trỏ với nhau?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000121", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", RubricPrf192Id, "Mối quan hệ tương đương giữa mảng một chiều và con trỏ trong C", "Hãy giải thích cơ chế phân rã tên mảng trong biểu thức và chứng minh mối quan hệ tương đương giữa việc truy cập phần tử mảng qua toán tử ngoặc vuông chỉ số i với phép cộng số học con trỏ rồi giải tham chiếu. Dựa vào tính chất toán học nào mà việc đảo vị trí chỉ số i ra ngoài và đặt tên mảng vào trong ngoặc vuông vẫn hợp lệ trong ngôn ngữ C?", "Trong ngôn ngữ C, mảng một chiều và con trỏ gắn kết chặt chẽ thông qua quy tắc phân rã mảng (Array Decay): khi tên mảng xuất hiện trong hầu hết các biểu thức tính toán hoặc truyền vào hàm, trình biên dịch tự động chuyển đổi tên mảng đó thành một địa chỉ trỏ thẳng tới phần tử đầu tiên tại vị trí chỉ số 0. Theo đặc tả chuẩn C, toán tử ngoặc vuông truy cập chỉ số mảng thực chất chỉ là cách diễn đạt rút gọn (Syntactic Sugar) của phép cộng số học con trỏ kết hợp giải tham chiếu: việc truy xuất phần tử thứ i của mảng được trình biên dịch dịch thẳng thành thao tác lấy địa chỉ gốc của mảng cộng thêm i phần tử rồi giải tham chiếu để lấy giá trị tại ô nhớ đó. Chính vì phép cộng giữa địa chỉ con trỏ và số nguyên i có tính chất giao hoán (địa chỉ gốc cộng i hoàn toàn bằng i cộng địa chỉ gốc), nên khi giải tham chiếu biểu thức đảo thứ tự này, việc đặt chỉ số i đứng trước và tên mảng nằm trong cặp ngoặc vuông vẫn được trình biên dịch quy đổi về đúng một biểu thức gốc và chạy hợp lệ. Tuy nhiên, tên mảng không phải là một biến con trỏ thực thụ: tên mảng là địa chỉ cố định không có lvalue khả biến nên cấm gán sang vùng nhớ khác hay tăng giảm trực tiếp, đồng thời toán tử sizeof áp trên tên mảng tĩnh trả về tổng số byte của toàn mảng chứ không phải 8 bytes kích thước con trỏ.", "[\"Giải thích cơ chế Array Decay về địa chỉ phần tử đầu tiên (3.0đ): Trình bày rõ tên mảng trong biểu thức tự động phân rã thành địa chỉ của phần tử tại vị trí chỉ số 0.\", \"Chứng minh tính tương đương của toán tử chỉ số và tính giao hoán (4.0đ): Giải thích rõ trình biên dịch quy đổi toán tử ngoặc vuông về phép cộng con trỏ rồi giải tham chiếu và tính giao hoán của phép cộng.\", \"Phân biệt tên mảng cố định với biến con trỏ qua phép gán và sizeof (3.0đ): Nêu rõ tên mảng không thể bị gán lại địa chỉ mới và sizeof trên mảng tĩnh trả về tổng dung lượng cả mảng.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Tên của một mảng tĩnh khác với một biến con trỏ thông thường ở những điểm cốt lõi nào khi dùng với toán tử sizeof hoặc khi thực hiện phép gán địa chỉ mới?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000122", CoursePrf192Id, "00000000-0000-0000-0000-000000000467", RubricPrf192Id, "Ma trận hai chiều (2D Array) và thứ tự lưu trữ ưu tiên dòng (Row-major order)", "Mảng hai chiều hay ma trận được tổ chức lưu trữ vật lý trong không gian bộ nhớ tuyến tính RAM như thế nào theo quy ước ưu tiên dòng Row-major order của ngôn ngữ C? Tại sao khi truyền một mảng hai chiều tĩnh vào tham số của hàm, ngôn ngữ C cho phép bỏ trống số dòng nhưng bắt buộc phải chỉ định rõ kích thước số cột?", "Mặc dù mảng hai chiều được lập trình viên hình dung theo bảng gồm các dòng và cột, nhưng bộ nhớ RAM vật lý chỉ là một dải địa chỉ tuyến tính một chiều duy nhất. Ngôn ngữ C ánh xạ mảng hai chiều xuống RAM theo quy ước ưu tiên dòng (Row-major order): toàn bộ C phần tử thuộc dòng 0 được xếp liền kề nhau trước, nối tiếp ngay sau đó là toàn bộ C phần tử của dòng 1, dòng 2 và cứ thế tuần tự cho đến hết dòng cuối cùng. Để tìm đến phần tử ở dòng i và cột j (đánh chỉ số từ 0), chương trình phải nhảy qua trọn vẹn i dòng phía trước (tương ứng i nhân C phần tử) rồi tiến thêm j phần tử trong dòng hiện tại; do đó độ lệch phần tử là i nhân C cộng j, và độ lệch địa chỉ byte bằng tổng đó nhân với kích thước byte của một phần tử (ví dụ nhân 4 bytes với kiểu int). Từ công thức ánh xạ này có thể thấy rõ lý do bắt buộc phải cung cấp số cột C trong tham số hàm: khi truyền mảng hai chiều vào hàm, nó phân rã thành con trỏ trỏ tới một mảng dòng có C phần tử, nên trình biên dịch bắt buộc phải biết chính xác bề rộng một dòng C mới sinh được mã máy tính bước nhảy qua mỗi dòng; ngược lại tổng số dòng R không xuất hiện trong công thức tính địa chỉ phần tử nên chỉ cần truyền kèm như một biến giới hạn vòng lặp.", "[\"Mô tả cơ chế trải phẳng tuần tự từng dòng Row-major order (3.5đ): Giải thích rõ RAM tuyến tính xếp trọn vẹn các phần tử dòng 0 rồi nối tiếp dòng 1, dòng 2 liên tục nhau.\", \"Trình bày đúng công thức tính độ lệch phần tử và độ lệch byte (3.0đ): Nêu chính xác độ lệch thứ tự bằng (i nhân số cột cộng j) và nhân với kích thước sizeof kiểu phần tử để ra số byte.\", \"Giải thích lý do trình biên dịch bắt buộc biết trước số cột (3.5đ): Phân tích rõ trình biên dịch cần số cột để xác định bước nhảy địa chỉ giữa hai dòng liên tiếp, còn số dòng không nằm trong công thức địa chỉ.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Với một ma trận số nguyên gồm R dòng và C cột trong đó mỗi phần tử chiếm 4 bytes, phần tử nằm ở dòng i cột j cách địa chỉ đầu tiên của ma trận bao nhiêu bytes?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000123", CoursePrf192Id, "00000000-0000-0000-0000-000000000467", RubricPrf192Id, "Nguyên lý thuật toán sắp xếp chọn (Selection Sort) trên mảng một chiều", "Hãy trình bày ý tưởng phân chia mảng và quy trình hoạt động từng bước của thuật toán Sắp xếp chọn Selection Sort để sắp xếp mảng N số nguyên tăng dần. Hãy phân tích số phép so sánh, số lần hoán đổi tối đa và độ phức tạp thời gian của thuật toán trong trường hợp tốt nhất cũng như xấu nhất.", "Thuật toán Sắp xếp chọn (Selection Sort) chia mảng một chiều gồm N phần tử thành hai phân vùng: vùng bên trái đã được sắp xếp đúng thứ tự cuối cùng và vùng bên phải chưa được sắp xếp. Thuật toán thực hiện đúng N trừ 1 lượt lặp ngoài với chỉ số i chạy từ 0 đến N trừ 2. Ở mỗi lượt thứ i, ta khởi tạo biến ghi nhận vị trí nhỏ nhất min_idx bằng chính i, sau đó dùng vòng lặp trong cho chỉ số j quét từ i cộng 1 đến N trừ 1 để so sánh và cập nhật lại min_idx mỗi khi bắt gặp phần tử nhỏ hơn giá trị tại min_idx. Kết thúc vòng quét trong, nếu min_idx khác i thì thực hiện đúng một phép hoán đổi đưa phần tử nhỏ nhất vừa tìm được về cố định tại vị trí i, mở rộng vùng đã sắp xếp thêm một phần tử. Về hiệu năng, vì vòng lặp trong luôn phải quét hết đoạn còn lại bất chấp dữ liệu đầu vào đã có thứ tự hay chưa, tổng số phép so sánh luôn cố định bằng N nhân (N trừ 1) chia 2; do đó độ phức tạp thời gian ở cả trường hợp tốt nhất, trung bình và xấu nhất đều bằng O(N bình phương), bù lại số lần hoán đổi vật lý rất ít (tối đa N trừ 1 lần) và chỉ tốn không gian phụ O(1) tại chỗ. Selection Sort không phải thuật toán ổn định (Unstable) vì phép hoán đổi nhảy xa có thể đẩy một phần tử ở đầu mảng vượt qua phần tử khác có cùng giá trị đứng sau nó.", "[\"Trình bày ý tưởng phân chia hai vùng và quy trình tìm vị trí nhỏ nhất (3.5đ): Mô tả rõ N trừ 1 lượt lặp ngoài, dùng biến lưu chỉ số nhỏ nhất quét đoạn từ i cộng 1 đến cuối rồi hoán đổi về vị trí i.\", \"Phân tích độ phức tạp O(N bình phương) mọi trường hợp và ưu điểm ít hoán đổi (3.5đ): Giải thích tổng số phép so sánh luôn cố định N(N-1)/2 nên Best Case và Worst Case đều là O(N^2), tối đa N-1 lần hoán vị tại chỗ.\", \"Giải thích tính chất không ổn định (Unstable Sort) của thuật toán (3.0đ): Phân tích đúng việc hoán đổi khoảng cách xa làm đảo lộn thứ tự xuất hiện ban đầu của hai phần tử bằng nhau.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Thuật toán Selection Sort cơ bản dùng phép hoán đổi trực tiếp có bảo toàn tính ổn định thứ tự tương đối giữa các phần tử mang giá trị bằng nhau hay không, vì sao?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000124", CoursePrf192Id, "00000000-0000-0000-0000-000000000468", RubricPrf192Id, "Nguy cơ bảo mật của hàm gets và kỹ thuật nhập chuỗi an toàn với fgets", "Tại sao hàm nhập chuỗi gets bị coi là lỗ hổng bảo mật nghiêm trọng và bị loại bỏ hoàn toàn khỏi chuẩn ngôn ngữ C11? Hãy trình bày cơ chế kiểm soát kích thước của hàm thay thế an toàn fgets khi đọc từ luồng bàn phím stdin và cách loại bỏ ký tự xuống dòng mà fgets giữ lại ở cuối chuỗi.", "Hàm gets bị khai tử khỏi chuẩn ISO C11 bởi thiết kế thiếu tham số giới hạn dung lượng vùng nhớ: hàm chỉ nhận duy nhất con trỏ trỏ vào đầu mảng ký tự và tiếp tục ghi không kiểm soát mọi ký tự người dùng gõ cho đến khi gặp phím Enter hoặc EOF. Khi chuỗi nhập vào dài hơn kích thước mảng, hàm gets ghi tràn thẳng qua các biến lân cận và ghi đè lên địa chỉ quay về trên Stack Frame (lỗ hổng Buffer Overflow), tạo điều kiện cho kẻ tấn công chiếm quyền điều khiển tiến trình. Giải pháp chuẩn là dùng hàm fgets nhận ba tham số gồm địa chỉ mảng đích, kích thước tối đa N của mảng và luồng đầu vào stdin: hàm cam kết chỉ đọc tối đa N trừ 1 ký tự (hoặc dừng sớm khi gặp ký tự xuống dòng) và luôn tự động gắn ký tự kết thúc chuỗi null vào vị trí cuối cùng. Khác với gets, nếu bộ đệm đủ chỗ thì fgets lưu cả ký tự xuống dòng vào ngay trước ký tự null; để làm sạch chuỗi, ta tìm vị trí ký tự xuống dòng đầu tiên bằng hàm strcspn trong string.h (hoặc kiểm tra ký tự ở chỉ số độ dài trừ 1) rồi ghi đè thành ký tự kết thúc chuỗi null. Trường hợp người dùng nhập vượt quá N trừ 1 ký tự, phần ký tự dư vẫn nằm lại trong bộ đệm stdin và cần đọc xả hết tới dấu xuống dòng trước lần nhập kế tiếp.", "[\"Phân tích nguyên nhân tràn bộ đệm Stack của hàm gets (3.5đ): Chỉ rõ hàm gets không nhận kích thước bộ đệm nên ghi tràn vượt ranh giới mảng, gây lỗ hổng bảo mật nghiêm trọng.\", \"Giải thích ba tham số và cơ chế đọc tối đa N trừ 1 ký tự của fgets (3.5đ): Trình bày rõ fgets giới hạn số byte đọc theo kích thước mảng trừ 1 để luôn chừa chỗ gắn ký tự kết thúc chuỗi null an toàn.\", \"Quy trình cắt bỏ ký tự xuống dòng và xử lý phần dư trong stdin (3.0đ): Nêu đúng kỹ thuật dùng strcspn hoặc kiểm tra cuối chuỗi để thay dấu xuống dòng bằng null và nhận diện dữ liệu thừa còn trong stdin.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Nếu người dùng gõ một dòng văn bản dài vượt quá sức chứa bộ đệm truyền vào hàm fgets, phần ký tự dư thừa chưa được đọc hết sẽ nằm ở đâu và gây ảnh hưởng gì cho lệnh nhập tiếp theo?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000125", CoursePrf192Id, "00000000-0000-0000-0000-000000000466", RubricPrf192Id, "Các hàm thao tác chuỗi cốt lõi trong string.h: strlen, strcmp, strcpy và strcat", "Hãy trình bày mục đích xử lý, vai trò các tham số và quy ước giá trị trả về của bốn hàm thao tác chuỗi cơ bản trong thư viện string.h gồm strlen, strcmp, strcpy và strcat. Tại sao trong ngôn ngữ C không thể dùng toán tử so bằng để so sánh nội dung hai chuỗi ký tự?", "Thư viện string.h cung cấp bốn hàm thao tác chuỗi ký tự cốt lõi dựa trên cột mốc kết thúc chuỗi null. Thứ nhất, hàm strlen nhận vào một con trỏ chuỗi chỉ đọc và đếm số lượng ký tự xuất hiện trước ký tự null (không tính bản thân byte null vào độ dài trả về kiểu size_t). Thứ hai, hàm strcmp đối chiếu lần lượt từng cặp ký tự tương ứng của hai chuỗi theo mã ASCII thứ tự từ điển: trả về số nguyên âm nếu tại vị trí khác nhau đầu tiên ký tự của chuỗi thứ nhất có mã ASCII nhỏ hơn chuỗi thứ hai, trả về 0 khi hai chuỗi trùng khớp hoàn toàn mọi ký tự, và trả về số nguyên dương nếu chuỗi thứ nhất lớn hơn. Thứ ba, hàm strcpy sao chép toàn bộ nội dung chuỗi nguồn bao gồm cả byte kết thúc null sang mảng đích, đòi hỏi mảng đích phải được cấp phát đủ dung lượng chứa. Thứ tư, hàm strcat tìm tới đúng vị trí byte null ở cuối chuỗi đích để ghi nối tiếp chuỗi nguồn vào đó rồi gắn byte null mới ở cuối cùng. Trong ngôn ngữ C, lập trình viên tuyệt đối không thể dùng toán tử so bằng giữa hai tên mảng hoặc hai biến con trỏ chuỗi để so sánh nội dung, vì phép toán đó chỉ kiểm tra xem hai con trỏ có trỏ cùng vào một địa chỉ ô nhớ vật lý hay không chứ không duyệt so sánh các ký tự bên trong.", "[\"Đặc tả chính xác cơ chế của hàm strlen và strcmp (4.0đ): Nêu rõ strlen đếm số ký tự không tính byte null và strcmp trả về âm, 0, dương theo mã ASCII từ điển.\", \"Đặc tả cơ chế sao chép strcpy và nối chuỗi strcat (3.0đ): Trình bày đúng quy trình chép kèm byte null và ghi đè từ vị trí null cuối chuỗi đích kèm điều kiện đủ bộ nhớ.\", \"Giải thích bản chất so sánh địa chỉ khi dùng toán tử so bằng (3.0đ): Chỉ rõ toán tử so bằng chỉ đối chiếu hai địa chỉ vùng nhớ của con trỏ chứ không so sánh nội dung xâu ký tự.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Hàm strcmp lần lượt trả về số âm, số 0 và số dương trong những trường hợp cụ thể nào khi so sánh hai chuỗi?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000126", CoursePrf192Id, "00000000-0000-0000-0000-000000000467", RubricPrf192Id, "Cấu trúc dữ liệu Struct và phân biệt toán tử truy xuất thành viên trong C", "Kiểu dữ liệu cấu trúc struct trong ngôn ngữ C giải quyết bài toán biểu diễn dữ liệu gì khác với mảng thông thường, và việc kết hợp từ khóa typedef mang lại lợi ích gì? Hãy phân biệt rõ khi nào sử dụng toán tử dấu chấm và khi nào sử dụng toán tử mũi tên để truy xuất các trường thành viên.", "Trong khi mảng chỉ lưu trữ được tập hợp các phần tử có cùng một kiểu dữ liệu đồng nhất, từ khóa struct trong ngôn ngữ C cho phép lập trình viên gom nhóm nhiều thuộc tính có kiểu dữ liệu khác nhau (chẳng hạn mã định danh kiểu nguyên, họ tên kiểu mảng ký tự và điểm trung bình kiểu số thực) thành một kiểu dữ liệu phức hợp thống nhất đại diện cho một thực thể nghiệp vụ. Việc kết hợp thêm từ khóa typedef giúp định nghĩa một tên bí danh kiểu ngắn gọn, cho phép tạo các biến hoặc tham số hàm trực tiếp bằng tên kiểu mới mà không phải lặp lại từ khóa struct phía trước. Để truy xuất tới từng trường thành viên bên trong cấu trúc, ngôn ngữ C cung cấp hai toán tử chuyên biệt tùy theo bản chất biến nắm giữ: toán tử dấu chấm (Direct Member Access) được dùng khi thao tác trực tiếp trên một biến giá trị thuộc kiểu cấu trúc; ngược lại, toán tử mũi tên (Indirect Member Access) được dùng khi thao tác thông qua một biến con trỏ đang lưu địa chỉ của cấu trúc đó (thường gặp khi truyền địa chỉ struct vào hàm để tiết kiệm chi phí sao chép bộ nhớ). Về bản chất, toán tử mũi tên hoàn toàn tương đương với việc giải tham chiếu con trỏ trước rồi mới dùng toán tử dấu chấm, nhưng bắt buộc phải đặt phép giải tham chiếu trong ngoặc đơn vì toán tử dấu chấm có độ ưu tiên cao hơn toán tử giải tham chiếu.", "[\"Bản chất gom nhóm đa kiểu của struct và lợi ích của typedef (3.5đ): Phân biệt rõ struct gom nhiều trường khác kiểu thành một thực thể và vai trò đặt bí danh kiểu gọn gàng của typedef.\", \"Phân biệt chính xác ngữ cảnh dùng toán tử dấu chấm và mũi tên (3.5đ): Chỉ rõ dùng dấu chấm cho biến cấu trúc trực tiếp và dùng mũi tên khi truy xuất qua con trỏ trỏ tới cấu trúc.\", \"Giải thích tính tương đương và thứ tự ưu tiên toán tử (3.0đ): Lý giải đúng sự tương đương với phép giải tham chiếu kèm dấu chấm và vai trò bắt buộc của ngoặc đơn do độ ưu tiên.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Khi truy xuất một trường dữ liệu thông qua con trỏ cấu trúc bằng toán tử giải tham chiếu kết hợp toán tử dấu chấm, tại sao bắt buộc phải bao cặp ngoặc đơn quanh phép giải tham chiếu con trỏ?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000127", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", RubricPrf192Id, "Quản lý bộ nhớ động trong C: Phân biệt malloc, calloc, realloc và free", "Hãy phân tích cơ chế hoạt động và sự khác nhau căn bản giữa bốn hàm quản lý bộ nhớ động trên phân vùng Heap trong thư viện stdlib.h gồm malloc, calloc, realloc và free. Tại sao ngay sau mỗi lời gọi cấp phát động, chương trình luôn bắt buộc phải kiểm tra kết quả khác NULL trước khi sử dụng?", "Bốn hàm trong thư viện stdlib.h quản lý toàn bộ vòng đời vùng nhớ động trên phân vùng Heap lúc chạy. Thứ nhất, hàm malloc nhận tổng số byte cần xin và cấp phát một khối nhớ liên tục chưa khởi tạo (vẫn chứa dữ liệu rác) nhằm đạt tốc độ nhanh nhất. Thứ hai, hàm calloc nhận hai tham số là số phần tử và kích thước mỗi phần tử, đồng thời tự động xóa toàn bộ các byte trong khối nhớ mới về giá trị 0. Thứ ba, hàm realloc dùng để co giãn kích thước khối nhớ đã cấp phát: nếu vùng trống kế tiếp đủ rộng thì nó nới rộng ngay tại chỗ; nếu không đủ chỗ liền kề, realloc tự tìm khối nhớ mới đủ lớn ở nơi khác trên Heap, sao chép nguyên vẹn dữ liệu cũ sang vùng mới, giải phóng khối cũ rồi trả về địa chỉ mới (nếu truyền con trỏ NULL thì tương đương malloc). Thứ tư, hàm free hoàn trả khối nhớ Heap về cho hệ thống tái sử dụng. Sau mọi thao tác cấp phát, lập trình viên bắt buộc kiểm tra kết quả khác NULL vì khi cạn RAM hoặc thiếu khối liên tục đủ lớn, các hàm trên trả về NULL; giải tham chiếu địa chỉ NULL sẽ gây lỗi Segmentation Fault làm sập tiến trình ngay lập tức.", "[\"Phân biệt tham số và trạng thái khởi tạo giữa malloc và calloc (3.0đ): Nêu rõ malloc nhận tổng số byte chứa dữ liệu rác, còn calloc nhận số phần tử kèm kích thước và khởi tạo toàn bộ byte bằng 0.\", \"Phân tích hai kịch bản mở rộng tại chỗ và di dời khối nhớ của realloc (3.5đ): Giải thích rõ cơ chế nới rộng liền kề hoặc cấp phát vùng mới, sao chép dữ liệu cũ sang và tự giải phóng khối cũ.\", \"Vai trò thu hồi của free và lý do bắt buộc kiểm tra khác NULL (3.5đ): Nêu rõ free trả vùng nhớ Heap cho hệ thống và kiểm tra NULL để chống lỗi Segmentation Fault khi hết bộ nhớ.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, "Khi gọi hàm realloc để nới rộng vùng nhớ nhưng các ô nhớ liền kề phía sau trên Heap đã bị chiếm dụng không đủ chỗ, hàm realloc sẽ xử lý dữ liệu cũ như thế nào?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000128", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", RubricPrf192Id, "Phân tích ba lỗi bộ nhớ nguy hiểm: Memory Leak, Dangling Pointer và Double Free", "Hãy phân tích bản chất kỹ thuật, kịch bản phát sinh và hậu quả vận hành của ba lỗi bộ nhớ nghiêm trọng trong ngôn ngữ C gồm: Rò rỉ bộ nhớ Memory Leak, Con trỏ lơ lửng Dangling Pointer và Giải phóng hai lần Double Free. Trình bày quy tắc lập trình phòng ngừa cho từng loại lỗi.", "Ba lỗi bộ nhớ trên đe dọa trực tiếp độ ổn định và an ninh của tiến trình C. Thứ nhất, Rò rỉ bộ nhớ (Memory Leak) xảy ra khi vùng nhớ đã cấp phát trên Heap bị mất địa chỉ tham chiếu trước khi gọi free, chẳng hạn gán đè địa chỉ khác lên con trỏ duy nhất hoặc thoát hàm quên thu hồi; hậu quả là khối nhớ bị chiếm giữ vô ích khiến tiến trình dài hạn cạn dần RAM, nên phải đảm bảo mọi nhánh thoát hàm đều giải phóng tài nguyên. Thứ hai, Con trỏ lơ lửng (Dangling Pointer) phát sinh khi biến con trỏ vẫn giữ địa chỉ của khối nhớ Heap đã bị free hoặc địa chỉ biến cục bộ của hàm đã kết thúc; đọc ghi qua con trỏ này gây lỗi Use-After-Free làm hỏng dữ liệu đối tượng mới hoặc sập chương trình ngẫu nhiên. Thứ ba, Giải phóng hai lần (Double Free) là gọi free lặp lại trên cùng địa chỉ Heap chưa cấp phát mới, phá hỏng cấu trúc siêu dữ liệu Heap Metadata và tạo lỗ hổng an ninh nghiêm trọng. Quy tắc phòng vệ cốt lõi cho cả Dangling Pointer lẫn Double Free là gán ngay con trỏ về NULL sau lệnh free đầu tiên, bởi chuẩn C bảo đảm lời gọi free trên con trỏ NULL luôn là thao tác rỗng an toàn.", "[\"Phân tích kịch bản mất tham chiếu và hậu quả của Memory Leak (3.0đ): Giải thích rõ vùng nhớ Heap không được gọi free trước khi mất con trỏ dẫn tới tích lũy tiêu hao cạn kiệt RAM.\", \"Phân tích lỗi Use-After-Free của Dangling Pointer (3.5đ): Chỉ rõ nguy cơ truy xuất vùng nhớ đã thu hồi trên Heap hoặc Stack làm hỏng dữ liệu mới và gây sập ngẫu nhiên.\", \"Phân tích lỗi hỏng Heap Metadata của Double Free và quy tắc gán NULL (3.5đ): Lý giải việc gọi free hai lần phá vỡ cấu trúc quản lý Heap và chứng minh gán NULL sau free bảo vệ an toàn nhờ free(NULL) là no-op.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Thói quen gán biến con trỏ về NULL ngay lập tức sau khi gọi hàm free giúp triệt tiêu trực tiếp những lỗi nào trong ba lỗi kể trên và tại sao?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000129", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", RubricPrf192Id, "Quy trình cấp phát động ma trận hai chiều qua con trỏ cấp hai và thứ tự giải phóng bộ nhớ", "Hãy trình bày chi tiết quy trình hai giai đoạn để cấp phát động một ma trận gồm M dòng và N cột số nguyên trên Heap thông qua con trỏ cấp hai. Nếu quá trình cấp phát bị thất bại giữa chừng ở dòng thứ k thì chương trình phải xử lý thu hồi như thế nào, và tại sao khi dùng xong bắt buộc phải giải phóng theo thứ tự từ các dòng con ra con trỏ quản lý ngoài?", "Cấp phát ma trận động M dòng N cột qua con trỏ cấp hai tiến hành theo hai giai đoạn phân cấp. Ở giai đoạn một, chương trình gọi malloc cấp phát trên Heap một mảng quản lý gồm M con trỏ kiểu int và kiểm tra kết quả khác NULL. Ở giai đoạn hai, duyệt vòng lặp i từ 0 đến M trừ 1, mỗi bước gọi malloc cấp phát một mảng con N số nguyên kiểu int gán vào phần tử thứ i của mảng con trỏ ngoài. Nếu tại dòng thứ k bất kỳ mà hết RAM khiến malloc trả về NULL, chương trình bắt buộc chạy vòng lặp từ 0 đến k trừ 1 gọi free thu hồi toàn bộ k dòng con đã xin trước đó, rồi gọi free giải phóng mảng con trỏ ngoài trước khi báo lỗi thoát hàm để tránh rò rỉ bộ nhớ dở dang. Khi dùng xong ma trận, quy trình thu hồi bắt buộc đi ngược thứ tự từ trong ra ngoài: lặp giải phóng toàn bộ M mảng dòng con từ 0 đến M trừ 1 trước, cuối cùng mới gọi free lên con trỏ cấp hai bên ngoài và gán về NULL. Nếu gọi free con trỏ ngoài trước, bảng lưu địa chỉ M dòng con bị hủy mất khiến M mảng dữ liệu bị mồ côi vĩnh viễn trên Heap (Memory Leak) và mọi truy cập tiếp theo vào các dòng con sẽ gây lỗi Use-After-Free.", "[\"Trình bày đúng quy trình cấp phát phân cấp hai giai đoạn (3.5đ): Mô tả rõ bước 1 cấp phát mảng M con trỏ dòng và bước 2 lặp cấp phát mảng N số nguyên cho từng dòng.\", \"Cơ chế dọn dẹp cuốn chiếu khi cấp phát thất bại giữa chừng (3.0đ): Phân tích đúng thao tác thu hồi toàn bộ các dòng từ 0 đến k trừ 1 kèm mảng con trỏ ngoài nếu dòng thứ k trả về NULL.\", \"Giải thích thứ tự giải phóng từ trong ra ngoài và hậu quả làm ngược (3.5đ): Khẳng định phải free từng dòng con trước khi free con trỏ cấp hai ngoài cùng để tránh mất địa chỉ gây Memory Leak và Use-After-Free.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Điều gì sẽ xảy ra đối với bộ nhớ Heap nếu lập trình viên gọi hàm free trên con trỏ cấp hai bên ngoài trước rồi mới tìm cách giải phóng các dòng bên trong?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000130", CoursePrf192Id, "00000000-0000-0000-0000-000000000467", RubricPrf192Id, "Căn chỉnh bộ nhớ (Data Alignment) và Byte Padding trong cấu trúc Struct C", "Giả sử một cấu trúc dữ liệu struct trong ngôn ngữ C chứa lần lượt ba trường theo thứ tự: một biến kiểu char 1 byte, tiếp theo là một biến kiểu int 4 bytes, và cuối cùng là một biến kiểu char 1 byte trên hệ thống 32-bit hoặc 64-bit. Tại sao kích thước thực tế của cấu trúc này khi đo bằng sizeof lại chiếm 12 bytes thay vì 6 bytes? Hãy giải thích nguyên lý căn chỉnh bộ nhớ Data Alignment, cơ chế chèn Byte Padding và cách sắp xếp lại thứ tự các trường để tối ưu hóa dung lượng RAM.", "Vi xử lý hiện đại đọc bộ nhớ RAM theo từng khối từ nhớ (Word 4 hoặc 8 bytes) chứ không đọc lẻ từng byte. Để đọc trọn một biến nguyên thủy chỉ trong một chu kỳ bus, phần cứng áp dụng quy tắc căn chỉnh tự nhiên (Natural Data Alignment): trường kích thước K bytes phải đặt tại độ lệch offset chia hết cho K, và tổng kích thước struct phải chia hết cho kích thước trường lớn nhất bên trong. Với cấu trúc gồm char 1 byte, int 4 bytes rồi char 1 byte: biến char đầu nằm tại offset 0; biến int kế tiếp đòi hỏi offset chia hết cho 4 nên trình biên dịch chèn 3 byte đệm trống (Byte Padding) ở offset 1 đến 3 rồi đặt biến int tại offset 4 đến 7; biến char thứ hai nằm ở offset 8; cuối cùng trình biên dịch chèn thêm 3 byte đệm đuôi ở offset 9 đến 11 để tổng dung lượng chia hết cho 4, nâng kích thước lên 12 bytes. Để tối ưu bộ nhớ mà vẫn giữ nguyên tốc độ truy xuất của CPU, ta gom các trường cùng kích thước hoặc xếp theo thứ tự kích thước giảm dần: đặt hai biến char liền nhau ở offset 0 và 1, chỉ cần 2 byte đệm ở offset 2 và 3 rồi đặt biến int ở offset 4 đến 7, giảm kích thước struct xuống còn đúng 8 bytes.", "[\"Giải thích nguyên lý đọc khối Word của CPU và quy tắc Natural Alignment (3.5đ): Nêu rõ yêu cầu đặt biến K bytes tại offset chia hết cho K và quy tắc căn chỉnh đuôi theo thành viên lớn nhất.\", \"Phân tích chính xác vị trí các byte đệm tạo thành 12 bytes (3.5đ): Chỉ rõ 3 byte đệm giữa trường char đầu với trường int (offset 1..3) và 3 byte đệm cuối sau trường char thứ hai (offset 9..11).\", \"Trình bày giải pháp sắp xếp lại thứ tự trường giảm xuống 8 bytes (3.0đ): Giải thích việc xếp liền hai biến char hoặc xếp theo kích thước giảm dần giúp giảm còn 2 byte đệm và tổng dung lượng 8 bytes.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Nếu gom hai trường kiểu char đặt liền kề nhau trước rồi mới đến trường kiểu int ở cuối, tổng kích thước của cấu trúc sẽ giảm xuống còn bao nhiêu bytes và các byte đệm nằm ở vị trí nào?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000131", CoursePrf192Id, "00000000-0000-0000-0000-000000000467", RubricPrf192Id, "Tổ chức mảng cấu trúc quản lý sinh viên và chiến lược sắp xếp đa tiêu chí", "Khi tổ chức một mảng các cấu trúc Sinh viên gồm mã sinh viên, họ tên và điểm trung bình GPA trong ngôn ngữ C, hãy trình bày chiến lược thiết lập điều kiện so sánh để sắp xếp danh sách theo tiêu chí kép: ưu tiên điểm GPA giảm dần, và nếu hai sinh viên có điểm GPA bằng nhau thì xếp theo thứ tự từ điển tăng dần của chuỗi họ tên.", "Để quản lý danh sách N sinh viên, mỗi phần tử trong mảng một chiều là một cấu trúc đóng gói ba trường gồm mảng ký tự mã số, mảng ký tự họ tên và biến số thực lưu điểm GPA. Trong thuật toán sắp xếp đa tiêu chí, trọng tâm nằm ở logic đối chiếu thứ bậc ưu tiên giữa phần tử đứng trước và phần tử đứng sau. Ở tiêu chí chính thứ nhất, thuật toán xét trường điểm GPA: nếu phần tử đứng sau có GPA lớn hơn phần tử đứng trước thì đánh dấu hoán đổi ngay để đưa điểm cao lên đầu. Ở tiêu chí phụ thứ hai khi hai sinh viên có GPA bằng nhau (với số thực nên kiểm tra trị tuyệt đối hiệu số nhỏ hơn ngưỡng epsilon rất nhỏ như 1e-6 để tránh sai số nhị phân), thuật toán gọi hàm strcmp so sánh hai chuỗi họ tên; nếu kết quả strcmp nhỏ hơn 0 tức tên người đứng sau xếp trước theo bảng chữ cái ASCII thì thực hiện hoán đổi. Khi đổi chỗ hai phần tử vừa phải, chuẩn C hỗ trợ phép gán trực tiếp nguyên khối giữa hai biến cùng kiểu struct qua một biến tạm an toàn thay vì chép lẻ từng trường. Riêng khi mỗi bản ghi rất lớn hàng kilobyte, nên lập mảng phụ các con trỏ trỏ tới từng struct rồi chỉ tráo đổi các địa chỉ 8 bytes trên mảng con trỏ đó.", "[\"Tổ chức cấu trúc bản ghi Sinh viên hợp lý trong mảng một chiều (2.5đ): Trình bày rõ cách đóng gói các trường chuỗi mã số, chuỗi họ tên và số thực GPA thành phần tử của mảng cấu trúc.\", \"Thiết lập đúng logic so sánh đa tiêu chí GPA giảm dần và Tên tăng dần (4.5đ): Phân tích chính xác thứ tự ưu tiên xét GPA trước, lưu ý ngưỡng epsilon khi bằng điểm và dùng strcmp đối chiếu chuỗi họ tên.\", \"Cơ chế gán nguyên khối struct và kỹ thuật sắp xếp qua mảng con trỏ (3.0đ): Giải thích phép gán trực tiếp toàn bộ biến struct qua biến tạm và giải pháp tráo con trỏ 8 bytes khi kích thước bản ghi lớn.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, "Khi cần đổi chỗ hai sinh viên trong mảng cấu trúc, ta nên hoán đổi rời rạc từng trường thành viên hay gán trực tiếp cả biến cấu trúc, và nếu mỗi cấu trúc có kích thước rất lớn hàng kilobyte thì nên tối ưu bằng kỹ thuật nào?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000132", CoursePrf192Id, "00000000-0000-0000-0000-000000000468", RubricPrf192Id, "Phân tích bản chất lỗi tràn bộ đệm (Buffer Overflow) trên Call Stack và cơ chế phòng thủ", "Lỗi tràn bộ đệm trên ngăn xếp Stack-based Buffer Overflow xảy ra do nguyên nhân nào? Hãy trình bày thứ tự bố trí các thành phần trong một Stack Frame từ địa chỉ thấp lên địa chỉ cao và giải thích tại sao việc ghi tràn qua mảng ký tự cục bộ lại có thể làm thay đổi luồng điều khiển của vi xử lý.", "Lỗi tràn bộ đệm trên ngăn xếp (Stack-based Buffer Overflow) xảy ra khi hàm ghi dữ liệu vào mảng cục bộ vượt quá sức chứa cấp phát do dùng các hàm thiếu kiểm tra giới hạn biên như gets, strcpy hay sprintf. Trên kiến trúc x86 và x86-64, ngăn xếp Call Stack phát triển về phía địa chỉ thấp, nhưng thao tác ghi vào mảng ký tự lại tiến từ địa chỉ thấp lên địa chỉ cao. Xét từ địa chỉ thấp lên cao trong một Stack Frame, các vùng nhớ xếp lần lượt gồm: mảng đệm cục bộ, các biến cục bộ khác, con trỏ khung đã lưu (Saved Base Pointer EBP/RBP) và ngay phía trên là Địa chỉ lệnh quay về (Return Address EIP/RIP). Do chiều ghi mảng hướng thẳng về Return Address, nếu dữ liệu nhập vượt độ dài mảng đệm thì các byte dư thừa sẽ tràn qua biến cục bộ, đè lên con trỏ khung và ghi đè giá trị giả mạo lên ô nhớ Return Address; khi hàm thực thi lệnh thoát, CPU nạp địa chỉ bị ghi đè đó vào thanh ghi con trỏ lệnh làm sập tiến trình hoặc chuyển hướng thực thi trái phép. Để phòng thủ, phải thay bằng các hàm giới hạn kích thước như fgets, snprintf kết hợp cơ chế Stack Canary đặt một giá trị ngẫu nhiên bí mật chắn trước Return Address để kiểm tra và ngắt tiến trình ngay nếu phát hiện bị ghi đè.", "[\"Nguyên nhân gốc rễ gây tràn bộ đệm trên ngăn xếp (3.0đ): Nêu rõ việc ghi dữ liệu vượt dung lượng mảng cục bộ do dùng hàm thiếu kiểm tra giới hạn biên như gets, strcpy, sprintf.\", \"Trình bày đúng thứ tự bố trí các thành phần trong Stack Frame (3.5đ): Mô tả chính xác chiều ghi mảng từ địa chỉ thấp lên cao hướng về phía con trỏ khung đã lưu và ô nhớ Return Address.\", \"Phân tích tác động ghi đè Return Address và cơ chế Stack Canary (3.5đ): Giải thích rõ cơ chế làm lệch thanh ghi lệnh khi hàm thoát cùng nguyên lý đặt giá trị canh gác Stack Canary kết hợp hàm an toàn.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Cơ chế bảo vệ Stack Canary trong các trình biên dịch hiện đại như GCC hoạt động như thế nào để kịp thời phát hiện và ngăn chặn hành vi ghi đè địa chỉ trả về?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000133", CoursePrf192Id, "00000000-0000-0000-0000-000000000469", RubricPrf192Id, "Phân biệt tệp văn bản (Text File) và tệp nhị phân (Binary File): Cơ chế mã hóa và hiệu năng", "Hãy so sánh toàn diện giữa Tệp văn bản Text File và Tệp nhị phân Binary File trong ngôn ngữ C theo bốn khía cạnh: cơ chế biểu diễn dữ liệu trên đĩa, kích thước lưu trữ đối với số nguyên 123456789 kiểu int 4 bytes, tốc độ đọc ghi I/O và tính tương thích đa nền tảng.", "Tệp văn bản và tệp nhị phân khác biệt căn bản ở cách ánh xạ dữ liệu giữa RAM và đĩa cứng. Thứ nhất, tệp văn bản chuyển đổi mọi giá trị thành chuỗi ký tự mã ASCII/UTF-8 theo dòng (trên Windows, chế độ văn bản còn tự động dịch ký tự xuống dòng thành cặp hai byte CRLF khi ghi và gộp ngược lại khi đọc); trái lại, tệp nhị phân sao chép nguyên bản luồng byte thô từ RAM xuống đĩa không qua bước dịch ký tự nào. Thứ hai, với số nguyên 123456789 kiểu int 4 bytes: tệp văn bản phải lưu 9 chữ số thành 9 ký tự ASCII tốn 9 bytes, còn tệp nhị phân luôn chiếm cố định đúng 4 bytes nhị phân của kiểu int, tiết kiệm hơn một nửa dung lượng. Thứ ba, về hiệu năng I/O, tệp nhị phân dùng fread và fwrite chép thẳng khối nhớ nên rất nhanh, trong khi tệp văn bản dùng fprintf và fscanf chậm hơn do CPU tốn chi phí chuyển đổi định dạng giữa chuỗi cơ số 10 và số nhị phân. Đổi lại, tệp văn bản đọc sửa trực tiếp được bằng trình soạn thảo và độc lập phần cứng, còn tệp nhị phân phụ thuộc thứ tự byte Endianness và căn chỉnh Padding giữa các kiến trúc máy khác nhau.", "[\"Phân biệt cơ chế mã hóa ký tự ASCII và sao chép luồng byte thô (3.0đ): Giải thích rõ tệp văn bản định dạng thành ký tự kèm dịch dòng CRLF trên Windows, còn tệp nhị phân ghi nguyên bản byte RAM.\", \"So sánh chính xác dung lượng 9 bytes văn bản và 4 bytes nhị phân (3.5đ): Chứng minh số 123456789 tốn 9 bytes cho 9 ký tự chữ số ở tệp văn bản so với cố định 4 bytes kiểu int ở tệp nhị phân.\", \"Đánh giá hiệu năng chuyển đổi định dạng và tính tương thích Endianness (3.5đ): Chỉ rõ chi phí phân tích chuỗi của fprintf/fscanf so với tốc độ khối của fread/fwrite cùng hạn chế phụ thuộc Endianness và Padding.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Trên hệ điều hành Windows, việc mở tệp ở chế độ văn bản khác với chế độ nhị phân như thế nào đối với quá trình dịch tự động ký tự xuống dòng?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000134", CoursePrf192Id, "00000000-0000-0000-0000-000000000469", RubricPrf192Id, "Nguyên lý lưu trữ và phục hồi mảng cấu trúc bằng fread và fwrite trên tệp nhị phân", "Hãy giải thích vai trò của bốn tham số đầu vào cùng ý nghĩa giá trị trả về của hai hàm fread và fwrite trong thư viện stdio.h. Trình bày quy trình chuẩn để ghi trọn vẹn một mảng N cấu trúc Sinh viên xuống tệp nhị phân rồi đọc phục hồi trở lại bộ nhớ RAM một cách an toàn.", "Hai hàm fwrite và fread thao tác khối dữ liệu nhị phân qua bốn tham số tuần tự: con trỏ địa chỉ vùng đệm trên RAM, kích thước byte của một phần tử đo bằng sizeof(Student), số lượng phần tử cần đọc ghi và con trỏ luồng tệp FILE. Cả hai hàm đều trả về số phần tử thực tế đã ghi hoặc đọc trọn vẹn kiểu size_t, giúp đối chiếu với số lượng yêu cầu để phát hiện lỗi đầy đĩa hoặc chạm cuối tệp sớm. Để lưu mảng N sinh viên, chương trình mở tệp chế độ ghi nhị phân wb, kiểm tra con trỏ tệp khác NULL, gọi một lệnh fwrite cho cả N phần tử, kiểm tra giá trị trả về bằng N rồi đóng tệp bằng fclose; khi phục hồi, mở tệp chế độ rb, kiểm tra khác NULL, gọi fread nạp vào mảng đích và lấy giá trị trả về làm số bản ghi thực tế trước khi fclose. Đặc biệt lưu ý: cấu trúc ghi thẳng bằng fwrite chỉ được dùng mảng cố định chứ tuyệt đối cấm chứa trường con trỏ, bởi fwrite chỉ sao chép nông địa chỉ RAM 8 bytes xuống đĩa thay vì nội dung chuỗi trên Heap, khiến lần chạy sau đọc lên một địa chỉ vô hiệu gây lỗi Dangling Pointer làm sập tiến trình.", "[\"Giải thích chính xác 4 tham số và giá trị trả về của fread, fwrite (3.5đ): Trình bày đúng vai trò địa chỉ vùng đệm, kích thước mỗi phần tử, số phần tử, luồng tệp và kiểm tra số phần tử thực tế trả về.\", \"Trình bày đầy đủ quy trình mở nhị phân wb và rb, kiểm tra NULL và đóng tệp (3.5đ): Nêu rõ chế độ nhị phân có hậu tố b, kiểm tra mở tệp thành công trước khi đọc ghi và gọi fclose giải phóng luồng tệp.\", \"Phân tích cạm bẫy ghi địa chỉ vô hiệu khi cấu trúc chứa trường con trỏ (3.0đ): Giải thích sâu việc fwrite sao chép nông địa chỉ RAM thay vì dữ liệu đích trên Heap gây lỗi Dangling Pointer khi nạp lại.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, "Nếu bên trong cấu trúc Sinh viên có chứa một trường thành viên là biến con trỏ kiểu char trỏ tới vùng nhớ ghi chú trên Heap, việc dùng fwrite ghi thẳng cấu trúc đó ra tệp nhị phân sẽ gây ra lỗi nghiêm trọng gì khi đọc lại ở lần chạy chương trình sau?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000135", CoursePrf192Id, "00000000-0000-0000-0000-000000000469", RubricPrf192Id, "Truy cập ngẫu nhiên trên tệp với fseek, ftell, rewind và bẫy lỗi vòng lặp feof", "Hãy giải thích chức năng của ba hàm điều khiển vị trí tệp gồm fseek, ftell, rewind cùng ý nghĩa ba hằng số mốc SEEK_SET, SEEK_CUR và SEEK_END trong ngôn ngữ C. Tại sao thói quen kiểm tra phủ định của hàm feof làm điều kiện duy trì vòng lặp while khi đọc tệp lại thường gây lỗi xử lý lặp lại bản ghi cuối cùng hai lần?", "Thư viện stdio.h cung cấp ba hàm định vị ngẫu nhiên trên tệp: fseek dịch chuyển vị trí đọc ghi theo độ lệch byte tính từ mốc đầu tệp SEEK_SET, mốc hiện tại SEEK_CUR hoặc mốc cuối tệp SEEK_END; ftell trả về độ lệch byte hiện hành tính từ đầu tệp; còn rewind đưa vị trí tệp về ngay đầu tệp đồng thời xóa cờ lỗi. Nhờ vậy, để đo kích thước byte của tệp nhị phân, ta gọi fseek dịch 0 byte tới SEEK_END, gọi ftell lấy tổng số byte rồi gọi rewind quay lại đầu tệp. Về bẫy lỗi dùng phủ định của hàm feof làm điều kiện vòng lặp while: trong chuẩn C, cờ kết thúc tệp EOF không tự bật ngay lúc vừa đọc xong bản ghi cuối cùng, mà chỉ bật sau khi một lệnh đọc kế tiếp cố đọc vượt quá đáy tệp và thất bại. Vì thế sau khi đọc bản ghi cuối, feof vẫn trả về sai khiến vòng lặp chạy dư thêm một lượt; ở lượt dư này lệnh fread hoặc fscanf thất bại không ghi dữ liệu mới vào biến đệm, làm chương trình xử lý lặp lại giá trị cũ của bản ghi cuối hai lần. Giải pháp chuẩn là đặt trực tiếp biểu thức kiểm tra giá trị trả về của chính hàm đọc (như fread bằng 1 hoặc fgets khác NULL) làm điều kiện vòng lặp.", "[\"Trình bày chức năng fseek, ftell, rewind và 3 mốc định vị (3.5đ): Giải thích chuẩn vai trò từng hàm, ba hằng SEEK_SET, SEEK_CUR, SEEK_END và quy trình đo kích thước tệp nhị phân.\", \"Phân tích cơ chế trễ của cờ EOF gây lặp thừa bản ghi cuối (3.5đ): Chỉ rõ cờ EOF chỉ bật sau một thao tác đọc vượt đáy tệp bị thất bại, làm biến đệm giữ giá trị cũ và bị xử lý hai lần.\", \"Giải pháp kiểm tra trực tiếp kết quả trả về của hàm đọc (3.0đ): Trình bày đúng nguyên tắc dùng giá trị trả về của fread, fscanf hoặc fgets làm điều kiện dừng vòng lặp an toàn.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Làm thế nào để xác định chính xác kích thước byte của một tệp nhị phân bằng sự kết hợp giữa hai hàm fseek và ftell rồi đưa con trỏ tệp về lại vị trí đầu tiên?"),
            CreatePracticeSeed("00000000-0000-0000-0004-000000000136", CoursePrf192Id, "00000000-0000-0000-0000-000000000466", RubricPrf192Id, "Con trỏ hàm (Function Pointer) và cơ chế Callback trong hàm thư viện chuẩn qsort", "Con trỏ hàm trong ngôn ngữ C lưu trữ thông tin gì và cơ chế gọi ngược Callback được hàm thư viện chuẩn qsort trong stdlib.h vận dụng như thế nào để sắp xếp được mảng thuộc bất kỳ kiểu dữ liệu nào? Tại sao bên trong hàm so sánh hai số nguyên kiểu int của qsort, việc trả về trực tiếp hiệu của hai số lại tiềm ẩn lỗi tràn số nguyên có dấu và nên thay thế bằng cách so sánh nào?", "Con trỏ hàm (Function Pointer) lưu trữ địa chỉ bắt đầu đoạn mã máy của một hàm trong phân vùng Text/Code Segment, cho phép truyền hàm làm đối số. Hàm chuẩn qsort trong stdlib.h ứng dụng cơ chế gọi ngược (Callback) qua bốn đối số: địa chỉ mảng gốc kiểu void, số phần tử, kích thước byte mỗi phần tử và con trỏ hàm so sánh. Vì qsort chỉ hoán đổi các khối byte thô mà không biết kiểu phần tử cụ thể, mỗi khi cần xét thứ tự hai phần tử nó gọi ngược hàm so sánh với hai tham số kiểu con trỏ hằng tổng quát const void (chấp nhận mọi kiểu dữ liệu và cam kết không sửa phần tử gốc). Trong hàm so sánh số nguyên, ta ép kiểu tường minh hai con trỏ const void sang con trỏ const int rồi giải tham chiếu lấy hai giá trị a, b để trả về âm, 0 hoặc dương. Tuyệt đối cấm trả về trực tiếp hiệu a trừ b vì khi a bằng âm 2 tỷ và b bằng dương 1 tỷ, hiệu toán học âm 3 tỷ vượt giới hạn INT_MIN 32-bit gây tràn số nguyên có dấu (Undefined Behavior) lật thành số dương làm sắp xếp sai hoàn toàn; thay vào đó, phải dùng phép so sánh quan hệ trả về -1, 0, 1 hoặc hiệu của (a lớn hơn b) trừ (a nhỏ hơn b) để miễn nhiễm tràn số tuyệt đối.", "[\"Giải thích bản chất con trỏ hàm và cơ chế Callback của qsort (3.5đ): Trình bày rõ con trỏ hàm trỏ vào vùng mã lệnh và cách qsort gọi ngược hàm so sánh để sắp xếp mảng tổng quát.\", \"Vai trò của tham số const void và quy trình ép kiểu giải tham chiếu (3.5đ): Giải thích lý do dùng con trỏ tổng quát chỉ đọc và quy trình ép sang con trỏ kiểu đích cụ thể trước khi đọc giá trị.\", \"Phân tích bẫy tràn số nguyên có dấu khi lấy hiệu và cách so sánh an toàn (3.0đ): Chứng minh phép trừ a trừ b gây tràn số lật dấu ở biên INT_MIN/INT_MAX và nêu cách trả về dựa trên phép so sánh quan hệ.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Tại sao hai tham số truyền vào hàm so sánh của qsort lại mang kiểu con trỏ hằng tổng quát const void, và quy trình chuyển đổi để đọc được giá trị phần tử bên trong diễn ra như thế nào?"),
            // =========================================================================
            // 2. CSD201 — 36 CÂU HỎI KHO LUYỆN TẬP & THI THỬ (12 Easy, 12 Medium, 12 Hard)
            // =========================================================================
            CreatePracticeSeed("00000000-0000-0000-0000-000000000521", CourseCsd201Id, "00000000-0000-0000-0000-000000000561", RubricCsd201Id, "Phân tích Ký pháp Big-O và So sánh Tốc độ Tăng trưởng Thời gian", "Ký pháp Big-O là gì? Hãy sắp xếp các độ phức tạp thời gian sau theo thứ tự tăng dần về tốc độ tăng trưởng khi kích thước dữ liệu n tiến tới vô cùng: O(n^2), O(1), O(n log n), O(2^n), O(log n), O(n). Với mỗi cấp độ, hãy cho biết một ví dụ thuật toán điển hình.", "Ký pháp Big-O biểu diễn chặn trên tiệm cận (asymptotic upper bound) của thời gian thực thi hoặc không gian bộ nhớ thuật toán khi kích thước đầu vào n tiến tới vô cùng: f(n) = O(g(n)) nếu tồn tại hằng số c > 0 và n0 >= 1 sao cho f(n) <= c * g(n) với mọi n >= n0.\n\nThứ tự sắp xếp theo tốc độ tăng trưởng tăng dần (từ nhanh nhất/tốt nhất đến chậm nhất/tồi nhất):\n1. O(1) - Hằng số: Truy xuất phần tử mảng qua chỉ số `arr[i]`, lấy đỉnh ngăn xếp `stack.peek()`.\n2. O(log n) - Lôgarit: Tìm kiếm nhị phân (Binary Search) trên mảng đã sắp xếp.\n3. O(n) - Tuyến tính: Tìm kiếm tuyến tính (Linear Search), duyệt qua một danh sách liên kết.\n4. O(n log n) - Tuyến tính - lôgarit: Thuật toán sắp xếp MergeSort, HeapSort.\n5. O(n^2) - Bậc hai: Thuật toán sắp xếp cơ bản như Bubble Sort, Selection Sort, lồng 2 vòng lặp duyệt mảng.\n6. O(2^n) - Cấp số nhân: Đệ quy ngây thơ tính số Fibonacci, bài toán Tháp Hà Nội.", "[\"Định nghĩa ký pháp Big-O (2.5đ): Định nghĩa chính xác bản chất toán học chặn trên tiệm cận O(g(n)) và ý nghĩa trong đánh giá thuật toán.\", \"Sắp xếp thứ tự tăng trưởng (4.0đ): Sắp xếp đúng 100% thứ tự: O(1) < O(log n) < O(n) < O(n log n) < O(n^2) < O(2^n).\", \"Ví dụ thuật toán tương ứng (3.5đ): Cung cấp chính xác ví dụ thuật toán kinh điển cho từng cấp độ độ phức tạp.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Nếu một thuật toán A có độ phức tạp O(n^2) với hằng số ẩn c = 1, và thuật toán B có độ phức tạp O(n) nhưng hằng số ẩn c = 1,000,000, thì trong thực tế với quy mô dữ liệu n < 1000 thuật toán nào sẽ thực thi nhanh hơn và tại sao phân tích Big-O lý thuyết lại bỏ qua các hằng số này?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000522", CourseCsd201Id, "00000000-0000-0000-0000-000000000561", RubricCsd201Id, "Cơ chế Cấp phát Bộ nhớ và Chi phí Truy xuất giữa Mảng và Singly Linked List", "Hãy so sánh Mảng (Array) và Danh sách liên kết đơn (Singly Linked List) về cơ chế cấp phát bộ nhớ, chi phí truy xuất phần tử ngẫu nhiên và chi phí chèn một phần tử vào đầu danh sách.", "1. Cơ chế cấp phát bộ nhớ:\n- Mảng (Array): Cấp phát một vùng nhớ liên tục (contiguous memory blocks) có kích thước cố định tại thời điểm khởi tạo. Tận dụng tối đa bộ nhớ đệm CPU (CPU cache locality).\n- Singly Linked List: Cấp phát bộ nhớ động rời rạc (non-contiguous) trên Heap cho từng nút (Node). Mỗi nút chứa dữ liệu và một con trỏ tham chiếu `next`, dẫn đến tốn bộ nhớ phụ (memory overhead) cho các tham chiếu.\n\n2. Chi phí truy xuất ngẫu nhiên (Random Access):\n- Mảng: Đạt O(1) do địa chỉ phần tử được tính trực tiếp bằng công thức: `Address(A[i]) = Base_Address + i * sizeof(Element)`.\n- Singly Linked List: Chi phí O(n) do không có chỉ số trực tiếp; muốn truy xuất phần tử thứ k, bắt buộc phải duyệt tuần tự từ nút đầu `head` qua k bước.\n\n3. Chi phí chèn vào đầu (Insert at Head):\n- Mảng: Chi phí O(n) do phải dịch chuyển toàn bộ n phần tử hiện có sang phải một vị trí.\n- Singly Linked List: Chi phí O(1) vì chỉ cần tạo nút mới, gán `newNode.next = head`, sau đó cập nhật `head = newNode`.", "[\"So sánh cơ chế cấp phát bộ nhớ (3.0đ): Nêu rõ bộ nhớ liên tục vs bộ nhớ động phân mảnh và overhead con trỏ tham chiếu.\", \"Phân tích chi phí truy xuất ngẫu nhiên (3.5đ): Giải thích công thức tính địa chỉ O(1) của mảng và thao tác duyệt tuần tự O(n) của danh sách liên kết.\", \"Phân tích chi phí chèn đầu danh sách (3.5đ): Chỉ rõ chi phí dịch mảng O(n) so với phép gán con trỏ O(1) trong Singly Linked List.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Tại sao khi duyệt tuần tự một mảng (Array traversal), tốc độ thực thi đo bằng số chu kỳ CPU thường nhanh hơn gấp nhiều lần so với duyệt Danh sách liên kết đơn dù cả hai cấu trúc cùng có độ phức tạp thời gian lý thuyết là O(n)?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000523", CourseCsd201Id, "00000000-0000-0000-0000-000000000561", RubricCsd201Id, "Cấu trúc Nút và Ưu thế của Doubly Linked List so với Singly Linked List", "Mô tả cấu trúc của một nút trong Danh sách liên kết đôi (Doubly Linked List). Cấu trúc này mang lại ưu thế gì vượt trội so với Danh sách liên kết đơn khi thực hiện thao tác xóa một nút đã biết trước tham chiếu?", "Cấu trúc của một nút trong Doubly Linked List gồm 3 trường thông tin:\n1. Trường dữ liệu `data`: Lưu trữ giá trị phần tử của danh sách.\n2. Tham chiếu `prev`: Trỏ tới nút liền trước (nút tiền nhiệm).\n3. Tham chiếu `next`: Trỏ tới nút liền sau (nút kế nhiệm).\n\nƯu thế vượt trội khi xóa một nút đích đã biết trước tham chiếu:\n- Trong Singly Linked List: Dù đã nắm trực tiếp tham chiếu tới nút cần xóa, ta không thể lùi về nút đứng trước nó. Thuật toán bắt buộc phải duyệt tuần tự từ nút đầu `head` để tìm nút tiền nhiệm có liên kết kế tiếp trỏ vào nút đích, dẫn tới chi phí thời gian O(n).\n- Trong Doubly Linked List: Ta truy cập trực tiếp nút tiền nhiệm qua con trỏ `prev` và nút kế nhiệm qua con trỏ `next`. Thao tác ngắt liên kết diễn ra tức thì trong thời gian hằng số O(1): nếu nút tiền nhiệm khác rỗng thì nối con trỏ `next` của nó sang nút kế nhiệm (ngược lại cập nhật lại `head`), và nếu nút kế nhiệm khác rỗng thì nối con trỏ `prev` của nó về nút tiền nhiệm (ngược lại cập nhật lại `tail`).\n- Đổi lại, Doubly Linked List tốn thêm bộ nhớ cho tham chiếu `prev` trên mỗi nút và đòi hỏi cập nhật đồng bộ cả hai chiều liên kết khi chèn hoặc xóa.", "[\"Mô tả cấu trúc nút Doubly Linked List (3.0đ): Nêu đủ 3 thành phần: data, prev pointer, next pointer.\", \"Phân tích thao tác xóa nút đã biết tham chiếu (4.0đ): So sánh rõ ràng chi phí O(n) của Singly Linked List vs O(1) của Doubly Linked List kèm logic cập nhật con trỏ.\", \"Đánh giá trade-off bộ nhớ và bảo trì (3.0đ): Nêu được chi phí phụ trội bộ nhớ và sự phức tạp khi cập nhật liên kết kép.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Trong thao tác xóa một nút đích khỏi Doubly Linked List khi đã có sẵn tham chiếu tới nút đó, những trường hợp biên (Edge Cases) nào bắt buộc phải kiểm tra để tránh ném ngoại lệ NullPointerException?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000524", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", RubricCsd201Id, "Biểu diễn Cây Tổng quát (First-Child / Next-Sibling) và Cấu trúc Cây Biểu thức (Expression Tree)", "Làm thế nào để biểu diễn một Cây tổng quát (General Tree — nơi mỗi nút có thể có số lượng nút con bất kỳ) bằng cấu trúc nút chỉ gồm đúng hai con trỏ cố định First-Child và Next-Sibling mà không gây lãng phí bộ nhớ? Tiếp theo, hãy trình bày nguyên lý dùng Ngăn xếp (Stack) để dựng Cây biểu thức (Expression Tree) từ biểu thức hậu tố (Postfix) và giải thuật đệ quy định giá biểu thức trên cây đó.", "1. Biểu diễn Cây tổng quát bằng cấu trúc First-Child / Next-Sibling (Con cả - Anh em kế tiếp):\n- Thay vì cấp phát mảng cố định K con trỏ tại mỗi nút gây lãng phí nhiều ô rỗng ở các nút lá, mô hình First-Child / Next-Sibling ánh xạ tương đương mọi Cây tổng quát sang Cây nhị phân với đúng 2 tham chiếu mỗi nút: con trỏ `firstChild` trỏ tới nút con đầu tiên bên trái nhất của nút hiện tại, và con trỏ `nextSibling` trỏ tới nút anh chị em ruột kế tiếp ngay bên phải có cùng nút cha. Nhờ đó, cây n nút luôn chỉ dùng đúng 2n con trỏ bất kể bậc tối đa của cây.\n\n2. Giải thuật dựng Cây biểu thức từ chuỗi hậu tố (Postfix) bằng Stack:\n- Trên Cây biểu thức, mọi nút lá chứa toán hạng (số hoặc biến), còn mọi nút nội chứa toán tử hai ngôi. Duyệt tuần tự từng phần tử của chuỗi Postfix từ trái sang phải: nếu gặp toán hạng thì tạo nút lá đẩy vào Stack; nếu gặp toán tử thì lấy 2 nút từ đỉnh Stack ra, trong đó nút lấy ra đầu tiên gắn làm con phải (`right`), nút lấy ra thứ hai gắn làm con trái (`left`) của nút toán tử mới, rồi đẩy nút toán tử này trở lại Stack. Phần tử duy nhất còn lại cuối cùng là gốc cây.\n\n3. Giải thuật đệ quy định giá Cây biểu thức:\n- Áp dụng phép duyệt Hậu thứ tự (Post-order): điều kiện dừng xảy ra khi gặp nút lá (cả hai con trái và phải đều rỗng), trả về trực tiếp giá trị số của toán hạng. Ở bước đệ quy, gọi hàm định giá cây con trái trước, cây con phải sau, kiểm tra ca biên mẫu số bằng 0 đối với phép chia rồi kết hợp hai kết quả theo toán tử tại nút cha với độ phức tạp O(n) thời gian và O(h) không gian ngăn xếp.", "[\"Giải thích cấu trúc biểu diễn First-Child / Next-Sibling cho Cây tổng quát (3.0đ): Làm rõ ý nghĩa 2 con trỏ firstChild (con đầu tiên) và nextSibling (anh em kế tiếp cùng cha) giúp tiết kiệm bộ nhớ.\", \"Mô tả đúng thuật toán dựng Expression Tree từ Postfix bằng Stack (3.5đ): Trình bày đúng quy tắc đẩy toán hạng vào Stack và lấy 2 nút (nút đầu làm con phải, nút sau làm con trái) khi gặp toán tử.\", \"Trình bày quy trình đệ quy Hậu thứ tự định giá Cây biểu thức (3.5đ): Nêu đúng điều kiện dừng tại nút lá, thứ tự tính đệ quy hai nhánh trái - phải, xử lý chia cho 0 và độ phức tạp O(n).\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Trên một Cây biểu thức (Expression Tree), nếu ta thực hiện phép duyệt Trung thứ tự (In-order Traversal) thông thường mà không bổ sung các cặp dấu ngoặc đơn bao quanh mỗi cây con toán tử, kết quả biểu thức trung tố thu được sẽ gặp sai lệch ngữ nghĩa gì?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000525", CourseCsd201Id, "00000000-0000-0000-0000-000000000562", RubricCsd201Id, "Nguyên lý FIFO của Hàng đợi (Queue) và Hiện tượng Tràn Giả (False Overflow) trên Mảng Tuyến tính", "Giải thích nguyên lý FIFO (First-In, First-Out) và ba thao tác cơ bản enqueue, dequeue, first của Hàng đợi (Queue). Tại sao khi biểu diễn Queue trên mảng một chiều thông thường mà chỉ tăng dần hai chỉ số front và rear, ta lại gặp hiện tượng Tràn giả (False Overflow) dù trong mảng vẫn còn nhiều ô trống?", "1. Nguyên lý FIFO và các thao tác cơ bản của Queue:\n- Hàng đợi (Queue) là cấu trúc dữ liệu tuyến tính vận hành theo cơ chế Vào trước - Ra trước (FIFO): phần tử được đưa vào sớm nhất sẽ được trích xuất xử lý đầu tiên, tương tự hàng đợi in ấn hoặc điều phối tác vụ.\n- Ba thao tác chuẩn đều đạt thời gian hằng số O(1): `enqueue` chèn phần tử mới vào cuối hàng đợi tại chỉ số `rear`; `dequeue` lấy ra và loại bỏ phần tử ở đầu hàng đợi tại chỉ số `front` (trả về rỗng hoặc báo lỗi nếu hàng đợi rỗng); `first` (hoặc `peek`) đọc giá trị phần tử đầu `front` mà không xóa.\n\n2. Nguyên nhân gây hiện tượng Tràn giả (False Overflow) trên mảng tuyến tính:\n- Giả sử mảng tĩnh có kích thước N với `front = 0` và `rear = -1`. Mỗi lần `enqueue` làm tăng `rear` thêm 1, còn mỗi lần `dequeue` làm tăng `front` thêm 1 để giữ chi phí O(1) mà không dịch mảng.\n- Sau nhiều thao tác thêm và xóa đan xen (ví dụ chèn N phần tử rồi xóa N - 1 phần tử đầu), cả vùng dữ liệu bị trôi dần về cuối mảng khiến `front = N - 1` và `rear = N - 1`.\n- Lúc này khi gọi tiếp `enqueue`, chỉ số `rear` đã chạm biên vật lý cuối mảng nên hệ thống báo tràn hàng đợi, mặc dù thực tế chỉ còn đúng 1 phần tử và toàn bộ N - 1 ô từ chỉ số `0` đến `front - 1` đang hoàn toàn bỏ trống. Hiện tượng này gọi là Tràn giả, đòi hỏi dùng mảng vòng với phép chia lấy dư modulo N để tái sử dụng vùng trống đầu mảng.", "[\"Giải thích nguyên lý FIFO và 3 thao tác cơ bản của Queue (3.5đ): Trình bày rõ cơ chế Vào trước - Ra trước và vai trò của enqueue (vào rear), dequeue/first (tại front).\", \"Phân tích cơ chế dịch chuyển chỉ số front và rear trên mảng tuyến tính (3.5đ): Mô tả rõ việc tăng front++ khi dequeue và tăng rear++ khi enqueue dẫn tới vùng dữ liệu trôi dần về cuối mảng.\", \"Làm rõ bản chất hiện tượng Tràn giả (False Overflow) (3.0đ): Giải thích chính xác tình huống rear chạm N-1 báo đầy giả tạo trong khi các ô từ 0 đến front-1 vẫn đang bỏ trống.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Nếu ta khắc phục hiện tượng Tràn giả bằng cách dịch chuyển toàn bộ các phần tử còn lại về đầu mảng mỗi khi lấy phần tử ra ở đầu hàng đợi, độ phức tạp thời gian của thao tác dequeue sẽ bị suy thoái từ O(1) xuống mức nào và vì sao?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000526", CourseCsd201Id, "00000000-0000-0000-0000-000000000563", RubricCsd201Id, "Điều kiện Dừng (Base Case) và Bước Đệ quy trong Cấu trúc Hàm Đệ quy", "Một hàm đệ quy chuẩn mực bắt buộc phải bao gồm những thành phần cơ bản nào? Điều gì sẽ xảy ra nếu lập trình viên quên định nghĩa điều kiện dừng (Base Case) hoặc thiết kế điều kiện dừng không bao giờ đạt được?", "Một hàm đệ quy chuẩn mực bắt buộc phải bao gồm 2 thành phần cốt lõi:\n1. Điều kiện dừng (Base Case): Tình huống đơn giản nhất của bài toán mà kết quả có thể xác định ngay lập tức mà không cần gọi thêm bất kỳ lời gọi đệ quy nào. Base case đóng vai trò neo chặn, ngăn chặn đệ quy vô hạn.\n2. Bước đệ quy (Recursive Step): Lời gọi hàm chính nó với kích thước dữ liệu đầu vào nhỏ hơn hoặc gần với Base Case hơn, phân rã bài toán lớn thành bài toán con tương tự.\n\nHậu quả khi thiếu hoặc sai Base Case:\n- Hàm sẽ liên tục tự gọi chính nó mà không có điểm dừng (infinite recursion).\n- Mỗi lời gọi hàm mới sẽ đẩy một khung ngăn xếp (stack frame) chứa địa chỉ hoàn trả và biến cục bộ vào vùng nhớ Call Stack của hệ điều hành/JVM.\n- Do bộ nhớ Call Stack có giới hạn cố định, việc tích tụ không ngừng này sẽ nhanh chóng dẫn đến hiện tượng tràn bộ nhớ ngăn xếp, gây ném ngoại lệ nghiêm trọng `java.lang.StackOverflowError` và làm sập ứng dụng.", "[\"Đặc tả 2 thành phần đệ quy (4.0đ): Giải thích chính xác vai trò của Base Case và Recursive Step.\", \"Cơ chế phân rã dữ liệu (2.5đ): Nêu rõ dữ liệu đầu vào phải thu hẹp dần về phía Base Case.\", \"Phân tích lỗi StackOverflowError (3.5đ): Mô tả cơ chế tích lũy stack frame trên Call Stack dẫn tới tràn bộ nhớ.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Tại sao việc hàm đệ quy đã có điều kiện dừng (Base Case) vẫn có thể gây ra lỗi nghiêm trọng StackOverflowError nếu bước đệ quy không đảm bảo quy mô dữ liệu n giảm dần hội tụ về Base Case?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000527", CourseCsd201Id, "00000000-0000-0000-0000-000000000562", RubricCsd201Id, "Nguyên lý LIFO và Ba Thao tác Cơ bản của Ngăn xếp Stack", "Ngăn xếp (Stack) hoạt động theo nguyên lý nào? Hãy nêu tên, ý nghĩa và độ phức tạp thời gian của 3 thao tác chính trên Stack. Nêu 2 ứng dụng thực tế của Stack trong khoa học máy tính.", "Stack hoạt động theo nguyên lý LIFO (Last-In-First-Out) - phần tử nào được thêm vào sau cùng sẽ được lấy ra đầu tiên. Mọi thao tác thêm và xóa đều diễn ra tại một đầu duy nhất gọi là đỉnh ngăn xếp (top).\n\nBa thao tác cơ bản trên Stack:\n1. `push(x)`: Thêm phần tử x vào đỉnh ngăn xếp. Độ phức tạp: O(1).\n2. `pop()`: Xóa và trả về phần tử nằm ở đỉnh ngăn xếp. Ném ngoại lệ hoặc trả về rỗng nếu Stack rỗng. Độ phức tạp: O(1).\n3. `peek()` (hoặc `top()`): Trả về giá trị của phần tử ở đỉnh ngăn xếp mà không xóa nó. Độ phức tạp: O(1).\n\nHai ứng dụng thực tế kinh điển trong khoa học máy tính:\n1. Quản lý ngăn xếp lời gọi hàm (Call Stack): Lưu trữ địa chỉ hoàn trả và các biến cục bộ khi thực thi chương trình hoặc gọi hàm đệ quy.\n2. Kiểm tra tính hợp lệ của dấu ngoặc trong trình biên dịch và chức năng Undo/Redo trong các phần mềm soạn thảo văn bản.", "[\"Giải thích nguyên lý LIFO (2.5đ): Trình bày chính xác cơ chế Last-In-First-Out và khái niệm đỉnh Top.\", \"Đặc tả 3 thao tác cơ bản và Big-O (4.5đ): Mô tả đầy đủ push, pop, peek kèm độ phức tạp O(1) cho mỗi thao tác.\", \"Ứng dụng thực tế (3.0đ): Nêu đúng ít nhất 2 ứng dụng tiêu biểu (Call Stack, Undo/Redo, biên dịch biểu thức).\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Khi biểu diễn Stack bằng mảng động tự co giãn kích thước, thao tác đẩy phần tử mới khi mảng bị đầy có chi phí xấu nhất là O(n); tại sao trong phân tích thuật toán người ta vẫn kết luận độ phức tạp trung bình khấu hao của thao tác push là Amortized O(1)?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000528", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", RubricCsd201Id, "Đặc tính Thứ tự của Cây Tìm kiếm Nhị phân (BST) và Phép duyệt In-Order", "Hãy nêu đặc tính cốt lõi (BST Property) của một Cây tìm kiếm nhị phân (Binary Search Tree). Khi thực hiện phép duyệt trung thứ tự (In-Order Traversal) trên một cây BST, kết quả dãy khóa thu được có đặc điểm gì đặc biệt?", "1. Đặc tính cốt lõi của Cây tìm kiếm nhị phân (BST Property):\nVới mọi nút x bất kỳ trong cây BST:\n- Mọi nút y thuộc cây con bên trái (Left Subtree) của x đều có khóa nhỏ hơn khóa của x: `key(y) < key(x)`.\n- Mọi nút z thuộc cây con bên phải (Right Subtree) của x đều có khóa lớn hơn khóa của x: `key(z) > key(x)`.\n(Nếu cho phép khóa trùng nhau, quy ước khóa trùng nằm bên trái hoặc bên phải nhất quán).\n\n2. Đặc điểm của phép duyệt trung thứ tự (In-Order Traversal):\nPhép duyệt In-Order tuân theo quy tắc đệ quy: Duyệt cây con Trái -> Thăm nút Gốc -> Duyệt cây con Phải (L-N-R).\nĐặc điểm đặc biệt: Khi áp dụng trên BST, phép duyệt In-Order luôn sinh ra một dãy khóa được sắp xếp theo thứ tự tăng dần nghiêm ngặt (Monotonically Increasing Sequence).\nLý do: Theo đặc tính BST, mọi phần tử ở cây con trái (nhỏ hơn gốc) được in ra trước, sau đó đến gốc, rồi mới đến toàn bộ phần tử ở cây con phải (lớn hơn gốc).", "[\"Đặc tả tính chất BST (4.0đ): Nêu rõ ràng điều kiện so sánh khóa giữa cây con trái, nút gốc và cây con phải.\", \"Mô tả quy trình duyệt In-Order (3.0đ): Trình bày đúng thứ tự duyệt L-N-R (Left -> Node -> Right).\", \"Chứng minh dãy tăng dần (3.0đ): Chỉ ra dãy khóa thu được luôn tăng dần và giải thích nguyên nhân logic.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Nếu ta biết kết quả thứ tự duyệt In-order và Pre-order của một Cây tìm kiếm nhị phân có các khóa phân biệt, ta có thể khôi phục lại cấu trúc hình học duy nhất của cây ban đầu không? Tại sao?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000529", CourseCsd201Id, "00000000-0000-0000-0000-000000000565", RubricCsd201Id, "So sánh Biểu diễn Đồ thị bằng Ma trận Kề và Danh sách Kề", "Hãy so sánh hai phương pháp biểu diễn đồ thị: Ma trận kề (Adjacency Matrix) và Danh sách kề (Adjacency List) về không gian bộ nhớ sử dụng và chi phí kiểm tra sự tồn tại của một cạnh nối giữa hai đỉnh u và v. Khi nào nên dùng cấu trúc nào?", "1. So sánh về không gian bộ nhớ (Space Complexity):\n- Ma trận kề (Adjacency Matrix): Sử dụng mảng 2 chiều kích thước V x V. Không gian bộ nhớ luôn là O(V^2), bất kể số lượng cạnh E.\n- Danh sách kề (Adjacency List): Sử dụng một mảng gồm V danh sách liên kết (hoặc ArrayList). Không gian bộ nhớ là O(V + E) cho đồ thị có hướng và O(V + 2E) cho đồ thị vô hướng.\n\n2. Chi phí kiểm tra sự tồn tại của cạnh (u, v):\n- Ma trận kề: O(1) bằng cách truy xuất trực tiếp ô `matrix[u][v]`.\n- Danh sách kề: O(deg(u)) vì phải duyệt tuần tự qua danh sách các đỉnh kề của đỉnh u (trong trường hợp xấu nhất là O(V)).\n\n3. Tiêu chí lựa chọn ứng dụng thực tế:\n- Dùng Ma trận kề khi: Đồ thị dày (Dense Graph, E xấp xỉ V^2), hoặc khi kích thước số đỉnh V nhỏ và cần kiểm tra cạnh nhanh O(1).\n- Dùng Danh sách kề khi: Đồ thị thưa (Sparse Graph, E << V^2, đa số đồ thị thực tế như mạng xã hội, bản đồ giao thông) để tiết kiệm tối đa bộ nhớ và duyệt nhanh các đỉnh kề trong O(deg(u)).", "[\"So sánh không gian bộ nhớ (3.5đ): Nêu chính xác O(V^2) của Ma trận kề vs O(V + E) của Danh sách kề.\", \"So sánh kiểm tra cạnh (u, v) (3.5đ): Chỉ rõ O(1) của Ma trận kề so với O(deg(u)) của Danh sách kề.\", \"Phân loại Dense vs Sparse Graph (3.0đ): Đưa ra tiêu chí lựa chọn chính xác dựa trên mật độ cạnh của đồ thị.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Với đồ thị có V = 1,000,000 đỉnh và E = 2,000,000 cạnh, nếu chọn biểu diễn bằng Ma trận kề kiểu boolean trong Java thì hệ thống sẽ tiêu tốn bao nhiêu RAM và có nguy cơ ném ngoại lệ OutOfMemoryError không?"),
            CreatePracticeSeed("00000000-0000-0000-0000-00000000052a", CourseCsd201Id, "00000000-0000-0000-0000-000000000566", RubricCsd201Id, "Nguyên lý Đổi chỗ và Độ phức tạp Thời gian của Thuật toán Bubble Sort", "Trình bày nguyên lý vận hành của thuật toán Sắp xếp nổi bọt (Bubble Sort). Phân tích độ phức tạp thời gian trong trường hợp tốt nhất (Best-case) và trường hợp xấu nhất (Worst-case). Thuật toán này có tính ổn định (Stable) không, vì sao?", "1. Nguyên lý vận hành của Bubble Sort:\nThuật toán duyệt qua mảng nhiều lượt. Ở mỗi lượt, thuật toán so sánh từng cặp phần tử liền kề `a[j]` và `a[j+1]`. Nếu chúng đứng sai thứ tự (ví dụ `a[j] > a[j+1]`), thuật toán sẽ đổi chỗ (swap) chúng. Sau mỗi lượt lặp, phần tử lớn nhất trong đoạn chưa sắp xếp sẽ 'nổi bọt' về đúng vị trí cuối cùng của mảng.\n\n2. Phân tích độ phức tạp thời gian:\n- Trường hợp xấu nhất (Worst-case): Khi mảng bị sắp xếp ngược thứ tự hoàn toàn. Số phép so sánh và đổi chỗ là n(n-1)/2, dẫn tới độ phức tạp O(n^2).\n- Trường hợp tốt nhất (Best-case): Khi mảng đã có thứ tự sẵn. Nếu thuật toán có cờ hiệu `swapped` để dừng sớm khi không còn phép hoán vị nào trong một lượt, độ phức tạp đạt O(n). Nếu không có cờ hiệu tối ưu, độ phức tạp vẫn là O(n^2).\n\n3. Tính ổn định (Stability):\nBubble Sort là một thuật toán sắp xếp ổn định (Stable). Khi gặp hai phần tử có giá trị bằng nhau (`a[j] == a[j+1]`), điều kiện đổi chỗ không được kích hoạt (`>` chứ không phải `>=`), do đó thứ tự tương đối ban đầu giữa các phần tử bằng nhau được bảo toàn nguyên vẹn.", "[\"Trình bày cơ chế nổi bọt (3.5đ): Mô tả chính xác thao tác so sánh cặp phần tử liền kề và đưa phần tử lớn nhất về cuối.\", \"Phân tích Big-O Best/Worst case (3.5đ): Phân tích O(n^2) trường hợp ngược và O(n) trường hợp tốt nhất kèm cờ hiệu swapped.\", \"Đánh giá tính ổn định (3.0đ): Khẳng định thuật toán Stable và giải thích rõ tại sao không đổi chỗ khi hai khóa bằng nhau.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Làm thế nào để tối ưu hóa thuật toán Bubble Sort bằng cách sử dụng một cờ hiệu (boolean swapped) để thuật toán nhận diện được mảng đã sắp xếp sẵn và kết thúc sớm ngay ở lượt lặp đầu tiên với thời gian O(n)?"),
            CreatePracticeSeed("00000000-0000-0000-0000-00000000052b", CourseCsd201Id, "00000000-0000-0000-0000-000000000567", RubricCsd201Id, "Khái niệm Bảng băm, Hàm băm và Nguyên nhân Gây ra Hiện tượng Xung đột", "Bảng băm (Hash Table) và Hàm băm (Hash Function) là gì? Hiện tượng xung đột (Collision) trong bảng băm xảy ra khi nào và tại sao hiện tượng này về mặt toán học là không thể tránh khỏi?", "1. Bảng băm và Hàm băm:\n- Bảng băm (Hash Table): Cấu trúc dữ liệu liên kết (associative array) lưu trữ các cặp khóa - giá trị (Key - Value), cho phép các thao tác tìm kiếm, chèn, xóa đạt thời gian trung bình O(1).\n- Hàm băm (Hash Function): Hàm toán học `h(k)` chuyển đổi một khóa k bất kỳ (chuỗi, đối tượng, số lớn) thành một số nguyên nằm trong phạm vi chỉ số của mảng băm `[0 .. M-1]`.\n\n2. Hiện tượng xung đột (Collision):\n- Xung đột xảy ra khi hai khóa khác nhau k1 != k2 được hàm băm ánh xạ tới cùng một vị trí chỉ số trong bảng băm: `h(k1) == h(k2)`.\n\n3. Lý do toán học không thể tránh khỏi xung đột:\n- Dựa trên Nguyên lý lồng chim bồ câu (Pigeonhole Principle): Không gian của tập các khóa có thể có (Domain of Keys) là vô hạn hoặc rất lớn (ví dụ chuỗi ký tự bất kỳ), trong khi kích thước bảng băm M là hữu hạn và thường nhỏ hơn rất nhiều.\n- Khi số lượng khóa cần lưu trữ n > M, chắc chắn phải có ít nhất 2 khóa rơi vào cùng một ô lưu trữ. Do đó, mọi bảng băm thực tế đều bắt buộc phải trang bị chiến lược xử lý xung đột (Separate Chaining hoặc Open Addressing).", "[\"Định nghĩa bảng băm và hàm băm (3.0đ): Nêu đúng khái niệm Key-Value, vai trò hàm băm và thời gian trung bình O(1).\", \"Đặc tả hiện tượng xung đột (3.0đ): Giải thích chính xác biểu thức h(k1) == h(k2) với k1 != k2.\", \"Giải thích bằng Pigeonhole Principle (4.0đ): Chứng minh bằng toán học lý do không gian khóa lớn hơn kích thước bảng băm dẫn tới xung đột tất yếu.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Nguyên lý toán học Dirichlet (Pigeonhole Principle - Nguyên lý chuồng bồ câu) giải thích như thế nào về tính tất yếu không thể tránh khỏi của hiện tượng xung đột (Collision) khi không gian khóa lớn hơn kích thước bảng băm?"),
            CreatePracticeSeed("00000000-0000-0000-0000-00000000052c", CourseCsd201Id, "00000000-0000-0000-0000-000000000568", RubricCsd201Id, "Phân biệt Nén Dữ liệu Không Tổn hao và Nén Có Tổn hao", "Hãy phân biệt Nén không tổn hao (Lossless Compression) và Nén có tổn hao (Lossy Compression) về khả năng phục hồi dữ liệu gốc. Với các tệp mã nguồn phần mềm (.java, .cs) và tệp văn bản tài liệu, ta bắt buộc phải sử dụng phương pháp nào, vì sao?", "1. Phân biệt hai phương pháp nén dữ liệu:\n- Nén không tổn hao (Lossless Compression):\n+ Nguyên lý: Loại bỏ các mẫu dư thừa trong dữ liệu (redundancy) dựa trên thống kê hoặc từ điển.\n+ Phục hồi: Quá trình giải nén cam kết phục hồi lại chính xác 100% từng bit dữ liệu gốc mà không có bất kỳ sai lệch nào.\n+ Các thuật toán tiêu biểu: Huffman Coding, LZW, Run-Length Encoding, Deflate (trong tệp .zip, .png).\n- Nén có tổn hao (Lossy Compression):\n+ Nguyên lý: Chấp nhận loại bỏ một phần thông tin mà giác quan con người khó nhận biết (âm thanh tần số cao, chi tiết màu tinh vi).\n+ Phục hồi: Dữ liệu sau giải nén chỉ là xấp xỉ dữ liệu gốc, không thể khôi phục lại dữ liệu nguyên bản hoàn hảo. Đổi lại, tỷ lệ nén cao hơn rất nhiều.\n+ Các định dạng tiêu biểu: JPEG (ảnh), MP3 (âm thanh), MP4 (video).\n\n2. Yêu cầu với tệp mã nguồn phần mềm (.java, .cs) và tài liệu văn bản:\n- Bắt buộc 100% phải sử dụng Nén không tổn hao (Lossless).\n- Lý do: Trong mã nguồn chương trình và văn bản, mỗi ký tự, dấu chấm, dấu phẩy hay từ khóa đều mang ngữ nghĩa cú pháp tuyệt đối. Chỉ cần sai lệch hoặc mất đi một ký tự duy nhất (ví dụ mất dấu chấm phẩy hoặc đổi tên biến), chương trình sẽ bị lỗi biên dịch (Compilation Error) hoặc chạy sai logic nghiệp vụ.", "[\"Phân biệt Lossless vs Lossy (4.0đ): Nêu rõ nguyên lý và khả năng khôi phục nguyên vẹn 100% của Lossless so với xấp xỉ của Lossy.\", \"Thuật toán và định dạng ví dụ (2.5đ): Liệt kê chính xác ví dụ minh họa cho từng trường phái (ZIP/PNG vs JPEG/MP3).\", \"Lập luận cho tệp mã nguồn (3.5đ): Chứng minh tính bắt buộc của Lossless trong mã nguồn do yêu cầu bảo toàn cú pháp tuyệt đối.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Theo Định lý Shannon về Mã hóa nguồn (Shannon's Source Coding Theorem), giới hạn lý thuyết entropy nào chi phối việc ta không thể nén một tệp dữ liệu không tổn hao xuống kích thước nhỏ tùy ý?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000113", CourseCsd201Id, "00000000-0000-0000-0000-000000000561", RubricCsd201Id, "Giải thuật Đảo ngược Danh sách Liên kết Đơn tại Chỗ với Ba Con trỏ", "Hãy trình bày giải thuật đảo ngược một Danh sách liên kết đơn tại chỗ (in-place) bằng ba con trỏ mà không cấp phát thêm danh sách mới. Nêu rõ vai trò, giá trị khởi tạo và thứ tự cập nhật của ba con trỏ trong mỗi bước lặp, cách xử lý danh sách rỗng hoặc một phần tử, cùng độ phức tạp thời gian và không gian.", "1. Vai trò và giá trị khởi tạo của ba con trỏ:\n- Con trỏ `prev` theo dõi nút đứng liền trước đã được đảo chiều xong (khởi tạo bằng `null` vì nút đầu cũ sau khi đảo sẽ trở thành nút đuôi mới trỏ vào `null`).\n- Con trỏ `curr` trỏ vào nút hiện tại đang xét (khởi tạo bằng `head`).\n- Con trỏ tạm `nextTemp` dùng để giữ lại địa chỉ nút kế tiếp bên phải trước khi ngắt liên kết xuôi.\n\n2. Thứ tự 4 bước cập nhật bất biến trong vòng lặp khi `curr` khác `null`:\n- Bước 1: Lưu giữ liên kết kế tiếp vào `nextTemp` bằng tham chiếu `next` của `curr` để không làm đứt gãy phần đuôi danh sách.\n- Bước 2: Đảo ngược chiều liên kết bằng cách trỏ trường `next` của `curr` ngược về `prev`.\n- Bước 3: Dịch chuyển con trỏ `prev` tiến lên vị trí của `curr`.\n- Bước 4: Dịch chuyển con trỏ `curr` tiến lên vị trí `nextTemp` đã lưu.\n- Khi `curr` chạm `null`, vòng lặp kết thúc và `prev` chính là nút đầu mới của danh sách đã đảo ngược.\n\n3. Xử lý ca biên và độ phức tạp:\n- Nếu danh sách rỗng (`head == null`), vòng lặp không chạy và trả về `prev` bằng `null`. Nếu danh sách chỉ có 1 phần tử, sau đúng 1 lượt lặp `prev` trỏ vào phần tử đó và trường `next` vẫn là `null`.\n- Độ phức tạp thời gian đạt O(n) do duyệt qua mỗi nút đúng một lần; độ phức tạp không gian phụ đạt O(1) tuyệt đối vì chỉ dùng ba biến tham chiếu cục bộ tại chỗ.", "[\"Vai trò và khởi tạo ba con trỏ prev, curr, nextTemp (3.5đ): Mô tả chuẩn xác chức năng và giá trị khởi tạo của từng con trỏ trước khi bước vào vòng lặp.\", \"Thứ tự 4 bước cập nhật liên kết và xử lý ca biên (3.5đ): Trình bày đúng trình tự lưu nút kế, bẻ ngược con trỏ, dịch chuyển prev/curr, trả về prev và kiểm chứng danh sách rỗng hoặc 1 nút.\", \"Phân tích độ phức tạp thời gian và không gian (3.0đ): Chỉ rõ thời gian tuyến tính O(n) và không gian bộ nhớ phụ hằng số O(1) tại chỗ.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Trong mỗi vòng lặp đảo ngược Danh sách liên kết đơn bằng ba con trỏ, nếu ta quên lưu giữ tham chiếu tới nút kế tiếp trước khi bẻ ngược liên kết của nút hiện tại về nút phía trước, điều gì sẽ xảy ra với phần còn lại của danh sách?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000114", CourseCsd201Id, "00000000-0000-0000-0000-000000000562", RubricCsd201Id, "Ứng dụng Stack trong Bài toán Kiểm tra Dãy Ngoặc Hợp lệ", "Hãy trình bày giải thuật sử dụng Ngăn xếp (Stack) để kiểm tra một chuỗi gồm ba loại dấu ngoặc tròn, ngoặc vuông và ngoặc nhọn có phải là dãy ngoặc hợp lệ hay không. Phân tích điều kiện kết luận cuối cùng, các trường hợp biên điển hình và độ phức tạp thời gian, không gian.", "1. Nguyên lý giải thuật sử dụng cấu trúc LIFO của Stack:\n- Vì dấu ngoặc mở ra sau cùng bắt buộc phải được đóng lại đầu tiên, Ngăn xếp (Stack) là cấu trúc tự nhiên nhất để đối chiếu các cặp ngoặc lồng nhau.\n- Trước khi duyệt, có thể tối ưu dừng sớm: nếu chuỗi có độ dài lẻ thì lập tức kết luận không hợp lệ vì các dấu ngoặc luôn đi theo cặp chẵn.\n- Duyệt tuần tự từng ký tự của chuỗi từ trái sang phải:\n+ Nếu gặp dấu ngoặc mở (tròn, vuông hoặc nhọn), đẩy ký tự đó vào đỉnh Stack để chờ đóng.\n+ Nếu gặp dấu ngoặc đóng: trước hết kiểm tra Stack có rỗng hay không; nếu Stack đang rỗng nghĩa là dấu đóng xuất hiện dư thừa không có ngoặc mở tương ứng nên trả về sai ngay. Ngược lại, lấy phần tử ở đỉnh Stack ra (`pop`) và đối chiếu cặp loại ngoặc; nếu không khớp đúng chủng loại (ví dụ ngoặc mở vuông đi với ngoặc đóng tròn) thì trả về sai ngay lập tức.\n\n2. Điều kiện kết thúc, các trường hợp biên và độ phức tạp:\n- Sau khi duyệt hết chuỗi, bắt buộc kiểm tra Stack phải hoàn toàn rỗng thì mới kết luận hợp lệ (`true`); nếu Stack còn phần tử nghĩa là còn ngoặc mở chưa được đóng (`false`).\n- Các ca biên quan trọng: chuỗi rỗng là hợp lệ; chuỗi bắt đầu bằng ngoặc đóng bị chặn ngay khi kiểm tra Stack rỗng; chuỗi toàn ngoặc mở bị phát hiện ở bước kiểm tra rỗng cuối cùng.\n- Độ phức tạp thời gian là O(n) với một lượt duyệt chuỗi, và không gian phụ xấu nhất là O(n) khi cả chuỗi gồm toàn dấu ngoặc mở.", "[\"Nguyên lý đẩy ngoặc mở và đối chiếu ngoặc đóng trên Stack (3.5đ): Trình bày rõ quy tắc push khi gặp ngoặc mở, pop và so khớp đúng loại ngoặc khi gặp ngoặc đóng theo cơ chế LIFO.\", \"Điều kiện kết thúc và độ phức tạp thuật toán (3.5đ): Khẳng định điều kiện Stack bắt buộc rỗng sau khi duyệt xong chuỗi, nêu đúng O(n) thời gian và O(n) bộ nhớ phụ xấu nhất.\", \"Phân tích đầy đủ các trường hợp biên (3.0đ): Nêu đủ cách xử lý chuỗi rỗng, chuỗi độ dài lẻ, bắt đầu bằng ngoặc đóng và dư ngoặc mở cuối chuỗi.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Thuật toán kiểm tra dãy ngoặc hợp lệ bằng Stack sẽ xử lý như thế nào khi chuỗi đầu vào chỉ chứa toàn dấu đóng ngoặc hoặc khi đã duyệt hết toàn bộ chuỗi mà trong Stack vẫn còn phần tử?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000115", CourseCsd201Id, "00000000-0000-0000-0000-000000000562", RubricCsd201Id, "Cơ chế Hàng đợi Vòng (Circular Queue) trên Mảng Cố định với Toán tử Modulo", "Để khắc phục hiện tượng tràn giả trên mảng tuyến tính, cơ chế Hàng đợi vòng (Circular Queue) sử dụng toán tử chia lấy dư (Modulo) để điều hướng hai chỉ số đầu và cuối như thế nào? Hãy mô tả quy trình thêm phần tử (enqueue), lấy phần tử (dequeue), cách quản lý biến đếm kích thước để kiểm soát trạng thái biên và độ phức tạp đạt được.", "1. Bản chất xoay vòng chỉ số bằng toán tử Modulo:\n- Thay vì xem mảng cố định kích thước K như một đoạn thẳng kết thúc tại chỉ số `K - 1`, Hàng đợi vòng nối khép kín ô cuối mảng `K - 1` quay trở về ô đầu mảng `0`.\n- Mọi bước tịnh tiến chỉ số đều áp dụng phép chia lấy dư: chỉ số mới bằng `(chỉ số hiện tại + 1) mod K`. Khi con trỏ đang đứng ở `K - 1`, cộng thêm 1 rồi chia lấy dư cho K sẽ tự động cuộn chỉ số về `0` để tái sử dụng các ô nhớ đã được giải phóng ở đầu mảng.\n\n2. Quy trình vận hành với ba biến trạng thái `front`, `rear` và `size`:\n- Khởi tạo mảng dung lượng K với `front = 0`, `rear = -1` (hoặc `0`) và `size = 0`.\n- Thao tác `enqueue`: Kiểm tra nếu `size == K` thì báo hàng đợi đầy và từ chối chèn. Ngược lại, cập nhật `rear = (rear + 1) mod K`, ghi phần tử mới vào ô `rear` và tăng `size` thêm 1.\n- Thao tác `dequeue`: Kiểm tra nếu `size == 0` thì báo hàng đợi rỗng. Ngược lại, trích xuất giá trị tại ô `front`, cập nhật `front = (front + 1) mod K` và giảm `size` đi 1.\n\n3. Xử lý trường hợp biên và đánh giá hiệu năng:\n- Nhờ biến đếm `size` tách biệt rõ trạng thái rỗng (`size == 0`) và đầy (`size == K`), hàng đợi tận dụng tối đa 100% K ô nhớ của mảng mà không phải hy sinh một ô trống làm vách ngăn. Cả `enqueue`, `dequeue` và `peek` đều chạy trong thời gian O(1) tuyệt đối và không gian phụ O(1).", "[\"Nguyên lý cuộn vòng mảng bằng toán tử Modulo (3.0đ): Giải thích rõ cách công thức (index + 1) mod K đưa chỉ số từ vị trí cuối K - 1 quay về 0 để triệt tiêu tràn giả.\", \"Quy trình cập nhật chỉ số trong enqueue và dequeue (4.0đ): Trình bày chính xác thứ tự kiểm tra biên, cập nhật rear/front theo modulo và tăng giảm biến đếm size.\", \"Kiểm soát trạng thái đầy/rỗng và độ phức tạp O(1) (3.0đ): Làm rõ vai trò biến size tận dụng 100% dung lượng mảng và khẳng định mọi thao tác đạt thời gian hằng số O(1).\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Nếu không duy trì biến đếm số phần tử hiện tại, làm thế nào để phân biệt trạng thái Hàng đợi rỗng và Hàng đợi đầy trong Hàng đợi vòng khi cả hai trạng thái đều có thể dẫn tới sự trùng nhau giữa hai chỉ số đầu và cuối?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000116", CourseCsd201Id, "00000000-0000-0000-0000-000000000563", RubricCsd201Id, "Phân loại Đệ quy Tuyến tính, Đệ quy Nhị phân và Giải thuật Tính Lũy thừa Nhanh Chia để Trị", "Hãy phân biệt Đệ quy tuyến tính (Linear Recursion) và Đệ quy nhị phân (Binary Recursion) dựa trên số lượng lời gọi đệ quy trong mỗi khung kích hoạt. Tiếp theo, trình bày giải thuật chia để trị tính lũy thừa nhanh x mũ n trong thời gian O(log n), và giải thích tại sao nếu gọi lặp lại hai lần lời gọi đệ quy cho nửa số mũ thay vì lưu kết quả trung gian vào biến tạm thì độ phức tạp sẽ bị suy thoái nghiêm trọng?", "1. Phân biệt Đệ quy tuyến tính và Đệ quy nhị phân:\n- Đệ quy tuyến tính (Linear Recursion): Mỗi khung kích hoạt (ngoài điều kiện dừng) chỉ phát sinh tối đa đúng 1 lời gọi đệ quy, tạo thành chuỗi gọi hàm thẳng tắp trên Call Stack (ví dụ tính giai thừa hoặc tổng mảng tuần tự).\n- Đệ quy nhị phân (Binary Recursion): Mỗi khung kích hoạt phát sinh 2 lời gọi đệ quy độc lập để giải hai bài toán con, tạo thành cây kích hoạt phân nhánh đôi (ví dụ duyệt cây nhị phân hoặc MergeSort).\n\n2. Giải thuật tính lũy thừa nhanh (Fast Exponentiation) đạt O(log n):\n- Điều kiện dừng: khi số mũ bằng 0 thì kết quả bằng 1. Nếu số mũ âm, nghịch đảo cơ số thành `1 / x` và chuyển số mũ sang kiểu nguyên 64-bit trước khi đổi dấu dương để tránh tràn số tại biên âm cực tiểu.\n- Bước chia để trị: thực hiện duy nhất 1 lời gọi đệ quy tính giá trị lũy thừa với số mũ `n / 2` và lưu vào biến tạm `half`. Nếu `n` chẵn thì trả về `half * half`; nếu `n` lẻ thì trả về `x * half * half`. Vì số mũ giảm một nửa sau mỗi bước nên cả thời gian thực thi và chiều sâu ngăn xếp đều đạt O(log n).\n\n3. Nguyên nhân suy thoái khi gọi lặp hai lần lời gọi đệ quy:\n- Nếu không lưu biến tạm `half` mà gọi trực tiếp hai lần hàm đệ quy cho `n / 2` rồi nhân với nhau, thuật toán biến tướng từ Đệ quy tuyến tính sang Đệ quy nhị phân với phương trình truy hồi `T(n) = 2 * T(n / 2) + O(1)`. Cây đệ quy phình ra thành xấp xỉ n nút, làm thời gian chạy suy thoái từ O(log n) về lại O(n) không khác gì nhân tuần tự.", "[\"Phân biệt rõ Đệ quy tuyến tính và Đệ quy nhị phân (3.0đ): Nêu đúng số lượng lời gọi đệ quy trong mỗi khung kích hoạt (1 lời gọi so với 2 lời gọi) kèm ví dụ minh họa.\", \"Trình bày giải thuật lũy thừa nhanh chia đôi số mũ đạt O(log n) (4.0đ): Mô tả rõ điều kiện dừng mũ 0, xử lý số mũ âm an toàn, lưu biến tạm half và tách hai nhánh số mũ chẵn/lẻ.\", \"Chứng minh sự suy thoái từ O(log n) về O(n) khi gọi lặp 2 lần (3.0đ): Giải thích phương trình truy hồi T(n) = 2T(n/2) + O(1) làm cây đệ quy nở rộng thành O(n) lời gọi nếu không lưu biến tạm.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Nếu số mũ nguyên n truyền vào giải thuật tính lũy thừa nhanh mang giá trị âm cực tiểu của kiểu số nguyên 32-bit có dấu, thao tác đổi dấu trực tiếp từ âm sang dương sẽ gặp lỗi tràn số gì và cần xử lý ra sao?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000117", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", RubricCsd201Id, "Nguyên lý Ba Phép Duyệt Cây Nhị phân Pre-order, In-order và Post-order", "Hãy trình bày nguyên lý đệ quy, điều kiện dừng và thứ tự thăm các thành phần của ba phép duyệt cây nhị phân theo chiều sâu: Tiền thứ tự (Pre-order), Trung thứ tự (In-order) và Hậu thứ tự (Post-order). Phân tích độ phức tạp thời gian, không gian và nêu hai bài toán thực tế bắt buộc dùng phép duyệt Post-order.", "1. Điều kiện dừng và quy tắc ba phép duyệt đệ quy theo chiều sâu:\n- Mọi phép duyệt đều dùng chung điều kiện dừng cơ sở: nếu nút hiện tại bằng `null` (nhánh cây rỗng) thì thoát khỏi khung gọi ngay lập tức mà không thao tác gì.\n- Duyệt Tiền thứ tự (Pre-order — Gốc - Trái - Phải): Xử lý dữ liệu nút hiện tại trước tiên, sau đó gọi đệ quy duyệt toàn bộ cây con trái, rồi mới duyệt cây con phải; thường dùng để nhân bản cây hoặc tuần tự hóa cấu trúc tiền tố.\n- Duyệt Trung thứ tự (In-order — Trái - Gốc - Phải): Gọi đệ quy duyệt hết cây con trái, thăm nút hiện tại ở giữa, rồi duyệt cây con phải; đặc biệt xuất dãy khóa tăng dần khi áp dụng trên cây BST.\n- Duyệt Hậu thứ tự (Post-order — Trái - Phải - Gốc): Duyệt trọn vẹn cả cây con trái lẫn cây con phải trước, chỉ xử lý nút cha hiện tại ở bước cuối cùng.\n\n2. Độ phức tạp và ứng dụng bắt buộc của Post-order:\n- Thời gian thực thi của cả ba phép duyệt đều là O(n) vì mỗi nút được thăm đúng một lần. Không gian bộ nhớ phụ trên Call Stack tỉ lệ với chiều cao cây O(h), tức O(log n) trên cây cân bằng và suy biến thành O(n) trên cây lệch thẳng.\n- Ứng dụng điển hình của Post-order: (1) Tính tổng dung lượng thư mục trên hệ thống tệp tin (phải cộng xong kích thước mọi tệp và thư mục con mới chốt được dung lượng thư mục cha); (2) Định giá Cây biểu thức số học hoặc giải phóng bộ nhớ cây từ lá ngược lên gốc để không làm mất con trỏ tới các nhánh con.", "[\"Quy tắc duyệt Pre-order, In-order và điều kiện dừng (3.5đ): Trình bày chính xác điều kiện dừng nút rỗng và thứ tự thăm Gốc - Trái - Phải (Pre-order), Trái - Gốc - Phải (In-order).\", \"Quy tắc duyệt Post-order và độ phức tạp thời gian - không gian (3.5đ): Nêu đúng thứ tự Trái - Phải - Gốc, thời gian O(n) và không gian ngăn xếp O(h) biến thiên từ O(log n) đến O(n).\", \"Ứng dụng thực tế của phép duyệt Post-order (3.0đ): Phân tích xác đáng ít nhất 2 ứng dụng phụ thuộc dữ liệu con như tính dung lượng thư mục, định giá cây biểu thức hoặc hủy cây.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Tại sao phép duyệt Hậu thứ tự (Post-order Traversal) lại là lựa chọn bắt buộc khi tính toán tổng dung lượng thư mục trên hệ thống tệp tin hoặc khi thu hồi bộ nhớ các nút của cây nhị phân trong các ngôn ngữ quản lý bộ nhớ thủ công?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000118", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", RubricCsd201Id, "Thao tác Chèn Phần tử vào Min-Heap và Quy trình Vun Đống Ngược", "Khi biểu diễn một Binary Min-Heap bằng mảng đánh chỉ số từ 0, công thức xác định chỉ số nút cha, nút con trái và nút con phải là gì? Hãy trình bày quy trình chèn một phần tử mới vào Min-Heap và cơ chế vun đống ngược lên (siftUp), nêu rõ điều kiện dừng và độ phức tạp thời gian.", "1. Công thức ánh xạ chỉ số trên mảng đánh số từ 0 (0-indexed):\n- Nhờ tính chất Cây nhị phân hoàn chỉnh, với một nút bất kỳ nằm tại chỉ số `i`:\n+ Chỉ số nút cha (khi `i > 0`): `(i - 1) / 2` (chia lấy phần nguyên).\n+ Chỉ số nút con trái: `2 * i + 1`.\n+ Chỉ số nút con phải: `2 * i + 2`.\n\n2. Quy trình chèn phần tử mới và cơ chế vun đống ngược (`siftUp` / `upHeap`):\n- Bước 1 (Bảo toàn hình học Complete Binary Tree): Đặt phần tử mới vào ngay ô trống cuối cùng của mảng tại chỉ số `size` (tương ứng vị trí lá trống ngoài cùng bên trái ở tầng đáy), rồi tăng `size` thêm 1. Nếu mảng động đã đầy, gấp đôi dung lượng mảng trước khi chèn.\n- Bước 2 (Khôi phục thứ tự Min-Heap bằng `siftUp`): Xuất phát từ chỉ số `i` vừa chèn, lặp lại việc tính chỉ số cha `parent = (i - 1) / 2` và so sánh giá trị. Nếu khóa tại `i` nhỏ hơn khóa tại `parent` (vi phạm bất biến cha nhỏ hơn hoặc bằng con), ta hoán vị hai phần tử này và cập nhật `i = parent` để tiếp tục kiểm tra lên tầng trên.\n- Điều kiện dừng và độ phức tạp: Quá trình dừng lại ngay khi `i == 0` (đã trồi lên tới gốc cây) hoặc khi giá trị nút hiện tại lớn hơn hoặc bằng nút cha. Do chiều cao cây nhị phân hoàn chỉnh là `floor(log2 n)`, thao tác chèn tốn tối đa O(log n) thời gian và O(1) bộ nhớ phụ.", "[\"Công thức ánh xạ chỉ số mảng 0-indexed (2.5đ): Nêu đúng công thức Parent: (i - 1) / 2, Left Child: 2*i + 1 và Right Child: 2*i + 2.\", \"Quy trình đặt phần tử mới bảo toàn cây hoàn chỉnh (3.5đ): Mô tả chuẩn xác thao tác thêm vào cuối mảng tại chỉ số size, xử lý mảng đầy và kích hoạt vun đống ngược.\", \"Cơ chế hoán vị Sift-Up, điều kiện dừng và Big-O (4.0đ): Giải thích rõ vòng lặp so sánh hoán vị với nút cha, hai điều kiện dừng (chạm gốc hoặc thỏa thứ tự) và độ phức tạp O(log n).\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Khi thực hiện chèn liên tiếp một dãy n phần tử có thứ tự giảm dần nghiêm ngặt vào một Min-Heap ban đầu rỗng, mỗi thao tác chèn sẽ phải đi ngược lên bao nhiêu mức và tổng chi phí thời gian khi đó là bao nhiêu?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000119", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", RubricCsd201Id, "Quy trình Xóa Nút có Hai Con trên Cây BST bằng In-order Successor", "Hãy trình bày giải thuật xóa một nút có đầy đủ hai nút con trên Cây tìm kiếm nhị phân (BST) bằng phần tử kế nhiệm trung thứ tự (In-order Successor). Phần tử kế nhiệm này được xác định ở vị trí nào, và tại sao sau khi sao chép khóa của nó lên nút cần xóa, bước xóa đệ quy tiếp theo bắt buộc phải thực hiện trên cây con bên phải và cập nhật lại con trỏ phải của nút hiện tại mà tuyệt đối không được gọi trên cây con bên trái?", "1. Tổng quan ba trường hợp và quy trình xóa nút có hai con trên BST:\n- Khi tìm thấy nút cần xóa: nếu là nút lá (0 con) thì trả về `null`; nếu chỉ có 1 con thì trả thẳng về nút con duy nhất đó để nối tắt lên nút cha.\n- Khi nút cần xóa có đủ cả con trái lẫn con phải, ta không thể xóa trực tiếp ngay vì sẽ để lại hai nhánh con mồ côi. Quy trình chuẩn gồm 3 bước:\n+ Bước 1: Tìm nút thế thân In-order Successor, tức là nút mang khóa nhỏ nhất nằm trong cây con bên phải của nút cần xóa (xuất phát từ con phải, đi rẽ trái liên tục cho tới khi gặp nút không còn con trái).\n+ Bước 2: Sao chép giá trị khóa của nút thế thân đó ghi đè lên khóa của nút hiện tại. Vì khóa này lớn hơn toàn bộ cây con trái và nhỏ hơn mọi nút còn lại của cây con phải nên bất biến thứ tự BST tại nút gốc được bảo toàn.\n+ Bước 3: Gọi đệ quy xóa khóa của nút thế thân ngay bên trong cây con bên phải và gán kết quả trả về cập nhật lại cho con trỏ con phải của nút hiện tại.\n\n2. Lý do bắt buộc xóa trên cây con phải và tính chất cơ sở của nút thế thân:\n- Nút thế thân ban đầu nằm bên nhánh phải; nếu gọi nhầm phép xóa sang nhánh trái thì sẽ không tìm thấy khóa để xóa, khiến bản sao khóa bị trùng lặp bên nhánh phải và phá hỏng tính chất BST.\n- Hơn nữa, vì In-order Successor là nút tận cùng bên trái của nhánh phải nên con trái của nó chắc chắn bằng `null`; nó chỉ có tối đa 1 con phải, giúp bước xóa đệ quy kết thúc ngay ở trường hợp cơ sở trong tổng thời gian O(h).", "[\"Mô tả chính xác quy trình tìm và thay khóa bằng In-order Successor (3.5đ): Nêu rõ cách đi sang con phải rồi rẽ trái liên tục tìm khóa nhỏ nhất nhánh phải và sao chép khóa lên nút cần xóa.\", \"Giải thích cơ chế xóa đệ quy và nối lại liên kết trên cây con phải (3.5đ): Phân tích rõ cả 3 trường hợp (0, 1, 2 con) và lý do bắt buộc xóa bản sao trên cây con phải để không làm hỏng thứ tự BST.\", \"Chứng minh In-order Successor có tối đa 1 con và độ phức tạp O(h) (3.0đ): Lập luận chặt chẽ nút trái nhất của nhánh phải không có con trái nên phép xóa quy ngay về trường hợp cơ bản.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Tại sao nút thế thân In-order Successor được đảm bảo chắc chắn không bao giờ có nút con bên trái, nhờ đó bước xóa đệ quy nút thế thân luôn quy về trường hợp cơ sở chỉ có không hoặc một nút con?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000120", CourseCsd201Id, "00000000-0000-0000-0000-000000000565", RubricCsd201Id, "Nguyên lý Giải thuật Duyệt Đồ thị Theo Chiều Rộng (BFS) với Hàng đợi", "Hãy trình bày giải thuật duyệt đồ thị theo chiều rộng (BFS) xuất phát từ một đỉnh nguồn s trên đồ thị vô hướng được biểu diễn bằng Danh sách kề. Nêu rõ vai trò của Hàng đợi FIFO và mảng đánh dấu đỉnh đã thăm, quy tắc cập nhật trong mỗi bước lặp, điều kiện dừng và phân tích độ phức tạp thời gian, không gian.", "1. Cấu trúc dữ liệu phụ trợ và quy trình giải thuật BFS:\n- Giải thuật sử dụng một Hàng đợi FIFO (`Queue`) để duy trì biên khám phá theo từng lớp khoảng cách tăng dần từ nguồn `s`, kết hợp một mảng đánh dấu `visited` kích thước V (khởi tạo toàn bộ là `false`) để ngăn duyệt lặp vô hạn khi đồ thị có chu trình.\n- Bước khởi tạo: Kiểm tra tính hợp lệ của đỉnh nguồn `s`, đánh dấu `visited[s] = true` ngay lập tức và đưa `s` vào cuối Hàng đợi.\n- Vòng lặp khám phá (lặp khi Hàng đợi chưa rỗng):\n+ Lấy đỉnh `u` ở đầu Hàng đợi ra (`poll` / `dequeue`) và thực hiện xử lý đỉnh `u`.\n+ Duyệt qua toàn bộ các đỉnh kề `v` nằm trong danh sách kề của `u`: nếu `v` chưa được thăm, bắt buộc đánh dấu `visited[v] = true` ngay tại thời điểm này rồi mới đẩy `v` vào cuối Hàng đợi.\n- Điều kiện dừng: Thuật toán kết thúc khi Hàng đợi hoàn toàn rỗng, tức đã thăm hết mọi đỉnh thuộc cùng thành phần liên thông với `s` (các đỉnh cô lập hoặc thuộc thành phần liên thông khác sẽ giữ nguyên trạng thái chưa thăm).\n\n2. Phân tích độ phức tạp thời gian và không gian:\n- Thời gian: Đạt O(V + E) trên Danh sách kề vì mỗi đỉnh chỉ được đánh dấu và đưa vào Hàng đợi tối đa 1 lần (tốn O(V)), và danh sách kề của các đỉnh được quét qua tổng cộng tối đa 2E phần tử trên đồ thị vô hướng (tốn O(E)).\n- Không gian bộ nhớ phụ: Đạt O(V) dùng cho mảng `visited` và Hàng đợi chứa tối đa V đỉnh.", "[\"Vai trò của Hàng đợi FIFO và mảng đánh dấu chống chu trình (3.0đ): Nêu rõ cơ chế duyệt theo lớp sóng của Queue FIFO và tác dụng của mảng visited ngăn lặp vô tận.\", \"Quy trình phối hợp Hàng đợi, thời điểm đánh dấu và điều kiện dừng (4.0đ): Trình bày chính xác bước khởi tạo nguồn, lấy đỉnh đầu, đánh dấu visited ngay khi đẩy đỉnh kề vào Queue và dừng khi Queue rỗng.\", \"Phân tích độ phức tạp thời gian và không gian bộ nhớ (3.0đ): Giải thích rõ thời gian tuyến tính O(V + E) trên danh sách kề và không gian phụ O(V).\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Trong giải thuật BFS, nếu ta quên đánh dấu đỉnh đã thăm ngay tại thời điểm đẩy đỉnh vào Hàng đợi mà chờ đến lúc lấy đỉnh ra khỏi Hàng đợi mới đánh dấu, hiện tượng gì sẽ xảy ra trên đồ thị có nhiều chu trình?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000121", CourseCsd201Id, "00000000-0000-0000-0000-000000000565", RubricCsd201Id, "Giải thuật Duyệt Đồ thị Theo Chiều Sâu (DFS) và Xác định Thành phần Liên thông", "Hãy trình bày giải thuật sử dụng phép Duyệt theo chiều sâu (DFS) để đếm số lượng thành phần liên thông (Connected Components) của một đồ thị vô hướng gồm V đỉnh được biểu diễn bằng Danh sách kề. Giải thích sự phối hợp giữa vòng lặp quét đỉnh bên ngoài với thủ tục DFS bên trong, cách xử lý đỉnh cô lập và phân tích độ phức tạp.", "1. Nguyên lý phối hợp quét đỉnh và lan truyền DFS:\n- Một phép gọi DFS xuất phát từ đỉnh `u` sẽ đi sâu tối đa theo các cạnh kề và đánh dấu toàn bộ các đỉnh có đường đi tới `u` (tức trọn vẹn 1 thành phần liên thông chứa `u`).\n- Để đếm tổng số thành phần liên thông trên toàn đồ thị có thể bị phân mảnh, ta khởi tạo mảng đánh dấu `visited` gồm V phần tử bằng `false` và biến đếm `count = 0`.\n- Thực hiện vòng lặp ngoài duyệt tuần tự từng đỉnh `i` từ `0` đến `V - 1`:\n+ Nếu `visited[i]` đã là `true`, đỉnh này thuộc về một thành phần liên thông đã được đếm trước đó nên bỏ qua.\n+ Nếu `visited[i]` đang là `false`, ta vừa phát hiện một thành phần liên thông hoàn toàn mới: tăng `count` thêm 1 và kích hoạt thủ tục `DFS(i)` để đánh dấu `visited = true` cho `i` cùng mọi đỉnh liên thông với `i` thông qua việc đệ quy (hoặc dùng Stack tường minh) trên các đỉnh kề chưa thăm.\n\n2. Xử lý các trường hợp biên và độ phức tạp:\n- Các ca biên tự động được giải quyết chính xác: nếu đồ thị rỗng (`V = 0`) trả về `0`; nếu có đỉnh cô lập không nối cạnh nào, khi vòng lặp ngoài chạm tới nó sẽ tăng `count` thêm 1 và `DFS` dừng ngay vì danh sách kề rỗng.\n- Độ phức tạp thời gian là O(V + E) do mỗi đỉnh chỉ kích hoạt thân hàm DFS đúng 1 lần và mỗi cạnh được kiểm tra đúng 2 lần. Độ phức tạp không gian phụ là O(V) cho mảng `visited` và ngăn xếp đệ quy Call Stack trong trường hợp xấu nhất đồ thị suy biến thành đường thẳng.", "[\"Thiết kế vòng lặp quét toàn bộ đỉnh kết hợp biến đếm (3.5đ): Giải thích rõ lý do cần vòng lặp ngoài từ 0 đến V - 1 kiểm tra đỉnh chưa thăm để tăng biến đếm thành phần liên thông.\", \"Cơ chế lan truyền đánh dấu đỉnh qua DFS và xử lý đỉnh cô lập (3.5đ): Mô tả chính xác cách DFS đánh dấu trọn vẹn một cụm liên thông, chống lặp chu trình và xử lý đúng đỉnh cô lập.\", \"Phân tích độ phức tạp thời gian và không gian ngăn xếp (3.0đ): Chứng minh thời gian O(V + E) trên danh sách kề và không gian bộ nhớ O(V) bao gồm chiều sâu Call Stack.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Trên một đồ thị có một trăm nghìn đỉnh nối tiếp nhau thành một đường thẳng duy nhất, giải thuật DFS đệ quy thực thi trên máy ảo Java với cấu hình mặc định sẽ gặp sự cố gì và hướng khắc phục triệt để là gì?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000122", CourseCsd201Id, "00000000-0000-0000-0000-000000000566", RubricCsd201Id, "Thuật toán Phân hoạch Lomuto trong QuickSort và Cách Lựa chọn Pivot", "Hãy trình bày giải thuật phân hoạch Lomuto (Lomuto Partition) trên đoạn mảng từ chỉ số low đến high trong QuickSort khi chọn phần tử cuối đoạn làm chốt Pivot. Giải thích rõ bất biến vai trò của hai chỉ số i và j trong suốt quá trình quét, bước hoán vị chốt cuối cùng và độ phức tạp của thủ tục phân hoạch.", "1. Vai trò bất biến của hai chỉ số `i` và `j` trong phân hoạch Lomuto:\n- Thuật toán chọn phần tử cuối đoạn `pivot = arr[high]` làm giá trị chốt, khởi tạo chỉ số ranh giới `i = low - 1` (vùng nhỏ hơn hoặc bằng chốt ban đầu rỗng) và cho chỉ số quét `j` chạy tuần tự từ `low` đến `high - 1`.\n- Trong suốt vòng lặp, thuật toán duy trì bất biến 3 vùng nghiêm ngặt:\n+ Vùng từ `low` đến `i`: chứa các phần tử đã xác nhận nhỏ hơn hoặc bằng `pivot`.\n+ Vùng từ `i + 1` đến `j - 1`: chứa các phần tử đã khảo sát và lớn hơn hẳn `pivot`.\n+ Vùng từ `j` đến `high - 1`: chứa các phần tử chưa được khảo sát.\n\n2. Quy trình dịch chuyển, đặt chốt cuối cùng và độ phức tạp:\n- Tại mỗi bước quét `j`: nếu `arr[j] <= pivot`, ta tăng `i` lên 1 đơn vị (mở rộng biên vùng nhỏ hơn hoặc bằng) rồi hoán vị `arr[i]` với `arr[j]` để đẩy phần tử lớn hơn trước đó sang phải; ngược lại nếu `arr[j] > pivot` thì giữ nguyên `i` và chỉ tăng `j`.\n- Kết thúc vòng quét khi `j` chạm `high`, vị trí `i + 1` là phần tử đầu tiên của vùng lớn hơn `pivot`. Ta thực hiện phép hoán vị cuối cùng giữa `arr[i + 1]` và `arr[high]` để đặt `pivot` vào đúng vị trí chuẩn xác của nó trong mảng sắp xếp hoàn chỉnh, rồi trả về chỉ số `i + 1`.\n- Thủ tục phân hoạch duyệt qua `high - low` phần tử đúng một lần nên tốn thời gian tuyến tính O(n) trên kích thước đoạn và không gian phụ tại chỗ O(1).", "[\"Bất biến ba vùng của hai con trỏ chỉ số i và j (3.5đ): Mô tả chuẩn xác giá trị khởi tạo i = low - 1, phạm vi quét của j và ý nghĩa ranh giới vùng nhỏ hơn hoặc bằng so với vùng lớn hơn pivot.\", \"Quy trình hoán vị trong vòng quét và bước đặt chốt cuối (4.0đ): Trình bày chính xác thao tác tăng i rồi hoán vị khi arr[j] <= pivot, kết thúc bằng phép đổi chỗ arr[i + 1] với arr[high] và trả về i + 1.\", \"Độ phức tạp thời gian và không gian của bước phân hoạch (2.5đ): Khẳng định chi phí quét tuyến tính O(n) theo độ dài đoạn mảng và thực hiện tại chỗ O(1) bộ nhớ phụ.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Nếu đoạn mảng đầu vào chứa tất cả các phần tử có giá trị hoàn toàn bằng nhau, thủ tục phân hoạch Lomuto sẽ trả về vị trí chốt ở đâu và khiến QuickSort suy thoái độ phức tạp thời gian về mức nào?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000123", CourseCsd201Id, "00000000-0000-0000-0000-000000000567", RubricCsd201Id, "Cơ chế Giải quyết Xung đột Bảng băm bằng Dây chuyền Tách biệt (Separate Chaining)", "Hãy mô tả cấu trúc lưu trữ bên trong của Bảng băm sử dụng chiến lược Dây chuyền tách biệt (Separate Chaining). Trình bày chi tiết quy trình thực hiện ba thao tác thêm hoặc cập nhật khóa (put), tra cứu giá trị theo khóa (get) và xóa khóa (remove) khi xảy ra xung đột, đồng thời phân tích độ phức tạp theo hệ số tải.", "1. Cấu trúc lưu trữ của Separate Chaining:\n- Bảng băm duy trì một mảng chính kích thước M ngăn chứa (buckets). Thay vì lưu trực tiếp một phần tử duy nhất tại mỗi ô mảng, mỗi ô `table[idx]` đóng vai trò là đầu mối trỏ tới một danh sách liên kết chứa các nút cặp `(key, value)` cùng băm về chỉ số `idx`. Khi tính chỉ số từ mã băm số nguyên, cần triệt tiêu dấu âm trước khi chia lấy dư cho M để tránh lỗi vượt biên chỉ số âm.\n\n2. Quy trình thực hiện các thao tác `put`, `get` và `remove`:\n- Thao tác `put(key, value)`: Tính chỉ số ngăn `idx` từ hàm băm. Duyệt tuần tự qua danh sách liên kết tại `table[idx]`: nếu bắt gặp một nút đã có khóa trùng với `key` (so khớp bằng phép kiểm tra bằng nhau), ta ghi đè cập nhật `value` mới ngay trên nút đó và kết thúc (đảm bảo tính duy nhất của khóa); nếu duyệt hết dây chuyền chưa thấy, tạo nút `(key, value)` mới nối vào danh sách và tăng tổng số phần tử `n`.\n- Thao tác `get(key)`: Băm khóa ra chỉ số `idx`, duyệt danh sách tại `table[idx]` đối chiếu từng khóa; nếu khớp thì trả về `value`, nếu hết danh sách hoặc ngăn rỗng thì trả về `null`.\n- Thao tác `remove(key)`: Băm ra `idx`, tìm nút khớp khóa trong danh sách liên kết tại `table[idx]` và ngắt liên kết xóa nút trực tiếp mà không cần đánh dấu mộ giả (tombstone) như địa chỉ mở.\n\n3. Độ phức tạp theo hệ số tải `alpha = n / M`:\n- Dưới giả định phân phối băm đồng đều, độ dài trung bình mỗi dây chuyền là `alpha`, giúp cả ba thao tác đạt thời gian trung bình O(1 + alpha) ~ O(1) khi duy trì `alpha` hằng số; trường hợp xấu nhất mọi khóa dồn vào một ngăn duy nhất tốn O(n).", "[\"Kiến trúc mảng các danh sách liên kết Entry(key, value) (3.0đ): Mô tả chính xác mảng M buckets trỏ tới các dây chuyền nút khóa - giá trị và xử lý chuẩn hóa mã băm không âm.\", \"Quy trình thêm mới, cập nhật khóa trùng (put) và tra cứu (get) (4.0đ): Trình bày rõ bước quét dây chuyền để ghi đè giá trị nếu trùng khóa, nối nút mới nếu chưa có và trả về null khi tra cứu thất bại.\", \"Ưu điểm khi xóa phần tử (remove) và độ phức tạp theo hệ số tải (3.0đ): Nêu rõ thao tác xóa nút trực tiếp không cần đánh dấu giả và phân tích thời gian trung bình O(1 + alpha) so với xấu nhất O(n).\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Khi một ngăn chứa (bucket) trong Separate Chaining tích tụ quá nhiều phần tử do xung đột (ví dụ vượt ngưỡng 8 nút), cấu trúc dữ liệu nào được lớp HashMap của Java từ phiên bản 8 sử dụng để thay thế danh sách liên kết nhằm bảo đảm thời gian tra cứu xấu nhất O(log n)?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000124", CourseCsd201Id, "00000000-0000-0000-0000-000000000568", RubricCsd201Id, "Giải thuật Tìm kiếm Mẫu Chuỗi Vét cạn (Brute-Force Pattern Matching) và Trường hợp Suy biến", "Hãy trình bày nguyên lý hoạt động của giải thuật Tìm kiếm mẫu chuỗi vét cạn (Brute-Force Pattern Matching) để tìm vị trí xuất hiện đầu tiên của chuỗi mẫu P độ dài m bên trong chuỗi văn bản T độ dài n. Nêu rõ phạm vi dịch chuyển chỉ số căn lề, điều kiện biên và xây dựng một kịch bản dữ liệu khiến giải thuật suy biến về độ phức tạp O(n * m).", "1. Nguyên lý trượt cửa sổ đối sánh và xử lý điều kiện biên:\n- Xử lý ca biên trước tiên: nếu chuỗi mẫu rỗng (`m == 0`) trả về vị trí `0`; nếu mẫu dài hơn văn bản (`m > n`) thì chắc chắn không thể khớp nên trả về `-1` ngay lập tức.\n- Giải thuật dùng chỉ số căn lề ngoài `i` trượt từng bước một từ vị trí `0` đến tối đa `n - m` (không cần xét vượt quá `n - m` vì phần văn bản còn lại ngắn hơn `m`).\n- Tại mỗi vị trí căn lề `i`, dùng chỉ số phụ `j` bắt đầu từ `0` đối chiếu từng cặp ký tự `T[i + j]` với `P[j]`. Chừng nào `j < m` và hai ký tự còn khớp nhau thì tăng `j` lên 1. Nếu `j` tiến tới đúng bằng `m`, toàn bộ chuỗi mẫu đã khớp hoàn toàn nên trả về ngay vị trí `i`. Nếu lệch ở bất kỳ ký tự nào, vòng lặp trong dừng lại, tăng `i` thêm 1 để thử cửa sổ kế tiếp. Hết vòng lặp ngoài mà chưa khớp thì trả về `-1`.\n\n2. Phân tích kịch bản suy biến đạt độ phức tạp xấu nhất O(n * m):\n- Xét kịch bản văn bản `T` gồm toàn ký tự `'A'` lặp lại kết thúc bằng `'B'` (ví dụ `\"AAAA...AAAB\"`) và mẫu `P` cũng gồm chuỗi `'A'` kết thúc bằng `'B'` (ví dụ `\"AAAB\"`).\n- Tại mỗi vị trí căn lề `i`, giải thuật luôn khớp thành công `m - 1` ký tự `'A'` đầu tiên và chỉ phát hiện sai khác ở ký tự thứ `m` cuối cùng. Vì không ghi nhớ cấu trúc lặp đã đọc, giải thuật hủy bỏ toàn bộ công sức vừa so khớp, dịch cửa sổ nhích sang `i + 1` (tương đương lùi vị trí đọc văn bản lại `m - 2` ký tự) và so sánh lại từ đầu, tốn tổng cộng `(n - m + 1) * m` phép so sánh, tức O(n * m).", "[\"Nguyên lý trượt cửa sổ đối sánh và kiểm soát điều kiện biên (4.0đ): Trình bày rõ giới hạn căn lề i từ 0 đến n - m, con trỏ quét mẫu j từ 0 đến m - 1, ca biên m > n và điều kiện trả về i hoặc -1.\", \"Xây dựng kịch bản dữ liệu lặp gây trường hợp xấu nhất (3.0đ): Đưa ra đúng dạng chuỗi nhiều ký tự lặp giống nhau ở đầu và chỉ sai khác ở ký tự cuối cùng của mẫu.\", \"Chứng minh cơ chế lùi con trỏ đọc văn bản và độ phức tạp O(n*m) (3.0đ): Giải thích việc không tận dụng thông tin đã khớp làm mỗi vị trí trong n - m + 1 cửa sổ đều tốn đúng m phép so sánh.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Tại sao khi chuỗi văn bản và chuỗi mẫu chứa nhiều ký tự giống hệt nhau lặp lại ở đầu nhưng chỉ khác biệt ở ký tự cuối mẫu, giải thuật đối sánh vét cạn lại buộc phải lùi con trỏ kiểm tra trên văn bản lặp đi lặp lại và gây suy thoái về bậc hai?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000125", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", RubricCsd201Id, "Cơ chế Phép Quay Đơn, Phép Quay Kép trên Cây AVL và Thuật toán Cân bằng Toàn cục DSW", "Hãy phân tích cơ chế biến đổi con trỏ và thứ tự cập nhật chiều cao nút khi thực hiện phép quay đơn sang phải (rotateRight) và phép quay kép Trái-Phải (rotateLeftRight) trên cây AVL. Tiếp theo, khi một cây BST bị suy thoái nặng nhưng không duy trì điều kiện AVL sau mỗi lần chèn, giải thuật DSW (Day-Stout-Warren) cân bằng lại toàn bộ cây về Cây nhị phân hoàn chỉnh trong thời gian O(n) và bộ nhớ phụ O(1) qua hai giai đoạn tạo trục xương sống và nén cây như thế nào?", "1. Cơ chế con trỏ và thứ tự cập nhật chiều cao trong phép quay đơn và quay kép AVL:\n- Phép quay đơn phải tại nút `y` (xử lý lệch Trái-Trái): Gọi `x` là con trái của `y` và `T2` là cây con phải của `x` (mọi khóa thuộc `T2` đều lớn hơn `x` và nhỏ hơn `y`). Ta nâng `x` lên làm gốc mới bằng cách trỏ con phải của `x` vào `y`, đồng thời gắn `T2` sang làm con trái mới của `y`. Về chiều cao, bắt buộc cập nhật chiều cao nút `y` (nay đã hạ xuống làm con) trước theo công thức `1 + max(height(left), height(right))`, sau đó mới tính chiều cao nút `x` (nay là cha của `y`); nếu tính ngược sẽ lấy chiều cao cũ sai lệch của `y`.\n- Phép quay kép Trái-Phải tại nút `z`: Tổ hợp tuần tự hai phép quay đơn gồm quay trái tại con trái của `z` để duỗi nhánh gấp khúc thành thẳng trục Trái-Trái, rồi quay phải tại chính nút `z`.\n\n2. Hai giai đoạn cân bằng toàn cục tại chỗ của giải thuật DSW (Day-Stout-Warren):\n- Giai đoạn 1 — Tạo trục xương sống phải (Backbone/Vine): Duyệt dọc theo đường biên phải từ nút giả đầu cây; mỗi khi nút hiện tại còn con trái thì thực hiện phép quay phải để kéo con trái lên và đẩy nút hiện tại xuống nhánh phải. Sau tối đa `n - 1` phép quay phải, cây duỗi thẳng thành danh sách liên kết nghiêng phải tăng dần.\n- Giai đoạn 2 — Nén trục xương sống (Compress): Đặt `m = 2^(floor(log2(n + 1))) - 1` là số nút của cây nhị phân đầy đủ lớn nhất không vượt quá `n`. Thực hiện đợt đầu `n - m` phép quay trái cách quãng dọc trục phải để gom các lá tầng đáy, sau đó lặp chia đôi `m = m / 2` và thực hiện `m` phép quay trái ở mỗi lượt. Tổng số phép quay nhỏ hơn `2n`, đạt thời gian Theta(n) và không gian phụ Theta(1) không cần mảng trung gian.", "[\"Cơ chế biến đổi con trỏ và thứ tự cập nhật chiều cao trong phép quay AVL (4.0đ): Trình bày chính xác cách chuyển cây con trung gian T2, tổ hợp hai bước của quay kép LR và nguyên tắc cập nhật chiều cao nút con y trước nút cha x.\", \"Giai đoạn 1 của DSW: Duỗi cây thành trục xương sống nghiêng phải (3.0đ): Giải thích rõ việc dùng chuỗi phép quay phải mỗi khi gặp con trái để biến BST thành danh sách nghiêng phải tăng dần trong tối đa n - 1 phép quay.\", \"Giai đoạn 2 của DSW: Nén bằng phép quay trái đạt O(n) time và O(1) space (3.0đ): Nêu đúng công thức m = 2^(floor(log2(n + 1))) - 1, đợt quay trái n - m đầu tiên và vòng lặp chia đôi m tại chỗ với bộ nhớ phụ O(1).\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Trong phép quay đơn sang phải quanh nút gốc y để nâng nút con trái x lên làm gốc mới trên cây AVL, tại sao bắt buộc phải tính lại chiều cao của nút y trước khi tính lại chiều cao của nút x?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000126", CourseCsd201Id, "00000000-0000-0000-0000-000000000561", RubricCsd201Id, "Thuật toán Floyd's Tortoise and Hare Phát hiện Chu trình trong Singly Linked List", "Trình bày nguyên lý thuật toán Rùa và Thỏ của Floyd (Floyd's Tortoise and Hare) để phát hiện chu trình trong Danh sách liên kết đơn. Chứng minh về mặt toán học vì sao hai con trỏ chắc chắn sẽ gặp nhau nếu có chu trình và giải thích thuật toán tìm nút bắt đầu chu trình.", "1. Nguyên lý hai con trỏ Rùa và Thỏ:\n- Khởi tạo con trỏ Chậm (`slow`) và con trỏ Nhanh (`fast`) cùng xuất phát tại `head`. Ở mỗi bước lặp, `slow` tiến 1 nút còn `fast` tiến 2 nút. Nếu danh sách không có chu trình, `fast` hoặc `fast.next` sẽ chạm `null` sau O(n) bước. Nếu có chu trình, cả hai đều đi vào vòng khép kín với không gian phụ O(1).\n\n2. Chứng minh toán học hai con trỏ chắc chắn gặp nhau mà không nhảy vọt qua nhau:\n- Giả sử chu trình có độ dài L nút. Ngay khi `slow` vừa đặt chân vào nút đầu chu trình, `fast` đã ở trong chu trình và đang đuổi phía sau `slow` một khoảng cách `d` bước (với `0 <= d < L`).\n- Mỗi lượt di chuyển tiếp theo, `slow` tiến 1 bước trong khi `fast` tiến 2 bước, nên khoảng cách đuổi bắt bị thu hẹp chính xác `2 - 1 = 1` nút mỗi lượt. Khoảng cách giảm đơn điệu từng đơn vị `d, d - 1, ..., 1, 0` sau tối đa L bước, bảo đảm `fast` bắt kịp đúng vị trí `slow` mà không bao giờ nhảy vọt qua mặt.\n\n3. Xác định nút bắt đầu chu trình:\n- Gọi `a` là số cạnh từ `head` tới đầu chu trình và `b` là số cạnh từ đầu chu trình tới điểm gặp nhau `M`. Vì quãng đường `fast` gấp đôi `slow` nên `2(a + b) = a + b + k * L`, suy ra `a = k * L - b`. Hệ thức này chứng tỏ nếu đặt một con trỏ về lại `head` và giữ con trỏ kia tại `M`, cho cả hai cùng tiến 1 bước mỗi lượt thì sau đúng `a` bước chúng sẽ hội tụ chính xác tại nút mở đầu chu trình.", "[\"Nguyên lý hai con trỏ Tortoise & Hare (3.0đ): Mô tả đúng vận tốc 1 bước vs 2 bước và điều kiện dừng.\", \"Chứng minh toán học chắc chắn gặp nhau (3.5đ): Phân tích khoảng cách tương đối giảm 1 đơn vị mỗi bước (modulo L).\", \"Thuật toán tìm nút bắt đầu chu trình (3.5đ): Trình bày thuật toán reset con trỏ về head và chứng minh công thức a = k*L - b.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Trong thuật toán Rùa và Thỏ của Floyd, sau khi hai con trỏ gặp nhau bên trong chu trình, tại sao nếu ta đặt lại con trỏ Chậm về nút đầu (head) và cho cả hai di chuyển cùng tốc độ 1 bước, điểm gặp nhau tiếp theo chính là điểm bắt đầu chu trình?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000127", CourseCsd201Id, "00000000-0000-0000-0000-000000000562", RubricCsd201Id, "Phân tích Chi phí Hàng đợi Ưu tiên Biểu diễn bằng Mảng và Đống Nhị phân (Binary Heap)", "Hãy so sánh ba phương pháp biểu diễn Hàng đợi ưu tiên (Priority Queue) gồm: Mảng chưa sắp xếp (Unsorted Array), Mảng đã sắp xếp (Sorted Array) và Đống nhị phân (Binary Heap) về độ phức tạp thời gian của các thao tác chèn phần tử (insert), xóa phần tử nhỏ nhất (removeMin) và xem phần tử nhỏ nhất (min). Vì sao Binary Heap là lựa chọn tối ưu cho các hệ thống thực tế?", "1. Đối sánh độ phức tạp thời gian của ba cấu trúc biểu diễn Priority Queue:\n- Mảng chưa sắp xếp (Unsorted Array): Thao tác `insert` chỉ cần ghi vào cuối mảng nên đạt O(1); tuy nhiên cả `removeMin` lẫn `min` đều phải quét tuyến tính toàn bộ n phần tử để tìm khóa nhỏ nhất nên tốn O(n).\n- Mảng đã sắp xếp (Sorted Array — giữ phần tử nhỏ nhất ở cuối mảng để tránh dịch mảng khi xóa): Thao tác `removeMin` và `min` truy xuất trực tiếp phần tử cuối mảng trong O(1); nhưng thao tác `insert` dù tìm vị trí bằng tìm kiếm nhị phân O(log n) vẫn phải dịch chuyển các phần tử đứng sau sang phải nên tốn O(n).\n- Đống nhị phân (Binary Heap): Thao tác `min` đọc ngay gốc `heap[0]` trong O(1); thao tác `insert` (thêm cuối mảng rồi vun ngược `siftUp`) và `removeMin` (đưa phần tử cuối lên gốc rồi vun xuống `siftDown`) đều đạt O(log n).\n\n2. Lý do Binary Heap tối ưu vượt trội trong hệ thống thực tế:\n- Xóa bỏ điểm nghẽn tuyến tính O(n): Cả hai phương án mảng thuần túy đều bị nghẽn O(n) ở một đầu (ghi hoặc xóa), khiến chuỗi n thao tác đan xen trong điều phối CPU hoặc giải thuật Dijkstra suy thoái tổng thời gian thành O(n^2). Binary Heap cân bằng hoàn hảo cả hai chiều ở mức O(log n), rút ngắn tổng thời gian xuống O(n log n) (với 1 triệu phần tử chỉ tốn khoảng 20 phép so sánh mỗi bước), đồng thời lưu trên mảng phẳng liên tục nên tối ưu bộ nhớ đệm CPU và không tốn con trỏ.", "[\"So sánh độ phức tạp thao tác trên ba cấu trúc biểu diễn (4.0đ): Phân tích chính xác 100% độ phức tạp của insert, removeMin và min cho Unsorted Array, Sorted Array và Binary Heap.\", \"Phân tích điểm nghẽn O(n) gây suy thoái tổng thể O(n^2) (3.0đ): Chỉ ra sự mất cân đối cực đoan giữa chèn và xóa của hai phương án mảng dẫn tới nghẽn O(n^2) khi tải hỗn hợp.\", \"Lập luận ưu thế cân bằng O(log n) và bộ nhớ của Binary Heap (3.0đ): Chứng minh tính cân bằng O(log n) cho cả đọc/ghi và lợi thế cache locality nhờ lưu trữ trên mảng một chiều phẳng.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Trong kịch bản hệ thống phát sinh thao tác chèn phần tử cực kỳ dày đặc nhưng thao tác trích xuất phần tử ưu tiên rất hiếm khi được gọi, cấu trúc biểu diễn nào giữa Mảng chưa sắp xếp và Binary Heap sẽ mang lại tổng thông lượng cao hơn?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000128", CourseCsd201Id, "00000000-0000-0000-0000-000000000563", RubricCsd201Id, "Kỹ thuật Khử Đệ quy Đuôi Tối ưu hóa Bộ nhớ Call Stack", "Thế nào là Đệ quy đuôi (Tail Recursion)? Tại sao hàm đệ quy tính giai thừa kinh điển nhân n với kết quả lời gọi giai thừa của n trừ 1 lại không phải là đệ quy đuôi? Hãy giải thích cách bổ sung tham số tích lũy (Accumulator) để biến đổi nó về dạng đệ quy đuôi chuẩn và khử đệ quy hoàn toàn sang vòng lặp với không gian bộ nhớ O(1).", "1. Định nghĩa Đệ quy đuôi và lý do hàm giai thừa kinh điển không thỏa mãn:\n- Một hàm đệ quy được gọi là Đệ quy đuôi (Tail Recursion) khi lời gọi đệ quy là hành động thực thi cuối cùng tuyệt đối trong thân hàm; giá trị trả về của lời gọi con được chuyển thẳng làm kết quả của hàm cha mà không còn bất kỳ phép toán chờ xử lý nào phía sau.\n- Trong công thức giai thừa kinh điển trả về `n * factorial(n - 1)`, lời gọi đệ quy không phải là thao tác cuối cùng vì sau khi `factorial(n - 1)` quay lui trả kết quả, khung hàm hiện tại vẫn phải thực hiện phép nhân với biến cục bộ `n`. Do đó hệ thống buộc phải giữ nguyên n khung kích hoạt trên Call Stack để lưu các giá trị `n, n - 1, ..., 2`, tốn không gian bộ nhớ phụ O(n).\n\n2. Chuyển đổi bằng biến tích lũy (Accumulator) và khử đệ quy sang vòng lặp O(1):\n- Để chuyển thành đệ quy đuôi, ta bổ sung tham số tích lũy `acc` (khởi tạo bằng `1`) nhằm tính trước phép nhân ngay trên đối số truyền đi: nếu `n <= 1` thì trả về trực tiếp `acc`, ngược lại gọi đệ quy đuôi với cặp đối số `(n - 1, n * acc)`. Lúc này không còn phép toán dở dang nào sau lời gọi đệ quy.\n- Từ dạng đệ quy đuôi này, ta khử đệ quy cơ học sang vòng lặp: khởi tạo biến `acc = 1`, lặp chừng nào `n > 1` thì cập nhật `acc = acc * n` và giảm `n` đi 1, cuối cùng trả về `acc`. Giải pháp vòng lặp chạy trong thời gian O(n), triệt tiêu 100% chi phí cấp phát Call Stack và đạt không gian phụ O(1).", "[\"Định nghĩa chính xác bản chất Đệ quy đuôi (3.0đ): Nêu rõ lời gọi đệ quy là thao tác cuối cùng tuyệt đối và trả thẳng kết quả mà không còn phép toán hậu xử lý.\", \"Phân tích phép nhân chờ xử lý gây tốn O(n) Call Stack (3.0đ): Chỉ rõ phép nhân phụ thuộc biến cục bộ n buộc hệ thống duy trì toàn bộ chuỗi stack frames cho tới khi chạm đáy.\", \"Nguyên lý biến tích lũy Accumulator và khử đệ quy sang vòng lặp O(1) (4.0đ): Trình bày chính xác cách truyền tích lũy (n - 1, n * acc) và quy tắc chuyển sang vòng lặp giảm bộ nhớ phụ từ O(n) xuống O(1).\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Máy ảo JVM của ngôn ngữ Java hiện tại có tự động thực hiện tối ưu hóa lời gọi đuôi (Tail Call Optimization — TCO) để tái sử dụng khung ngăn xếp như một số trình biên dịch C/C++ hay ngôn ngữ lập trình hàm không, và vì sao?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000129", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", RubricCsd201Id, "Phân tích Hiện tượng Thoái hóa O(n) của Cây BST và Cơ chế Tự Cân bằng 4 Phép Quay trên Cây AVL", "Hệ số cân bằng (Balance Factor) của nút trong Cây AVL được định nghĩa như thế nào? Hãy phân tích 4 trường hợp mất cân bằng (Left-Left, Right-Right, Left-Right, Right-Left) và giải thích vì sao trường hợp Left-Right bắt buộc phải sử dụng phép xoay kép (Double Rotation) mà một phép xoay đơn không thể giải quyết được.", "1. Hệ số cân bằng (Balance Factor — BF) và điều kiện AVL:\n- Tại mỗi nút `u`, hệ số cân bằng được tính bằng hiệu chiều cao cây con trái trừ chiều cao cây con phải: `BF(u) = Height(u.left) - Height(u.right)`. Cây BST là cây AVL khi mọi nút đều có `BF` thuộc tập `{-1, 0, +1}` (trị tuyệt đối của `BF` không vượt quá 1), ngăn chặn triệt để hiện tượng BST suy thoái thành đường thẳng O(n) khi chèn dãy khóa có thứ tự. Mất cân bằng xảy ra ngay khi trị tuyệt đối của `BF` lớn hơn hoặc bằng 2.\n\n2. Bốn trường hợp mất cân bằng tại nút thấp nhất `z` và phép xoay khôi phục:\n- Lệch Trái-Trái (LL): `BF(z) = +2` và con trái có `BF >= 0` -> Xoay đơn sang phải (Single Right Rotation) tại `z`.\n- Lệch Phải-Phải (RR): `BF(z) = -2` và con phải có `BF <= 0` -> Xoay đơn sang trái (Single Left Rotation) tại `z`.\n- Lệch Trái-Phải (LR): `BF(z) = +2` nhưng con trái `y` có `BF = -1` -> Xoay kép Trái-Phải: xoay trái tại `y`, rồi xoay phải tại `z`.\n- Lệch Phải-Trái (RL): `BF(z) = -2` nhưng con phải `y` có `BF = +1` -> Xoay kép Phải-Trái: xoay phải tại `y`, rồi xoay trái tại `z`.\n\n3. Chứng minh vì sao trường hợp LR bắt buộc dùng phép xoay kép:\n- Trong cấu hình LR, đường đi tới nhánh sâu nhất bị gấp khúc dạng chữ chi (từ `z` rẽ trái sang `y`, rồi rẽ phải sang cháu `x`). Nếu chỉ xoay phải đơn tại `z`, toàn bộ cây con gốc `x` (nhánh đang nhô cao nhất) chỉ bị bốc từ nhánh phải của `y` sang gắn làm nhánh trái của `z` ở cùng độ sâu cũ, khiến cây đổi sang lệch ngược bên phải mà không hề giảm chiều cao. Bắt buộc phải xoay trái tại `y` trước để đưa `x` lên nắn thẳng trục thành dạng LL, sau đó xoay phải tại `z` mới đưa `x` lên làm gốc cân bằng đối xứng cho cả `y` và `z`.", "[\"Định nghĩa Balance Factor (2.5đ): Nêu đúng công thức BF = Height(Left) - Height(Right) và ngưỡng [-1, 0, 1].\", \"Phân loại 4 trường hợp mất cân bằng (3.5đ): Mô tả đầy đủ LL, RR, LR, RL kèm phép xoay tương ứng.\", \"Chứng minh bản chất phép xoay kép LR (4.0đ): Giải thích hiện tượng zigzag và chứng minh phép xoay đơn chỉ làm đảo bên lệch chứ không giảm chiều cao.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Trong phép xoay kép Left-Right (LR) trên Cây AVL, thứ tự thực hiện hai phép xoay đơn lần lượt tại các nút nào và hệ số cân bằng của nút gốc mới sau khi xoay sẽ phụ thuộc vào yếu tố nào?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000130", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", RubricCsd201Id, "Phân tích Thuật toán HeapSort: Giai đoạn Build-Heap Tuyến tính O(n)", "Thuật toán HeapSort gồm 2 giai đoạn: Xây dựng Max-Heap (Build-Heap) và Trích xuất phần tử sắp xếp. Tại sao giai đoạn xây dựng Max-Heap từ dưới lên (Bottom-up) từ một mảng lộn xộn chỉ tốn chi phí thời gian tuyến tính O(n) thay vì O(n log n)? Hãy trình bày chứng minh toán học.", "1. Hai giai đoạn của HeapSort:\n- Giai đoạn 1 (Build-Heap): Biến mảng n phần tử thành Max-Heap từ dưới lên, bắt đầu từ nút nội cuối cùng tại chỉ số `(n / 2) - 1` lùi dần về gốc `0` và gọi `siftDown` tại mỗi nút.\n- Giai đoạn 2 (Sorting): Lặp `n - 1` lần việc hoán vị gốc `a[0]` với phần tử cuối vùng đống `a[size - 1]`, giảm `size` đi 1 rồi gọi `siftDown(0)`, tốn O(n log n).\n\n2. Chứng minh toán học giai đoạn Build-Heap chỉ tốn thời gian tuyến tính O(n):\n- Ngộ nhận thường gặp là có `n / 2` lần gọi `siftDown`, mỗi lần tốn O(log n) nên tổng là O(n log n). Thực chất, chi phí `siftDown` của một nút tỉ lệ thuận với chiều cao `h` tính từ nút đó xuống lá, chứ không phải độ sâu từ gốc!\n- Trên cây nhị phân hoàn chỉnh n nút, phần lớn các nút tập trung ở các tầng đáy có chiều cao rất nhỏ: có xấp xỉ `n / 2` nút lá ở chiều cao `h = 0` (tốn 0 bước), `n / 4` nút ở `h = 1` (tối đa 1 bước), `n / 8` nút ở `h = 2` (tối đa 2 bước), và tổng quát có không quá `ceil(n / 2^(h + 1))` nút ở chiều cao `h`.\n- Tổng số bước hoán vị `S` trên toàn cây bị chặn trên bởi tổng `sum_{h >= 0} (n / 2^(h + 1)) * h = (n / 2) * sum_{h >= 0} (h / 2^h)`.\n- Vì chuỗi vô hạn hội tụ `sum_{h=0..infinity} (h / 2^h) = 1/2 + 2/4 + 3/8 + ... = 2`, thay vào ta được `S <= (n / 2) * 2 = n`. Do đó, giai đoạn Build-Heap chạy trong thời gian chặt O(n) với bộ nhớ phụ O(1).", "[\"Tổng quan 2 giai đoạn HeapSort (2.5đ): Mô tả đúng Build-Heap Bottom-up và giai đoạn trích xuất gốc O(n log n).\", \"Phân tích số nút theo chiều cao h (3.5đ): Chỉ ra công thức số lượng nút ở chiều cao h là n / 2^(h+1).\", \"Chứng minh chuỗi toán học hội tụ (4.0đ): Tính chính xác tổng chuỗi sum(h / 2^h) = 2 và kết luận chặn trên O(n).\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Nếu thay vì dùng giải thuật Bottom-up Build-Heap tuyến tính O(n), ta xây dựng heap bằng cách gọi n lần thao tác chèn phần tử liên tiếp vào một heap ban đầu rỗng thì độ phức tạp thời gian xấu nhất sẽ là bao nhiêu và tại sao phương pháp này kém tối ưu hơn?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000131", CourseCsd201Id, "00000000-0000-0000-0000-000000000565", RubricCsd201Id, "Thuật toán Dijkstra Tìm Đường đi Ngắn nhất: Bản chất Tham lam và Cạnh Âm", "Thuật toán Dijkstra tìm đường đi ngắn nhất nguồn đơn hoạt động theo chiến lược thiết kế thuật toán nào? Hãy phân tích độ phức tạp thời gian khi sử dụng Mảng đánh dấu vs Min-Heap. Giải thích cặn kẽ vì sao thuật toán Dijkstra thất bại khi đồ thị xuất hiện cạnh có trọng số âm?", "1. Chiến lược thiết kế và phân tích độ phức tạp thời gian:\n- Dijkstra vận hành theo chiến lược Tham lam (Greedy Strategy): ở mỗi bước, thuật toán luôn chọn đỉnh `u` chưa chốt có khoảng cách ước lượng `dist[u]` nhỏ nhất từ nguồn để khóa cố định kết quả và nới lỏng (relax) các cạnh kề xuất phát từ `u`.\n- Khi biểu diễn tập đỉnh chờ bằng Mảng quét tuyến tính: tìm đỉnh cực tiểu tốn O(V) lặp V lần là O(V^2), nới lỏng E cạnh tốn O(E), tổng cộng O(V^2) (tối ưu cho đồ thị rất dày `E ~ V^2`).\n- Khi dùng Hàng đợi ưu tiên Min-Heap: trích xuất đỉnh cực tiểu V lần tốn O(V log V) và cập nhật khoảng cách trên E cạnh tốn O(E log V), tổng cộng O((V + E) log V) (vượt trội trên đồ thị thưa).\n\n2. Nguyên nhân cốt lõi khiến Dijkstra thất bại khi có cạnh trọng số âm:\n- Tính đúng đắn của Dijkstra dựa hoàn toàn vào bất biến đơn điệu của trọng số không âm: một khi đỉnh `u` có `dist[u]` nhỏ nhất được rút ra chốt sổ, mọi đường đi vòng qua các đỉnh chưa chốt khác đều có khoảng cách khởi đầu lớn hơn hoặc bằng `dist[u]` và cộng thêm các cạnh không âm nên không bao giờ tạo ra đường đi ngắn hơn tới `u`.\n- Khi xuất hiện cạnh âm, bất biến này sụp đổ: xét nguồn S nối tới A (trọng số 3), S nối tới B (trọng số 5) và cạnh âm B nối sang A (trọng số -4). Dijkstra thấy `dist[A] = 3 < dist[B] = 5` nên chốt cứng `dist[A] = 3` trước; đến khi xét B mới phát hiện đường S -> B -> A có tổng chi phí `5 + (-4) = 1 < 3`, nhưng A đã bị đóng khóa không xét lại nữa, dẫn tới kết quả sai (phải dùng Bellman-Ford O(V * E)).", "[\"Bản chất chiến lược Greedy (2.5đ): Nêu rõ nguyên lý chọn đỉnh có dist nhỏ nhất chưa thăm để chốt kết quả.\", \"So sánh Big-O Mảng vs Min-Heap (3.5đ): Phân tích chính xác O(V^2) cho mảng và O((V+E) log V) cho Min-Heap.\", \"Chứng minh thất bại với cạnh âm (4.0đ): Chỉ rõ vi phạm giả định bất biến 'khoảng cách đã chốt không giảm' kèm phản ví dụ cụ thể.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Nếu ta cộng thêm một hằng số dương lớn C vào tất cả các trọng số cạnh của một đồ thị có trọng số âm để triệt tiêu số âm rồi chạy thuật toán Dijkstra, liệu đường đi ngắn nhất tìm được có còn đảm bảo chính xác không, vì sao?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000132", CourseCsd201Id, "00000000-0000-0000-0000-000000000565", RubricCsd201Id, "So sánh Chuyên sâu Thuật toán Prim và Kruskal Tìm Cây Khung Nhỏ nhất", "Hãy so sánh toàn diện hai thuật toán tìm Cây khung nhỏ nhất (MST): Thuật toán Prim và Thuật toán Kruskal về: Cách tiếp cận phát triển cây, Cấu trúc dữ liệu bổ trợ, Độ phức tạp thời gian và Tiêu chuẩn lựa chọn trên đồ thị dày (Dense) vs đồ thị thưa (Sparse).", "1. Cách tiếp cận phát triển cây và cấu trúc dữ liệu bổ trợ:\n- Thuật toán Prim (Tiếp cận theo đỉnh — Vertex-centric): Xuất phát từ một đỉnh bất kỳ, duy trì một cây liên thông duy nhất và liên tục mở rộng bằng cách kết nạp cạnh nhẹ nhất nối từ tập đỉnh đã thuộc cây sang một đỉnh bên ngoài. Prim sử dụng Hàng đợi ưu tiên (Min-Heap) hoặc mảng khoảng cách để chọn nhanh cạnh cắt nhỏ nhất.\n- Thuật toán Kruskal (Tiếp cận theo cạnh — Edge-centric): Sắp xếp toàn bộ E cạnh theo trọng số không giảm, khởi tạo một rừng gồm V cây rời rạc và lần lượt xét từng cạnh từ nhỏ đến lớn; nếu cạnh nối hai thành phần liên thông khác nhau (không tạo chu trình) thì đưa vào MST. Kruskal bắt buộc dùng cấu trúc các tập rời nhau Disjoint Set Union (Union-Find) tối ưu bằng Nén đường đi và Hợp nhất theo hạng để kiểm tra chu trình trong thời gian khấu hao gần hằng số O(alpha(V)).\n\n2. Độ phức tạp thời gian và tiêu chuẩn lựa chọn Dense vs Sparse:\n- Với Binary Heap, Prim đạt O((V + E) log V) ~ O(E log V); nếu dùng mảng trên Ma trận kề thì Prim đạt O(V^2) không phụ thuộc E. Kruskal tốn O(E log E) = O(E log V) do bước sắp xếp toàn bộ tập cạnh chi phối.\n- Trên đồ thị thưa (`E ~ V`), ưu tiên Kruskal vì đơn giản, dễ triển khai trên danh sách cạnh và chạy rất nhanh. Trên đồ thị dày (`E ~ V^2`), Prim dùng mảng O(V^2) vượt trội hơn hẳn vì tránh được chi phí O(V^2 log V) sắp xếp hàng triệu cạnh của Kruskal.", "[\"So sánh cách tiếp cận Vertex vs Edge (3.0đ): Phân biệt rõ cây liên thông phát triển dần của Prim so với rừng gộp cạnh của Kruskal.\", \"Đặc tả vai trò cấu trúc DSU của Kruskal (3.5đ): Mô tả vai trò của Union-Find chống chu trình trong Kruskal so với Min-Heap của Prim.\", \"Phân tích Big-O và tiêu chí lựa chọn (3.5đ): So sánh chính xác độ phức tạp O(E log V) / O(V^2) và đưa ra quyết định Dense vs Sparse.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Trong thuật toán Kruskal, vai trò cốt lõi của cấu trúc dữ liệu Disjoint Set Union (DSU / Union-Find) kết hợp kỹ thuật Nén đường đi (Path Compression) và Hợp nhất theo hạng (Union by Rank) là gì trong việc kiểm soát chu trình đồ thị?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000133", CourseCsd201Id, "00000000-0000-0000-0000-000000000565", RubricCsd201Id, "Phân tích Điều kiện Tồn tại Chu trình Euler và So sánh với Chu trình Hamilton", "Định nghĩa Chu trình Euler (Eulerian Cycle) và Chu trình Hamilton (Hamiltonian Cycle). Nêu điều kiện cần và đủ để một đồ thị vô hướng liên thông có Chu trình Euler. Tại sao bài toán kiểm tra chu trình Euler thuộc lớp P trong khi bài toán chu trình Hamilton thuộc lớp NP-Đầy đủ (NP-Complete)?", "1. Định nghĩa và điều kiện cần và đủ của Chu trình Euler:\n- Chu trình Euler là chu trình khép kín đi qua mỗi cạnh của đồ thị đúng một lần rồi quay về đỉnh xuất phát. Chu trình Hamilton là chu trình khép kín đi qua mỗi đỉnh của đồ thị đúng một lần trước khi quay lại đỉnh đầu.\n- Theo Định lý Euler, một đồ thị vô hướng liên thông (xét trên các đỉnh có cạnh) tồn tại Chu trình Euler khi và chỉ khi 100% các đỉnh của nó đều có bậc chẵn (`deg(v) mod 2 == 0`), bởi mỗi lần đi vào và rời khỏi một đỉnh luôn tiêu thụ đúng một cặp 2 cạnh.\n\n2. Bản chất đối lập về lớp độ phức tạp P và NP-Complete:\n- Bài toán Chu trình Euler thuộc lớp P (giải được trong thời gian đa thức tuyến tính O(V + E)): điều kiện bậc chẵn là một bất biến cục bộ tại từng đỉnh nhưng lại đồng thời là điều kiện đủ toàn cục. Chỉ cần một lượt BFS/DFS kiểm tra liên thông kết hợp đếm bậc đỉnh là kết luận được ngay, và giải thuật Hierholzer dựng chu trình trực tiếp trong O(V + E) mà không cần quay lui thử sai.\n- Ngược lại, bài toán Chu trình Hamilton thuộc lớp NP-Complete: vì mỗi đỉnh chỉ được ghé thăm đúng một lần nên việc chọn một cạnh đi tiếp sẽ khóa cứng nhiều lựa chọn tương lai, biến bài toán thành ràng buộc cấu trúc toàn cục (chỉ có các điều kiện đủ riêng lẻ như Dirac hay Ore, không có điều kiện cần và đủ cục bộ). Mọi giải thuật chính xác tổng quát hiện biết đều phải quay lui hoặc quy hoạch động trạng thái bitmask tốn thời gian hàm mũ O(n^2 * 2^n) hoặc O(n!).", "[\"Định nghĩa chính xác 2 chu trình (3.0đ): Nêu rõ Euler đi qua mỗi CẠNH 1 lần, Hamilton đi qua mỗi ĐỈNH 1 lần.\", \"Định lý bậc chẵn của Euler (3.0đ): Phát biểu chuẩn xác điều kiện cần và đủ: liên thông và mọi đỉnh có bậc chẵn.\", \"Lập luận lớp P vs NP-Complete (4.0đ): Giải thích bản chất kiểm tra cục bộ O(V+E) của Euler so với tính chất toàn cục mũ của Hamilton.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Định lý Euler-Hierholzer sử dụng điều kiện bậc chẵn của các đỉnh để xây dựng chu trình Euler trong thời gian O(V + E) như thế nào, và tại sao tính chất bậc đỉnh cục bộ lại hoàn toàn bất lực trong việc xác định sự tồn tại của chu trình Hamilton?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000134", CourseCsd201Id, "00000000-0000-0000-0000-000000000566", RubricCsd201Id, "So sánh Toàn diện QuickSort vs MergeSort", "Hãy so sánh toàn diện QuickSort và MergeSort trên các phương diện: Nguyên lý chia để trị, Độ phức tạp thời gian (Best, Average, Worst), Bộ nhớ phụ trợ (Space Complexity), Tính ổn định (Stability) và Hiệu ứng bộ nhớ đệm (Cache Locality). Tại sao Java sử dụng Dual-Pivot QuickSort cho kiểu dữ liệu nguyên thủy (primitives) nhưng lại dùng TimSort/MergeSort cho mảng đối tượng (Objects)?", "1. Đối sánh năm chiều kỹ thuật giữa QuickSort và MergeSort:\n- Triết lý chia để trị: QuickSort nặng ở bước Chia (phân hoạch các phần tử quanh chốt Pivot) và nhẹ ở bước Trị (không cần gộp); ngược lại MergeSort chia đôi chỉ số rất nhẹ nhưng nặng ở bước Gộp hai mảng con đã sắp xếp.\n- Độ phức tạp thời gian: Cả hai đều đạt O(n log n) ở trường hợp tốt nhất và trung bình; nhưng trường hợp xấu nhất QuickSort có thể suy thoái về O(n^2) nếu chọn Pivot lệch cực đoan, còn MergeSort cam kết chặt O(n log n) trong mọi trường hợp.\n- Bộ nhớ phụ, Tính ổn định và Cache Locality: QuickSort sắp xếp tại chỗ chỉ tốn O(log n) ngăn xếp đệ quy, quét tuần tự trên cùng một mảng nên tận dụng CPU Cache Locality cực tốt, nhưng không ổn định (Unstable) do hoán vị xa. MergeSort bảo đảm tính ổn định (Stable) tuyệt đối nhưng phải cấp phát mảng đệm phụ O(n) và chép dữ liệu qua lại làm tăng chi phí băng thông bộ nhớ.\n\n2. Lý do thư viện chuẩn Java JDK tách biệt hai giải thuật trong `Arrays.sort`:\n- Với kiểu nguyên thủy (`int`, `double`): Hai giá trị số bằng nhau hoàn toàn không thể phân biệt danh tính nên tính ổn định là vô nghĩa; Dual-Pivot QuickSort chạy tại chỗ không cấp phát Heap và tối ưu bộ nhớ đệm CPU nên đạt tốc độ thực thi cao nhất.\n- Với mảng đối tượng (`Object[]`): Bảo toàn thứ tự tương đối giữa các bản ghi bằng khóa nhau (như sắp xếp theo Điểm nhưng giữ nguyên thứ tự Tên trước đó) là yêu cầu nghiệp vụ bắt buộc, nên Java dùng TimSort (lai giữa MergeSort và Insertion Sort) để đảm bảo Stable 100% và chặn trên O(n log n).", "[\"So sánh đa chiều về thuật toán, bộ nhớ, tính ổn định và cache (4.0đ): Phân tích đầy đủ và chính xác nguyên lý chia - gộp, 3 kịch bản Big-O, Space O(log n) vs O(n), Stability và Cache Locality.\", \"Giải thích lựa chọn Dual-Pivot QuickSort cho kiểu nguyên thủy (3.0đ): Chỉ ra tính vô nghĩa của Stability với primitives và ưu thế in-place, tối ưu CPU cache của QuickSort.\", \"Giải thích lựa chọn TimSort/MergeSort cho mảng đối tượng (3.0đ): Chứng minh tính bắt buộc của Stability trong sắp xếp đa tiêu chí trên đối tượng và cam kết xấu nhất O(n log n).\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Tại sao tính ổn định (Stability) của thuật toán sắp xếp lại là yêu cầu sống còn khi sắp xếp danh sách đối tượng nhiều trường dữ liệu (ví dụ: sắp xếp sinh viên theo Điểm thi sau khi đã sắp xếp theo Tên), khiến Java buộc phải dùng TimSort thay vì Dual-Pivot QuickSort?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000135", CourseCsd201Id, "00000000-0000-0000-0000-000000000567", RubricCsd201Id, "Hiện tượng Cụm Chính trong Linear Probing, Hệ số Tải và Kỹ thuật Rehashing", "Hiện tượng Cụm chính (Primary Clustering) trong phương pháp Dò tuyến tính (Linear Probing) là gì và tại sao nó khiến hiệu năng tìm kiếm suy thoái nghiêm trọng về O(n)? Hãy giải thích ý nghĩa của Hệ số tải (Load Factor alpha = n/M) và mô tả quy trình Rehashing khi alpha vượt ngưỡng cho phép.", "1. Hiện tượng Cụm chính (Primary Clustering) trong Dò tuyến tính:\n- Trong Linear Probing, khi xung đột tại `h(k)`, thuật toán dò tuần tự các ô liền kề `(h(k) + 1) mod M`, `(h(k) + 2) mod M`,... Các phần tử va chạm liên kết lại thành từng dải ô đầy liên tiếp gọi là các cụm (clusters).\n- Hiệu ứng quả cầu tuyết xảy ra vì bất kỳ khóa mới nào băm rơi vào bất cứ vị trí nào bên trong một cụm dài K ô đều phải trượt hết chiều dài cụm để điền vào ngay ô trống cuối cụm, làm cụm tăng lên K + 1 ô (xác suất cụm phình to tỉ lệ thuận với chính độ dài của nó). Các cụm nhanh chóng sáp nhập thành siêu cụm khiến số bước dò tìm trung bình suy thoái từ O(1) về O(n).\n\n2. Hệ số tải (`alpha = n / M`) và quy trình Tái băm (Rehashing):\n- Hệ số tải `alpha` là tỉ số giữa số khóa hiện có `n` và kích thước bảng `M`. Trong địa chỉ mở, bắt buộc `alpha < 1` (thường khóa ngưỡng 0.5 đến 0.75) vì khi `alpha` tiến sát 1, chi phí dò tìm tăng vọt theo hàm `1 / (1 - alpha)^2`.\n- Khi `alpha` chạm ngưỡng, hệ thống kích hoạt Rehashing qua 3 bước: (1) Cấp phát bảng mới kích thước lớn hơn (thường gấp đôi hoặc số nguyên tố kế tiếp sau `2 * M`); (2) Quét toàn bộ các khóa hợp lệ ở bảng cũ, tính lại vị trí băm mới theo `M_moi` (tuyệt đối không chép nguyên chỉ số cũ vì phép chia dư đã đổi mẫu số) và chèn lại vào bảng mới; (3) Thay thế tham chiếu sang bảng mới. Dù một lần Rehash tốn O(n), tần suất thưa sau mỗi O(n) lần chèn giúp chi phí trung bình khấu hao vẫn đạt Amortized O(1).", "[\"Giải thích hiện tượng Primary Clustering (3.5đ): Mô tả cơ chế quả cầu tuyết của cụm dài làm tăng số bước dò tiệm cận O(n).\", \"Định nghĩa Load Factor và ngưỡng suy thoái (2.5đ): Nêu đúng công thức alpha = n/M và mối quan hệ với sự tăng vọt số bước dò khi alpha tiến gần 1.\", \"Quy trình Rehashing và phân tích Amortized O(1) (4.0đ): Mô tả đầy đủ việc cấp phát bảng mới lớn hơn, tính lại hàm băm toàn bộ khóa theo M mới và chứng minh chi phí khấu hao O(1).\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Phương pháp Băm kép (Double Hashing) giải quyết triệt để hiện tượng phân cụm như thế nào và hàm băm phụ thứ hai cần thỏa mãn điều kiện toán học gì đối với kích thước bảng M để đảm bảo duyệt qua được mọi vị trí trong bảng?"),
            CreatePracticeSeed("00000000-0000-0000-0005-000000000136", CourseCsd201Id, "00000000-0000-0000-0000-000000000568", RubricCsd201Id, "Nguyên lý Xây dựng Cây Mã hóa Huffman Tối ưu Tiền tố và Thuật toán Giải nén Bit", "Thuật toán mã hóa Huffman sử dụng cấu trúc dữ liệu nào để xây dựng cây mã hóa tối ưu? Hãy trình bày các bước xây dựng cây Huffman từ bảng tần số ký tự. Thế nào là Mã tiền tố (Prefix Code) và làm thế nào để giải mã (decode) một luồng bit nén bằng cây Huffman?", "1. Cấu trúc dữ liệu và quy trình tham lam dựng Cây Huffman:\n- Giải thuật sử dụng Hàng đợi ưu tiên cực tiểu (Min-Heap) sắp xếp các nút cây theo tần số xuất hiện tăng dần.\n- Quy trình xây dựng: (1) Tạo một nút lá độc lập cho mỗi ký tự kèm tần số của nó và đưa toàn bộ vào Min-Heap; (2) Lặp chừng nào Min-Heap còn nhiều hơn 1 nút: rút ra hai nút có tần số nhỏ nhất `left` và `right`, tạo một nút nội cha mới có tần số bằng tổng `left.freq + right.freq` nối với hai con đó, rồi đẩy nút cha trở lại Min-Heap; (3) Nút duy nhất còn lại cuối cùng là Gốc cây Huffman. Gán nhãn nhánh trái là bit `0` và nhánh phải là bit `1`: ký tự xuất hiện càng nhiều càng nằm gần gốc nên có từ mã bit ngắn nhất, đạt độ phức tạp dựng cây O(k log k) với k ký tự phân biệt.\n\n2. Bản chất Mã tiền tố (Prefix-Free Code) và giải thuật giải nén luồng bit:\n- Do mọi ký tự gốc đều chỉ nằm ở các nút lá của cây nhị phân (không có ký tự nào nằm ở nút nội trên đường đi tới ký tự khác), không tồn tại từ mã của bất kỳ ký tự nào là phần đầu (tiền tố) của từ mã ký tự khác. Tính chất Prefix-Free này giúp luồng bit nén giải mã tức thì, duy nhất mà không cần ký tự phân cách.\n- Khi giải nén: bắt đầu từ Gốc cây, đọc tuần tự từng bit (gặp `0` rẽ trái, gặp `1` rẽ phải); ngay khi chạm tới nút lá thì xuất ký tự tại lá đó và lập tức đặt lại con trỏ về Gốc cây để đọc tiếp bit kế tiếp cho đến hết luồng dữ liệu.", "[\"Thuật toán dựng cây dùng Min-Heap (4.0đ): Trình bày đủ quy trình rút 2 nút nhỏ nhất, gộp tổng tần số và chèn lại heap cho đến khi còn 1 nút.\", \"Định nghĩa Mã tiền tố (Prefix Code) (3.0đ): Giải thích tính chất không có từ mã nào là tiền tố của từ mã khác nhờ mọi ký tự nằm ở nút lá chống mơ hồ.\", \"Thuật toán duyệt bit giải mã (3.0đ): Mô tả chuẩn xác quá trình đi theo bit 0/1 từ gốc đến lá và quay lại gốc ngay khi giải mã xong một ký tự.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Nếu bảng tần số của n ký tự là dãy số Fibonacci (1, 1, 2, 3, 5, 8, ...), cây mã hóa Huffman thu được sẽ có hình dạng đặc biệt gì và độ dài từ mã của ký tự có tần số nhỏ nhất sẽ là bao nhiêu?"),
            // =========================================================================
            // 3. DBI202 — 36 CÂU HỎI KHO LUYỆN TẬP & THI THỬ (12 Easy, 14 Medium, 10 Hard)
            // =========================================================================
            CreatePracticeSeed("00000000-0000-0000-0000-000000000621", CourseDbi202Id, "00000000-0000-0000-0000-000000000661", RubricDbi202Id, "Khái niệm Hệ quản trị cơ sở dữ liệu (DBMS) và Kiến trúc 3 mức ANSI-SPARC", "Hệ quản trị cơ sở dữ liệu (DBMS) là gì? Hãy nêu 3 cấp độ trong kiến trúc ANSI-SPARC và giải thích tại sao kiến trúc này lại đảm bảo được tính độc lập dữ liệu (Data Independence)?", "Hệ quản trị cơ sở dữ liệu (DBMS) là phần mềm trung gian quản lý việc định nghĩa, tạo lập, lưu trữ, truy xuất và kiểm soát an ninh, toàn vẹn của cơ sở dữ liệu. Kiến trúc ANSI-SPARC gồm 3 mức: (1) Mức ngoài (External/View Level) là khung nhìn dữ liệu của từng nhóm người dùng; (2) Mức khái niệm (Conceptual/Logical Level) mô tả toàn bộ cấu trúc dữ liệu, mối quan hệ và ràng buộc nghiệp vụ tổng thể của doanh nghiệp; (3) Mức trong (Internal/Physical Level) mô tả cách dữ liệu được tổ chức lưu trữ vật lý trên đĩa (tệp tin, chỉ mục, khối lưu trữ). Kiến trúc này đảm bảo tính độc lập dữ liệu thông qua 2 cấp: Độc lập dữ liệu vật lý (Physical Data Independence - thay đổi mức trong như tạo thêm Index không ảnh hưởng đến mức khái niệm và ứng dụng) và Độc lập dữ liệu logic (Logical Data Independence - thêm thực thể, thuộc tính ở mức khái niệm không làm thay đổi các View ngoài hiện có).", "[\"Định nghĩa DBMS & Vai trò cốt lõi (3.0đ): Nêu rõ khái niệm DBMS là hệ thống phần mềm quản lý, lưu trữ, truy vấn và bảo đảm an toàn dữ liệu.\", \"Trình bày 3 cấp độ kiến trúc ANSI-SPARC (4.0đ): Mô tả chính xác đặc điểm và ranh giới của Mức ngoài (External), Mức khái niệm (Conceptual) và Mức trong (Internal).\", \"Phân tích tính độc lập dữ liệu (Logical & Physical) (3.0đ): Giải thích rõ ràng cơ chế phân tách tầng giúp ứng dụng không bị phụ thuộc vào cấu trúc lưu trữ đĩa hay mở rộng schema.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Nếu người dùng thay đổi chỉ mục (Index) hoặc cấu trúc lưu trữ tệp trên đĩa cứng thì các ứng dụng bên ngoài có bị ảnh hưởng hay phải biên dịch lại không? Thuộc tính độc lập dữ liệu nào thể hiện điều này?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000622", CourseDbi202Id, "00000000-0000-0000-0000-000000000662", RubricDbi202Id, "Phân biệt Lược đồ quan hệ (Schema) và Thể hiện quan hệ (Instance)", "Trong mô hình quan hệ, hãy phân biệt giữa Lược đồ quan hệ (Relation Schema) và Thể hiện quan hệ (Relation Instance). Cho ví dụ cụ thể để minh họa sự khác nhau về tính biến đổi theo thời gian giữa hai khái niệm này.", "Lược đồ quan hệ (Relation Schema) là thiết kế cấu trúc tĩnh bao gồm tên quan hệ, danh sách các thuộc tính (cột) kèm miền giá trị (kiểu dữ liệu) và các ràng buộc toàn vẹn; Schema ít khi thay đổi trong suốt vòng đời hoạt động của hệ thống (ví dụ: Student(StudentID: INT, FullName: NVARCHAR(100), GPA: FLOAT)). Ngược lại, Thể hiện quan hệ (Relation Instance) là trạng thái dữ liệu động tại một thời điểm cụ thể, bao gồm tập hợp các bộ dữ liệu (bản ghi/dòng) hiện có trong bảng. Khi người dùng thực hiện thao tác DML như INSERT, UPDATE, DELETE thì chỉ làm thay đổi Thể hiện quan hệ (Instance) mà không làm biến đổi Lược đồ (Schema). Lược đồ chỉ thay đổi khi quản trị viên thực thi lệnh DDL như ALTER TABLE thêm hoặc xóa cột.", "[\"Định nghĩa chính xác Relation Schema (3.0đ): Nêu rõ Schema là cấu trúc tĩnh, metadata mô tả bảng, cột, kiểu dữ liệu và ràng buộc.\", \"Định nghĩa chính xác Relation Instance (3.5đ): Nêu rõ Instance là trạng thái snapshot tập hợp các dòng dữ liệu cụ thể tại một thời điểm.\", \"So sánh tính biến đổi và ví dụ minh họa (3.5đ): Đưa ra ví dụ thực tế chỉ rõ DDL thay đổi Schema còn DML thay đổi Instance một cách chính xác.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Khi một câu lệnh INSERT hoặc DELETE được thực thi thành công trên bảng, thành phần nào bị thay đổi: Schema hay Instance?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000623", CourseDbi202Id, "00000000-0000-0000-0000-000000000662", RubricDbi202Id, "Các phép toán cơ bản trong Đại số quan hệ: Selection và Projection", "Hãy giải thích bản chất xử lý, mục đích và tên ký hiệu đặc trưng của hai phép toán cơ bản trong Đại số quan hệ là Phép chọn (Selection) và Phép chiếu (Projection). Hai phép toán này tương ứng với những mệnh đề nào trong câu truy vấn SELECT của SQL?", "Trong Đại số quan hệ, Phép chọn (Selection, ký hiệu bằng chữ cái Hy Lạp sigma) là phép lọc dữ liệu theo chiều ngang, trả về tập các bộ dữ liệu thỏa mãn một điều kiện vị từ xác định và giữ nguyên số lượng cột của quan hệ gốc; phép toán này tương ứng trực tiếp với mệnh đề WHERE trong SQL. Ngược lại, Phép chiếu (Projection, ký hiệu bằng chữ cái Hy Lạp pi) là phép lọc dữ liệu theo chiều dọc, trích xuất danh sách các thuộc tính được chỉ định từ quan hệ và loại bỏ các cột không cần thiết, tương ứng với danh sách cột nêu sau mệnh đề SELECT trong SQL. Điểm khác biệt quan trọng là Đại số quan hệ thuần túy xây dựng trên lý thuyết tập hợp (Set Semantics), trong đó một tập hợp không chấp nhận phần tử trùng lặp nên phép chiếu luôn ngầm định khử dòng trùng; trái lại, SQL vận hành theo ngữ nghĩa đa tập (Bag Semantics) để tránh chi phí sắp xếp khử trùng đắt đỏ, do đó chỉ loại bỏ bản ghi trùng khi lập trình viên chỉ định tường minh từ khóa DISTINCT.", "[\"Bản chất xử lý của Phép chọn (Selection) (3.5đ): Giải thích đúng cơ chế lọc ngang theo điều kiện dòng (ký hiệu sigma) và sự tương ứng với mệnh đề WHERE trong SQL.\", \"Bản chất xử lý của Phép chiếu (Projection) (3.5đ): Giải thích đúng cơ chế trích xuất cột theo chiều dọc (ký hiệu pi) và sự tương ứng với danh sách cột của mệnh đề SELECT.\", \"Phân biệt Set Semantics vs Bag Semantics (3.0đ): Giải thích được cơ chế loại bỏ trùng lặp trong đại số quan hệ hình thức so với cơ chế đa tập mặc định của SQL.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Tại sao trong đại số quan hệ thuần túy, phép chiếu luôn tự động loại bỏ các dòng trùng lặp, trong khi câu lệnh SELECT của SQL lại giữ lại bản ghi trùng lặp trừ khi có từ khóa DISTINCT?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000624", CourseDbi202Id, "00000000-0000-0000-0000-000000000664", RubricDbi202Id, "Phân loại thuộc tính trong Sơ đồ Thực thể Kết hợp (ERD)", "Trong mô hình ERD, hãy phân biệt: Thuộc tính đơn (Simple), Thuộc tính phức hợp (Composite), Thuộc tính đa trị (Multi-valued) và Thuộc tính phái sinh (Derived). Cho ví dụ thực tế cho từng loại.", "(1) Thuộc tính đơn (Simple): Không thể phân chia nhỏ hơn, ví dụ: Tuổi, Giới tính, Điểm số. (2) Thuộc tính phức hợp (Composite): Bao gồm nhiều thành phần con có ý nghĩa độc lập, ví dụ: Họ tên (gồm Họ, Tên lót, Tên) hoặc Địa chỉ (gồm Số nhà, Tên đường, Phường, Thành phố). (3) Thuộc tính đa trị (Multi-valued, ký hiệu hình oval nét đôi): Có thể chứa đồng thời nhiều giá trị cho một thực thể duy nhất, ví dụ: Số điện thoại hoặc Kỹ năng của nhân viên. (4) Thuộc tính phái sinh (Derived, ký hiệu hình oval nét đứt): Giá trị không cần lưu trữ cứng mà được tính toán suy luận từ thuộc tính khác, ví dụ: Tuổi được suy ra từ Ngày sinh (CurrentDate - DateOfBirth). Khi chuyển đổi sang CSDL quan hệ, để bảo đảm 1NF, thuộc tính đa trị phải được tách thành một bảng phụ riêng chứa khóa chính của thực thể cha kèm giá trị thuộc tính đa trị, tạo thành khóa chính phức hợp.", "[\"Phân biệt Thuộc tính Đơn và Thuộc tính Phức hợp (3.0đ): Nêu đúng khái niệm, khả năng chia nhỏ của thuộc tính và đưa ví dụ thực tế chuẩn mực.\", \"Phân biệt Thuộc tính Đa trị và Thuộc tính Phái sinh (3.5đ): Nêu đúng ký hiệu quy ước trong ERD, đặc điểm chứa nhiều giá trị và cơ chế tính toán giá trị phái sinh.\", \"Quy tắc ánh xạ thuộc tính đa trị sang bảng quan hệ (3.5đ): Giải thích rõ việc tách thành bảng phụ riêng để bảo toàn dạng chuẩn 1 (1NF).\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Khi chuyển đổi sơ đồ ERD sang mô hình cơ sở dữ liệu quan hệ, thuộc tính đa trị (như số điện thoại của khách hàng) được xử lý như thế nào để không vi phạm dạng chuẩn 1 (1NF)?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000625", CourseDbi202Id, "00000000-0000-0000-0000-000000000664", RubricDbi202Id, "Bội số kết hợp (Multiplicity) trong mô hình ERD: 1:1, 1:N và M:N", "Bội số kết hợp (Multiplicity) trong mô hình ERD là gì? Hãy trình bày 3 loại mối kết hợp phổ biến (1:1, 1:N, M:N) và cho ví dụ thực tế tương ứng trong một hệ thống quản lý trường đại học.", "Bội số kết hợp (Multiplicity) xác định số lượng thực thể của một tập thực thể có thể liên kết với một thực thể của tập thực thể khác thông qua mối quan hệ. (1) Quan hệ Một - Một (1:1): Mỗi thực thể bên A liên kết với tối đa 1 thực thể bên B và ngược lại, ví dụ: Mỗi Trưởng khoa quản lý 1 Khoa và mỗi Khoa chỉ do 1 Trưởng khoa đứng đầu. (2) Quan hệ Một - Nhiều (1:N): Một thực thể bên A liên kết với nhiều thực thể bên B, nhưng mỗi thực thể B chỉ thuộc về duy nhất 1 thực thể A, ví dụ: Một Khoa có nhiều Giảng viên công tác, nhưng mỗi Giảng viên chỉ thuộc 1 Khoa. Khi ánh xạ sang quan hệ vật lý, khóa chính của bên 1 (DepartmentID) sẽ được đưa sang bên N (bảng Lecturer) làm khóa ngoại để lưu trữ tham chiếu không bị dư thừa. (3) Quan hệ Nhiều - Nhiều (M:N): Một thực thể bên A liên kết với nhiều bên B và ngược lại, ví dụ: Một Sinh viên đăng ký nhiều Môn học và một Môn học có nhiều Sinh viên theo học.", "[\"Khái niệm Multiplicity trong ERD (3.0đ): Nêu đúng định nghĩa bản số và vai trò ràng buộc số lượng thể hiện trong mối quan hệ.\", \"Trình bày chi tiết 3 loại quan hệ kèm ví dụ (4.0đ): Giải thích rõ ràng 1:1, 1:N, M:N với các ví dụ thực tiễn trong môi trường quản lý đào tạo.\", \"Quy tắc đặt Khóa ngoại cho quan hệ 1:N (3.0đ): Giải thích chính xác lý do đặt khóa chính bên 1 sang bảng bên N làm khóa ngoại.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Trong quan hệ 1:N giữa Khoa (Department) và Giảng viên (Lecturer), khi ánh xạ sang bảng quan hệ vật lý, khóa ngoại (Foreign Key) sẽ được đặt ở bảng nào? Tại sao?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000626", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", RubricDbi202Id, "Khái niệm Khóa chính (Primary Key) và Khóa ngoại (Foreign Key)", "Khóa chính (Primary Key) và Khóa ngoại (Foreign Key) là gì? Khóa chính bảo đảm quy tắc toàn vẹn nào và Khóa ngoại bảo đảm quy tắc toàn vẹn nào trong mô hình quan hệ?", "Khóa chính (Primary Key) là một hoặc một nhóm thuộc tính được chọn để định danh duy nhất mỗi bộ (dòng) trong bảng; nó bảo đảm Quy tắc toàn vẹn thực thể (Entity Integrity Constraint) - giá trị khóa chính phải duy nhất và tuyệt đối cấm mang giá trị NULL. Khóa ngoại (Foreign Key) là một hoặc một tập thuộc tính trong một bảng tham chiếu trực tiếp đến khóa chính (hoặc khóa ứng viên duy nhất) của một bảng khác (hoặc chính bảng đó); nó bảo đảm Quy tắc toàn vẹn tham chiếu (Referential Integrity Constraint) - mọi giá trị trong cột khóa ngoại phải tồn tại trong cột khóa chính được tham chiếu, HOẶC mang giá trị NULL. Khóa ngoại mang giá trị NULL thể hiện rằng thực thể hiện tại chưa có mối liên kết với thực thể cha nào (ví dụ: một nhân viên mới vào công ty chưa được phân bổ về phòng ban nào, nên DepartmentID của nhân viên đó là NULL).", "[\"Định nghĩa Khóa chính & Toàn vẹn thực thể (3.5đ): Nêu đúng khái niệm Primary Key, tính duy nhất và quy tắc bắt buộc NOT NULL.\", \"Định nghĩa Khóa ngoại & Toàn vẹn tham chiếu (3.5đ): Nêu đúng khái niệm Foreign Key, quan hệ tham chiếu và bảo vệ tính nhất quán liên bảng.\", \"Ý nghĩa và quy định giá trị NULL (3.0đ): Giải thích chính xác PK cấm NULL và FK được phép mang NULL biểu thị chưa gán liên kết.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, "Một khóa chính có được phép nhận giá trị NULL không? Một khóa ngoại có được phép nhận giá trị NULL không? Giải thích ý nghĩa thực tế khi khóa ngoại mang giá trị NULL."),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000627", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", RubricDbi202Id, "Các toán tử lọc dữ liệu BETWEEN, IN, LIKE (Wildcards) và phân trang OFFSET-FETCH trong T-SQL", "Trong mệnh đề WHERE của MS SQL Server, hãy giải thích bản chất hoạt động của các cơ chế lọc và phân trang dữ liệu sau: (1) Toán tử khoảng BETWEEN a AND b có bao gồm hai giá trị đầu mút a và b hay không? (2) Ý nghĩa của các ký tự đại diện phần trăm, dấu gạch dưới và cặp ngoặc vuông trong toán tử LIKE khác nhau như thế nào, và làm cách nào để tìm chuỗi văn bản có chứa chính ký tự phần trăm thực sự thông qua từ khóa ESCAPE? (3) Nguyên lý phân trang tập kết quả bằng cặp mệnh đề OFFSET và FETCH đi kèm ORDER BY vận hành ra sao?", "Thứ nhất, toán tử BETWEEN a AND b mang tính chất bao gồm cả hai đầu mút (Inclusive), tương đương hoàn toàn với điều kiện lớn hơn hoặc bằng a đồng thời nhỏ hơn hoặc bằng b, trong đó mốc nhỏ phải đặt trước mốc lớn. Toán tử IN kiểm tra giá trị bằng với ít nhất một phần tử trong danh sách theo phép tuyển OR, nên có lẫn NULL vẫn giữ được các dòng khớp TRUE; ngược lại NOT IN tương đương chuỗi phép hội AND kiểm tra khác từng phần tử, mà phép so sánh khác NULL luôn trả về UNKNOWN làm toàn bộ biểu thức hội không bao giờ đạt TRUE và trả về 0 dòng. Thứ hai, trong toán tử LIKE của T-SQL, dấu phần trăm đại diện cho chuỗi bất kỳ gồm không, một hoặc nhiều ký tự; dấu gạch dưới đại diện cho đúng một ký tự đơn lẻ; còn cặp ngoặc vuông khớp một ký tự thuộc dải hoặc tập ký tự chỉ định. Khi cần tìm chính ký tự phần trăm hoặc gạch dưới thật trong dữ liệu như chuỗi khuyến mãi giảm 50 phần trăm, ta khai báo thêm một ký tự thoát thông qua từ khóa ESCAPE đặt ngay trước ký tự đó để báo cho SQL Server hiểu đây là ký tự văn bản thông thường. Thứ ba, cơ chế phân trang OFFSET - FETCH bắt buộc phải đi kèm mệnh đề ORDER BY nhằm cố định thứ tự dòng; để lấy trang thứ PageNumber với kích thước PageSize dòng mỗi trang, mệnh đề OFFSET sẽ bỏ qua số dòng bằng PageNumber trừ 1 rồi nhân với PageSize, sau đó mệnh đề FETCH NEXT trích xuất đúng PageSize dòng kế tiếp.", "[\"Giải thích tính bao gồm 2 đầu mút của BETWEEN và lưu ý NOT IN với NULL (3.5đ): Khẳng định BETWEEN bao gồm cả hai cận đầu mút và giải thích rõ logic 3 giá trị UNKNOWN khiến NOT IN có chứa NULL trả về tập rỗng.\", \"Phân biệt các ký tự đại diện trong LIKE và cơ chế thoát ký tự ESCAPE (3.5đ): Nêu đúng ý nghĩa dấu phần trăm, gạch dưới, ngoặc vuông trong T-SQL và giải thích đúng cách dùng từ khóa ESCAPE để tìm ký tự đặc biệt thật.\", \"Trình bày nguyên lý phân trang bằng OFFSET - FETCH đi kèm ORDER BY (3.0đ): Giải thích rõ vai trò bắt buộc phải có mệnh đề ORDER BY và công thức tính số dòng cần bỏ qua theo thứ tự trang.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Tại sao khi danh sách đối chiếu của toán tử NOT IN có lẫn dù chỉ một giá trị NULL thì câu truy vấn luôn trả về tập kết quả rỗng không có dòng nào, trong khi toán tử IN có lẫn giá trị NULL vẫn trả về được các dòng khớp với những giá trị xác định còn lại?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000628", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", RubricDbi202Id, "Xử lý giá trị NULL trong SQL và toán tử IS NULL / IS NOT NULL", "Giá trị NULL trong cơ sở dữ liệu quan hệ mang ý nghĩa gì? Tại sao trong SQL chúng ta bắt buộc phải sử dụng toán tử IS NULL hoặc IS NOT NULL để kiểm tra dữ liệu khuyết thiếu thay vì dùng phép so sánh bằng hoặc phép so sánh khác thông thường?", "Giá trị NULL trong CSDL quan hệ biểu thị trạng thái chưa xác định (Unknown), dữ liệu bị khuyết thiếu (Missing) hoặc không áp dụng được (Not Applicable); NULL hoàn toàn khác với con số 0 và cũng không phải là chuỗi ký tự rỗng. SQL vận hành dựa trên Hệ logic ba giá trị (Three-Valued Logic) gồm TRUE, FALSE và UNKNOWN. Mọi phép toán so sánh đại số thông thường như bằng, khác, lớn hơn hay nhỏ hơn khi đặt cạnh NULL (kể cả so sánh NULL bằng NULL) đều không trả về TRUE hay FALSE mà luôn trả về trạng thái UNKNOWN. Trong khi đó, mệnh đề lọc WHERE chỉ giữ lại những bản ghi có biểu thức điều kiện đánh giá ra đúng giá trị TRUE và loại bỏ cả FALSE lẫn UNKNOWN. Do vậy, nếu viết điều kiện lọc cột Lương bằng NULL bằng dấu bằng thông thường, toàn bộ các dòng đều nhận giá trị UNKNOWN và câu truy vấn luôn trả về tập rỗng 0 dòng. Chuẩn ANSI SQL cung cấp vị từ chuyên biệt IS NULL và IS NOT NULL để kiểm tra trạng thái khuyết thiếu và trả về kết quả boolean TRUE hoặc FALSE tường minh.", "[\"Bản chất của giá trị NULL trong RDBMS (3.0đ): Nêu đúng NULL là dữ liệu chưa biết hoặc không áp dụng, phân biệt rõ với số 0 và chuỗi rỗng.\", \"Nguyên lý Logic 3 giá trị (Three-Valued Logic) (4.0đ): Giải thích rõ kết quả UNKNOWN khi dùng phép toán so sánh bằng hoặc khác thông thường với NULL.\", \"Toán tử chuẩn IS NULL và hành vi lọc của mệnh đề WHERE (3.0đ): Phân tích vì sao so sánh bằng NULL trong mệnh đề WHERE trả về 0 dòng và vai trò của vị từ IS NULL.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Khi lập trình viên đặt điều kiện lọc cột Lương bằng NULL thông qua dấu bằng thông thường trong mệnh đề WHERE, biểu thức đó sẽ đánh giá ra giá trị logic gì và tập kết quả trả về của câu truy vấn sẽ như thế nào?"),
            CreatePracticeSeed("00000000-0000-0000-0000-000000000629", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", RubricDbi202Id, "Định nghĩa Dạng chuẩn 1 (1NF) và điều kiện nguyên tử của thuộc tính", "Thế nào là một quan hệ đạt Dạng chuẩn 1 (First Normal Form - 1NF)? Hãy chỉ ra hai trường hợp vi phạm dạng chuẩn 1 thường gặp trong thiết kế cơ sở dữ liệu và cách khắc phục.", "Một lược đồ quan hệ đạt Dạng chuẩn 1 (1NF) khi và chỉ khi: (1) Mọi thuộc tính đều mang giá trị nguyên tử (Atomic value), nghĩa là mỗi ô giao giữa dòng và cột chỉ chứa duy nhất một giá trị đơn lẻ, không thể và không cần phân chia nhỏ hơn; (2) Không tồn tại nhóm thuộc tính lặp lại (Repeating groups) hoặc mảng/danh sách giá trị trong cùng một cột. Hai trường hợp vi phạm phổ biến: (a) Lưu danh sách giá trị trong một ô (ví dụ cột Phones chứa '0901234567, 0987654321'); khắc phục bằng cách tách mỗi số điện thoại thành một dòng riêng hoặc tạo bảng phụ liên kết. (b) Thiết kế các cột lặp lại để chứa danh sách (ví dụ Phone1, Phone2, Phone3); khắc phục bằng cách chuẩn hóa đưa về bảng phụ có khóa ngoại trỏ về bảng chính. Cột lưu danh sách ngăn cách bằng dấu phẩy vi phạm nghiêm trọng tính nguyên tử của 1NF vì gây khó khăn khi tìm kiếm, indexing và làm mất tính toàn vẹn dữ liệu.", "[\"Định nghĩa Dạng chuẩn 1 (1NF) (3.5đ): Nêu rõ điều kiện tính nguyên tử (Atomicity) và cấm mảng/nhóm lặp trong thuộc tính.\", \"Chỉ ra 2 trường hợp vi phạm điển hình (3.5đ): Nhận diện đúng trường hợp chứa chuỗi ghép giá trị và trường hợp tạo cột lặp Phone1, Phone2.\", \"Giải pháp chuẩn hóa khắc phục (3.0đ): Trình bày cách tách bảng phụ để chuẩn hóa về 1NF chuẩn mực.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Một cột lưu trữ chuỗi JSON hoặc danh sách các giá trị ngăn cách bởi dấu phẩy như 'Hà Nội, Đà Nẵng, TP.HCM' có vi phạm 1NF không?"),
            CreatePracticeSeed("00000000-0000-0000-0000-00000000062a", CourseDbi202Id, "00000000-0000-0000-0000-000000000667", RubricDbi202Id, "Định nghĩa 4 thuộc tính ACID trong Giao dịch (Transaction)", "Giao dịch (Transaction) trong cơ sở dữ liệu là gì? Hãy nêu tên và giải thích ngắn gọn ý nghĩa của 4 thuộc tính ACID bảo đảm độ tin cậy của giao dịch.", "Giao dịch (Transaction) là một đơn vị công việc logic bao gồm một chuỗi các thao tác truy xuất hoặc cập nhật CSDL phải được thực thi như một khối duy nhất. 4 thuộc tính ACID gồm: (1) Atomicity (Tính nguyên tố): Nguyên lý 'Tất cả hoặc không có gì' (All-or-Nothing) - toàn bộ các lệnh trong giao dịch phải thành công trọn vẹn, nếu có bất kỳ thao tác nào thất bại thì toàn bộ giao dịch phải được khôi phục (Rollback) về trạng thái ban đầu. (2) Consistency (Tính nhất quán): Giao dịch đưa CSDL từ một trạng thái hợp lệ này sang một trạng thái hợp lệ khác, bảo đảm không vi phạm bất kỳ ràng buộc toàn vẹn nào. (3) Isolation (Tính cô lập): Các giao dịch thực thi đồng thời không được nhìn thấy dữ liệu trung gian chưa hoàn tất của nhau. (4) Durability (Tính bền vững): Một khi giao dịch đã Commit thành công, kết quả thay đổi sẽ được lưu trữ vĩnh viễn trên đĩa kể cả khi hệ thống bị sập nguồn đột ngột. Trong bài toán chuyển tiền bị mất điện, thuộc tính Atomicity kết hợp cơ chế ghi nhật ký phục hồi (WAL/Undo Log) sẽ tự động rollback thao tác trừ tiền, bảo toàn số dư cho khách hàng.", "[\"Định nghĩa Giao dịch (Transaction) (2.5đ): Nêu đúng bản chất đơn vị công việc logic không thể tách rời.\", \"Giải thích chi tiết 4 thuộc tính ACID (4.5đ): Trình bày rõ ràng ý nghĩa của Atomicity, Consistency, Isolation, Durability.\", \"Vận dụng vào kịch bản sập nguồn chuyển tiền (3.0đ): Chỉ ra chính xác Atomicity bảo đảm cơ chế Rollback chống mất mát tiền.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, "Trong trường hợp hệ thống chuyển tiền giữa 2 tài khoản ngân hàng, nếu tiền đã bị trừ ở tài khoản người gửi nhưng máy chủ bị mất điện đột ngột trước khi cộng tiền vào tài khoản người nhận, thuộc tính ACID nào sẽ bảo vệ hệ thống?"),
            CreatePracticeSeed("00000000-0000-0000-0000-00000000062b", CourseDbi202Id, "00000000-0000-0000-0000-000000000666", RubricDbi202Id, "Khái niệm và mục đích sử dụng Khung nhìn (View) trong cơ sở dữ liệu", "View trong cơ sở dữ liệu là gì? Nêu 3 lợi ích quan trọng nhất của việc sử dụng View đối với ứng dụng và bảo mật dữ liệu.", "View là một bảng ảo (Virtual Table) được định nghĩa dựa trên một câu lệnh truy vấn SQL (SELECT). Một Standard View không trực tiếp lưu trữ dữ liệu các dòng trên đĩa cứng mà chỉ lưu trữ câu lệnh định nghĩa (Definition Metadata) trong Data Dictionary của hệ thống. Khi người dùng thực thi lệnh SELECT từ View, DBMS sẽ kết hợp (Merge) câu lệnh của người dùng với định nghĩa gốc của View để truy vấn trực tiếp từ các bảng vật lý cơ sở (Base Tables). 3 lợi ích quan trọng: (1) Đơn giản hóa truy vấn phức tạp: Đóng gói các phép JOIN nhiều bảng, Subquery, biểu thức tính toán phức tạp thành một bảng ảo dễ gọi; (2) Tăng cường bảo mật: Cho phép phân quyền người dùng chỉ được xem các cột hoặc dòng nhất định (ví dụ giấu cột PasswordHash, Salary) mà không cần cấp quyền truy cập toàn bộ bảng gốc; (3) Tính độc lập dữ liệu logic: Khi cấu trúc bảng cơ sở thay đổi nhẹ, ta có thể sửa lại định nghĩa View để giữ nguyên giao diện dữ liệu cho các ứng dụng client mà không cần sửa code ứng dụng.", "[\"Định nghĩa chính xác Khung nhìn (View) (3.0đ): Nêu rõ View là bảng ảo lưu câu lệnh truy vấn, không lưu dữ liệu vật lý riêng (với Standard View).\", \"Cơ chế hoạt động khi truy vấn View (3.5đ): Giải thích được cơ chế Query Merger/Expansion đọc dữ liệu từ các Base Tables.\", \"Trình bày 3 lợi ích cốt lõi (Query, Security, Independence) (3.5đ): Nêu rõ ràng và phân tích đúng giá trị của View trong đơn giản hóa, an ninh dữ liệu và độc lập logic.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Một View chuẩn (Standard View) có thực sự lưu trữ dữ liệu các dòng trên đĩa cứng như một bảng vật lý thông thường không? Dữ liệu hiển thị từ View được lấy từ đâu khi người dùng gọi lệnh SELECT?"),
            CreatePracticeSeed("00000000-0000-0000-0000-00000000062c", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", RubricDbi202Id, "Phân biệt ngôn ngữ DDL và DML trong SQL", "Ngôn ngữ DDL (Data Definition Language) và DML (Data Manipulation Language) trong SQL khác nhau như thế nào? Hãy liệt kê ít nhất 3 lệnh tiêu biểu cho mỗi nhóm.", "DDL (Data Definition Language - Ngôn ngữ định nghĩa dữ liệu) được sử dụng để tạo lập, sửa đổi và hủy bỏ cấu trúc các đối tượng trong cơ sở dữ liệu (Database, Table, View, Index, Trigger, Stored Procedure). Các lệnh tiêu biểu: CREATE, ALTER, DROP, TRUNCATE. Khi chạy lệnh DDL, hệ thống cập nhật siêu dữ liệu (Metadata/Catalog) và thường tự động Commit ngầm định. Ngược lại, DML (Data Manipulation Language - Ngôn ngữ thao tác dữ liệu) được sử dụng để truy xuất và sửa đổi dữ liệu thực tế bên trong các bảng mà không làm thay đổi cấu trúc bảng. Các lệnh tiêu biểu: SELECT, INSERT, UPDATE, DELETE. Lệnh DML có thể kiểm soát hoàn toàn bằng Transaction (COMMIT/ROLLBACK). Câu lệnh TRUNCATE TABLE thuộc nhóm DDL (mặc dù mang mục đích xóa dữ liệu) vì nó hoạt động bằng cách giải phóng (deallocate) toàn bộ các trang dữ liệu (Data Pages) ở mức cấu trúc lưu trữ của bảng, ghi log tối thiểu trên trang chứ không quét và xóa từng dòng dữ liệu như lệnh DML DELETE.", "[\"Khái niệm và đặc điểm của DDL (3.5đ): Nêu đúng DDL thao tác trên Metadata/cấu trúc và liệt kê CREATE, ALTER, DROP.\", \"Khái niệm và đặc điểm của DML (3.5đ): Nêu đúng DML thao tác trên dữ liệu bộ và liệt kê SELECT, INSERT, UPDATE, DELETE.\", \"Bản chất phân loại của TRUNCATE TABLE (3.0đ): Giải thích chính xác vì sao TRUNCATE là DDL dựa trên cơ chế deallocate data pages và ghi log.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, "Câu lệnh TRUNCATE TABLE thuộc nhóm DDL hay DML? Tại sao?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000113", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", RubricDbi202Id, "Phân biệt Phép kết nối trong (INNER JOIN) và Phép kết nối ngoài (OUTER JOIN)", "Phân biệt sự khác nhau về bản chất xử lý dữ liệu giữa INNER JOIN và các loại OUTER JOIN (LEFT, RIGHT, FULL OUTER JOIN). Trong trường hợp nào chúng ta bắt buộc phải sử dụng LEFT OUTER JOIN thay vì INNER JOIN?", "INNER JOIN chỉ giữ lại các cặp dòng từ hai bảng có giá trị khóa kết nối khớp nhau hoàn toàn theo điều kiện ON; các dòng không tìm thấy bản ghi khớp ở bảng đối chiếu sẽ bị loại bỏ khỏi kết quả. Ngược lại, OUTER JOIN được thiết kế để giữ lại cả những dòng không khớp: (1) LEFT OUTER JOIN giữ lại toàn bộ dòng của bảng bên trái; nếu không có bản ghi khớp ở bảng bên phải, các cột của bảng phải sẽ được điền giá trị NULL; (2) RIGHT OUTER JOIN giữ lại toàn bộ dòng của bảng phải; (3) FULL OUTER JOIN giữ lại toàn bộ dòng của cả hai bảng, vị trí không khớp ở bên nào sẽ điền NULL ở bên đó. Chúng ta bắt buộc phải dùng LEFT JOIN khi muốn truy vấn toàn diện danh sách thực thể chính kể cả khi chúng chưa có liên kết nghiệp vụ ở bảng phụ (ví dụ: 'Liệt kê danh sách tất cả khách hàng kèm số lượng đơn đã mua, bao gồm cả những khách hàng mới chưa mua đơn hàng nào'). Với INNER JOIN, khách hàng chưa mua hàng sẽ bị loại bỏ hoàn toàn; với LEFT JOIN, khách hàng đó vẫn hiển thị trên kết quả và các cột OrderID, OrderDate sẽ mang giá trị NULL.", "[\"Bản chất xử lý của INNER JOIN (3.0đ): Giải thích rõ ràng cơ chế chỉ lấy các dòng khớp điều kiện ở cả hai bảng.\", \"Cơ chế xử lý của các loại OUTER JOIN (4.0đ): Phân tích chính xác cách LEFT, RIGHT, FULL OUTER JOIN giữ lại dòng và điền giá trị NULL.\", \"Tình huống nghiệp vụ bắt buộc dùng LEFT JOIN (3.0đ): Đưa ra kịch bản khách hàng chưa mua hàng và so sánh kết quả cụ thể.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Nếu một khách hàng chưa từng mua đơn hàng nào, câu truy vấn dùng INNER JOIN giữa Customers và Orders có hiển thị thông tin khách hàng đó không? Còn LEFT JOIN sẽ hiển thị như thế nào?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000114", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", RubricDbi202Id, "Phân biệt mệnh đề WHERE và HAVING khi kết hợp với GROUP BY", "Trong câu truy vấn SQL có sử dụng mệnh đề GROUP BY, hãy phân biệt sự khác nhau giữa mệnh đề WHERE và mệnh đề HAVING về: thời điểm thực thi, đối tượng tác động và việc sử dụng hàm tổng hợp (Aggregate Functions). Nêu một tình huống thực tế cần kết hợp cả WHERE lẫn HAVING trong cùng một truy vấn thống kê và giải thích luồng lọc dữ liệu qua từng bước.", "Sự khác biệt cốt lõi giữa WHERE và HAVING nằm ở ba khía cạnh: (1) Thời điểm thực thi: mệnh đề WHERE chạy trước khi phép gom nhóm GROUP BY diễn ra, còn mệnh đề HAVING chạy sau khi các nhóm đã được hình thành và tính toán tổng hợp xong. (2) Đối tượng tác động: WHERE lọc trực tiếp trên từng dòng bản ghi đơn lẻ từ bảng nguồn, trong khi HAVING lọc trên từng nhóm dữ liệu tổng hợp. (3) Hàm tổng hợp: WHERE tuyệt đối không được chứa trực tiếp các hàm tổng hợp như SUM, AVG, COUNT, MAX, MIN, còn HAVING chuyên dùng để đặt điều kiện lọc trên kết quả của các hàm tổng hợp đó. Chẳng hạn trong bài toán thống kê các phòng ban có mức lương trung bình trên 20 triệu đồng nhưng chỉ tính những nhân viên đang làm việc chính thức: bước đầu tiên mệnh đề WHERE quét bảng Nhân viên và loại bỏ ngay các nhân viên đã nghỉ việc hoặc thử việc; bước thứ hai GROUP BY gom những nhân viên chính thức còn lại theo từng Mã phòng ban và tính trung bình lương AVG; bước thứ ba HAVING giữ lại các nhóm phòng ban có mức lương trung bình vượt 20 triệu. Nếu đặt nhầm điều kiện lọc Mã phòng ban vào HAVING, truy vấn vẫn chạy được vì cột đó có trong GROUP BY, nhưng hệ thống phải gom nhóm toàn bộ bảng trước rồi mới loại bỏ nhóm thừa, làm tốn thêm rất nhiều CPU và bộ nhớ RAM.", "[\"So sánh Thời điểm thực thi & Đối tượng tác động (3.5đ): Chỉ rõ WHERE chạy trước để lọc dòng đơn lẻ; HAVING chạy sau GROUP BY để lọc các nhóm dữ liệu.\", \"Quy tắc sử dụng Hàm tổng hợp (3.5đ): Giải thích rõ ràng WHERE không chứa trực tiếp hàm tổng hợp, còn HAVING chuyên dùng lọc trên hàm tổng hợp.\", \"Tình huống thực tế & Phân tích tối ưu hiệu năng (3.0đ): Trình bày rõ luồng lọc từng bước trên tình huống thực tế và giải thích hậu quả lãng phí tài nguyên khi đẩy điều kiện lọc dòng xuống HAVING.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Điều gì xảy ra nếu lập trình viên đặt điều kiện lọc theo Mã phòng ban ngay trong mệnh đề HAVING thay vì đặt ở mệnh đề WHERE? Truy vấn thống kê đó có thực thi được không và gây lãng phí hiệu năng như thế nào?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000115", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", RubricDbi202Id, "Phân biệt hàm COUNT(*) và COUNT(tên_cột) khi bảng chứa giá trị NULL", "Trong SQL, hàm COUNT(*) và hàm COUNT(column_name) khác nhau như thế nào khi bảng dữ liệu có chứa các dòng mang giá trị NULL? Cho ví dụ minh họa kết quả cụ thể.", "Sự khác biệt cốt lõi: COUNT(*) đếm tổng số lượng dòng (bản ghi) thỏa mãn điều kiện trong bảng mà không quan tâm đến nội dung hay tính chất của các cột; kể cả khi tất cả các cột trong dòng đó mang giá trị NULL thì dòng đó vẫn được đếm vào kết quả. Ngược lại, COUNT(column_name) chỉ đếm số lượng các dòng mà tại đó cột được chỉ định mang giá trị KHÁC NULL; mọi dòng có giá trị NULL tại cột đó sẽ bị bỏ qua hoàn toàn. Ví dụ: Bảng Employees có 5 dòng với cột Bonus nhận các giá trị: 500, NULL, 300, NULL, 200. Khi đó: COUNT(*) sẽ trả về kết quả là 5; nhưng COUNT(Bonus) sẽ chỉ trả về kết quả là 3. Đối với hàm COUNT(DISTINCT column_name), hệ thống sẽ lọc bỏ toàn bộ các giá trị trùng lặp và loại bỏ hoàn toàn giá trị NULL trước khi đếm; như trong ví dụ trên nếu có thêm 1 dòng Bonus = 500 nữa thì COUNT(DISTINCT Bonus) sẽ trả về 3 (chỉ đếm các giá trị phân biệt: 500, 300, 200).", "[\"Cơ chế đếm của COUNT(*) (3.0đ): Nêu rõ COUNT(*) đếm mọi dòng thỏa mãn điều kiện, không phụ thuộc vào giá trị NULL.\", \"Cơ chế đếm của COUNT(column_name) (3.5đ): Giải thích chính xác cơ chế tự động bỏ qua các dòng mang giá trị NULL ở cột chỉ định.\", \"Ví dụ thực tế và giải thích COUNT(DISTINCT) (3.5đ): Đưa ra bảng ví dụ minh họa sự khác biệt số lượng và nêu rõ COUNT(DISTINCT) loại bỏ NULL.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Hàm COUNT(DISTINCT column_name) hoạt động như thế nào và nó có đếm giá trị NULL vào số lượng phân biệt không?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000116", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", RubricDbi202Id, "Ý nghĩa và Quy trình Xác định Bao đóng của Tập thuộc tính (Attribute Closure)", "Trong lý thuyết phụ thuộc hàm, Bao đóng của một tập thuộc tính (Attribute Closure) mang ý nghĩa gì và đóng vai trò như thế nào trong thiết kế cơ sở dữ liệu? Hãy trình bày quy trình lặp từng bước để xác định bao đóng của một tập thuộc tính, sau đó minh họa nhanh bằng lời trên một ví dụ bắc cầu trực quan (như bảng Hồ sơ Sinh viên gồm Mã sinh viên, Họ tên, Mã lớp và Khoa quản lý, trong đó Mã sinh viên xác định Họ tên và Mã lớp, còn Mã lớp xác định Khoa quản lý) để kết luận xem Mã sinh viên có phải là Siêu khóa và Khóa ứng viên hay không.", "Bao đóng của một tập thuộc tính X đối với tập phụ thuộc hàm F là tập hợp tất cả các thuộc tính trong bảng có thể suy dẫn hàm một cách hợp lệ từ X; đây là công cụ nền tảng giúp kiểm tra nhanh một phụ thuộc hàm có được suy ra từ F hay không và xác định tập thuộc tính nào đủ khả năng làm khóa mà không cần áp dụng thủ công từng tiên đề Armstrong. Quy trình lặp tìm bao đóng gồm ba bước: Bước 1 khởi tạo tập kết quả ban đầu chứa chính các thuộc tính trong X; Bước 2 duyệt qua các phụ thuộc hàm trong F, nếu toàn bộ các thuộc tính ở vế trái của phụ thuộc hàm nào đã nằm trong tập kết quả hiện tại thì bổ sung các thuộc tính ở vế phải của nó vào tập kết quả; Bước 3 lặp lại Bước 2 cho đến khi không thể mở rộng thêm bất kỳ thuộc tính mới nào nữa thì dừng. Minh họa trên bảng Hồ sơ Sinh viên: xuất phát từ Mã sinh viên, vòng lặp đầu tiên áp dụng phụ thuộc Mã sinh viên xác định Họ tên và Mã lớp để mở rộng tập bao đóng thành Mã sinh viên, Họ tên và Mã lớp; vòng lặp thứ hai thấy Mã lớp đã có mặt nên áp dụng tiếp phụ thuộc Mã lớp xác định Khoa quản lý, thu được trọn vẹn cả 4 thuộc tính của bảng. Vì bao đóng của Mã sinh viên phủ kín toàn bộ bảng nên Mã sinh viên là một Siêu khóa; đồng thời vì nó chỉ gồm một thuộc tính đơn lẻ tối tiểu nên Mã sinh viên chính là Khóa ứng viên của bảng.", "[\"Giải thích ý nghĩa và vai trò của Bao đóng thuộc tính (2.5đ): Nêu đúng khái niệm tập mọi thuộc tính suy dẫn được từ tập gốc và vai trò kiểm tra suy dẫn hàm, nhận diện khóa.\", \"Trình bày chuẩn xác quy trình lặp 3 bước tìm bao đóng (3.5đ): Mô tả rõ bước khởi tạo, vòng lặp kiểm tra vế trái nằm trong tập kết quả để nạp thêm vế phải và điều kiện dừng.\", \"Minh họa bằng lời trên ví dụ thực tế và lập luận Khóa (4.0đ): Diễn giải mạch lạc luồng mở rộng bắc cầu từ Mã sinh viên ra toàn bảng và kết luận đúng tính chất Siêu khóa, Khóa ứng viên tối tiểu.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Giả sử trong bảng Hồ sơ Sinh viên ở trên, ta xét tập gồm hai thuộc tính là Mã sinh viên ghép với Mã lớp. Tập hai thuộc tính này có bao đóng phủ toàn bộ bảng không, và nó có được coi là một Khóa ứng viên của bảng hay không? Tại sao?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000117", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", RubricDbi202Id, "Phân biệt Phụ thuộc hàm đầy đủ và Phụ thuộc hàm bộ phận trong 2NF", "Thế nào là Phụ thuộc hàm đầy đủ (Full Functional Dependency) và Phụ thuộc hàm bộ phận (Partial Functional Dependency)? Một quan hệ đạt Dạng chuẩn 2 (2NF) khi nào? Cho ví dụ một quan hệ vi phạm 2NF và cách phân rã chuẩn hóa.", "Xét quan hệ R có khóa ứng viên K và một thuộc tính không khóa A. Thuộc tính A được gọi là phụ thuộc hàm đầy đủ vào K nếu K xác định hàm A và không tồn tại bất kỳ tập con thực sự nào của K có thể tự mình xác định được A. Ngược lại, nếu chỉ cần một phần tập con thực sự của khóa K đã đủ để xác định A thì đó là phụ thuộc hàm bộ phận. Một quan hệ đạt Dạng chuẩn 2 (2NF) khi và chỉ khi nó đã đạt chuẩn 1NF và mọi thuộc tính không khóa đều phụ thuộc hàm đầy đủ vào mọi khóa ứng viên (tức không tồn tại phụ thuộc bộ phận). Ví dụ bảng Đăng ký học lưu bốn cột là Mã sinh viên, Mã môn học, Điểm số và Tên môn học với khóa chính phức hợp gồm cặp Mã sinh viên và Mã môn học: trong khi Điểm số phụ thuộc đầy đủ vào cả cặp khóa, thì Tên môn học lại chỉ phụ thuộc riêng vào Mã môn học (một phần của khóa chính), gây dư thừa lặp lại Tên môn học và vi phạm 2NF. Cách chuẩn hóa là tách thành hai bảng gồm bảng Đăng ký học (Mã sinh viên, Mã môn học, Điểm số) và bảng Môn học (Mã môn học, Tên môn học). Đặc biệt, nếu bảng đã đạt 1NF và chỉ có khóa đơn gồm duy nhất một thuộc tính thì bảng đó tự động đạt 2NF vì khóa đơn không có tập con thực sự khác rỗng.", "[\"Định nghĩa Phụ thuộc đầy đủ vs Phụ thuộc bộ phận (3.0đ): Nêu rõ sự khác biệt dựa trên việc thuộc tính không khóa có phụ thuộc vào một tập con thực sự của khóa hay không.\", \"Điều kiện Dạng chuẩn 2 (2NF) (3.0đ): Khẳng định điều kiện đạt 1NF và mọi thuộc tính không khóa phụ thuộc đầy đủ vào khóa ứng viên.\", \"Ví dụ vi phạm, cách phân rã & Hệ quả khóa đơn (4.0đ): Đưa ví dụ Đăng ký học phân tích đúng vi phạm, tách bảng chính xác và giải thích vì sao khóa đơn tự động đạt 2NF.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Nếu một quan hệ có khóa chính chỉ bao gồm duy nhất 1 thuộc tính đơn lẻ và đã đạt chuẩn 1NF, thì quan hệ đó có thể vi phạm Dạng chuẩn 2 (2NF) được không? Tại sao?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000118", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", RubricDbi202Id, "Ba dạng dị thường dữ liệu (Insertion, Deletion, Update Anomalies)", "Hãy phân tích chi tiết 3 dạng dị thường dữ liệu (Anomalies) thường gặp trong cơ sở dữ liệu chưa chuẩn hóa: Dị thường chèn (Insertion Anomaly), Dị thường xóa (Deletion Anomaly) và Dị thường cập nhật (Update Anomaly). Cho ví dụ thực tế minh họa.", "Trong một bảng chưa chuẩn hóa (gộp nhiều thực thể vào một bảng, ví dụ gộp Sinh viên và Khoa: Student_Dept(StudentID, StudentName, DeptID, DeptName, DeptDean)): (1) Dị thường chèn (Insertion Anomaly): Không thể thêm thông tin của một thực thể độc lập nếu chưa có thực thể kia; ví dụ: Nhà trường vừa thành lập 'Khoa Trí tuệ Nhân tạo' mới nhưng chưa có sinh viên nào nhập học; do StudentID là khóa chính (cấm NULL) nên hệ thống không thể chèn bản ghi thông tin của Khoa mới này vào CSDL. (2) Dị thường xóa (Deletion Anomaly): Khi xóa thông tin của một thực thể thì vô tình làm mất luôn thông tin quan trọng của một thực thể khác; ví dụ: Nếu sinh viên duy nhất của Khoa Triết học tốt nghiệp và bị xóa khỏi bảng, thông tin về tên khoa và trưởng khoa Triết học cũng bị biến mất hoàn toàn khỏi hệ thống. (3) Dị thường cập nhật (Update Anomaly): Do dữ liệu bị lặp lại ở nhiều dòng (ví dụ tên Trưởng khoa bị lặp lại ở 1,000 dòng sinh viên), khi Trưởng khoa thay đổi, nếu không cập nhật đồng bộ ở toàn bộ 1,000 dòng thì dữ liệu sẽ rơi vào trạng thái mâu thuẫn mất nhất quán (Inconsistent state). Phương pháp cốt lõi để loại bỏ 3 dị thường này là Kỹ thuật Chuẩn hóa dữ liệu (Normalization) bằng cách phân rã quan hệ thành các bảng độc lập bảo toàn thông tin.", "[\"Phân tích Dị thường chèn (Insertion Anomaly) (3.0đ): Giải thích rõ nguyên nhân không chèn được thực thể mới do vướng ràng buộc khóa chính.\", \"Phân tích Dị thường xóa (Deletion Anomaly) (3.0đ): Giải thích rõ hiện tượng xóa thực thể này kéo theo mất dữ liệu của thực thể độc lập khác.\", \"Phân tích Dị thường cập nhật & Giải pháp Chuẩn hóa (4.0đ): Chỉ rõ rủi ro mâu thuẫn dữ liệu do dư thừa và khẳng định giải pháp phân rã chuẩn hóa.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Phương pháp cốt lõi nào trong lý thuyết cơ sở dữ liệu được sử dụng để loại bỏ triệt để 3 dạng dị thường này?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000119", CourseDbi202Id, "00000000-0000-0000-0000-000000000664", RubricDbi202Id, "Quy tắc chuyển đổi mối kết hợp Nhiều - Nhiều (M:N) từ ERD sang Lược đồ quan hệ", "Khi chuyển đổi một mối kết hợp Nhiều - Nhiều (M:N) từ sơ đồ ERD sang mô hình cơ sở dữ liệu quan hệ, chúng ta phải thực hiện như thế nào? Bảng trung gian (Junction Table) sinh ra sẽ có cấu trúc, khóa chính và các khóa ngoại như thế nào?", "Khi chuyển đổi mối kết hợp Nhiều - Nhiều (M:N) giữa hai tập thực thể A và B sang mô hình quan hệ, chúng ta không thể đặt khóa ngoại trực tiếp ở bảng A hay bảng B vì sẽ gây vi phạm tính nguyên tử (1NF) hoặc dư thừa dữ liệu. Giải pháp bắt buộc là: Tạo một Bảng trung gian (Junction Table / Bridge Table / Associative Table), đại diện cho chính mối kết hợp đó. Cấu trúc của bảng trung gian bao gồm: (1) Khóa ngoại trỏ về khóa chính của bảng A; (2) Khóa ngoại trỏ về khóa chính của bảng B; (3) Khóa chính của bảng trung gian thông thường là Khóa chính phức hợp (Composite Primary Key) kết hợp từ 2 khóa ngoại nói trên (hoặc tạo một Surrogate Key ID độc lập kèm ràng buộc UNIQUE trên cặp 2 khóa ngoại). Toàn bộ các thuộc tính gắn liền với mối kết hợp M:N (ví dụ: 'Grade', 'Semester' của mối quan hệ đăng ký học giữa Student và Course) sẽ được chuyển thành các cột thuộc tính nằm trực tiếp trong bảng trung gian này.", "[\"Nguyên lý tạo Bảng trung gian (Junction Table) (3.0đ): Giải thích rõ vì sao không thể đặt FK ở bảng gốc và bắt buộc phải tách bảng trung gian.\", \"Xác định cấu trúc Khóa chính & Khóa ngoại của bảng trung gian (4.0đ): Chỉ rõ cặp FK tham chiếu về 2 bảng cha và cấu trúc Composite Primary Key.\", \"Vị trí lưu trữ các thuộc tính của mối kết hợp (3.0đ): Khẳng định chính xác các thuộc tính riêng của relationship được đặt trực tiếp trong bảng trung gian.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Nếu mối kết hợp M:N đó có chứa các thuộc tính riêng (ví dụ mối kết hợp 'Đăng ký học' giữa Sinh viên và Môn học có thuộc tính 'Điểm thi' và 'Học kỳ'), các thuộc tính này sẽ được đặt ở đâu trong lược đồ quan hệ?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000120", CourseDbi202Id, "00000000-0000-0000-0000-000000000664", RubricDbi202Id, "Khái niệm Thực thể yếu (Weak Entity) và Khóa bộ phận (Discriminator)", "Thực thể yếu (Weak Entity Set) là gì? Khóa bộ phận (Discriminator / Partial Key) có đặc điểm gì? Hãy nêu quy tắc chuyển đổi một thực thể yếu sang bảng trong mô hình quan hệ và cho ví dụ minh họa.", "Thực thể yếu (Weak Entity Set) là tập thực thể không có đủ thuộc tính để tự tạo thành một khóa chính độc lập; sự tồn tại của nó phụ thuộc hoàn toàn vào một thực thể cha (Identifying / Owner Entity) thông qua một mối kết hợp định danh (Identifying Relationship - ký hiệu hình thoi nét đôi). Khóa bộ phận (Discriminator / Partial Key - ký hiệu gạch chân nét đứt) là thuộc tính chỉ giúp phân biệt các thể hiện thực thể yếu cùng thuộc về một thực thể cha duy nhất. Quy tắc chuyển đổi sang mô hình quan hệ: Tạo một bảng riêng cho thực thể yếu; Khóa chính của bảng này là một Khóa phức hợp gồm: Khóa chính của thực thể cha (đóng vai trò Khóa ngoại) + Khóa bộ phận của chính nó. Ví dụ: Thực thể Nhân viên (Employee: EmpID) và thực thể yếu Người phụ thuộc (Dependent: DependentName, Relationship, BirthDate). Bảng Dependent sẽ có khóa chính là (EmpID, DependentName), trong đó EmpID là Foreign Key tham chiếu đến Employee(EmpID). Tùy chọn ON DELETE CASCADE là bắt buộc về mặt nghiệp vụ: khi một nhân viên nghỉ việc và bị xóa khỏi CSDL, toàn bộ hồ sơ người phụ thuộc của họ phải tự động bị xóa theo.", "[\"Định nghĩa Thực thể yếu & Khóa bộ phận (3.5đ): Nêu rõ tính phụ thuộc tồn tại, ký hiệu nét đôi/nét đứt và vai trò của Discriminator.\", \"Quy tắc ánh xạ sang bảng quan hệ (3.5đ): Trình bày đúng cấu trúc Khóa chính phức hợp ghép từ FK của thực thể cha và Discriminator.\", \"Ví dụ thực tế & Phân tích ON DELETE CASCADE (3.0đ): Đưa ra ví dụ Employee-Dependent chuẩn xác và giải thích tầm quan trọng của CASCADE delete.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Trên bảng quan hệ biểu diễn thực thể yếu, tùy chọn xóa 'ON DELETE CASCADE' ở ràng buộc khóa ngoại có vai trò đặc biệt quan trọng như thế nào?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000121", CourseDbi202Id, "00000000-0000-0000-0000-000000000667", RubricDbi202Id, "Phân biệt Clustered Index và Non-Clustered Index trong MS SQL Server", "Trong MS SQL Server, hãy phân biệt sự khác nhau giữa Clustered Index và Non-Clustered Index về: cấu trúc tổ chức vật lý trên đĩa, số lượng chỉ mục tối đa trên một bảng và con trỏ tại mức lá (Leaf Node).", "Sự khác biệt cốt lõi: (1) Cấu trúc lưu trữ vật lý: Clustered Index xác định trực tiếp thứ tự sắp xếp vật lý của các dòng dữ liệu thực tế trên đĩa cứng; bản thân các trang dữ liệu (Data Pages) tại mức lá (Leaf Level) của cây B-Tree chính là dòng dữ liệu thực tế của bảng. Vì các dòng dữ liệu vật lý trên đĩa chỉ có thể sắp xếp theo duy nhất một thứ tự cụ thể, nên mỗi bảng CHỈ CÓ THỂ CÓ DUY NHẤT 1 Clustered Index. Ngược lại, Non-Clustered Index có cấu trúc cây B-Tree lưu trữ hoàn toàn tách rời khỏi các trang dữ liệu của bảng. (2) Con trỏ tại mức lá (Leaf Node): Mức lá của Clustered Index chứa toàn bộ dữ liệu của bản ghi. Mức lá của Non-Clustered Index chỉ chứa các cột khóa chỉ mục và một con trỏ trỏ về dòng dữ liệu thực tế (con trỏ là RID - Row Identifier nếu bảng là Heap không có Clustered Index; hoặc con trỏ chính là giá trị Clustered Key nếu bảng đã có Clustered Index). (3) Số lượng chỉ mục: Một bảng chỉ có tối đa 1 Clustered Index, nhưng có thể tạo tới 999 Non-Clustered Index trong MS SQL Server.", "[\"Bản chất và cấu trúc Clustered Index (3.5đ): Giải thích rõ Clustered Index định đoạt vị trí vật lý trên đĩa và leaf level là data pages.\", \"Bản chất và con trỏ mức lá của Non-Clustered Index (3.5đ): Phân tích rõ cấu trúc tách rời và con trỏ mức lá trỏ về RID hoặc Clustered Key.\", \"Giải thích giới hạn số lượng chỉ mục trên bảng (3.0đ): Lập luận chính xác vì sao chỉ có duy nhất 1 Clustered Index và số lượng Non-Clustered Index.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Tại sao mỗi bảng trong SQL Server chỉ có thể có duy nhất 1 Clustered Index, trong khi có thể có hàng trăm Non-Clustered Index?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000122", CourseDbi202Id, "00000000-0000-0000-0000-000000000666", RubricDbi202Id, "Bảng ảo inserted và deleted trong cơ chế hoạt động của DML Trigger", "Trong MS SQL Server, hai bảng ảo inserted và deleted là gì? Hãy trình bày trạng thái dữ liệu có trong hai bảng ảo này khi thực hiện lần lượt các thao tác DML: INSERT, DELETE và UPDATE.", "Hai bảng ảo 'inserted' và 'deleted' là các bảng tạm thời trong bộ nhớ RAM do SQL Server tự động tạo ra và quản lý trong suốt quá trình một DML Trigger đang thực thi; chúng có cùng lược đồ cấu trúc cột giống hệt bảng gốc mà trigger gắn vào. Trạng thái dữ liệu qua các thao tác: (1) Thao tác INSERT: Bảng 'inserted' chứa bản sao của toàn bộ các dòng mới vừa được thêm vào; bảng 'deleted' hoàn toàn rỗng. (2) Thao tác DELETE: Bảng 'deleted' chứa bản sao của toàn bộ các dòng vừa bị xóa khỏi bảng gốc; bảng 'inserted' hoàn toàn rỗng. (3) Thao tác UPDATE: Bản chất của câu lệnh UPDATE trong kiến trúc của hệ cơ sở dữ liệu quan hệ được mô phỏng như một cặp thao tác kép: Xóa dòng cũ và Chèn dòng mới. Do đó, bảng 'deleted' sẽ chứa trạng thái dữ liệu CŨ của các dòng trước khi được cập nhật; còn bảng 'inserted' sẽ chứa trạng thái dữ liệu MỚI của chính các dòng đó sau khi được chỉnh sửa. Lập trình viên sử dụng hai bảng này để so sánh giá trị cũ và mới nhằm thực hiện kiểm tra nghiệp vụ và ghi vết kiểm toán (Audit Trail).", "[\"Khái niệm và đặc điểm của bảng inserted / deleted (3.0đ): Nêu rõ đây là bảng ảo RAM tạm thời, cấu trúc tương đồng với bảng cơ sở.\", \"Trạng thái dữ liệu trong thao tác INSERT và DELETE (3.5đ): Mô tả chính xác trạng thái có dữ liệu và rỗng của inserted/deleted trong INSERT và DELETE.\", \"Cơ chế hoạt động trong thao tác UPDATE (3.5đ): Phân tích rõ bản chất UPDATE = DELETE (dòng cũ) + INSERT (dòng mới) trên 2 bảng ảo.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Bản chất của thao tác UPDATE trong SQL Server được hai bảng ảo inserted và deleted mô phỏng như thế nào?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000123", CourseDbi202Id, "00000000-0000-0000-0000-000000000666", RubricDbi202Id, "Phân biệt Stored Procedure và User-Defined Function (UDF)", "Trong T-SQL, hãy so sánh sự khác nhau giữa Stored Procedure (Thủ tục lưu trữ) và User-Defined Function (Hàm người dùng định nghĩa) về: giá trị trả về, khả năng thay đổi trạng thái dữ liệu (DML), và cách thức gọi thực thi trong câu lệnh SQL.", "Sự khác biệt cốt lõi: (1) Giá trị trả về: Function BẮT BUỘC phải trả về một giá trị duy nhất (với Scalar Function) hoặc một bảng dữ liệu (với Table-Valued Function) thông qua mệnh đề RETURNS. Ngược lại, Stored Procedure không bắt buộc trả về giá trị; SP có thể trả về 0, 1 hoặc nhiều tập kết quả (Result Sets), kèm theo mã trạng thái RETURN (kiểu INT) và hỗ trợ nhiều tham số đầu ra (OUTPUT parameters). (2) Khả năng thay đổi dữ liệu (Side Effects): Function tuyệt đối KHÔNG ĐƯỢC làm thay đổi trạng thái của CSDL (cấm các lệnh INSERT, UPDATE, DELETE trên bảng vật lý, cấm dùng Transaction); Function được thiết kế thuần túy để tính toán. Stored Procedure được phép thực hiện mọi thao tác DDL, DML, quản lý Transaction (BEGIN TRAN, COMMIT, ROLLBACK). (3) Cách thức gọi thực thi: Function có thể được nhúng trực tiếp vào các mệnh đề SELECT, WHERE, HAVING, JOIN của câu truy vấn SQL như một biểu thức. Ngược lại, Stored Procedure phải được gọi độc lập bằng lệnh EXECUTE (hoặc EXEC) và TUYỆT ĐỐI KHÔNG THỂ gọi bên trong mệnh đề WHERE của SELECT.", "[\"So sánh cơ chế Giá trị trả về (3.5đ): Chỉ rõ Function bắt buộc RETURNS giá trị/bảng; SP linh hoạt result sets và OUTPUT params.\", \"So sánh Tác động trạng thái CSDL (DML/Transaction) (3.5đ): Nêu rõ Function cấm side-effects, SP được phép thao tác DML và quản trị Transaction.\", \"So sánh Cách thức gọi & Giải thích lệnh EXEC (3.0đ): Khẳng định Function gọi trong SELECT/WHERE; SP chỉ gọi bằng EXEC và cấm trong WHERE.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Chúng ta có thể gọi một Stored Procedure bên trong mệnh đề WHERE của câu lệnh SELECT được không? Tại sao?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000124", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", RubricDbi202Id, "Tùy chọn xử lý vi phạm khóa ngoại: ON DELETE CASCADE vs ON DELETE SET NULL", "Khi khai báo ràng buộc Khóa ngoại (FOREIGN KEY) trong SQL, các tùy chọn ON DELETE CASCADE, ON DELETE SET NULL và ON DELETE NO ACTION hoạt động như thế nào? Trong tình huống nào thì bắt buộc không được dùng CASCADE?", "Khi một bản ghi ở bảng cha (chứa khóa chính) bị xóa, hệ thống sẽ xử lý các bản ghi tương ứng ở bảng con (chứa khóa ngoại) theo 3 tùy chọn: (1) ON DELETE NO ACTION (Mặc định): Hệ thống từ chối thao tác xóa ở bảng cha và ném ra lỗi vi phạm toàn vẹn tham chiếu nếu còn tồn tại bản ghi ở bảng con trỏ tới nó. (2) ON DELETE CASCADE: Xóa dây chuyền - hệ thống tự động xóa toàn bộ các bản ghi liên quan ở bảng con khi bản ghi cha tương ứng bị xóa. Thích hợp cho quan hệ cha-con phụ thuộc sống còn (như Đơn hàng và Chi tiết đơn hàng). (3) ON DELETE SET NULL: Hệ thống giữ lại các bản ghi ở bảng con, nhưng tự động cập nhật giá trị của cột khóa ngoại thành NULL. Để sử dụng được ON DELETE SET NULL, điều kiện tiên quyết là cột khóa ngoại ở bảng con BẮT BUỘC PHẢI CHO PHÉP NHẬN GIÁ TRỊ NULL (nghĩa là không được khai báo NOT NULL). Tình huống bắt buộc CẤM dùng CASCADE: Khi quan hệ có tính chất tham chiếu độc lập hoặc nhiều đường dẫn quan hệ vòng (Multiple Cascade Paths / Cycles) gây lỗi Deadlock hoặc tự xóa dây chuyền mất kiểm soát (ví dụ xóa Khoa không được tự ý xóa vĩnh viễn Giảng viên).", "[\"Cơ chế hoạt động của NO ACTION và CASCADE (3.5đ): Giải thích rõ NO ACTION chặn lỗi và CASCADE xóa dây chuyền bản ghi bảng con.\", \"Cơ chế SET NULL và điều kiện DDL bắt buộc (3.5đ): Nêu rõ việc gán NULL và điều kiện tiên quyết cột khóa ngoại phải Nullable (không NOT NULL).\", \"Rủi ro kỹ thuật và trường hợp cấm dùng CASCADE (3.0đ): Chỉ ra nguy cơ mất dữ liệu diện rộng và hiện tượng Multiple Cascade Paths gây lỗi trong SQL Server.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Để sử dụng được tùy chọn ON DELETE SET NULL, cột khóa ngoại ở bảng con bắt buộc phải thỏa mãn điều kiện gì về mặt cấu trúc DDL?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000125", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", RubricDbi202Id, "Phân biệt câu lệnh DELETE và TRUNCATE TABLE", "Hãy so sánh chi tiết sự khác biệt giữa câu lệnh DELETE và TRUNCATE TABLE trong MS SQL Server về: mệnh đề WHERE, cơ chế ghi Transaction Log, việc kích hoạt DML Trigger và hành vi với cột IDENTITY.", "So sánh chi tiết: (1) Mệnh đề WHERE: DELETE là lệnh DML cho phép sử dụng mệnh đề WHERE để xóa có chọn lọc từng dòng; TRUNCATE là lệnh DDL luôn xóa sạch 100% dữ liệu của bảng, không hỗ trợ WHERE. (2) Ghi Transaction Log: DELETE quét từng dòng, xóa dòng và ghi chi tiết việc xóa của từng dòng vào transaction log, dẫn đến chi phí I/O cao và log file phình to; TRUNCATE ghi log tối thiểu (Minimally Logged), nó chỉ ghi nhận việc giải phóng (deallocate) toàn bộ các trang dữ liệu (Extents/Pages) nên tốc độ thực thi nhanh vượt trội. (3) Kích hoạt Trigger: DELETE kích hoạt các AFTER/INSTEAD OF DELETE Trigger; TRUNCATE tuyệt đối KHÔNG kích hoạt bất kỳ DELETE Trigger nào. (4) Cột IDENTITY: DELETE giữ nguyên giá trị bộ đếm hiện tại của IDENTITY; TRUNCATE tự động đặt lại (reset) giá trị cột IDENTITY về giá trị Seed ban đầu. (5) Khóa ngoại: Nếu một bảng đang được tham chiếu bởi một FOREIGN KEY constraint từ một bảng khác thì lệnh TRUNCATE TABLE sẽ bị HỆ THỐNG CHẶN HOÀN TOÀN (báo lỗi), ngay cả khi bảng con tham chiếu hiện tại không có dữ liệu nào.", "[\"So sánh Khả năng lọc có điều kiện với WHERE & Phạm vi thao tác (2.5đ): Nêu rõ DELETE có mệnh đề WHERE xóa chọn lọc, TRUNCATE xóa toàn bộ bảng không hỗ trợ WHERE.\", \"So sánh Cơ chế Ghi Log & Tốc độ hiệu năng (3.0đ): Phân tích rõ Row-by-row logging của DELETE so với Page deallocation minimal logging của TRUNCATE.\", \"So sánh Hành vi với Trigger và cột IDENTITY (2.5đ): Chỉ rõ DELETE kích hoạt Trigger và giữ Seed; TRUNCATE không kích hoạt Trigger và reset Seed.\", \"Ràng buộc toàn vẹn tham chiếu Foreign Key (2.0đ): Khẳng định chính xác TRUNCATE bị chặn tuyệt đối nếu bảng đang là đích tham chiếu của FK.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, "Nếu một bảng đang được tham chiếu bởi một Khóa ngoại (FOREIGN KEY) từ bảng khác thì lệnh TRUNCATE TABLE trên bảng đó có thực hiện được không, ngay cả khi bảng con đang hoàn toàn rỗng?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000126", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", RubricDbi202Id, "Kỹ thuật tự kết nối (SELF JOIN) để biểu diễn mối quan hệ đệ quy", "Kỹ thuật tự kết nối (SELF JOIN) là gì và thường được áp dụng cho những kịch bản cấu trúc dữ liệu nào trong thực tế? Giả sử bảng Nhân viên (Employees) lưu Mã nhân viên, Họ tên và cột Mã người quản lý (ManagerID) tự tham chiếu về chính Mã nhân viên, hãy trình bày cách tổ chức kết nối bảng Employees với chính nó thông qua bí danh (Alias) để lấy thông tin Nhân viên kèm Người quản lý trực tiếp, đồng thời lý giải vì sao cần dùng LEFT JOIN thay vì INNER JOIN.", "SELF JOIN là kỹ thuật kết nối một bảng vật lý với chính nó trong cùng một câu truy vấn; để hệ quản trị CSDL không bị nhầm lẫn ngữ cảnh cột, ta bắt buộc phải đặt hai bí danh (Alias) khác nhau cho bảng đó như thể đang thao tác trên hai bảng độc lập. Trong thực tế, SELF JOIN chuyên dùng để khai thác các mối quan hệ một ngôi tự tham chiếu hoặc cấu trúc phân cấp một cấp như Nhân viên và Người quản lý trực tiếp, hoặc Danh mục hàng hóa cha và Danh mục con. Trên bảng Employees, ta gán bí danh E đóng vai trò tập Nhân viên cấp dưới đặt ở vế trái và bí danh M đóng vai trò tập Người quản lý đặt ở vế phải, với điều kiện kết nối so khớp cột ManagerID của bảng E bằng với cột EmpID của bảng M. Việc sử dụng LEFT JOIN thay cho INNER JOIN là bắt buộc về mặt nghiệp vụ vì Tổng giám đốc ở đỉnh tháp tổ chức có ManagerID mang giá trị NULL; nếu dùng INNER JOIN thì bản ghi Tổng giám đốc sẽ không khớp với bất kỳ dòng nào ở bảng M và bị loại khỏi danh sách, trong khi LEFT JOIN bảo toàn đầy đủ mọi nhân viên và cho phép dùng hàm ISNULL hoặc COALESCE trên cột tên quản lý của bảng M để hiển thị chuỗi mặc định thân thiện.", "[\"Khái niệm SELF JOIN & Vai trò bắt buộc của Bí danh (Alias) (3.0đ): Nêu đúng bản chất tự kết nối một bảng với chính nó và việc bắt buộc gán hai bí danh riêng biệt để phân tách hai vai trò logic.\", \"Kịch bản ứng dụng cấu trúc phân cấp tự tham chiếu (3.0đ): Chỉ ra chính xác các quan hệ đệ quy một ngôi phổ biến như Nhân viên - Quản lý trực tiếp hoặc Cây danh mục cha - con.\", \"Cơ chế kết nối khóa tự tham chiếu & Lý giải LEFT JOIN (4.0đ): Trình bày đúng điều kiện ghép ManagerID của bí danh nhân viên với EmpID của bí danh quản lý, giải thích rõ lý do dùng LEFT JOIN và hàm xử lý NULL để giữ lại cấp CEO.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, "Đối với nhân viên cấp cao nhất là Tổng giám đốc không có người quản lý trực tiếp (cột ManagerID mang giá trị NULL), làm thế nào để kết quả truy vấn hiển thị chữ 'Không có quản lý' thay vì NULL, và nếu bài toán mở rộng sang truy xuất toàn bộ cây phân cấp nhiều tầng không giới hạn độ sâu thì ta cần chuyển sang kỹ thuật nào trong SQL Server?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000127", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", RubricDbi202Id, "Truy vấn con tương quan (Correlated Subquery) và tối ưu hóa với toán tử EXISTS", "Truy vấn con tương quan (Correlated Subquery) khác với Truy vấn con độc lập (Uncorrelated/Non-correlated Subquery) như thế nào về cơ chế thực thi? Tại sao khi kiểm tra sự tồn tại của dữ liệu, toán tử EXISTS thường mang lại hiệu năng tối ưu hơn so với toán tử IN khi tập dữ liệu lớn?", "Truy vấn con độc lập không phụ thuộc vào truy vấn bên ngoài nên chỉ cần thực thi duy nhất một lần trước khi truy vấn cha chạy, kết quả tạm được cung cấp cho truy vấn ngoài đối chiếu. Ngược lại, Truy vấn con tương quan (Correlated Subquery) tham chiếu trực tiếp tới cột của dòng hiện hành thuộc truy vấn cha, nên về mặt logic phải đánh giá lặp lại ứng với từng dòng ứng viên của bảng ngoài. Khi kiểm tra sự tồn tại trên tập dữ liệu lớn, toán tử EXISTS thường tối ưu hơn IN nhờ cơ chế đánh giá đoản mạch (Short-circuit Evaluation) và phép bán kết nối (Semi-Join): bộ tối ưu hóa dừng quét nhánh con ngay lập tức khi bắt gặp dòng đầu tiên thỏa mãn điều kiện mà không cần đọc hết các dòng khớp còn lại hay nạp toàn bộ danh sách giá trị vào vùng nhớ tạm. Đặc biệt, toán tử NOT IN tiềm ẩn bẫy logic nghiêm trọng khi tập kết quả của truy vấn con có lẫn dù chỉ một giá trị NULL: vì kiểm tra một giá trị không nằm trong danh sách đồng nghĩa với chuỗi phép hội AND kiểm tra khác từng phần tử, phép so sánh khác NULL luôn sinh ra trạng thái UNKNOWN làm toàn bộ mệnh đề WHERE không bao giờ đạt TRUE và trả về 0 dòng. Trái lại, NOT EXISTS chỉ kiểm tra xem truy vấn con có trả về dòng nào hay không nên hoàn toàn miễn nhiễm với giá trị NULL.", "[\"Cơ chế thực thi Correlated vs Non-correlated Subquery (3.0đ): Phân tích rõ cơ chế chạy 1 lần của subquery độc lập so với đánh giá phụ thuộc từng dòng ngoài của correlated subquery.\", \"Phân tích tối ưu hóa của EXISTS (Short-circuit & Semi-Join) (3.5đ): Giải thích cơ chế dừng sớm ngay khi tìm thấy bản ghi khớp đầu tiên giúp tiết kiệm I/O và bộ nhớ.\", \"Bẫy logic của NOT IN với NULL và giải pháp NOT EXISTS (3.5đ): Giải thích chặt chẽ logic ba giá trị UNKNOWN khiến NOT IN trả về tập rỗng và tính an toàn tuyệt đối của NOT EXISTS.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Toán tử NOT IN gặp phải lỗi logic nghiêm trọng nào khi tập kết quả của subquery chứa ít nhất một giá trị NULL? Toán tử NOT EXISTS xử lý vấn đề này an toàn ra sao?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000128", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", RubricDbi202Id, "Điều kiện Dạng chuẩn 3 (3NF) vs Dạng chuẩn Boyce-Codd (BCNF)", "Hãy nêu định nghĩa hình thức chuẩn mực của Dạng chuẩn 3 (3NF) và Dạng chuẩn Boyce-Codd (BCNF). Điểm khác biệt mấu chốt giữa 3NF và BCNF là gì? Trong trường hợp nào một quan hệ đạt chuẩn 3NF nhưng lại KHÔNG đạt chuẩn BCNF?", "Xét lược đồ quan hệ R cùng tập phụ thuộc hàm F: với mọi phụ thuộc hàm không tầm thường mà tập thuộc tính X xác định thuộc tính A, lược đồ R đạt Dạng chuẩn 3 (3NF) khi và chỉ khi vế trái X là một Siêu khóa của R HOẶC vế phải A là một Thuộc tính khóa (Prime Attribute, tức nằm trong ít nhất một Khóa ứng viên). Trong khi đó, R đạt Dạng chuẩn Boyce-Codd (BCNF) khi và chỉ khi với mọi phụ thuộc hàm không tầm thường, vế trái X bắt buộc phải là một Siêu khóa mà không có bất kỳ ngoại lệ nào. Điểm khác biệt mấu chốt là BCNF loại bỏ hoàn toàn điều kiện nới lỏng cho thuộc tính khóa ở vế phải của 3NF. Một quan hệ đạt 3NF nhưng vi phạm BCNF thường xuất hiện khi bảng có từ hai Khóa ứng viên phức hợp trở lên bị gối chồng chéo thuộc tính lên nhau (Overlapping Candidate Keys), ví dụ bảng gồm Sinh viên, Môn học và Giảng viên trong đó cặp Sinh viên - Môn học xác định Giảng viên còn Giảng viên xác định Môn học: phụ thuộc Giảng viên xác định Môn học thỏa 3NF vì Môn học là thuộc tính khóa, nhưng vi phạm BCNF vì Giảng viên không phải siêu khóa. Trong thực tế doanh nghiệp, kỹ sư thường dừng ở 3NF vì chuẩn 3NF luôn bảo đảm vừa kết nối không mất thông tin vừa bảo toàn 100% phụ thuộc hàm, tránh chi phí JOIN liên bảng hoặc Trigger đắt đỏ khi ép lên BCNF.", "[\"Định nghĩa chuẩn mực của 3NF và BCNF (3.0đ): Nêu chính xác điều kiện vế trái là siêu khóa hoặc vế phải là prime attribute trong 3NF so với điều kiện bắt buộc siêu khóa của BCNF.\", \"Phân tích điều kiện Overlapping Candidate Keys (4.0đ): Đưa ví dụ thực tế chỉ rõ trường hợp các khóa ứng viên phức hợp chồng chéo làm bảng đạt 3NF nhưng trượt BCNF.\", \"Đánh đổi kỹ thuật giữa BCNF và Bảo toàn phụ thuộc (3.0đ): Lập luận sâu sắc lý do thực tế chọn 3NF để tránh mất khả năng kiểm tra phụ thuộc hàm cục bộ trên từng bảng.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Tại sao trong thực tế thiết kế phần mềm doanh nghiệp, các kỹ sư thường chấp nhận dừng lại ở 3NF thay vì cố gắng phân rã lên BCNF?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000129", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", RubricDbi202Id, "Kiểm tra tính Bảo toàn Phụ thuộc hàm (Dependency Preservation) và Sự đánh đổi giữa 3NF với BCNF", "Thế nào là một phép phân rã lược đồ đảm bảo tính chất Bảo toàn phụ thuộc hàm (Dependency Preservation)? Tại sao trong hệ quản trị cơ sở dữ liệu thực tế, việc phân rã làm mất phụ thuộc hàm lại gây tốn kém hiệu năng nghiêm trọng mỗi khi thực hiện thao tác thêm mới hoặc cập nhật dữ liệu? Hãy phân tích ví dụ kinh điển trên lược đồ Đăng ký học gồm ba thuộc tính Sinh viên, Môn học và Giảng viên (trong đó cặp Sinh viên và Môn học xác định duy nhất Giảng viên, còn mỗi Giảng viên chỉ phụ trách giảng dạy đúng một Môn học) để giải thích vì sao ta không thể vừa phân rã đạt chuẩn BCNF vừa bảo toàn được toàn bộ phụ thuộc hàm.", "Một phép phân rã lược đồ gốc thành các bảng con được gọi là Bảo toàn phụ thuộc hàm nếu hợp của tất cả các phụ thuộc hàm cục bộ nằm gọn trên từng bảng con có khả năng suy dẫn lại trọn vẹn toàn bộ tập phụ thuộc hàm ban đầu. Về mặt hiệu năng thực thi, khi bảo toàn được phụ thuộc hàm, mỗi quy tắc phụ thuộc đều nằm trọn trong một bảng duy nhất nên hệ quản trị CSDL kiểm tra tức thì bằng chỉ mục PRIMARY KEY hoặc UNIQUE cục bộ với chi phí cực thấp. Ngược lại, nếu một phụ thuộc hàm bị xé lẻ qua nhiều bảng, mỗi lần chạy lệnh INSERT hoặc UPDATE hệ thống buộc phải thực hiện phép kết nối JOIN liên bảng hoặc gọi Trigger kiểm tra chéo gây nghẽn nghiêm trọng. Xét lược đồ Đăng ký học gồm Sinh viên, Môn học và Giảng viên: bảng này có hai Khóa ứng viên chồng chéo là cặp Sinh viên - Môn học và cặp Sinh viên - Giảng viên, nên cả ba thuộc tính đều là thuộc tính khóa. Phụ thuộc Giảng viên xác định Môn học thỏa mãn chuẩn 3NF (vì Môn học là thuộc tính khóa) nhưng vi phạm BCNF (vì một mình Giảng viên không phải siêu khóa). Để khử vi phạm BCNF, ta buộc phải tách thành bảng Phân công gồm Giảng viên và Môn học cùng bảng Lớp học gồm Sinh viên và Giảng viên; khi đó không còn bảng đơn lẻ nào chứa đồng thời cả Sinh viên và Môn học để ràng buộc quy tắc một sinh viên học một môn chỉ học với một giảng viên duy nhất, khiến phụ thuộc hàm này bị đánh mất.", "[\"Giải thích bản chất Bảo toàn phụ thuộc hàm và chi phí hiệu năng khi vi phạm (3.5đ): Nêu rõ khả năng kiểm tra toàn bộ phụ thuộc hàm ngay trên từng bảng con bằng khóa PK/UNIQUE cục bộ mà không cần JOIN liên bảng khi thêm hoặc sửa.\", \"Xác định hai khóa ứng viên chồng chéo và lý giải đạt 3NF nhưng vi phạm BCNF (3.5đ): Chỉ rõ hai khóa ứng viên Sinh viên - Môn học và Sinh viên - Giảng viên, giải thích vì sao quy tắc Giảng viên xác định Môn học thỏa 3NF nhưng trượt BCNF.\", \"Phân tích hệ quả tách bảng lên BCNF làm mất phụ thuộc hàm liên thuộc tính (3.0đ): Giải thích rõ sau khi tách thành hai bảng hai cột, không bảng nào chứa đồng thời cả Sinh viên, Môn học và Giảng viên để kiểm soát cục bộ quy tắc đăng ký môn.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Khi gặp bài toán giống như lược đồ Đăng ký học gồm Sinh viên, Môn học và Giảng viên ở trên trong dự án thực tế, kiến trúc sư cơ sở dữ liệu thường quyết định giữ nguyên thiết kế ở chuẩn 3NF hay chấp nhận tách bảng lên BCNF? Nếu bắt buộc phải tách lên BCNF thì phải dùng cơ chế gì để kiểm soát lại quy tắc bị mất?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000130", CourseDbi202Id, "00000000-0000-0000-0000-000000000667", RubricDbi202Id, "Phân tích 4 mức cô lập giao dịch (Transaction Isolation Levels) và hiện tượng Phantom Read", "Hãy phân tích và đối chiếu 4 mức cô lập giao dịch chuẩn ANSI SQL (Read Uncommitted, Read Committed, Repeatable Read và Serializable) trước 3 hiện tượng đọc sai lệch tương tranh là Dirty Read, Non-repeatable Read và Phantom Read. Giải thích rõ bản chất của hiện tượng Đọc bóng ma (Phantom Read).", "Đối chiếu bốn mức cô lập chuẩn ANSI SQL theo chiều tăng dần độ chặt chẽ: (1) Read Uncommitted không đặt khóa chia sẻ khi đọc nên cho phép xảy ra cả ba hiện tượng Dirty Read, Non-repeatable Read và Phantom Read; (2) Read Committed (mặc định của SQL Server) chỉ đọc dữ liệu đã commit nên chặn được Dirty Read, nhưng giải phóng khóa đọc ngay sau câu lệnh nên vẫn bị Non-repeatable Read và Phantom Read; (3) Repeatable Read giữ khóa chia sẻ trên các dòng đã đọc đến hết giao dịch nên chặn được cả Dirty Read lẫn Non-repeatable Read, nhưng vẫn bị Phantom Read; (4) Serializable cô lập tuyệt đối và ngăn chặn triệt để cả ba hiện tượng. Bản chất của hiện tượng Phantom Read xảy ra khi Giao dịch 1 thực thi cùng một truy vấn lọc theo khoảng điều kiện (chẳng hạn tìm các đơn hàng có giá trị trên 10 triệu đồng) hai lần trong cùng một phiên giao dịch; xen giữa hai lần đọc đó, Giao dịch 2 thực hiện lệnh INSERT chèn thêm một đơn hàng mới trị giá 15 triệu đồng và COMMIT thành công, khiến lần đọc thứ hai của Giao dịch 1 xuất hiện thêm những dòng mới chưa từng có ở lần đầu. Repeatable Read không chặn được Phantom Read vì nó chỉ khóa các bản ghi hiện hữu chứ không khóa khoảng trống khóa chỉ mục; chỉ mức Serializable áp dụng khóa phạm vi (Key-Range Locks) mới chặn được lệnh INSERT chèn xen vào khoảng đang đọc.", "[\"Đối chiếu 4 mức cô lập giao dịch với 3 hiện tượng tương tranh (3.5đ): Phân tích chính xác khả năng ngăn chặn Dirty Read, Non-repeatable Read và Phantom Read của Read Uncommitted, Read Committed, Repeatable Read và Serializable.\", \"Phân tích bản chất hiện tượng Phantom Read (3.5đ): Giải thích rõ ràng kịch bản truy vấn lọc theo khoảng hai lần phát hiện thêm bản ghi mới do giao dịch khác INSERT và COMMIT xen giữa.\", \"Cơ chế khóa dòng Shared Lock so với khóa phạm vi Key-Range Lock (3.0đ): Lập luận thuyết phục vì sao khóa trên dòng hiện hữu không chặn được lệnh chèn mới và vai trò của Key-Range Lock ở mức Serializable.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Tại sao mức cô lập Repeatable Read có thể chống được Non-repeatable Read nhưng lại không thể ngăn chặn được hiện tượng Phantom Read?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000131", CourseDbi202Id, "00000000-0000-0000-0000-000000000667", RubricDbi202Id, "Bản chất Deadlock trong cơ sở dữ liệu và các kỹ thuật phòng chống / giải quyết", "Deadlock (Khóa chết) trong hệ quản trị cơ sở dữ liệu là gì và DBMS phát hiện Deadlock bằng cơ chế nào? Hãy trình bày 3 nguyên tắc thiết kế giao dịch và cơ chế cấu hình trong SQL Server giúp giảm thiểu tối đa rủi ro xảy ra Deadlock.", "Deadlock là trạng thái bế tắc vĩnh viễn xảy ra khi hai hay nhiều giao dịch chạy đồng thời cùng nắm giữ khóa độc quyền trên một tài nguyên và đồng thời chờ xin khóa trên tài nguyên mà giao dịch kia đang giữ, tạo thành chu trình chờ đợi khép kín (Circular Wait) khiến không giao dịch nào có thể tiến triển. Hệ quản trị CSDL phát hiện Deadlock nhờ tiến trình nền Deadlock Monitor quét định kỳ Đồ thị Chờ (Wait-For Graph); nếu phát hiện chu trình khép kín trên đồ thị, hệ thống lập tức giải cứu bằng cách chọn một giao dịch làm Nạn nhân (Deadlock Victim), tự động ROLLBACK giao dịch đó và trả mã lỗi 1205 để ứng dụng thử lại, ưu tiên chọn giao dịch có độ ưu tiên thấp hơn (DEADLOCK_PRIORITY) hoặc tốn ít chi phí hoàn tác nhật ký Transaction Log nhất. Ba nguyên tắc cốt lõi giúp giảm thiểu tối đa Deadlock gồm: (1) Truy cập và khóa các bảng hoặc bản ghi theo một thứ tự cố định, nhất quán trên toàn bộ các thủ tục trong hệ thống để triệt tiêu điều kiện chờ vòng tròn; (2) Giữ phạm vi giao dịch ngắn gọn nhất có thể, kiểm tra nghiệp vụ trước khi mở giao dịch và tuyệt đối không chờ tương tác người dùng hay gọi dịch vụ mạng bên trong Transaction; (3) Thiết kế chỉ mục phù hợp để dùng khóa dòng thay vì quét bảng và bật cơ chế đa phiên bản dòng Read Committed Snapshot Isolation (RCSI) để thao tác đọc không tranh chấp khóa với thao tác ghi.", "[\"Định nghĩa Deadlock & Đồ thị Wait-For Graph (3.0đ): Nêu rõ bản chất chu trình chờ đợi khép kín giữa các giao dịch và cơ chế quét chu trình trên đồ thị Wait-For Graph.\", \"Cơ chế chọn Nạn nhân (Victim) & Rollback (3.5đ): Phân tích cách DBMS tự động rollback nạn nhân (lỗi 1205) và tiêu chí dựa trên mức ưu tiên cùng chi phí hoàn tác nhật ký.\", \"Ba nguyên tắc thiết kế giao dịch và cấu hình chống Deadlock (3.5đ): Trình bày chuẩn xác nguyên tắc cố định thứ tự khóa tài nguyên, rút ngắn thời gian giữ giao dịch và tối ưu chỉ mục kết hợp RCSI.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Khi phát hiện Deadlock, DBMS sẽ làm gì để giải phóng hệ thống và dựa vào tiêu chí nào để chọn 'Nạn nhân' (Deadlock Victim)?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000132", CourseDbi202Id, "00000000-0000-0000-0000-000000000667", RubricDbi202Id, "Các trường hợp vô hiệu hóa chỉ mục B-Tree (Index Invalidation) và giải pháp khắc phục", "Trong tối ưu hóa truy vấn SQL, hiện tượng Vô hiệu hóa chỉ mục do vi phạm tính SARGable (Search Argument Able) là gì? Hãy phân tích 3 thói quen đặt điều kiện lọc trong mệnh đề WHERE làm mất tính SARGable khiến bộ tối ưu hóa buộc phải bỏ qua Index Seek để chuyển sang quét toàn bộ Index Scan hoặc Table Scan, đồng thời trình bày nguyên tắc biến đổi lại điều kiện lọc để tận dụng Index Seek.", "Hiện tượng vô hiệu hóa chỉ mục xảy ra khi cột lọc đã được đánh chỉ mục B-Tree nhưng biểu thức trong mệnh đề WHERE lại biến đổi giá trị cột trước khi so sánh (vi phạm tính SARGable), khiến Query Optimizer không thể điều hướng từ nút gốc xuống nút lá bằng Index Seek mà buộc phải quét tuần tự toàn bộ trang chỉ mục hoặc toàn bộ bảng. Ba thói quen gây lỗi phổ biến và nguyên tắc khắc phục gồm: (1) Bọc hàm tính toán quanh cột chỉ mục, chẳng hạn gọi hàm lấy năm YEAR trên cột Ngày đặt hàng bằng 2024; nguyên tắc khắc phục là giữ nguyên cột Ngày đặt hàng đứng độc lập ở một vế và chuyển thành lọc khoảng nửa mở từ ngày đầu năm 2024 đến nhỏ hơn ngày đầu năm 2025. (2) Đặt phép toán số học trực tiếp lên cột chỉ mục, như lấy cột Lương nhân 1,1 lớn hơn 20 triệu; khắc phục bằng cách chuyển toàn bộ phép chia sang phía hằng số đối diện để cột Lương đứng nguyên bản. (3) Gây ép kiểu dữ liệu ngầm định (Implicit Conversion), ví dụ cột Số điện thoại lưu kiểu chuỗi VARCHAR không dấu nhưng tham số truyền vào lại là kiểu số nguyên hoặc chuỗi Unicode NVARCHAR có độ ưu tiên kiểu cao hơn, buộc SQL Server tự động bọc hàm CONVERT lên toàn bộ cột trên bảng; khắc phục bằng cách truyền đúng kiểu dữ liệu tương ứng với định nghĩa cột. Ngoài ra, đặt dấu phần trăm ở đầu mẫu LIKE cũng làm mất khả năng Index Seek vì cây B-Tree sắp xếp từ điển từ trái sang phải nên mất điểm neo ký tự đầu tiên.", "[\"Bản chất khái niệm SARGable & Index Invalidation (3.0đ): Giải thích rõ lý do biến đổi giá trị cột làm mất khả năng điều hướng cây B-Tree, đẩy kế hoạch thực thi từ Index Seek sang Scan.\", \"Phân tích 3 thói quen vi phạm SARGable và nguyên tắc khắc phục (4.5đ): Chỉ rõ lỗi bọc hàm lên cột, thực hiện phép toán trên cột và ép kiểu ngầm định kèm nguyên tắc cô lập cột gốc để bảo toàn Index Seek.\", \"Giải thích nguyên lý B-Tree với ký tự đại diện đầu chuỗi trong LIKE (2.5đ): Lập luận chính xác thứ tự sắp xếp từ trái sang phải của cây B-Tree khiến mẫu tìm kiếm bắt đầu bằng phần trăm không thể định vị nhánh.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Khi tìm kiếm chuỗi ký tự với toán tử LIKE mà đặt ký tự đại diện phần trăm ngay ở đầu mẫu tìm kiếm thì hệ quản trị cơ sở dữ liệu có tận dụng được chỉ mục B-Tree để thực hiện Index Seek hay không? Tại sao?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000133", CourseDbi202Id, "00000000-0000-0000-0000-000000000666", RubricDbi202Id, "So sánh Hàm Vô hướng (Scalar UDF) và Hàm Giá trị Bảng Nội tuyến (Inline TVF) trong T-SQL & Tối ưu hóa Hiệu năng", "Trong MS SQL Server, hãy phân biệt 3 loại Hàm do người dùng định nghĩa (User-Defined Functions) gồm: Scalar UDF, Inline Table-Valued Function và Multi-Statement Table-Valued Function. Tại sao việc đặt một Scalar UDF có truy vấn dữ liệu bên trong mệnh đề SELECT hoặc WHERE trên bảng hàng triệu dòng lại gây suy giảm hiệu năng nghiêm trọng, và hãy giải thích cơ chế chuyển đổi từ Scalar UDF sang Inline Table-Valued Function kết hợp toán tử CROSS APPLY giúp bộ tối ưu hóa trải phẳng truy vấn như thế nào?", "Trong MS SQL Server có ba loại hàm người dùng định nghĩa: (1) Scalar UDF có khối thân thủ tục BEGIN - END và trả về một giá trị đơn lẻ thuộc kiểu dữ liệu vô hướng; (2) Inline Table-Valued Function (iTVF) hoàn toàn không có khối BEGIN - END mà chỉ trả về trực tiếp kết quả của duy nhất một câu truy vấn SELECT, hoạt động tương đương một Khung nhìn có tham số (Parameterized View); (3) Multi-Statement Table-Valued Function (mTVF) khai báo một biến bảng trung gian, dùng nhiều câu lệnh nạp dữ liệu vào biến bảng trong thân hàm rồi mới trả về, thường ước lượng sai số dòng thống kê. Khi gọi một Scalar UDF có truy vấn bảng trên tập dữ liệu một triệu dòng, hiệu năng sụp đổ vì hai nguyên nhân chính: thứ nhất là hội chứng xử lý từng dòng RBAR khiến hàm bị khởi tạo ngữ cảnh và truy vấn lặp lại đúng một triệu lần riêng rẽ; thứ hai là Scalar UDF truyền thống chặn đứng khả năng thực thi đa luồng, ép toàn bộ câu truy vấn lớn phải chạy đơn luồng (Serial Plan). Khi chuyển logic tính toán sang một Inline TVF và ghép với bảng chính thông qua toán tử CROSS APPLY (tương tự INNER JOIN) hoặc OUTER APPLY (tương tự LEFT JOIN giữ cả dòng không khớp), bộ tối ưu hóa Query Optimizer sẽ mở bung và trải phẳng câu lệnh SELECT của hàm trực tiếp vào cây đại số của truy vấn chính để tạo thành một phép JOIN gom nhóm theo tập hợp duy nhất, tận dụng trọn vẹn chỉ mục và xử lý song song.", "[\"Phân biệt chính xác 3 loại UDF (Scalar UDF, Inline TVF, Multi-Statement TVF) (3.5đ): Trình bày rõ đặc điểm cấu trúc và kiểu trả về của từng loại, nhấn mạnh Inline TVF chỉ chứa một truy vấn SELECT đơn tương đương View có tham số.\", \"Phân tích đúng nguyên nhân nghẽn hiệu năng RBAR và chặn Parallelism của Scalar UDF (3.0đ): Chỉ rõ việc gọi lặp ngữ cảnh hàm theo từng dòng và hạn chế ép kế hoạch thực thi chạy đơn luồng trên bảng lớn.\", \"Giải thích cơ chế tối ưu bằng Inline TVF kết hợp toán tử APPLY (3.5đ): Phân tích rõ cách bộ tối ưu hóa trải phẳng Inline TVF vào cây truy vấn chính qua CROSS APPLY hoặc OUTER APPLY để xử lý theo tập hợp.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, "Tại sao một User-Defined Function trong MS SQL Server bị cấm thực hiện các thao tác có hiệu ứng phụ làm thay đổi trạng thái cơ sở dữ liệu như INSERT, UPDATE, DELETE lên bảng vật lý? Trong trường hợp chuyển sang dùng toán tử APPLY với Inline TVF, khi nào ta phải dùng OUTER APPLY thay cho CROSS APPLY?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000134", CourseDbi202Id, "00000000-0000-0000-0000-000000000664", RubricDbi202Id, "Phân tích ưu nhược điểm của 3 chiến lược ánh xạ mối quan hệ kế thừa ISA sang CSDL quan hệ", "Khi chuyển đổi một mối quan hệ kế thừa phân cấp (ISA Hierarchy, ví dụ: Lớp cha Person có 2 lớp con là Student và Instructor) sang cơ sở dữ liệu quan hệ, hãy phân tích chi tiết 3 chiến lược thiết kế phổ biến: (1) Tạo bảng cho từng thực thể (ER Approach / Table-per-Type); (2) Tạo bảng chỉ cho các lớp lá (OO Approach / Table-per-Concrete-Class); (3) Gộp tất cả vào một bảng duy nhất (Single Table / Table-per-Hierarchy). Đánh giá ưu nhược điểm của từng phương án.", "3 chiến lược ánh xạ quan hệ kế thừa: (1) Table-per-Type (ER Approach): Tạo bảng riêng cho cả lớp cha và từng lớp con. Bảng Person(PersonID, Name); Bảng Student(PersonID, GPA); Bảng Instructor(PersonID, Salary). PersonID ở bảng con vừa là Khóa chính vừa là Khóa ngoại trỏ về bảng cha. Ưu điểm: Chuẩn hóa 3NF tuyệt đối, không có giá trị NULL dư thừa, dễ dàng mở rộng lớp con mới. Nhược điểm: Truy vấn thông tin đầy đủ bắt buộc phải dùng JOIN nhiều bảng làm chậm hiệu năng. (2) Table-per-Concrete-Class (OO Approach): Chỉ tạo bảng cho các lớp con lá, mỗi bảng chứa toàn bộ thuộc tính của lớp cha và lớp con đó. Bảng Student(StudentID, Name, GPA); Bảng Instructor(InstructorID, Name, Salary). Ưu điểm: Truy vấn thực thể con nhanh chóng không cần JOIN. Nhược điểm: Trùng lặp cấu trúc thuộc tính chung ở nhiều bảng; rất khó truy vấn danh sách tổng hợp toàn bộ Person; không hỗ trợ một người vừa là Student vừa là Instructor (Overlapping). (3) Table-per-Hierarchy (Single Table): Gộp toàn bộ vào 1 bảng Person(PersonID, Name, Discriminator, GPA, Salary). Ưu điểm: Hiệu năng cao nhất, không cần JOIN, truy vấn cực kỳ đơn giản. Nhược điểm: Bảng bị phình to chứa rất nhiều giá trị NULL ở các cột đặc thù của lớp khác, và KHÔNG THỂ đặt ràng buộc NOT NULL trên các cột nghiệp vụ bắt buộc của lớp con (ví dụ không thể đặt GPA NOT NULL vì Instructor không có GPA).", "[\"Phân tích chiến lược Table-per-Type (TPT) (3.5đ): Mô tả đúng cấu trúc bảng cha/con, khóa ngoại và đánh giá ưu thế 3NF cùng nhược điểm phép JOIN.\", \"Phân tích chiến lược Table-per-Concrete-Class (TPC) (3.0đ): Mô tả đúng việc chỉ tạo bảng lá, ưu điểm không JOIN và nhược điểm khó truy vấn tổng hợp.\", \"Phân tích chiến lược Single Table (TPH) & Hạn chế NOT NULL (3.5đ): Chỉ rõ cơ chế dùng cột Discriminator, ưu thế tốc độ và nhược điểm nghiêm trọng mất ràng buộc NOT NULL.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Phương án gộp tất cả vào một bảng duy nhất (Single Table) gây ra nhược điểm lớn gì về mặt ràng buộc toàn vẹn dữ liệu (NOT NULL)?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000135", CourseDbi202Id, "00000000-0000-0000-0000-000000000666", RubricDbi202Id, "Tác động của Cursor đến hiệu năng hệ thống và giải pháp chuyển đổi sang tư duy tập hợp (Set-based)", "Cursor (Con trỏ) trong T-SQL là gì? Tại sao trong các hệ quản trị cơ sở dữ liệu quan hệ, việc lạm dụng Cursor bị coi là một Anti-pattern gây suy giảm hiệu năng nghiêm trọng? Nêu các giải pháp kỹ thuật hiện đại trong SQL để thay thế Cursor.", "Cursor là cơ chế trong T-SQL cho phép lập trình viên duyệt và xử lý dữ liệu theo từng dòng tuần tự (Row-by-Row) giống như vòng lặp trong các ngôn ngữ lập trình thủ tục. Thuật ngữ RBAR là viết tắt của Row-By-Agonizing-Row (Duyệt từng dòng đầy thống khổ), phản ánh sự xung đột trực tiếp với triết lý thiết kế cốt lõi của hệ quản trị CSDL quan hệ là Xử lý theo Tập hợp (Set-based processing). Lý do Cursor bị coi là Anti-pattern gây suy giảm hiệu năng nghiêm trọng gồm: (1) Chi phí tài nguyên: Cursor duy trì cấu trúc trạng thái con trỏ tốn kém trên bộ nhớ RAM và vùng nhớ tạm tempdb; (2) Khóa và tương tranh: Cursor mặc định giữ các khóa tài nguyên kéo dài qua từng vòng lặp dòng, dễ gây nghẽn hàng loạt và dẫn tới Deadlock; (3) Triệt tiêu khả năng tối ưu hóa: Bộ xử lý truy vấn không thể áp dụng thực thi song song (Parallelism) hay các thuật toán kết nối tập hợp hiệu quả như Hash Join, Merge Join. Các giải pháp thay thế chuẩn Set-based gồm: viết câu lệnh UPDATE hoặc INSERT kết hợp trực tiếp với JOIN và Subquery; tận dụng nhóm hàm cửa sổ Window Functions như ROW_NUMBER, RANK, LEAD, LAG hay hàm tổng hợp đi kèm mệnh đề OVER; dùng Biểu thức bảng chung đệ quy (Recursive CTE); hoặc kết hợp Inline TVF với toán tử CROSS APPLY.", "[\"Khái niệm Cursor & Thuật ngữ RBAR (3.0đ): Nêu đúng định nghĩa duyệt từng dòng và giải nghĩa chính xác thuật ngữ Row-By-Agonizing-Row.\", \"Phân tích 3 nguyên nhân Cursor làm suy giảm hiệu năng (4.0đ): Phân tích sâu sắc về chi phí RAM, hiện tượng giữ khóa gây Deadlock và vô hiệu hóa Parallelism.\", \"Các giải pháp kỹ thuật thay thế chuẩn Set-based (3.0đ): Đề xuất đầy đủ các công cụ hiện đại: Window Functions, Recursive CTE, APPLY và JOIN.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, "Khái niệm RBAR trong tối ưu hóa cơ sở dữ liệu là viết tắt của cụm từ gì và phản ánh bản chất gì của Cursor?"),
            CreatePracticeSeed("00000000-0000-0000-0006-000000000136", CourseDbi202Id, "00000000-0000-0000-0000-000000000667", RubricDbi202Id, "Thiết kế và quản lý Giao dịch lồng ghép (Nested Transactions) và Điểm lưu (Savepoints) trong T-SQL", "Trong MS SQL Server, biến hệ thống đếm mức giao dịch TRANCOUNT thay đổi giá trị như thế nào khi gặp các lệnh BEGIN TRANSACTION, COMMIT TRANSACTION và ROLLBACK TRANSACTION? Tại sao lệnh ROLLBACK TRANSACTION thông thường không thể chỉ hoàn tác một giao dịch con bên trong và cơ chế Điểm lưu SAVE TRANSACTION (Savepoint) giải quyết bài toán khôi phục từng phần này ra sao?", "Biến hệ thống TRANCOUNT dùng để theo dõi độ sâu của các mức giao dịch đang mở trong phiên hiện tại: (1) Mỗi lần gọi BEGIN TRANSACTION, giá trị TRANCOUNT tăng thêm 1 đơn vị; (2) Mỗi lần gọi COMMIT TRANSACTION ở mức trong, SQL Server chưa ghi xác nhận vật lý ngay mà chỉ giảm giá trị TRANCOUNT đi 1 đơn vị, dữ liệu chỉ thực sự được xác nhận bền vững xuống đĩa (Physical Commit) khi lệnh COMMIT ngoài cùng đưa TRANCOUNT giảm về đúng bằng 0; (3) Ngược lại, khi thực thi lệnh ROLLBACK TRANSACTION thông thường không chỉ định tên điểm lưu, toàn bộ công việc của tất cả các mức giao dịch từ ngoài vào trong đều bị hủy bỏ sạch sẽ và TRANCOUNT lập tức bị đưa thẳng về 0 (nếu bên ngoài cố gọi tiếp COMMIT khi TRANCOUNT đã bằng 0 sẽ phát sinh lỗi runtime). Vì SQL Server không hỗ trợ giao dịch con tự trị thực sự, muốn hoàn tác một phần công việc phụ mà vẫn giữ sống giao dịch chính, ta sử dụng lệnh SAVE TRANSACTION kèm một tên định danh để đánh dấu Điểm lưu (Savepoint). Khi nhánh phụ gặp lỗi nhẹ có thể bỏ qua, ta gọi ROLLBACK TRANSACTION trỏ đúng về tên Savepoint đó: hệ thống chỉ hoàn tác các thao tác phát sinh sau điểm lưu, giữ nguyên giá trị TRANCOUNT hiện tại để giao dịch chính tiếp tục chạy và COMMIT an toàn.", "[\"Cơ chế hoạt động của biến đếm mức giao dịch TRANCOUNT (3.5đ): Giải thích rõ ràng quy tắc tăng giảm của TRANCOUNT và điều kiện commit vật lý khi bộ đếm giảm về 0.\", \"Hành vi của lệnh ROLLBACK thông thường (3.0đ): Chỉ rõ ROLLBACK không kèm tên điểm lưu sẽ đưa TRANCOUNT ngay lập tức về 0 và hủy bỏ toàn bộ chuỗi lồng nhau.\", \"Kỹ thuật Savepoint (SAVE TRANSACTION) và Partial Rollback (3.5đ): Trình bày chính xác cơ chế hoàn tác có chọn lọc về điểm lưu mà vẫn giữ nguyên TRANCOUNT để giao dịch chính tiếp tục.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, "Nếu trong một chuỗi gồm 3 mức BEGIN TRANSACTION lồng nhau, một thủ tục ở mức trong cùng thực thi lệnh ROLLBACK TRANSACTION không kèm tên Savepoint thì giá trị của biến đếm TRANCOUNT sẽ trở thành bao nhiêu, và điều gì xảy ra nếu thủ tục bên ngoài không kiểm tra trạng thái mà tiếp tục gọi COMMIT TRANSACTION?"),
        };

        foreach (var q in questions)
        {
            if (!existingById.TryGetValue(q.Id, out var existingQ))
            {
                context.PracticeQuestions.Add(q);
            }
            else
            {
                existingQ.CloId = q.CloId;
                existingQ.RubricId = q.RubricId;
                existingQ.Title = q.Title;
                existingQ.Content = q.Content;
                existingQ.SampleAnswer = q.SampleAnswer;
                existingQ.KeyPoints = q.KeyPoints;
                existingQ.Difficulty = q.Difficulty;
                existingQ.BloomLevel = q.BloomLevel;
                existingQ.HasFollowUp = true;
                existingQ.FollowUpPrompt = q.FollowUpPrompt;
                existingQ.ApprovalStatus = ApprovalStatus.Approved;
                existingQ.ApprovedBy = DepartmentHeadUserId;
                existingQ.SubmittedBy = LecturerUserId;
                existingQ.IsActive = true;
            }
        }

        await context.SaveChangesAsync(cancellationToken);
    }

    private static async Task EnsureAdditionalExamQuestionsAsync(OralExamDbContext context, CancellationToken cancellationToken)
    {
        var existingExamQuestions = await context.ExamQuestions.ToListAsync(cancellationToken);
        var existingById = existingExamQuestions.ToDictionary(q => q.Id);

        var examQuestions = new List<ExamQuestion>
        {
            // =========================================================================
            // 1. PRF192 — 26 CÂU HỎI KHO THI THẬT (6 Remember, 8 Understand, 7 Apply, 5 Analyze)
            // =========================================================================
            CreateExamSeed("00000000-0000-0000-0004-000000000201", CoursePrf192Id, "00000000-0000-0000-0000-000000000461", StructurePrf192Id, RubricPrf192Id, "Quy chuẩn chú thích mã nguồn C và cơ chế xử lý của Preprocessor (CQ2.2)", "Hãy phân biệt hai kiểu chú thích theo khối nhiều dòng và chú thích trên một dòng trong ngôn ngữ C về lịch sử chuẩn hóa và phạm vi tác dụng. Tại sao chuẩn C không cho phép lồng các khối chú thích nhiều dòng vào nhau, và bộ tiền xử lý thay thế mỗi chú thích bằng ký tự gì trước khi biên dịch?", "Ngôn ngữ C hỗ trợ hai hình thức chú thích phục vụ tài liệu hóa mã nguồn. Thứ nhất là chú thích khối nhiều dòng (Block Comment) có mặt từ chuẩn ANSI C89, mở đầu bằng cặp dấu gạch chéo sao và kết thúc tại cặp dấu sao gạch chéo đầu tiên gặp phải, có thể trải trên nhiều dòng hoặc chèn giữa hai thành tố trên cùng một dòng. Thứ hai là chú thích một dòng (Single-line Comment) được chuẩn hóa chính thức từ chuẩn C99, bắt đầu bằng hai dấu gạch chéo liên tiếp và kéo dài đến hết dòng hiện hành. Chuẩn C nghiêm cấm lồng các khối chú thích nhiều dòng vào nhau bởi bộ phân tích từ vựng không đếm độ sâu đóng mở: ngay khi đã vào trạng thái chú thích khối, nó phớt lờ mọi dấu mở mới bên trong và lập tức đóng chú thích ngay tại dấu kết thúc đầu tiên bắt gặp, khiến phần nội dung phía sau lộ ra thành lệnh thực thi và gây lỗi biên dịch ở dấu đóng dư thừa cuối cùng. Do đó, khi muốn tạm ngắt một vùng lệnh lớn chứa sẵn nhiều chú thích, giải pháp chuẩn là bọc bằng cặp chỉ thị tiền xử lý điều kiện if 0 và endif vốn hỗ trợ lồng nhau an toàn. Ở giai đoạn tiền xử lý (Translation Phase 3), mỗi chú thích không bị xóa rỗng hoàn toàn mà được thay thế bằng đúng một ký tự khoảng trắng đơn, giúp ngăn hai từ khóa đứng sát hai bên chú thích bị dính liền thành một định danh sai.", "[\"Phân biệt chú thích khối nhiều dòng (C89) và chú thích một dòng (C99) (3.0đ): Trình bày rõ đặc điểm nhận diện, phạm vi tác dụng và chuẩn C áp dụng cho hai kiểu chú thích.\", \"Giải thích nguyên nhân lỗi khi lồng chú thích khối và giải pháp if 0 (4.0đ): Chỉ rõ bộ phân tích từ vựng đóng chú thích ngay tại dấu kết thúc đầu tiên và nêu giải pháp dùng chỉ thị tiền xử lý if 0 kèm endif.\", \"Cơ chế Preprocessor thay thế mỗi chú thích bằng một khoảng trắng đơn (3.0đ): Khẳng định giai đoạn tiền xử lý thay chú thích bằng đúng 1 khoảng trắng để tránh dính liền hai từ khóa hoặc định danh.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 1),
            CreateExamSeed("00000000-0000-0000-0004-000000000202", CoursePrf192Id, "00000000-0000-0000-0000-000000000462", StructurePrf192Id, RubricPrf192Id, "Các toán tử thao tác Bit (Bitwise Operators) và nguyên lý mặt nạ Bitmask trong C", "Hãy liệt kê sáu toán tử thao tác bit trong ngôn ngữ C và phân biệt sự khác nhau căn bản giữa nhóm toán tử AND bit, OR bit với nhóm toán tử AND logic, OR logic. Giải thích nguyên lý tạo mặt nạ bit bằng phép dịch trái hằng số 1 không dấu sang k vị trí rồi kết hợp các phép toán bit để bật, tắt, đảo trạng thái và kiểm tra bit thứ k của một biến cờ không dấu.", "Ngôn ngữ C cung cấp sáu toán tử thao tác trực tiếp mức nhị phân trên kiểu nguyên gồm: AND bit (cho bit 1 khi cả hai bit cùng bằng 1), OR bit (cho bit 1 khi ít nhất một bit bằng 1), XOR bit (cho bit 1 khi hai bit khác nhau), NOT bit (đảo toàn bộ 0 thành 1 và 1 thành 0), dịch trái (dịch các bit sang trái k vị trí, chèn 0 vào bên phải) và dịch phải (trên kiểu không dấu luôn chèn bit 0 vào bên trái; còn trên số âm có dấu thì phụ thuộc trình biên dịch chèn bit dấu 1 hay bit 0 nên cần dùng kiểu unsigned để đảm bảo dịch logic thuần túy). Nhóm toán tử AND bit và OR bit khác hẳn nhóm AND logic và OR logic ở hai điểm: toán tử bit tính toán độc lập trên từng cặp bit tương ứng và trả về một giá trị nguyên mới đồng thời luôn đánh giá cả hai toán hạng, trong khi toán tử logic chỉ xét tính đúng sai toàn cục trả về 0 hoặc 1 và có cơ chế đoản mạch dừng sớm. Để thao tác bit thứ k (tính từ 0), ta dịch trái hằng số không dấu 1U sang k vị trí để tạo mặt nạ chỉ có duy nhất bit thứ k bằng 1: dùng phép OR bit với mặt nạ để bật bit k lên 1; đảo ngược mặt nạ bằng NOT bit rồi thực hiện AND bit để tắt bit k về 0; dùng phép XOR bit với mặt nạ để lật trạng thái bit k; và dùng phép AND bit với mặt nạ rồi kiểm tra kết quả khác 0 để biết bit thứ k đang bật hay tắt.", "[\"Liệt kê đúng chức năng 6 toán tử thao tác bit (3.0đ): Trình bày chính xác vai trò của AND bit, OR bit, XOR bit, NOT bit, dịch trái và dịch phải kèm lưu ý kiểu không dấu.\", \"Phân biệt rõ toán tử mức bit với toán tử AND logic và OR logic (3.0đ): Chỉ rõ khác biệt giữa tính toán từng cặp bit trả số nguyên không đoản mạch so với đánh giá đúng sai có đoản mạch.\", \"Giải thích đúng nguyên lý 4 thao tác mặt nạ Bitmask tại bit thứ k (4.0đ): Mô tả chính xác cách dịch trái hằng 1U tạo mặt nạ rồi phối hợp OR để bật, AND với đảo mặt nạ để tắt, XOR để đảo và AND để kiểm tra.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 2),
            CreateExamSeed("00000000-0000-0000-0004-000000000203", CoursePrf192Id, "00000000-0000-0000-0000-000000000462", StructurePrf192Id, RubricPrf192Id, "Danh mục và mức ưu tiên của các toán tử số học, logic và quan hệ trong C", "Hãy sắp xếp bảy nhóm toán tử sau theo thứ tự độ ưu tiên từ cao nhất xuống thấp nhất trong ngôn ngữ C: nhóm toán tử gán, nhóm toán tử số học nhân chia lấy dư, nhóm toán tử logic AND và OR, cặp dấu ngoặc đơn gom biểu thức, nhóm toán tử số học cộng trừ, nhóm toán tử quan hệ lớn bé và nhóm toán tử quan hệ so bằng.", "Trong ngôn ngữ C, khi một biểu thức phức hợp chứa nhiều loại toán tử khác nhau, trình biên dịch quyết định thứ tự gom nhóm dựa trên bảng độ ưu tiên từ cao nhất xuống thấp nhất như sau. Đứng ở mức cao nhất là cặp dấu ngoặc đơn gom biểu thức cùng các toán tử truy xuất mảng và thành viên cấu trúc (ngoài ra ngay dưới nhóm này là các toán tử một ngôi như phủ định, lấy địa chỉ, giải tham chiếu, ép kiểu và sizeof). Tiếp theo ở nhóm số học là các toán tử nhân, chia và chia lấy dư, rồi mới đến nhóm toán tử cộng và trừ. Sau khi hoàn tất các phép tính số học, trình biên dịch mới đánh giá nhóm toán tử quan hệ so sánh thứ tự lớn hơn, nhỏ hơn, lớn hơn hoặc bằng, nhỏ hơn hoặc bằng; kế tiếp ngay bên dưới là nhóm quan hệ kiểm tra bằng nhau và khác nhau. Ở tầng logic, toán tử AND logic có độ ưu tiên cao hơn toán tử OR logic (giống phép nhân ưu tiên hơn phép cộng trong đại số Boole). Đứng thấp hơn nữa là toán tử điều kiện ba ngôi, và cuối cùng ở mức ưu tiên thấp nhất là nhóm các toán tử gán đơn giản và gán kết hợp nhằm đảm bảo toàn bộ vế phải luôn được tính xong trước khi ghi vào biến vế trái. Về tính kết hợp khi cùng mức ưu tiên, đa số toán tử kết hợp từ trái sang phải, riêng ba nhóm gồm toán tử một ngôi, toán tử điều kiện ba ngôi và toàn bộ các toán tử gán lại kết hợp từ phải sang trái.", "[\"Sắp xếp đúng thứ tự ưu tiên từ dấu ngoặc đơn xuống toán tử gán (4.5đ): Xếp chuẩn thứ tự: Ngoặc đơn, Nhân chia dư, Cộng trừ, Quan hệ lớn bé, So bằng, AND logic, OR logic rồi thấp nhất là Gán.\", \"Giải thích vai trò của tính kết hợp Associativity (2.5đ): Trình bày rõ quy tắc phân định thứ tự thực hiện khi nhiều toán tử có cùng mức độ ưu tiên đứng cạnh nhau.\", \"Nhận diện chính xác ba nhóm toán tử kết hợp từ phải sang trái (3.0đ): Chỉ rõ nhóm toán tử một ngôi, toán tử điều kiện ba ngôi và nhóm toán tử gán kết hợp từ phải qua trái.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 3),
            CreateExamSeed("00000000-0000-0000-0004-000000000204", CoursePrf192Id, "00000000-0000-0000-0000-000000000464", StructurePrf192Id, RubricPrf192Id, "Phân loại bốn lớp lưu trữ (Storage Classes) trong C: auto, register, static và extern", "Ngôn ngữ C quy định bốn lớp lưu trữ thông qua các từ khóa auto, register, static và extern. Hãy trình bày ý nghĩa, phân vùng lưu trữ, thời gian sống và phạm vi liên kết của từng lớp lưu trữ này.", "Bốn lớp lưu trữ trong ngôn ngữ C quy định nơi lưu trữ vật lý, thời gian sống và phạm vi liên kết của biến và hàm. Thứ nhất, lớp auto là mặc định cho biến cục bộ trong khối lệnh: nằm trên ngăn xếp Stack, cấp phát khi vào khối và hủy ngay khi rời khối lệnh. Thứ hai, lớp register có phạm vi và vòng đời cục bộ giống auto nhưng gợi ý trình biên dịch đặt biến thẳng vào thanh ghi tốc độ cao của CPU thay vì RAM; chính vì thanh ghi CPU không có địa chỉ bộ nhớ RAM nên chuẩn C cấm tuyệt đối việc lấy địa chỉ của biến register. Thứ ba, lớp static đặt biến vào phân vùng dữ liệu tĩnh Data hoặc BSS, tồn tại suốt vòng đời chương trình và mặc định khởi tạo bằng 0: gắn cho biến cục bộ giúp giữ nguyên giá trị giữa các lần gọi hàm, còn gắn cho biến toàn cục hoặc hàm giúp giới hạn thành liên kết nội bộ (Internal Linkage) chỉ nhìn thấy trong tệp nguồn hiện tại. Thứ tư, lớp extern thông báo biến toàn cục hoặc hàm có liên kết ngoài (External Linkage) đã được định nghĩa cấp phát ở một tệp nguồn khác để chia sẻ xuyên dự án mà không bị lỗi trùng lặp.", "[\"Đặc tả lớp lưu trữ auto và register kèm quy tắc cấm lấy địa chỉ (3.0đ): Nêu rõ auto nằm trên Stack còn register gợi ý đặt vào thanh ghi CPU không có địa chỉ RAM nên cấm lấy địa chỉ.\", \"Đặc tả hai vai trò của lớp lưu trữ static cục bộ và mức tệp (4.0đ): Phân tích rõ thời gian sống tĩnh suốt chương trình, giữ giá trị biến cục bộ và giới hạn Internal Linkage trong tệp nguồn.\", \"Đặc tả lớp lưu trữ extern và cơ chế liên kết đa tệp (3.0đ): Giải thích đúng vai trò tham chiếu tới biến hoặc hàm toàn cục định nghĩa ở tệp khác qua External Linkage.\"]", QuestionDifficulty.Medium, BloomLevel.Remember, 4),
            CreateExamSeed("00000000-0000-0000-0004-000000000205", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", StructurePrf192Id, RubricPrf192Id, "Phân biệt con trỏ NULL, con trỏ tổng quát void* và con trỏ hoang (Wild Pointer) trong C", "Hãy định nghĩa và phân biệt rõ bản chất giữa con trỏ NULL, con trỏ tổng quát kiểu void và con trỏ hoang Wild Pointer trong ngôn ngữ C. Tại sao trình biên dịch C ngăn cấm việc giải tham chiếu trực tiếp hoặc thực hiện phép cộng trừ số học trực tiếp trên con trỏ tổng quát kiểu void?", "Ba khái niệm con trỏ trên phản ánh ba trạng thái địa chỉ và kiểu dữ liệu khác nhau trong ngôn ngữ C. Thứ nhất, con trỏ NULL được gán tường minh hằng số NULL nhằm đánh dấu có chủ đích rằng nó hiện không trỏ tới vùng nhớ hợp lệ nào, giúp kiểm tra điều kiện khác NULL tin cậy trước khi truy xuất. Thứ hai, con trỏ tổng quát kiểu void (Generic Pointer) lưu địa chỉ vùng nhớ hợp lệ nhưng không gắn với kiểu dữ liệu cụ thể, thường dùng ở giá trị trả về của malloc hoặc tham số của memcpy, qsort. Thứ ba, con trỏ hoang (Wild Pointer) là con trỏ cục bộ trên Stack chưa khởi tạo nên chứa địa chỉ rác ngẫu nhiên; vì giá trị rác khác NULL nên bước kiểm tra khác NULL bị vô hiệu, gây ghi đè hỏng bộ nhớ hoặc lỗi Segmentation Fault, do đó con trỏ cục bộ chưa có đích phải khởi tạo bằng NULL ngay từ đầu. Trình biên dịch C cấm giải tham chiếu và cấm cộng trừ số học trực tiếp trên con trỏ kiểu void vì kiểu void không hoàn chỉnh, không có kích thước sizeof xác định để biết số byte cần đọc hay bước nhảy địa chỉ, nên bắt buộc ép kiểu tường minh sang con trỏ kiểu cụ thể trước khi thao tác.", "[\"Phân biệt chính xác bản chất NULL Pointer, Generic Pointer và Wild Pointer (4.0đ): Trình bày rõ hằng trạng thái rỗng NULL, con trỏ địa chỉ không kiểu void và mối nguy địa chỉ rác của Wild Pointer.\", \"Giải thích lý do cấm giải tham chiếu và số học trực tiếp trên con trỏ void (3.5đ): Phân tích rõ kiểu void không có kích thước sizeof xác định để biết số byte cần đọc hoặc bước nhảy địa chỉ.\", \"Nguyên tắc ép kiểu tường minh và khởi tạo NULL chống Wild Pointer (2.5đ): Nêu đúng yêu cầu ép sang con trỏ kiểu cụ thể trước khi truy xuất và quy tắc gán NULL ngay lúc tạo con trỏ cục bộ.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 5),
            CreateExamSeed("00000000-0000-0000-0004-000000000206", CoursePrf192Id, "00000000-0000-0000-0000-000000000469", StructurePrf192Id, RubricPrf192Id, "Danh mục các chế độ mở tệp (File Open Modes) trong hàm fopen", "Hãy phân biệt sự khác nhau giữa ba chế độ mở tệp cơ bản của hàm fopen trong ngôn ngữ C gồm chế độ đọc r, chế độ ghi mới w và chế độ ghi nối tiếp a xét trên hai tình huống: khi tệp đã tồn tại sẵn trên đĩa và khi tệp chưa tồn tại.", "Hàm fopen trong thư viện stdio.h thiết lập luồng giao tiếp với tệp trên đĩa theo hành vi được quy định chặt chẽ bởi chuỗi chế độ mở tệp. Thứ nhất, ở chế độ đọc r (Read), chương trình chỉ yêu cầu quyền đọc dữ liệu tính từ byte đầu tiên của tệp: nếu tệp đã tồn tại và đủ quyền truy cập thì mở thành công, ngược lại nếu tệp chưa tồn tại trên đĩa thì fopen tuyệt đối không tạo tệp mới mà lập tức thất bại và trả về con trỏ NULL. Thứ hai, ở chế độ ghi mới w (Write), cần đặc biệt cẩn trọng vì nếu tệp đã tồn tại sẵn trên đĩa, hệ điều hành sẽ lập tức cắt cụt xóa trắng toàn bộ nội dung cũ về 0 byte (Truncate) để ghi mới từ đầu; còn nếu tệp chưa tồn tại thì hệ thống tự động tạo mới một tệp rỗng. Thứ ba, ở chế độ ghi nối tiếp a (Append), nếu tệp đã tồn tại thì toàn bộ dữ liệu cũ được bảo toàn nguyên vẹn và mọi thao tác ghi luôn tự động đẩy xuống nối vào cuối tệp; nếu tệp chưa tồn tại thì hệ thống cũng tự động tạo tệp mới tương tự chế độ w. Khi ghép thêm hậu tố chữ b như rb, wb hoặc ab, chương trình chỉ định mở tệp ở chế độ nhị phân thuần túy (Binary Mode), buộc thư viện C đọc ghi nguyên vẹn từng byte thô và tắt hoàn toàn cơ chế tự động biến đổi qua lại giữa ký tự xuống dòng đơn và cặp ký tự xuống dòng về đầu dòng CRLF trên hệ điều hành Windows.", "[\"Đặc tả hành vi chế độ đọc r khi tệp tồn tại và chưa tồn tại (3.0đ): Nêu rõ mở đọc từ đầu tệp và trả về con trỏ NULL nếu tệp chưa tồn tại trên đĩa.\", \"So sánh hành vi xóa trắng của chế độ w với bảo toàn ghi đuôi của chế độ a (4.0đ): Phân tích rõ chế độ w xóa sạch dữ liệu cũ còn chế độ a giữ nguyên và ghi nối vào cuối, cả hai đều tự tạo tệp mới.\", \"Giải thích vai trò truyền luồng byte nguyên bản của hậu tố nhị phân b (3.0đ): Chỉ rõ cờ b ngăn chặn việc hệ điều hành tự động dịch đổi ký tự xuống dòng CRLF và bảo toàn dữ liệu nhị phân.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 6),
            CreateExamSeed("00000000-0000-0000-0004-000000000207", CoursePrf192Id, "00000000-0000-0000-0000-000000000466", StructurePrf192Id, RubricPrf192Id, "Đặc tả định dạng nhập xuất (Format Specifiers) và kiểm soát bộ đệm trong printf và scanf", "Trong hàm xuất printf và hàm nhập scanf của ngôn ngữ C, hãy giải thích tác dụng của cờ căn lề trái, cờ bù chữ số 0 ở đầu, độ rộng trường tối thiểu, độ chính xác phần thập phân và đặc tả scanset giới hạn số ký tự đọc đến trước dấu xuống dòng. Tại sao khi dùng scanf bắt buộc phải phân biệt đặc tả %f cho biến float với %lf cho biến double, và làm thế nào dựa vào giá trị trả về của scanf để xử lý khi người dùng nhập sai kiểu dữ liệu?", "Trong printf, cờ dấu trừ bật căn lề trái thay vì căn phải mặc định, chữ số 0 trước độ rộng trường bù các số 0 vào bên trái, độ rộng quy định số cột tối thiểu và phần sau dấu chấm làm tròn số chữ số thập phân. Trong scanf, đặc tả scanset phủ định dấu xuống dòng kèm giới hạn độ dài bằng kích thước mảng trừ 1 giúp đọc chuỗi có khoảng trắng mà không tràn bộ đệm. Sở dĩ scanf bắt buộc phân biệt %f cho con trỏ float (4 bytes) và %lf cho con trỏ double (8 bytes) vì scanf nhận địa chỉ ô nhớ đích nên không tự thăng hạng float lên double như printf; dùng nhầm %f cho biến double chỉ ghi 4 bytes làm hỏng giá trị. Hàm scanf trả về số mục đã gán thành công (hoặc EOF): khi người dùng nhập chữ vào mục số nguyên, scanf trả về nhỏ hơn số mục yêu cầu và giữ nguyên chuỗi lỗi trong stdin, nên phải kiểm tra giá trị trả về rồi lặp gọi getchar xả sạch tới dấu xuống dòng hoặc EOF. Riêng đặc tả %c không tự bỏ qua khoảng trắng nên sẽ nuốt phím Enter còn sót; chỉ cần đặt thêm một dấu cách trước %c trong chuỗi định dạng để tự bỏ qua mọi ký tự trắng tồn đọng.", "[\"Giải thích đúng cờ căn trái, bù số 0, độ rộng, độ chính xác và scanset (3.5đ): Phân tích chính xác vai trò định dạng xuất trong printf và giới hạn độ dài đọc chuỗi có khoảng trắng trong scanf.\", \"Lý giải sự khác biệt kích thước vùng nhớ giữa %f và %lf trong scanf (3.0đ): Chỉ rõ scanf truyền địa chỉ con trỏ không có thăng hạng tự động nên bắt buộc khớp 4 bytes của float và 8 bytes của double.\", \"Kiểm tra giá trị trả về của scanf, xả bộ đệm lỗi và xử lý trôi lệnh %c (3.5đ): Nêu đúng ý nghĩa số mục đọc thành công, quy trình đọc xả bằng getchar tới dấu xuống dòng và mẹo thêm khoảng trắng trước %c.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 7),
            CreateExamSeed("00000000-0000-0000-0004-000000000208", CoursePrf192Id, "00000000-0000-0000-0000-000000000462", StructurePrf192Id, RubricPrf192Id, "Cơ chế thăng hạng kiểu ngầm định (Implicit Type Promotion) trong biểu thức số học", "Quy tắc chuyển đổi số học thông thường và thăng hạng kiểu ngầm định trong ngôn ngữ C hoạt động như thế nào khi một biểu thức kết hợp các toán hạng khác kiểu dữ liệu? Hãy phân tích tại sao khi cộng một biến kiểu int có dấu mang giá trị âm 10 với một biến kiểu unsigned int không dấu mang giá trị dương 5 rồi so sánh tổng đó lớn hơn 0, kết quả điều kiện lại được đánh giá là đúng?", "Khi hai toán hạng trong phép toán số học hoặc quan hệ khác kiểu nhau, trình biên dịch C áp dụng quy tắc chuyển đổi số học thông thường (Usual Arithmetic Conversions) để đưa chúng về chung kiểu bậc cao hơn. Trước tiên, quy tắc thăng hạng số nguyên (Integer Promotion) tự động nâng các kiểu hẹp hơn int như char và short lên thành int. Tiếp theo, nếu vẫn lệch kiểu, toán hạng bậc thấp được nâng ngầm định theo thang từ int lên unsigned int, long, unsigned long, float, double và long double. Chính việc xếp unsigned int cao hơn signed int ở cùng độ rộng 32-bit tạo ra cạm bẫy khi cộng biến int bằng âm 10 với biến unsigned int bằng 5: số âm 10 bị ép chuyển ngầm định sang unsigned int. Trong hệ bù hai 32-bit, dãy bit của âm 10 (0xFFFFFFF6) khi diễn giải không dấu biến thành số dương khổng lồ 4.294.967.286; cộng thêm 5 cho ra 4.294.967.291 vẫn là số dương không dấu lớn hơn 0, khiến điều kiện lớn hơn 0 trả về đúng trái ngược trực giác toán học, do đó cần tuyệt đối tránh trộn lẫn kiểu có dấu và không dấu.", "[\"Trình bày quy tắc Integer Promotion và thang bậc chuyển đổi kiểu (3.0đ): Nêu rõ char và short tự thăng hạng lên int cùng thứ tự ưu tiên từ int lên unsigned int rồi đến các kiểu số thực.\", \"Phân tích việc ép ngầm định âm 10 sang unsigned int theo mã bù hai (3.5đ): Giải thích rõ khi trộn int với unsigned int thì số âm bị diễn dịch lại dãy bit bù hai thành số nguyên dương cực lớn.\", \"Chứng minh tổng không dấu lớn hơn 0 và bài học tránh trộn kiểu (3.5đ): Lý giải kết quả phép cộng xấp xỉ 4,29 tỷ lớn hơn 0 trả về đúng và cảnh báo không trộn lẫn kiểu có dấu với không dấu.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 8),
            CreateExamSeed("00000000-0000-0000-0004-000000000209", CoursePrf192Id, "00000000-0000-0000-0000-000000000463", StructurePrf192Id, RubricPrf192Id, "Phân tích vòng lặp lồng nhau (Nested Loops), biến cờ hiệu (Flag) và vòng lặp lính canh (Sentinel)", "Hãy phân tích cơ chế hoạt động và tổng số bước thực thi của cấu trúc hai vòng lặp lồng nhau độc lập khi vòng ngoài chạy M lần và vòng trong chạy N lần. Thế nào là vòng lặp điều khiển bằng giá trị lính canh Sentinel, và làm thế nào sử dụng biến cờ hiệu Flag để thoát êm đẹp khỏi cả hai tầng vòng lặp lồng nhau mà không lạm dụng câu lệnh nhảy goto?", "Trong vòng lặp lồng nhau (Nested Loops), mỗi một bước của vòng ngoài đều kích hoạt vòng trong khởi tạo lại và chạy trọn vẹn chu kỳ của nó. Vì vậy nếu vòng ngoài chạy M lần độc lập và vòng trong chạy N lần thì thân lệnh trong cùng thực thi M nhân N lần tức O(M nhân N); còn khi vòng trong phụ thuộc chỉ số ngoài cho j chạy từ i cộng 1 đến n trừ 1, tổng số bước bằng n nhân (n trừ 1) chia 2 tức O(n bình phương). Với bài toán chưa biết trước số lượng dữ liệu nhập, vòng lặp lính canh (Sentinel-Controlled Loop) quy ước một giá trị đặc biệt nằm ngoài miền hợp lệ (như âm 1 khi nhập điểm dương) làm tín hiệu dừng lặp và tuyệt đối không cộng giá trị lính canh này vào kết quả thống kê. Cuối cùng, vì lệnh break chỉ thoát được duy nhất một vòng lặp trực tiếp chứa nó, để dừng đồng thời cả hai vòng lặp lồng nhau mà không lạm dụng goto, ta khởi tạo biến cờ found bằng 0 và kết hợp điều kiện cờ bằng 0 bằng toán tử AND logic vào biểu thức duy trì của cả vòng trong lẫn vòng ngoài; khi tìm thấy đích và bật cờ lên 1, cả hai vòng lặp đều dừng ngay ở lần kiểm tra kế tiếp.", "[\"Phân tích quy tắc nhân số bước lặp độc lập và phụ thuộc chỉ số (3.5đ): Giải thích rõ chu kỳ toàn phần của vòng trong ứng với mỗi bước vòng ngoài cho chi phí M nhân N và công thức n(n-1)/2.\", \"Trình bày nguyên lý chọn và loại trừ giá trị lính canh Sentinel (3.0đ): Nêu rõ giá trị lính canh phải nằm ngoài miền hợp lệ và không được cộng gộp vào dữ liệu thống kê nghiệp vụ.\", \"Cơ chế kết hợp biến cờ hiệu Flag vào điều kiện lặp đa tầng (3.5đ): Chỉ rõ giới hạn của break chỉ thoát một tầng và cách ghép điều kiện kiểm tra cờ vào cả hai vòng lặp thay cho goto.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 9),
            CreateExamSeed("00000000-0000-0000-0004-000000000210", CoursePrf192Id, "00000000-0000-0000-0000-000000000464", StructurePrf192Id, RubricPrf192Id, "Nguyên lý thiết kế Module hóa chương trình C: Độ kết dính (Cohesion) và Độ ghép nối (Coupling)", "Trong phương pháp thiết kế chương trình C theo hướng Module hóa và làm mịn từng bước từ trên xuống Top-Down, hãy giải thích bản chất của hai tiêu chuẩn chất lượng cốt lõi là Độ kết dính nội tại cao High Cohesion và Độ ghép nối thấp Low Coupling. Tại sao việc lạm dụng biến toàn cục để trao đổi dữ liệu giữa các hàm lại vi phạm nghiêm trọng nguyên tắc Low Coupling?", "Thiết kế chương trình C theo hướng Module hóa và phân rã Top-Down chia bài toán lớn thành các hàm chuyên biệt tuân thủ hai tiêu chuẩn High Cohesion và Low Coupling. Độ kết dính nội tại cao (High Cohesion) yêu cầu mỗi hàm chỉ thực hiện trọn vẹn đúng một trách nhiệm duy nhất (Single Responsibility): ví dụ hàm tính thuế chỉ nhận thu nhập và trả về tiền thuế chứ không trộn lẫn lệnh nhập xuất scanf, printf bên trong, giúp hàm độc lập giao diện, dễ kiểm thử đơn vị và tái sử dụng linh hoạt. Độ ghép nối thấp (Low Coupling) đòi hỏi các hàm phụ thuộc nhau ít nhất và chỉ trao đổi dữ liệu minh bạch qua danh sách tham số cùng giá trị trả về (Data Coupling). Lạm dụng biến toàn cục gây ra liên kết chung chặt chẽ (Common Coupling) rất nguy hiểm: bất kỳ hàm nào cũng có thể âm thầm sửa đổi biến toàn cục tạo hiệu ứng phụ ngầm (Hidden Side Effects) khiến việc truy vết lỗi cực kỳ khó khăn, đồng thời làm hàm mất khả năng gọi đệ quy, không an toàn đa luồng và không thể tách sang dự án khác.", "[\"Giải thích nguyên lý High Cohesion và lợi ích tách biệt tính toán với nhập xuất (3.5đ): Trình bày rõ nguyên tắc mỗi hàm chỉ đảm nhận một trách nhiệm duy nhất giúp dễ hiểu, dễ kiểm thử và tái sử dụng.\", \"Giải thích nguyên lý Low Coupling giao tiếp qua tham số tường minh (3.5đ): Nêu rõ các module phụ thuộc tối thiểu và trao đổi dữ liệu minh bạch qua đối số cùng giá trị trả về.\", \"Phân tích tác hại của biến toàn cục tạo hiệu ứng phụ ngầm (3.0đ): Chỉ rõ lạm dụng biến toàn cục gây phụ thuộc chặt, khó gỡ lỗi khi giá trị bị sửa ngầm và phá vỡ tính tái sử dụng.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 10),
            CreateExamSeed("00000000-0000-0000-0004-000000000211", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", StructurePrf192Id, RubricPrf192Id, "Ý nghĩa của từ khóa const khi kết hợp với con trỏ và bảo vệ tham số mảng trong hàm C", "Trong ngôn ngữ C, vị trí của từ khóa const so với dấu sao của con trỏ quyết định đối tượng nào bị khóa quyền sửa đổi. Hãy phân biệt sự khác nhau về quyền thay đổi giá trị tại ô nhớ đích và quyền thay đổi địa chỉ lưu trong bản thân biến con trỏ giữa ba trường hợp: con trỏ trỏ tới dữ liệu hằng (const đặt trước dấu sao), con trỏ hằng trỏ tới dữ liệu khả biến (const đặt ngay sau dấu sao), và trường hợp đặt const ở cả hai vị trí. Tại sao các hàm chỉ đọc mảng hoặc chuỗi luôn gắn từ khóa const vào tham số đầu vào?", "Tác dụng của từ khóa const khi đi cùng con trỏ phụ thuộc vị trí của nó so với dấu sao. Trường hợp một, khi const đứng trước dấu sao (Pointer to Constant Data), vùng nhớ đích bị khóa chỉ đọc không được sửa qua con trỏ đó, nhưng bản thân biến con trỏ vẫn tự do đổi địa chỉ trỏ sang biến khác. Trường hợp hai, khi const đứng ngay sau dấu sao (Constant Pointer), biến con trỏ bị khóa cố định địa chỉ từ lúc khởi tạo không thể trỏ đi nơi khác, nhưng giá trị tại vùng nhớ đích vẫn được phép sửa đổi. Trường hợp ba, đặt const ở cả trước và sau dấu sao tạo khóa kép cấm đổi cả địa chỉ con trỏ lẫn giá trị vùng nhớ đích. Đối với các hàm chỉ đọc mảng hoặc chuỗi như strlen, vì mảng truyền vào hàm phân rã thành con trỏ địa chỉ gốc nên việc gắn const vào tham số thiết lập hợp đồng chỉ đọc (Const-Correctness), giúp trình biên dịch chặn ngay lỗi vô tình ghi đè mảng gốc và cho phép truyền cả mảng hằng lẫn mảng thường vào hàm. Nếu cố tình ép kiểu bỏ const để ghi đè lên đối tượng gốc vốn là hằng thực sự, chuẩn C xếp đó là hành vi không xác định (Undefined Behavior) gây sập tiến trình.", "[\"Phân biệt rõ const đặt trước dấu sao và const đặt sau dấu sao (4.0đ): Chỉ rõ const trước dấu sao khóa giá trị vùng nhớ đích còn const sau dấu sao khóa cố định địa chỉ bản thân biến con trỏ.\", \"Giải thích trường hợp khóa kép và hành vi ép kiểu bỏ const trái phép (2.5đ): Nêu rõ khóa cả địa chỉ lẫn giá trị khi đặt ở hai bên và cảnh báo lỗi Undefined Behavior nếu ép kiểu sửa đối tượng hằng gốc.\", \"Vai trò thiết lập hợp đồng chỉ đọc Const-Correctness cho tham số mảng (3.5đ): Giải thích mảng truyền theo địa chỉ nên cần const để trình biên dịch chặn lỗi sửa nhầm dữ liệu gốc và hỗ trợ truyền mảng hằng.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 11),
            CreateExamSeed("00000000-0000-0000-0004-000000000212", CoursePrf192Id, "00000000-0000-0000-0000-000000000468", StructurePrf192Id, RubricPrf192Id, "Phân biệt bản chất bộ nhớ giữa mảng ký tự trên Stack và con trỏ hằng chuỗi trong C", "Trong thân một hàm C, xét hai cách tạo chuỗi từ hằng văn bản Hello gồm 5 chữ cái: cách thứ nhất khởi tạo một mảng ký tự cục bộ s1 từ chuỗi Hello, và cách thứ hai tạo một biến con trỏ kiểu char tên s2 trỏ trực tiếp tới hằng chuỗi Hello. Hãy phân biệt sự khác nhau giữa s1 và s2 về phân vùng bộ nhớ lưu trữ, quyền chỉnh sửa ký tự bên trong và dung lượng bộ nhớ được cấp phát.", "Bản chất bộ nhớ giữa mảng ký tự cục bộ s1 và con trỏ chuỗi s2 khác biệt trên ba khía cạnh. Thứ nhất, về phân vùng lưu trữ: mảng s1 được cấp phát trực tiếp trên Stack Frame của hàm và sao chép toàn bộ 5 chữ cái kèm byte null vào vùng Stack đó; ngược lại với s2, chuỗi Hello là hằng chuỗi (String Literal) nằm cố định ở phân vùng dữ liệu chỉ đọc (Read-Only Data Segment), còn trên Stack chỉ có biến con trỏ s2 lưu địa chỉ trỏ tới phân vùng chỉ đọc kia. Thứ hai, về quyền sửa đổi: mảng s1 nằm trên Stack có đủ quyền đọc ghi nên đổi ký tự đầu sang chữ thường hoàn toàn hợp lệ; trái lại, ghi đè ký tự qua s2 xâm phạm vùng nhớ chỉ đọc gây hành vi không xác định và bị hệ điều hành ngắt tiến trình với lỗi Segmentation Fault (nên luôn gắn từ khóa const trước kiểu của s2 để trình biên dịch bắt lỗi sớm). Thứ ba, trên kiến trúc 64-bit, mảng s1 chiếm đúng 6 bytes trên Stack (sizeof bằng 6), trong khi cách dùng s2 tốn 6 bytes ở vùng hằng chỉ đọc cộng riêng 8 bytes cho biến con trỏ s2 trên Stack (sizeof bằng 8).", "[\"Phân biệt bản sao mảng trên Stack và con trỏ trỏ vào Read-Only Data Segment (3.5đ): Giải thích rõ s1 chép chuỗi lên vùng nhớ Stack, còn s2 chỉ lưu địa chỉ trỏ tới hằng chuỗi nằm ở phân vùng chỉ đọc.\", \"Phân tích lỗi Segmentation Fault khi sửa ký tự qua s2 và khuyến nghị const (3.5đ): Chỉ rõ s1 sửa đổi hợp lệ trên Stack còn ghi qua s2 vi phạm vùng nhớ chỉ đọc gây sập tiến trình, cần dùng const char con trỏ.\", \"So sánh dung lượng bộ nhớ thực tế và kết quả toán tử sizeof (3.0đ): Tính đúng mảng s1 chiếm 6 bytes (5 ký tự cộng byte null), còn s2 tốn thêm 8 bytes biến con trỏ trên kiến trúc 64-bit.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 12),
            CreateExamSeed("00000000-0000-0000-0004-000000000213", CoursePrf192Id, "00000000-0000-0000-0000-000000000467", StructurePrf192Id, RubricPrf192Id, "Nguyên lý Tìm kiếm tuyến tính (Linear Search) và Tìm kiếm nhị phân (Binary Search) trên mảng một chiều", "Hãy so sánh nguyên lý hoạt động, điều kiện tiên quyết của dữ liệu đầu vào và độ phức tạp thời gian ở trường hợp tốt nhất, xấu nhất giữa thuật toán Tìm kiếm tuyến tính Linear Search và Tìm kiếm nhị phân Binary Search trên mảng một chiều. Trong thuật toán Binary Search, tại sao khi xác định chỉ số chính giữa mid ta phải tính bằng biên trái cộng một nửa hiệu của biên phải trừ biên trái thay vì lấy tổng hai biên chia đôi?", "Tìm kiếm tuyến tính (Linear Search) quét tuần tự từng phần tử từ chỉ số 0 đến N trừ 1, trả về chỉ số đầu tiên khớp khóa hoặc âm 1 nếu không thấy; thuật toán chạy được trên mọi mảng không cần sắp xếp trước với độ phức tạp tốt nhất O(1) và xấu nhất O(N). Ngược lại, Tìm kiếm nhị phân (Binary Search) bắt buộc mảng đầu vào phải được sắp xếp có thứ tự: mỗi bước đối chiếu khóa với phần tử giữa mid để loại bỏ một nửa đoạn tìm kiếm (dời biên trái lên mid cộng 1 hoặc hạ biên phải xuống mid trừ 1), đạt tốt nhất O(1) và xấu nhất O(log2 N) (với một triệu phần tử chỉ tốn tối đa khoảng 20 lần so sánh). Tuy nhiên, nếu mảng chưa sắp xếp và chỉ tra cứu một lần duy nhất thì phải chọn Linear Search O(N), vì chi phí sắp xếp trước đã tốn tối thiểu O(N log N) lớn hơn một lần quét thẳng. Trong Binary Search bằng C, nếu tính mid bằng tổng left cộng right chia 2 thì khi cả hai biên đều vượt một nửa INT_MAX, tổng của chúng vượt ngưỡng 2,14 tỷ gây tràn số nguyên có dấu lật thành số âm làm truy cập ngoài mảng; công thức lấy left cộng (right trừ left) chia 2 luôn giữ hiệu không vượt quá right nên triệt tiêu hoàn toàn tràn số.", "[\"So sánh nguyên lý, điều kiện sắp xếp và độ phức tạp O(N) với O(log N) (4.0đ): Chỉ rõ Linear Search O(N) không đòi hỏi thứ tự, còn Binary Search O(log N) bắt buộc mảng đã sắp xếp và chia đôi khoảng tìm kiếm.\", \"Đánh giá đúng bài toán tìm kiếm một lần trên mảng chưa sắp xếp (2.5đ): Giải thích hợp lý chi phí sắp xếp O(N log N) đắt hơn quét tuyến tính O(N) khi chỉ thực hiện một truy vấn đơn lẻ.\", \"Phân tích công thức tính chỉ số mid chống lỗi tràn số nguyên có dấu (3.5đ): Chứng minh tổng left cộng right có thể vượt INT_MAX gây chỉ số âm và nêu đúng công thức left cộng (right trừ left) chia 2.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 13),
            CreateExamSeed("00000000-0000-0000-0004-000000000214", CoursePrf192Id, "00000000-0000-0000-0000-000000000466", StructurePrf192Id, RubricPrf192Id, "Cơ chế hoạt động của File Buffering trong thư viện stdio và vai trò của hàm fflush", "Cơ chế bộ đệm luồng tệp File Buffering trong thư viện stdio.h của ngôn ngữ C giải quyết bài toán hiệu năng gì? Hãy phân biệt ba chế độ đệm gồm không đệm, đệm theo dòng và đệm toàn phần. Hàm fflush đóng vai trò gì và tại sao chuẩn ISO C nghiêm cấm việc gọi hàm fflush trên luồng đầu vào bàn phím stdin?", "Giao tiếp trực tiếp với đĩa cứng qua System Call chậm hơn RAM hàng nghìn lần, nên thư viện stdio.h dùng vùng đệm trung gian trên RAM (Stream Buffer) để gom tích lũy dữ liệu từ fprintf, fwrite rồi mới đẩy theo lô xuống thiết bị khi đầy đệm hoặc khi đóng tệp bằng fclose. Chuẩn C gồm ba chế độ đệm: không đệm (Unbuffered) xuất ngay tức thì, mặc định cho luồng lỗi stderr để không mất thông báo lỗi khi sập; đệm theo dòng (Line-buffered) tự xả khi gặp ký tự xuống dòng, mặc định cho màn hình stdout; và đệm toàn phần (Fully-buffered) chỉ xả khi đầy khối 4KB đến 8KB, mặc định cho tệp trên đĩa. Hàm fflush dùng để cưỡng bức xả ngay dữ liệu đang chờ của luồng xuất xuống thiết bị vật lý. Theo chuẩn ISO C, fflush chỉ được định nghĩa cho luồng xuất; gọi fflush trên luồng nhập stdin là hành vi không xác định (Undefined Behavior) bị phớt lờ trên Linux/GCC. Để dọn sạch bộ đệm stdin chuẩn xác trên mọi hệ điều hành, phải dùng vòng lặp gọi getchar vào biến kiểu int đọc bỏ từng ký tự cho đến khi gặp dấu xuống dòng hoặc hằng EOF.", "[\"Giải thích mục đích giảm số lần gọi System Call của Stream Buffering (3.0đ): Nêu rõ bộ đệm RAM gom dữ liệu xuất nhập theo lô nhằm khắc phục tốc độ chậm của thiết bị ngoại vi và đĩa cứng.\", \"Phân biệt đúng 3 chế độ không đệm, đệm theo dòng và đệm toàn phần (3.5đ): Gắn đúng từng chế độ với luồng điển hình: không đệm cho stderr, đệm theo dòng cho stdout và đệm toàn phần cho tệp đĩa.\", \"Vai trò của fflush trên luồng xuất, lệnh cấm fflush(stdin) và vòng lặp getchar (3.5đ): Khẳng định fflush trên stdin là Undefined Behavior và trình bày quy trình dùng getchar đọc xả tới dấu xuống dòng hoặc EOF.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 14),
            CreateExamSeed("00000000-0000-0000-0004-000000000215", CoursePrf192Id, "00000000-0000-0000-0000-000000000464", StructurePrf192Id, RubricPrf192Id, "Nguyên lý tối ưu hóa vòng lặp và chống tràn số trong bài toán kiểm tra số nguyên tố", "Trong bài toán kiểm tra một số nguyên n có phải là số nguyên tố hay không bằng ngôn ngữ C, hãy trình bày cách xử lý các trường hợp biên khi n nhỏ hơn hoặc bằng 3 và các số chẵn. Giải thích cơ sở toán học tại sao vòng lặp tìm ước số chỉ cần kiểm tra tới căn bậc hai của n với bước nhảy bỏ qua bội số của 2 và 3, đồng thời phân tích lý do nên kiểm tra điều kiện lặp i nhỏ hơn hoặc bằng n chia i thay vì tích i nhân i nhỏ hơn hoặc bằng n.", "Số nguyên tố là số tự nhiên lớn hơn 1 chỉ chia hết cho 1 và chính nó, nên đầu hàm phải lọc ngay các ca biên: n nhỏ hơn hoặc bằng 1 trả về sai, n bằng 2 hoặc 3 trả về đúng, và n chia hết cho 2 hoặc 3 trả về sai ngay. Về giới hạn lặp, nếu n là hợp số bằng tích hai ước lớn hơn 1 thì chắc chắn ít nhất một ước không vượt quá căn bậc hai của n; nhờ đó chỉ cần tìm ước tới căn bậc hai của n là giảm độ phức tạp từ O(n) xuống O(căn bậc hai của n). Hơn nữa, mọi số nguyên lớn hơn 3 không chia hết cho 2 và 3 đều có dạng 6k trừ 1 hoặc 6k cộng 1, nên vòng lặp bắt đầu từ i bằng 5 với bước nhảy tăng 6 đơn vị mỗi lượt để chỉ xét cặp i và i cộng 2. Đặc biệt với kiểu int 32-bit có dấu (INT_MAX bằng 2.147.483.647 có căn bậc hai khoảng 46.340,95), khi i vượt ngưỡng 46.341 thì tích i nhân i lớn hơn INT_MAX gây tràn số nguyên có dấu lật thành số âm, làm điều kiện lặp luôn đúng gây lặp sai hoặc vô tận; đổi điều kiện lặp thành i nhỏ hơn hoặc bằng thương nguyên n chia i sẽ an toàn tuyệt đối trên toàn dải int.", "[\"Xử lý chặt chẽ các trường hợp biên từ số âm, 0, 1 đến 2, 3 và bội của 2, 3 (3.0đ): Trình bày đầy đủ quy tắc loại n nhỏ hơn hoặc bằng 1, nhận 2 và 3, loại sớm các số chia hết cho 2 hoặc 3.\", \"Chứng minh giới hạn căn bậc hai của n và bước nhảy tối ưu 6k cộng trừ 1 (3.5đ): Giải thích rõ tính chất cặp ước đối xứng quanh căn bậc hai giảm độ phức tạp xuống O(căn n) và cách nhảy bước tăng 2 hoặc tăng 6.\", \"Phân tích bẫy tràn số nguyên có dấu ở biên INT_MAX và điều kiện i <= n / i (3.5đ): Chứng minh tích i nhân i vượt ngưỡng 2,14 tỷ khi i trên 46.340 gây tràn số lật âm và lý giải tính an toàn của phép chia n chia i.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 15),
            CreateExamSeed("00000000-0000-0000-0004-000000000216", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", StructurePrf192Id, RubricPrf192Id, "Kỹ thuật hai con trỏ (Two Pointers) đảo ngược mảng một chiều tại chỗ", "Hãy trình bày quy trình hoạt động của kỹ thuật hai con trỏ gồm con trỏ đầu start và con trỏ cuối end để đảo ngược một mảng số nguyên một chiều ngay tại chỗ mà không cấp phát mảng phụ. Giải thích chi tiết cách kiểm tra tham số đầu vào, thao tác hoán đổi ở mỗi bước, hướng dịch chuyển hai con trỏ và điều kiện dừng vòng lặp trong cả hai trường hợp mảng có số phần tử chẵn và lẻ.", "Kỹ thuật hai con trỏ (Two Pointers) đảo ngược mảng một chiều ngay tại chỗ (In-place) không tốn mảng phụ. Đầu tiên, chương trình kiểm tra an toàn con trỏ khác NULL và nếu quản lý qua kích thước N thì thoát sớm ngay khi N nhỏ hơn hoặc bằng 1 để tránh tính địa chỉ lùi trước đầu mảng khi N bằng 0. Khi N lớn hơn 1, con trỏ start trỏ vào phần tử đầu tại chỉ số 0, còn con trỏ end trỏ vào phần tử cuối tại địa chỉ gốc cộng N trừ 1 phần tử. Vòng lặp duy trì chừng nào địa chỉ start còn nhỏ hơn nghiêm ngặt địa chỉ end (phép so sánh hai con trỏ cùng mảng hoàn toàn hợp lệ trong C). Ở mỗi lượt lặp, thuật toán dùng toán tử giải tham chiếu qua biến nguyên tạm để tráo đổi giá trị tại hai ô nhớ start và end, sau đó tăng start tiến sang phải một phần tử và giảm end lùi sang trái một phần tử. Với mảng số phần tử lẻ, hai con trỏ chạm nhau ở phần tử chính giữa làm start bằng end nên dừng lặp; với mảng số phần tử chẵn, hai con trỏ bước chéo qua nhau làm start lớn hơn end và cũng dừng ngay. Thuật toán tốn đúng N chia 2 phép hoán vị, đạt thời gian O(N) và không gian phụ O(1).", "[\"Trình bày quy trình tráo đổi qua giải tham chiếu và dịch chuyển hai con trỏ (4.0đ): Mô tả chính xác cách đặt start ở đầu, end ở cuối, hoán vị giá trị qua biến tạm rồi tăng start và giảm end mỗi bước.\", \"Phân tích điều kiện dừng start nhỏ hơn end cho cả mảng chẵn và mảng lẻ (3.0đ): Giải thích rõ phép so sánh địa chỉ con trỏ hợp lệ, dừng khi gặp nhau ở mảng lẻ hoặc bước chéo qua nhau ở mảng chẵn.\", \"Xác định địa chỉ đối số đầu cuối, bảo vệ ca biên mảng rỗng và độ phức tạp O(1) (3.0đ): Nêu đúng địa chỉ phần tử cuối là gốc cộng N trừ 1, kiểm tra an toàn khi mảng NULL hoặc N bằng 0 và độ phức tạp không gian O(1).\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 16),
            CreateExamSeed("00000000-0000-0000-0004-000000000217", CoursePrf192Id, "00000000-0000-0000-0000-000000000467", StructurePrf192Id, RubricPrf192Id, "Nguyên lý sắp xếp nổi bọt (Bubble Sort) và tối ưu dừng sớm bằng cờ hiệu", "Hãy trình bày nguyên lý so sánh các cặp phần tử liền kề của thuật toán Sắp xếp nổi bọt Bubble Sort trên mảng số nguyên một chiều. Giải thích cách sử dụng biến cờ hiệu theo dõi hoán đổi để giúp thuật toán dừng sớm và giảm độ phức tạp thời gian xuống mức tuyến tính O(N) trong trường hợp mảng đầu vào đã có thứ tự sẵn.", "Thuật toán Sắp xếp nổi bọt (Bubble Sort) quét dọc mảng từ trái sang phải qua nhiều lượt, so sánh từng cặp phần tử liền kề tại vị trí j và j cộng 1 rồi đổi chỗ ngay nếu phần tử trước lớn hơn phần tử sau. Qua mỗi lượt lặp ngoài thứ i, phần tử lớn nhất trong đoạn còn lại sẽ nổi dần về nằm cố định ở cuối đoạn, nghĩa là sau i lượt đã có đúng i phần tử lớn nhất đứng đúng chỗ ở đuôi mảng; vì vậy vòng lặp trong chỉ cần duyệt j từ 0 đến trước ngưỡng N trừ 1 trừ i, tiết kiệm một nửa phép so sánh thừa. Để khắc phục nhược điểm vẫn chạy đủ lượt khi mảng đã có thứ tự, đầu mỗi lượt lặp ngoài ta gán biến cờ swapped bằng 0 và chỉ bật lên 1 khi xảy ra ít nhất một lần hoán đổi. Kết thúc vòng lặp trong, nếu cờ swapped vẫn bằng 0 tức không cặp liền kề nào nghịch thế, thuật toán gọi break dừng hẳn vòng ngoài ngay lập tức. Nhờ tối ưu này, trường hợp tốt nhất mảng đã sắp xếp sẵn chỉ quét đúng một lượt đạt độ phức tạp O(N), trường hợp xấu nhất mảng ngược thứ tự là O(N bình phương), đồng thời thuật toán đảm bảo tính ổn định (Stable Sort).", "[\"Trình bày nguyên lý so sánh cặp liền kề và thu hẹp biên N trừ 1 trừ i (3.5đ): Mô tả rõ cơ chế đẩy phần tử lớn nhất về cuối sau mỗi lượt nên vòng trong không cần xét lại i phần tử cuối đã cố định.\", \"Giải thích quy trình đặt và kiểm tra cờ hiệu swapped để dừng sớm (3.5đ): Phân tích đúng việc đặt cờ bằng 0 đầu mỗi lượt ngoài, bật lên 1 khi có hoán đổi và thoát vòng lặp ngay nếu hết lượt cờ vẫn bằng 0.\", \"Phân tích độ phức tạp tốt nhất O(N), xấu nhất O(N bình phương) và tính ổn định (3.0đ): Chứng minh mảng đã sắp xếp chỉ chạy 1 lượt quét đạt O(N), mảng giảm dần tốn O(N^2) và giữ nguyên thứ tự phần tử bằng nhau.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 17),
            CreateExamSeed("00000000-0000-0000-0004-000000000218", CoursePrf192Id, "00000000-0000-0000-0000-000000000468", StructurePrf192Id, RubricPrf192Id, "Quy trình chuẩn hóa chuỗi họ tên tại chỗ và xử lý khoảng trắng trong C", "Hãy trình bày giải thuật chuẩn hóa chuỗi họ tên ngay tại chỗ trên mảng ký tự trong ngôn ngữ C nhằm thỏa mãn đồng thời ba quy tắc: loại bỏ toàn bộ khoảng trắng thừa ở đầu và cuối chuỗi, giữa hai từ liên tiếp chỉ giữ lại đúng một dấu cách duy nhất, đồng thời chuyển chữ cái đầu mỗi từ thành chữ hoa và các chữ cái còn lại thành chữ thường.", "Để chuẩn hóa chuỗi họ tên ngay tại chỗ với thời gian tuyến tính O(N) và không gian phụ O(1), giải thuật kết hợp hai chỉ số đọc ghi (read_idx và write_idx khởi tạo bằng 0) cùng biến cờ trạng thái in_word. Sau khi kiểm tra con trỏ chuỗi khác NULL, vòng lặp đầu tăng read_idx bỏ qua mọi khoảng trắng đầu chuỗi. Tiếp theo, duyệt read_idx tới trước ký tự null: nếu gặp khoảng trắng thì chỉ đặt cờ in_word về 0 báo hiệu kết thúc từ mà không ghi gì ra write_idx; nếu gặp ký tự chữ thì xét cờ in_word. Khi in_word đang bằng 0 (bắt đầu từ mới), nếu write_idx lớn hơn 0 (tức từ thứ hai trở đi) ta ghi trước đúng một dấu cách đơn vào write_idx rồi tăng write_idx, kế đến dùng toupper đổi chữ cái đầu thành chữ hoa ghi vào write_idx và bật in_word lên 1; ngược lại khi in_word bằng 1, dùng tolower đổi các chữ cái sau thành chữ thường ghi vào write_idx. Duyệt xong, ghi ký tự kết thúc chuỗi null chốt ngay tại write_idx là loại sạch khoảng trắng cuối. Lưu ý khi truyền ký tự vào isspace, toupper, tolower của ctype.h, bắt buộc ép kiểu sang unsigned char để tránh kiểu char có dấu mang giá trị âm gây hành vi không xác định.", "[\"Kỹ thuật hai chỉ số đọc ghi xử lý tại chỗ O(N) và chốt ký tự null cuối (3.5đ): Giải thích rõ cơ chế read_idx đi trước, write_idx ghi dồn tại chỗ và đặt ký tự null tại write_idx giúp sạch khoảng trắng đầu cuối.\", \"Cơ chế biến trạng thái in_word giữ đúng một dấu cách giữa các từ (3.5đ): Phân tích chuẩn logic chỉ chèn đúng 1 khoảng trắng khi chuyển trạng thái bắt đầu một từ mới kể từ từ thứ hai trở đi.\", \"Vận dụng isspace, toupper, tolower và lưu ý ép kiểu unsigned char (3.0đ): Nêu đúng ba hàm trong ctype.h để đổi hoa chữ đầu, thường chữ sau và lý do ép unsigned char tránh giá trị âm ngoài miền.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 18),
            CreateExamSeed("00000000-0000-0000-0004-000000000219", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", StructurePrf192Id, RubricPrf192Id, "Quy trình quản lý mảng động co giãn kích thước an toàn với malloc, realloc và free", "Hãy trình bày quy trình chuẩn từng bước để quản lý vòng đời một mảng số nguyên động trên Heap trong ngôn ngữ C: từ lúc cấp phát ban đầu bằng malloc, mở rộng gấp đôi sức chứa bằng realloc, khởi tạo phần tử mới cho đến khi thu hồi bằng free. Phân tích tại sao khi gọi realloc, lập trình viên tuyệt đối không được gán trực tiếp kết quả trả về đè thẳng lên biến con trỏ gốc đang quản lý mảng cũ?", "Quy trình quản lý vòng đời mảng động an toàn trên Heap gồm bốn bước. Bước một, gọi malloc xin khối nhớ N nhân sizeof(int) bytes và kiểm tra khác NULL trước khi gán dữ liệu cho chỉ số 0 đến N trừ 1. Bước hai, khi cần nới rộng lên 2N phần tử, gọi realloc truyền con trỏ hiện hành cùng dung lượng byte mới nhưng bắt buộc hứng kết quả vào một biến con trỏ tạm riêng biệt. Bước ba, kiểm tra con trỏ tạm: chỉ khi con trỏ tạm khác NULL mới cập nhật con trỏ chính bằng con trỏ tạm, rồi khởi tạo tiếp các phần tử mới từ chỉ số N đến 2N trừ 1 (vì phần nới thêm của realloc chứa dữ liệu rác). Bước bốn, dùng xong gọi free trên con trỏ chính và gán ngay về NULL. Sở dĩ cấm tuyệt đối việc gán trực tiếp kết quả realloc đè lên chính con trỏ gốc là vì theo chuẩn C, khi thiếu RAM khiến realloc thất bại trả về NULL, khối nhớ cũ ban đầu VẪN ĐƯỢC GIỮ NGUYÊN chứ không tự giải phóng; nếu gán đè trực tiếp, giá trị NULL sẽ xóa mất địa chỉ duy nhất của mảng cũ gây rò rỉ bộ nhớ (Memory Leak) không thể thu hồi, trong khi dùng con trỏ tạm giúp bảo toàn địa chỉ mảng cũ để xử lý hoặc gọi free an toàn.", "[\"Quy trình cấp phát malloc, khởi tạo phần mở rộng mới và thu hồi free (3.0đ): Trình bày đầy đủ kiểm tra NULL sau malloc, lưu ý phần nhớ mở rộng thêm chứa rác cần khởi tạo và gán NULL sau free.\", \"Kỹ thuật dùng con trỏ tạm trung gian hứng và xác thực kết quả realloc (3.5đ): Mô tả rõ chỉ cập nhật con trỏ chính sang con trỏ tạm sau khi đã kiểm tra con trỏ tạm khác NULL thành công.\", \"Phân tích cơ chế giữ nguyên khối cũ khi realloc trả NULL gây Memory Leak (3.5đ): Giải thích chính xác realloc thất bại không tự free vùng nhớ cũ, nên gán đè trực tiếp làm mất địa chỉ gốc gây rò rỉ bộ nhớ.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, 19),
            CreateExamSeed("00000000-0000-0000-0004-000000000220", CoursePrf192Id, "00000000-0000-0000-0000-000000000467", StructurePrf192Id, RubricPrf192Id, "Tổ chức mảng cấu trúc quản lý kho hàng và giải thuật tra cứu, lọc mặt hàng dưới định mức", "Để quản lý danh sách hàng hóa trong kho bằng ngôn ngữ C với các thông tin gồm mã định danh SKU, tên sản phẩm, đơn giá, số lượng tồn hiện tại và ngưỡng cảnh báo tồn tối thiểu, hãy trình bày cách chọn kiểu dữ liệu phù hợp cho từng trường trong cấu trúc Product. Tiếp theo, hãy mô tả giải thuật tìm chỉ số mặt hàng theo mã SKU và giải thuật lọc các mặt hàng dưới định mức để tính tổng chi phí cần nhập bù tối thiểu kèm các kiểm tra an toàn tham số.", "Cấu trúc Product được tổ chức gồm năm trường: hai mảng ký tự kích thước cố định lưu mã SKU và tên sản phẩm (luôn tính dư 1 byte cho ký tự null), biến kiểu số thực độ chính xác kép double cho đơn giá tiền tệ nhằm tránh sai số làm tròn của float, cùng hai biến kiểu int cho số lượng tồn kho và ngưỡng tồn tối thiểu. Ở giải thuật tra cứu theo mã SKU, trước hết kiểm tra các ca biên gồm con trỏ mảng khác NULL, chuỗi mã đích khác NULL và số phần tử N lớn hơn 0 (vi phạm trả về âm 1); sau đó duyệt tuyến tính i từ 0 đến N trừ 1, gọi strcmp đối chiếu trường sku thứ i với mã đích — nếu bằng 0 thì trả về ngay chỉ số i, hết mảng trả về âm 1 (bắt buộc dùng strcmp vì phép so bằng chỉ so sánh hai địa chỉ con trỏ chứ không đối chiếu nội dung ký tự). Ở giải thuật lọc hàng dưới định mức, sau khi kiểm tra mảng hợp lệ, khởi tạo tổng chi phí kiểu double bằng 0.0 rồi duyệt mảng xét các mục có tồn kho nhỏ hơn ngưỡng tối thiểu: tính lượng thiếu bằng ngưỡng trừ tồn, nhân với đơn giá cộng dồn vào tổng chi phí và xuất báo cáo. Cả hai hàm chỉ đọc dữ liệu nên gắn const vào tham số mảng để chặn lỗi ghi đè dữ liệu gốc.", "[\"Lựa chọn kiểu dữ liệu chuẩn xác cho 5 trường của cấu trúc Product (3.0đ): Trình bày hợp lý mảng ký tự đủ chỗ chứa byte null cho SKU và tên, kiểu double cho đơn giá và kiểu int cho tồn kho, ngưỡng.\", \"Giải thuật tìm kiếm mã SKU dùng strcmp kèm kiểm tra biên NULL và mảng rỗng (3.5đ): Mô tả đúng bước kiểm tra tham số đầu vào, duyệt đối chiếu bằng strcmp bằng 0 trả chỉ số hoặc âm 1 và giải thích lý do không dùng so bằng.\", \"Giải thuật lọc hàng dưới ngưỡng, tính chi phí bù và bảo vệ mảng bằng const (3.5đ): Trình bày đúng công thức lượng thiếu bằng ngưỡng trừ tồn nhân đơn giá cộng dồn kiểu double và vai trò chỉ đọc của const.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, 20),
            CreateExamSeed("00000000-0000-0000-0004-000000000221", CoursePrf192Id, "00000000-0000-0000-0000-000000000469", StructurePrf192Id, RubricPrf192Id, "Quy trình đọc và phân tích tệp văn bản có cấu trúc (CSV / Log File) an toàn bằng fgets và sscanf", "Giả sử một tệp văn bản CSV lưu nhật ký cảm biến theo từng dòng gồm ba cột cách nhau bởi dấu phẩy là mã cảm biến, nhiệt độ số thực và độ ẩm số nguyên. Tại sao việc gọi trực tiếp hàm fscanf bên trong vòng lặp rất dễ làm treo vòng lặp hoặc đọc lệch dây chuyền toàn bộ các dòng phía sau khi tệp xuất hiện một dòng bị hỏng định dạng? Hãy trình bày quy trình kết hợp hai hàm fgets và sscanf để cô lập bỏ qua dòng lỗi và tính nhiệt độ trung bình an toàn.", "Hàm fscanf đọc thẳng trên luồng byte liên tục và coi dấu xuống dòng như khoảng trắng thường nên không nhận biết ranh giới từng dòng. Nếu một dòng bị hỏng định dạng (như ghi chữ ERR vào cột nhiệt độ), fscanf dừng ngay tại ký tự lỗi và giữ nguyên nó trên luồng tệp, khiến các vòng lặp sau kẹt cứng tại chỗ hoặc ghép lệch cột dòng sau vào dòng trước. Giải pháp chuẩn là tách bước đọc dòng và bước phân tích bằng bộ đôi fgets và sscanf: mở tệp chế độ r, kiểm tra khác NULL, rồi lặp gọi fgets nạp trọn từng dòng độc lập vào mảng đệm RAM tới khi trả về NULL. Với mỗi dòng khác rỗng, gọi sscanf kèm giới hạn độ dài chuỗi mã, số thực double và số nguyên int, rồi kiểm tra kết quả trả về có bằng đúng 3 trường hay không: bằng 3 thì cộng dồn nhiệt độ và tăng biến đếm hợp lệ; khác 3 thì cảnh báo bỏ qua dòng lỗi mà lượt gọi fgets kế tiếp vẫn đọc sạch từ đầu dòng mới. Cuối cùng gọi fclose và kiểm tra biến đếm lớn hơn 0 trước khi chia trung bình để tránh chia cho 0 (nếu dòng quá dài khiến bộ đệm fgets chưa có dấu xuống dòng ở cuối, đọc xả phần dư tới dấu xuống dòng hoặc EOF trước khi đọc tiếp).", "[\"Phân tích lỗi kẹt luồng và lệch dòng dây chuyền khi dùng trực tiếp fscanf (3.5đ): Giải thích rõ fscanf không tách ranh giới dòng vật lý nên ký tự sai định dạng giữ nguyên trên luồng làm hỏng các lượt đọc sau.\", \"Quy trình cô lập từng dòng bằng fgets kết hợp kiểm tra sscanf trả về đúng 3 (3.5đ): Trình bày rõ fgets nạp trọn dòng vào bộ đệm, dùng sscanf có giới hạn độ dài chuỗi và đối chiếu số trường bóc tách bằng 3.\", \"Quản lý tệp an toàn, chống chia cho 0 và xử lý dòng vượt kích thước đệm (3.0đ): Nêu đầy đủ kiểm tra fopen khác NULL, gọi fclose, kiểm tra số dòng hợp lệ lớn hơn 0 trước khi chia và cách nhận biết dòng dài quá bộ đệm.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, 21),
            CreateExamSeed("00000000-0000-0000-0004-000000000222", CoursePrf192Id, "00000000-0000-0000-0000-000000000464", StructurePrf192Id, RubricPrf192Id, "Phân tích kiến trúc biên dịch đa tệp (Multi-file Compilation) và cơ chế Header Guards trong C", "Khi tổ chức một dự án C lớn thành nhiều tệp tiêu đề .h và tệp mã nguồn .c, hãy phân biệt bản chất và thời điểm phát sinh giữa lỗi biên dịch định nghĩa lại cấu trúc Redefinition với lỗi liên kết trùng lặp ký hiệu Multiple Definition. Cơ chế bảo vệ tệp tiêu đề Header Guards hoạt động như thế nào trong một đơn vị dịch, và tại sao dù đã có Header Guards vẫn tuyệt đối không được đặt định nghĩa cấp phát biến toàn cục hoặc thân hàm thông thường bên trong tệp .h?", "Trong dự án C đa tệp, mỗi tệp .c sau khi nhúng các tệp .h tạo thành một Đơn vị dịch độc lập (Translation Unit) và biên dịch riêng ra một tệp đối tượng .o trước khi Linker ghép lại. Lỗi Redefinition xảy ra lúc Compile trong cùng một đơn vị dịch khi một tệp .c nạp gián tiếp cùng một tệp .h nhiều lần làm kiểu struct bị định nghĩa lặp. Cơ chế Header Guards chặn lỗi này bằng bộ ba chỉ thị tiền xử lý ifndef, define và endif bọc quanh tệp .h: lần nạp đầu macro chưa tồn tại nên nội dung được giữ lại và macro được định nghĩa; các lần nạp lặp tiếp theo trong cùng tệp .c bị cắt bỏ hoàn toàn. Tuy nhiên, Header Guards chỉ có tác dụng cục bộ trong từng đơn vị dịch riêng rẽ và đặt lại từ đầu khi dịch tệp .c khác. Do đó, nếu đặt định nghĩa cấp phát biến toàn cục hoặc thân hàm thường trong tệp .h rồi nạp vào nhiều tệp .c, mọi tệp .o sinh ra đều xuất khẩu trùng một ký hiệu toàn cục (External Linkage) khiến Linker báo lỗi Multiple Definition; vì vậy tệp .h chỉ được đặt nguyên mẫu hàm và biến kèm extern, còn định nghĩa thực sự đặt ở duy nhất một tệp .c (hàm nội bộ gắn static sẽ mang Internal Linkage ẩn khỏi Linker).", "[\"Phân biệt rõ lỗi Redefinition lúc biên dịch và Multiple Definition lúc liên kết (3.5đ): Giải thích chính xác khái niệm Translation Unit, lỗi nạp lặp trong 1 tệp .c so với lỗi đụng độ ký hiệu khi Linker ghép nhiều tệp .o.\", \"Cơ chế hoạt động của Header Guards trong phạm vi một đơn vị dịch (3.5đ): Trình bày rõ cách bộ ba ifndef, define, endif giữ nội dung lần đầu và loại bỏ các lần nạp gián tiếp kế tiếp trong cùng một tệp .c.\", \"Quy tắc chỉ đặt extern trong tệp .h, định nghĩa ở 1 tệp .c và vai trò static hàm (3.0đ): Lý giải vì sao Header Guards không ngăn lỗi Linker giữa nhiều tệp .c và tác dụng ẩn ký hiệu Internal Linkage của từ khóa static.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 22),
            CreateExamSeed("00000000-0000-0000-0004-000000000223", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", StructurePrf192Id, RubricPrf192Id, "Phân tích lỗi trả về địa chỉ biến cục bộ trên Stack và hai phương pháp truyền bộ đệm an toàn", "Giả sử một hàm con trong ngôn ngữ C tạo một mảng ký tự cục bộ kích thước 64 bytes trên ngăn xếp Stack, ghép chuỗi lời chào vào mảng đó rồi trả về trực tiếp địa chỉ mảng cục bộ này cho hàm main sử dụng. Hãy phân tích cơ chế thu hồi Stack Frame để giải thích tại sao hàm trên chứa lỗi bộ nhớ cực kỳ nguy hiểm dù vẫn biên dịch thành tệp chạy được, đồng thời trình bày và so sánh ưu nhược điểm của hai phương pháp thiết kế lại giao diện hàm an toàn chuẩn công nghiệp.", "Mảng ký tự cục bộ lớp auto nằm hoàn toàn trên Stack Frame riêng của hàm con. Ngay khi hàm thực thi lệnh return, con trỏ ngăn xếp lập tức thu hồi Stack Frame đó, biến địa chỉ trả về cho hàm main thành con trỏ lơ lửng (Dangling Pointer); khi chương trình gọi hàm kế tiếp như printf, Stack Frame mới sẽ ghi đè lên vùng nhớ cũ làm chuỗi biến thành rác hoặc gây sập tiến trình (Undefined Behavior). Nếu chữa tạm bằng từ khóa static cho mảng cục bộ, mọi lần gọi hàm đều dùng chung duy nhất một bộ đệm tĩnh nên gọi hai lần trong cùng lệnh printf sẽ khiến lần gọi sau ghi đè xóa mất kết quả lần gọi trước và hoàn toàn mất an toàn đa luồng. Hai mẫu thiết kế an toàn chuẩn công nghiệp gồm: Phương pháp một (Caller-Allocated Buffer — khuyên dùng nhất) để hàm gọi tự cấp phát mảng đích rồi truyền con trỏ đệm kèm kích thước tối đa vào hàm con định dạng bằng snprintf, đạt tốc độ cao trên Stack, an toàn đa luồng và không bao giờ rò rỉ bộ nhớ; Phương pháp hai dùng malloc cấp phát động trên Heap trong hàm con rồi trả con trỏ ra ngoài, linh hoạt với chuỗi dài bất kỳ nhưng tốn chi phí Heap và buộc hàm gọi phải nhớ gọi free để tránh Memory Leak.", "[\"Phân tích cơ chế thu hồi Stack Frame biến địa chỉ trả về thành Dangling Pointer (3.5đ): Giải thích rõ vòng đời biến auto kết thúc ngay khi hàm return và vùng nhớ bị lời gọi hàm kế tiếp ghi đè gây Undefined Behavior.\", \"Trình bày mẫu Caller-Allocated Buffer kèm kích thước và chỉ rõ lỗi ghi đè của static (3.5đ): Mô tả đúng giao diện hàm nhận bộ đệm đích cùng dung lượng từ Caller và phân tích nhược điểm dùng chung một bộ đệm khi gắn static.\", \"Trình bày mẫu cấp phát động trên Heap và so sánh đánh đổi trách nhiệm gọi free (3.0đ): Nêu đúng phương án cấp phát malloc trả quyền sở hữu vùng nhớ cho Caller kèm so sánh độ linh hoạt và nguy cơ Memory Leak.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 23),
            CreateExamSeed("00000000-0000-0000-0004-000000000224", CoursePrf192Id, "00000000-0000-0000-0000-000000000465", StructurePrf192Id, RubricPrf192Id, "Biểu diễn ma trận động bằng mảng một chiều trải phẳng và tối ưu hóa CPU Cache Locality", "Thay vì cấp phát ma trận động gồm R dòng và C cột bằng con trỏ cấp hai phải gọi malloc R cộng 1 lần rời rạc, hãy trình bày kỹ thuật biểu diễn ma trận động bằng một mảng một chiều trải phẳng liên tục chỉ với một lần cấp phát duy nhất và công thức ánh xạ tọa độ dòng r, cột c. Trong thuật toán nhân hai ma trận theo cách biểu diễn này, tại sao việc hoán đổi thứ tự ba vòng lặp từ i-j-k truyền thống sang i-k-j lại giúp tăng tốc độ thực thi vượt trội nhờ tính cục bộ không gian Spatial Locality của CPU Cache?", "Biểu diễn ma trận động R dòng C cột bằng mảng một chiều trải phẳng dùng một con trỏ đơn xin trọn một khối nhớ liên tục gồm R nhân C phần tử trên Heap chỉ với một lệnh malloc hoặc calloc và giải phóng chỉ bằng một lệnh free. Cách này loại bỏ mảng con trỏ trung gian, chống phân mảnh Heap và xếp liền các dòng theo chuẩn Row-major order với chỉ số dòng r cột c là r nhân C cộng c (dùng kiểu không dấu 64-bit size_t để tránh tràn tích số nguyên int 32-bit trên ma trận lớn). Khối nhớ liên tục phát huy hiệu năng tối đa nhờ Tính cục bộ không gian (Spatial Locality): mỗi lần đọc RAM, CPU nạp nguyên một đường Cache Line 64 bytes (chứa 8 số double liền kề) lên Cache. Ở thứ tự nhân ma trận truyền thống i-j-k, vòng trong cùng chạy theo k truy cập ma trận thứ hai tại k nhân N cộng j (nhảy cóc dọc theo cột cách xa N phần tử mỗi bước) gây trượt Cache Miss liên tục. Khi đổi sang thứ tự i-k-j, phần tử ma trận đầu tại dòng i cột k được giữ trong thanh ghi, còn vòng trong cùng chạy theo j quét tuần tự từng phần tử liền kề trên cùng một dòng cho cả ma trận thứ hai lẫn ma trận tích, tận dụng 100 phần trăm dữ liệu trên Cache Line và tăng tốc gấp nhiều lần.", "[\"Ưu điểm cấp phát một khối nhớ liên tục duy nhất và công thức ánh xạ r * C + c (3.5đ): Giải thích rõ chỉ tốn 1 lệnh cấp phát và 1 lệnh free, chống phân mảnh Heap và công thức ánh xạ ưu tiên dòng.\", \"Phân tích nguyên nhân gây Cache Miss khi duyệt nhảy theo cột ở vòng lặp i-j-k (3.0đ): Chỉ rõ việc tăng chỉ số dòng k ở vòng trong cùng khiến địa chỉ nhảy bước lớn qua cả dòng gây trượt Cache Line.\", \"Chứng minh hiệu quả Spatial Locality của vòng lặp i-k-j và vai trò kiểu size_t (3.5đ): Giải thích bước nhảy liền kề theo dòng tận dụng tối đa Cache Line 64 bytes và dùng size_t chống tràn tích chỉ số.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 24),
            CreateExamSeed("00000000-0000-0000-0004-000000000225", CoursePrf192Id, "00000000-0000-0000-0000-000000000468", StructurePrf192Id, RubricPrf192Id, "Phân tích bẫy lỗi thiếu ký tự kết thúc chuỗi của strncpy và cơ chế ghép chuỗi an toàn với snprintf", "Nhiều lập trình viên lầm tưởng rằng chỉ cần thay hàm strcpy bằng hàm strncpy với tham số giới hạn bằng kích thước mảng đích là chuỗi luôn an toàn tuyệt đối. Hãy phân tích hai cạm bẫy thiết kế của hàm strncpy gồm lỗi không gắn ký tự kết thúc chuỗi null khi chuỗi nguồn dài bằng hoặc vượt kích thước đích và chi phí ghi đệm dư thừa khi đích rất lớn. Tiếp theo, hãy trình bày quy trình dùng hàm snprintf để ghép đường dẫn thư mục với tên tệp an toàn và cách dựa vào giá trị trả về của snprintf để phát hiện chính xác khi chuỗi bị cắt cụt.", "Hàm strncpy ẩn chứa hai cạm bẫy thiết kế nguy hiểm. Thứ nhất là mất ký tự kết thúc chuỗi null: nếu độ dài chuỗi nguồn lớn hơn hoặc bằng giới hạn n truyền vào, strncpy chỉ chép đúng n ký tự và KHÔNG tự gắn ký tự null ở cuối, khiến các hàm printf hay strlen sau đó đọc tràn qua vùng nhớ lân cận (Buffer Over-read); nếu dùng strncpy luôn phải chủ động gán cưỡng bức byte cuối mảng đích về null. Thứ hai là lãng phí Zero-padding: nếu nguồn chỉ dài vài ký tự nhưng kích thước đích n rất lớn, strncpy vẫn điền byte 0 vào toàn bộ phần trống còn lại. Để ghép đường dẫn thư mục và tên tệp an toàn trong C99/C11, ta kiểm tra các con trỏ khác NULL và kích thước buf_size lớn hơn 0 rồi gọi hàm snprintf: hàm chỉ ghi tối đa buf_size trừ 1 ký tự và LUÔN gắn ký tự kết thúc null ở cuối. Đặc biệt, snprintf trả về tổng số ký tự lẽ ra đã ghi (không tính null) nếu đủ chỗ, nên chỉ cần kiểm tra giá trị trả về nhỏ hơn 0 hoặc lớn hơn hay bằng buf_size là phát hiện chính xác chuỗi đã bị cắt cụt (Truncation). Khác với strncpy, hàm strncat luôn tự thêm một byte null sau tối đa n ký tự nối thêm, nên tham số n phải tính bằng kích thước mảng đích trừ độ dài chuỗi hiện có rồi trừ tiếp 1 byte cho ký tự null.", "[\"Phân tích đúng 2 cạm bẫy thiếu ký tự null khi nguồn dài >= n và zero-padding của strncpy (4.0đ): Giải thích rõ nguy cơ Buffer Over-read do strncpy không chèn null khi chạm ngưỡng n và sự lãng phí điền byte 0 khi đích lớn.\", \"Trình bày cơ chế bảo đảm gắn ký tự null của snprintf và công thức tham số strncat (3.0đ): Nêu rõ kiểm tra con trỏ NULL, buf_size > 0, cơ chế luôn chèn null cuối của snprintf và cách trừ 1 byte cho strncat.\", \"Giải thích điều kiện phát hiện cắt cụt chuỗi khi giá trị trả về >= buf_size (3.0đ): Hiểu rõ giá trị trả về của snprintf là độ dài chuỗi đầy đủ chưa tính null nên lớn hơn hoặc bằng buf_size chứng tỏ bị cắt cụt.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 25),
            CreateExamSeed("00000000-0000-0000-0004-000000000226", CoursePrf192Id, "00000000-0000-0000-0000-000000000469", StructurePrf192Id, RubricPrf192Id, "Kỹ thuật cập nhật trực tiếp bản ghi cấu trúc tại chỗ (In-Place Update) trên tệp nhị phân bằng fseek và ftell", "Giả sử một tệp nhị phân lưu trữ hàng triệu bản ghi cấu trúc Tài khoản có kích thước cố định như nhau. Làm thế nào để cập nhật số dư mới cho riêng bản ghi tại chỉ số thứ index (tính từ 0) với độ phức tạp thời gian hằng số O(1) mà không cần nạp toàn bộ tệp vào bộ nhớ RAM? Hãy trình bày chi tiết quy trình từ bước chọn chế độ mở tệp không làm mất dữ liệu cũ, xác thực chỉ số index nằm trong phạm vi tệp bằng fseek và ftell, đọc bản ghi lên sửa đổi cho đến bước định vị lùi lại để ghi đè đúng vị trí đó.", "Vì mỗi bản ghi Tài khoản trong tệp nhị phân có kích thước cố định bằng sizeof(Account) bytes, bản ghi thứ index luôn nằm tại độ lệch byte offset bằng index nhân sizeof(Account), cho phép định vị trực tiếp trong thời gian O(1). Quy trình cập nhật tại chỗ thực hiện qua năm bước: Bước một, mở tệp bằng chế độ cập nhật nhị phân rb+ (tuyệt đối không dùng wb+ vì sẽ xóa trắng tệp cũ ngay lúc mở) và kiểm tra khác NULL. Bước hai, gọi fseek tới mốc cuối SEEK_END rồi gọi ftell lấy kích thước tệp; nếu nhỏ hơn (index cộng 1) nhân sizeof(Account) thì index vượt ngoài tệp, cần đóng tệp báo lỗi. Bước ba, gọi fseek nhảy tới target_offset từ mốc SEEK_SET, gọi fread đọc 1 bản ghi lên RAM (kiểm tra trả về 1) và cộng cập nhật số dư. Bước bốn, vì lệnh fread vừa đẩy con trỏ tệp trôi sang đầu bản ghi kế tiếp, đồng thời chuẩn ANSI C bắt buộc trên luồng cập nhật rb+ phải có lời gọi định vị fseek hoặc fflush xen giữa thao tác đọc và thao tác ghi nhằm đồng bộ bộ đệm I/O nội bộ, nên chương trình bắt buộc gọi lại fseek lùi về đúng target_offset trước khi gọi fwrite ghi đè 1 bản ghi xuống đĩa. Bước năm, gọi fflush và fclose hoàn tất an toàn.", "[\"Công thức tính độ lệch byte O(1) và xác thực biên tệp bằng SEEK_END kèm ftell (3.5đ): Nêu đúng offset bằng index nhân sizeof(Account) và kiểm tra kích thước tệp đủ chứa bản ghi thứ index trước khi truy xuất.\", \"Lựa chọn đúng chế độ mở rb+ bảo toàn dữ liệu và kiểm tra kết quả fread, fwrite (3.5đ): Giải thích rõ phải mở bằng rb+ thay vì wb+ gây mất dữ liệu cũ, kèm kiểm tra giá trị trả về bằng 1 bản ghi ở cả đọc và ghi.\", \"Giải thích hai lý do bắt buộc gọi fseek lùi con trỏ tệp giữa fread và fwrite (3.0đ): Chỉ rõ vừa để lùi vị trí tệp về lại đầu bản ghi cần ghi đè, vừa tuân thủ chuẩn C đồng bộ bộ đệm khi chuyển từ đọc sang ghi trên luồng rb+.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 26),
            // =========================================================================
            // 2. CSD201 — 26 CÂU HỎI KHO THI THẬT (6 Remember, 8 Understand, 7 Apply, 5 Analyze)
