            CreateExamSeed("00000000-0000-0000-0005-000000000201", CourseCsd201Id, "00000000-0000-0000-0000-000000000561", StructureCsd201Id, RubricCsd201Id, "Định nghĩa Toán học Ba Ký pháp Tiệm cận Big-O, Big-Omega, Big-Theta và Ba Kịch bản Phân tích Thuật toán", "Hãy phát biểu định nghĩa toán học chính thức (theo các hằng số dương c và ngưỡng n0) của ba ký pháp tiệm cận: Big-O, Big-Omega và Big-Theta. Trong phân tích thuật toán, tại sao người ta thường ưu tiên đánh giá Trường hợp xấu nhất (Worst-Case) hơn là Trường hợp tốt nhất (Best-Case)?", "1. Định nghĩa toán học chính thức của ba ký pháp tiệm cận (xét hai hàm không âm `f(n)` và `g(n)`):\n- Ký pháp Big-O (Chặn trên tiệm cận): `f(n) = O(g(n))` nếu tồn tại hằng số thực dương `c > 0` và ngưỡng nguyên `n0 >= 1` sao cho `0 <= f(n) <= c * g(n)` với mọi `n >= n0`, biểu thị tốc độ tăng của `f(n)` không vượt quá bội số hằng của `g(n)`.\n- Ký pháp Big-Omega (Chặn dưới tiệm cận): `f(n) = Omega(g(n))` nếu tồn tại hằng số thực dương `c > 0` và `n0 >= 1` sao cho `0 <= c * g(n) <= f(n)` với mọi `n >= n0`, biểu thị `f(n)` tăng trưởng ít nhất ngang với `g(n)`.\n- Ký pháp Big-Theta (Chặn chặt tiệm cận): `f(n) = Theta(g(n))` nếu tồn tại hai hằng số dương `c1, c2 > 0` và `n0 >= 1` sao cho `0 <= c1 * g(n) <= f(n) <= c2 * g(n)` với mọi `n >= n0`. Điều kiện cần và đủ là `f(n)` đồng thời thuộc cả `O(g(n))` lẫn `Omega(g(n))`.\n\n2. Lý do ưu tiên đánh giá Trường hợp xấu nhất (Worst-Case) hơn Trường hợp tốt nhất (Best-Case):\n- Worst-Case cung cấp cam kết giới hạn trên tuyệt đối về thời gian phản hồi tối đa đối với mọi cấu hình dữ liệu đầu vào kích thước `n`, đóng vai trò sống còn trong hệ thống thời gian thực, cam kết SLA và phòng chống tấn công làm suy thoái độ phức tạp thuật toán (Algorithmic DoS).\n- Ngược lại, Best-Case chỉ phản ánh một vài đầu vào may mắn cá biệt (như tìm thấy phần tử ngay ô đầu mảng trong tìm kiếm tuyến tính), không đại diện cho hiệu năng vận hành thực tế; còn Average-Case đòi hỏi biết trước phân phối xác suất đầu vào.", "[\"Định nghĩa toán học chuẩn xác của Big-O và Big-Omega (4.0đ): Phát biểu đúng bất đẳng thức f(n) <= c*g(n) và f(n) >= c*g(n) kèm điều kiện tồn tại hằng số c > 0 và mọi n >= n0.\", \"Định nghĩa toán học của Big-Theta và quan hệ tương đương (3.0đ): Phát biểu đúng bất đẳng thức kẹp giữa c1*g(n) và c2*g(n), nêu điều kiện cần và đủ đồng thời là O(g(n)) và Omega(g(n)).\", \"Giải thích ý nghĩa thực tiễn của Worst-Case vs Best-Case (3.0đ): Làm rõ cam kết giới hạn thời gian tối đa của Worst-Case trong hệ thống thực tế và tính thiếu đại diện của Best-Case.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 30),
            CreateExamSeed("00000000-0000-0000-0005-000000000202", CourseCsd201Id, "00000000-0000-0000-0000-000000000562", StructureCsd201Id, RubricCsd201Id, "Định nghĩa Hàng đợi Hai đầu (Deque ADT) và Nhóm Thao tác Chuẩn tại Hai Đầu First/Last", "Kiểu dữ liệu trừu tượng Hàng đợi hai đầu (Deque — Double-Ended Queue) là gì? Hãy liệt kê các thao tác chuẩn thêm, xóa và truy vấn ở cả hai đầu của Deque, đồng thời giải thích vì sao trong bộ thư viện chuẩn Java Collections Framework, cấu trúc ArrayDeque được khuyến nghị dùng thay thế cho cả lớp Stack cũ lẫn LinkedList khi biểu diễn ngăn xếp và hàng đợi.", "1. Định nghĩa Deque ADT và sáu thao tác chuẩn tại hai đầu:\n- Deque (Double-Ended Queue) là cấu trúc dữ liệu tuyến tính tổng quát hóa cả Ngăn xếp và Hàng đợi, cho phép thêm và xóa phần tử đối xứng tại cả đầu trước (`front`/`first`) lẫn đầu sau (`rear`/`last`) với độ phức tạp chuẩn O(1).\n- Nhóm 4 thao tác cập nhật gồm: `addFirst`/`offerFirst` (chèn vào đầu trước), `addLast`/`offerLast` (chèn vào đầu sau), `removeFirst`/`pollFirst` (lấy và xóa phần tử đầu trước), `removeLast`/`pollLast` (lấy và xóa phần tử đầu sau). Nhóm 2 thao tác truy vấn không xóa gồm: `first`/`peekFirst` và `last`/`peekLast`.\n\n2. Cách giả lập Stack/Queue và lý do `ArrayDeque` vượt trội hơn `Stack` và `LinkedList`:\n- Để vận hành như Stack (LIFO), chỉ cần ghép cặp `addFirst` và `removeFirst` tại cùng một đầu; để vận hành như Queue (FIFO), ghép cặp chèn cuối `addLast` và lấy đầu `removeFirst`.\n- So với lớp `java.util.Stack` lịch sử: `Stack` kế thừa từ `Vector` nên khóa đồng bộ hóa (`synchronized`) trên mọi thao tác, gây hao tổn hiệu năng vô ích trong ngữ cảnh đơn luồng.\n- So với `LinkedList`: `ArrayDeque` lưu trữ trên mảng vòng liên tục nên tận dụng tối đa bộ nhớ đệm CPU (Cache Locality), không tốn chi phí cấp phát đối tượng nút liên kết đôi kèm hai tham chiếu `prev`, `next` trên mỗi phần tử và giảm mạnh áp lực thu gom rác (Garbage Collection).", "[\"Định nghĩa đúng bản chất cấu trúc dữ liệu Deque ADT (3.0đ): Nêu rõ Deque là hàng đợi hai đầu hỗ trợ chèn và xóa đối xứng ở cả đầu front và đầu rear với chi phí O(1).\", \"Liệt kê đầy đủ các thao tác chuẩn tại hai đầu First và Last (3.5đ): Nêu đúng 4 thao tác cập nhật (addFirst, addLast, removeFirst, removeLast) và 2 thao tác xem (first/peekFirst, last/peekLast).\", \"Giải thích cách giả lập Stack/Queue và ưu thế của ArrayDeque (3.5đ): Chỉ rõ cách ghép cặp thao tác làm LIFO/FIFO và phân tích ưu điểm không khóa synchronized, tối ưu CPU cache so với Stack/LinkedList.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 31),
            CreateExamSeed("00000000-0000-0000-0005-000000000203", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", StructureCsd201Id, RubricCsd201Id, "Định nghĩa Cây Nhị phân Đầy đủ và Cây Nhị phân Hoàn chỉnh", "Thế nào là một Cây nhị phân đầy đủ (Full Binary Tree / Proper Binary Tree) và thế nào là một Cây nhị phân hoàn chỉnh (Complete Binary Tree)? Cho biết cấu trúc nào là điều kiện tiên quyết của Binary Heap.", "1. Cây nhị phân đầy đủ (Full Binary Tree / Proper Binary Tree):\nLà cây nhị phân mà trong đó MỖI NÚT đều có đúng 0 hoặc 2 nút con. Nói cách khác, không có bất kỳ nút nào trong cây chỉ có duy nhất 1 nút con (bậc của mọi nút đều thuộc {0, 2}).\n\n2. Cây nhị phân hoàn chỉnh (Complete Binary Tree):\nLà cây nhị phân thỏa mãn hai điều kiện nghiêm ngặt:\n- Mọi tầng của cây đều được lấp đầy hoàn toàn các nút, ngoại trừ có thể tầng cuối cùng (tầng sâu nhất).\n- Tại tầng cuối cùng, toàn bộ các nút phải được xếp dồn liên tục về phía bên trái nhất có thể (từ trái qua phải, không để lại bất kỳ khoảng trống nào).\n\n3. Điều kiện tiên quyết của Binary Heap:\nCây nhị phân hoàn chỉnh (Complete Binary Tree) chính là cấu trúc hình học bắt buộc của Binary Heap. Nhờ đặc tính này, Binary Heap có thể biểu diễn hoàn hảo trên mảng một chiều phẳng mà không bị lãng phí ô nhớ.", "[\"Định nghĩa Full Binary Tree (3.5đ): Nêu rõ mọi nút đều có 0 hoặc 2 nút con, không có nút bậc 1.\", \"Định nghĩa Complete Binary Tree (4.0đ): Mô tả chuẩn xác lấp đầy các tầng và dồn nút về bên trái ở tầng cuối.\", \"Mối liên hệ với Binary Heap (2.5đ): Chỉ ra Complete Binary Tree là điều kiện hình học nền tảng của Heap.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 32),
            CreateExamSeed("00000000-0000-0000-0005-000000000204", CourseCsd201Id, "00000000-0000-0000-0000-000000000565", StructureCsd201Id, RubricCsd201Id, "Phát biểu Định lý Bắt tay (Handshaking Lemma) trong Lý thuyết Đồ thị", "Hãy phát biểu Định lý Bắt tay (Handshaking Lemma) trong lý thuyết đồ thị vô hướng. Nêu mối liên hệ toán học giữa tổng bậc của tất cả các đỉnh và tổng số cạnh của đồ thị. Từ định lý này, hãy suy ra tính chất về số lượng các đỉnh có bậc lẻ trong bất kỳ đồ thị vô hướng nào.", "1. Phát biểu Định lý Bắt tay (Handshaking Lemma):\nTrong mọi đồ thị vô hướng G gồm tập đỉnh V và tập cạnh E, tổng bậc của tất cả các đỉnh trong đồ thị luôn bằng đúng hai lần tổng số cạnh E. Ý nghĩa trực quan của định lý là mỗi cạnh nối giữa hai đầu mút luôn đóng góp chính xác 1 đơn vị bậc cho đỉnh thứ nhất và 1 đơn vị bậc cho đỉnh thứ hai, giống như mỗi cái bắt tay luôn cần đúng hai bàn tay tham gia.\n\n2. Suy luận tính chất số lượng đỉnh bậc lẻ:\n- Vì tổng bậc của toàn bộ các đỉnh bằng 2 nhân với số cạnh E nên tổng này bắt buộc là một số nguyên chẵn.\n- Nếu ta tách tập đỉnh của đồ thị thành hai nhóm rời nhau gồm nhóm các đỉnh có bậc chẵn và nhóm các đỉnh có bậc lẻ, thì tổng bậc của nhóm đỉnh bậc chẵn hiển nhiên là một số chẵn.\n- Để tổng chung của cả hai nhóm là số chẵn, phần tổng bậc của nhóm các đỉnh bậc lẻ cũng bắt buộc phải là một số chẵn. Mặt khác, tổng của các số nguyên lẻ chỉ có thể là số chẵn khi số lượng số hạng lẻ là một số chẵn. Do đó, trong mọi đồ thị vô hướng, số lượng đỉnh có bậc lẻ luôn luôn là một số chẵn.", "[\"Phát biểu đúng Định lý Bắt tay và mối quan hệ bậc - cạnh (4.0đ): Nêu rõ tổng bậc mọi đỉnh bằng hai lần số cạnh E và giải thích mỗi cạnh đóng góp 2 đơn vị bậc cho hai đầu mút.\", \"Chứng minh tính chẵn của tổng bậc nhóm đỉnh bậc lẻ (3.0đ): Chỉ ra hai lần số cạnh E là số chẵn và nhóm đỉnh bậc chẵn có tổng chẵn nên tổng bậc các đỉnh lẻ phải chẵn.\", \"Kết luận hệ quả số lượng đỉnh bậc lẻ luôn chẵn (3.0đ): Khẳng định chính xác số lượng các đỉnh có bậc lẻ trong bất kỳ đồ thị vô hướng nào luôn là một số chẵn.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 33),
            CreateExamSeed("00000000-0000-0000-0005-000000000205", CourseCsd201Id, "00000000-0000-0000-0000-000000000566", StructureCsd201Id, RubricCsd201Id, "Định nghĩa Tính Ổn định của Thuật toán Sắp xếp và Phân loại", "Tính ổn định (Stability) của một thuật toán sắp xếp là gì? Hãy liệt kê 2 thuật toán sắp xếp có tính ổn định và 2 thuật toán sắp xếp không có tính ổn định, đồng thời giải thích ngắn gọn nguyên nhân tạo nên sự khác biệt đó.", "1. Định nghĩa Tính ổn định (Stability) của thuật toán sắp xếp:\nMột thuật toán sắp xếp được gọi là ổn định nếu nó bảo toàn nguyên vẹn thứ tự xuất hiện tương đối ban đầu giữa các phần tử có giá trị khóa sắp xếp bằng nhau. Cụ thể, nếu bản ghi A đứng trước bản ghi B trong danh sách đầu vào và cả hai có cùng khóa so sánh, thì sau khi thuật toán kết thúc, bản ghi A chắc chắn vẫn đứng trước bản ghi B.\n\n2. Phân loại các thuật toán sắp xếp tiêu biểu và nguyên nhân:\n- Nhóm thuật toán ổn định gồm MergeSort và Insertion Sort (ngoài ra còn có Bubble Sort, Counting Sort, Radix Sort). Trong Insertion Sort và Bubble Sort, các phần tử chỉ dịch chuyển qua nhau khi lớn hơn thực sự chứ không vượt qua phần tử bằng nó; còn MergeSort luôn ưu tiên lấy phần tử ở nửa mảng bên trái trước khi hai nửa có giá trị bằng nhau.\n- Nhóm thuật toán không ổn định gồm QuickSort và HeapSort (cùng Selection Sort). Các thuật toán này thực hiện phép hoán đổi vị trí qua khoảng cách xa trong mảng (như đổi chỗ qua trục Pivot hoặc đưa phần tử cuối đống lên gốc rồi vun đống xuống), dễ làm phần tử đứng trước nhảy ra phía sau một phần tử khác có cùng giá trị khóa.", "[\"Định nghĩa chuẩn xác tính ổn định (4.0đ): Nêu rõ điều kiện bảo toàn thứ tự tương đối ban đầu giữa các phần tử có cùng khóa so sánh.\", \"Nhận diện đúng thuật toán ổn định và cơ chế giữ thứ tự (3.0đ): Liệt kê chính xác ít nhất 2 thuật toán ổn định như MergeSort, Insertion Sort và giải thích nguyên tắc không vượt qua khóa bằng nhau.\", \"Nhận diện đúng thuật toán không ổn định và nguyên nhân (3.0đ): Liệt kê chính xác ít nhất 2 thuật toán không ổn định như QuickSort, HeapSort và chỉ ra tác động của phép hoán đổi khoảng cách xa.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 34),
            CreateExamSeed("00000000-0000-0000-0005-000000000206", CourseCsd201Id, "00000000-0000-0000-0000-000000000567", StructureCsd201Id, RubricCsd201Id, "Định nghĩa Hàm Băm Hoàn Hảo và Tiêu chuẩn của Hàm Băm Lý tưởng", "Thế nào là một Hàm băm hoàn hảo (Perfect Hash Function) và khi nào nó được gọi là Hàm băm hoàn hảo tối thiểu? Hãy trình bày 3 tiêu chuẩn bắt buộc của một hàm băm tốt trong các hệ thống phần mềm thực tế.", "1. Định nghĩa Hàm băm hoàn hảo và Hàm băm hoàn hảo tối thiểu:\nMột hàm băm ánh xạ tập khóa tĩnh K vào bảng băm kích thước M được gọi là Hàm băm hoàn hảo nếu nó là ánh xạ đơn ánh, tức mọi cặp khóa phân biệt đều sinh ra hai chỉ số ô nhớ hoàn toàn khác nhau và không phát sinh bất kỳ xung đột nào. Đặc biệt, nếu kích thước bảng băm M bằng đúng số lượng khóa thực tế của tập K mà không dư thừa ô trống nào, hàm băm đó được gọi là Hàm băm hoàn hảo tối thiểu (Minimal Perfect Hash Function), thường ứng dụng cho tập từ khóa cố định của trình biên dịch.\n\n2. Ba tiêu chuẩn bắt buộc của một hàm băm tốt trong thực tế:\n- Phân phối đồng đều (Uniform Distribution): Hàm băm phải trải đều các khóa trên toàn bộ dải chỉ số của bảng băm, tận dụng hết mọi thành phần của khóa để giảm thiểu xác suất va chạm cụm.\n- Chi phí tính toán nhanh (Fast Computation): Quá trình tính mã băm phải hoàn tất trong thời gian hằng số O(1) bằng các phép toán số học và dịch bit nhẹ trên CPU, tránh biến bản thân hàm băm thành điểm nghẽn.\n- Tính tất định tuyệt đối (Deterministic): Với cùng một khóa đầu vào không đổi, hàm băm bắt buộc trả về chính xác cùng một mã băm ở mọi lần tra cứu trong suốt vòng đời phiên chạy.", "[\"Định nghĩa Hàm băm hoàn hảo và Tối thiểu (4.0đ): Nêu rõ tính chất đơn ánh không xung đột trên tập khóa tĩnh và điều kiện kích thước bảng bằng số lượng khóa của Minimal Perfect Hash.\", \"Tiêu chuẩn phân phối đồng đều và tính toán nhanh (3.0đ): Giải thích yêu cầu trải đều khóa giảm va chạm và thực thi nhanh O(1).\", \"Tiêu chuẩn tính tất định của mã băm (3.0đ): Khẳng định cùng một khóa đầu vào luôn phải cho ra cùng một chỉ số băm để tra cứu chính xác.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 35),
            CreateExamSeed("00000000-0000-0000-0005-000000000207", CourseCsd201Id, "00000000-0000-0000-0000-000000000561", StructureCsd201Id, RubricCsd201Id, "Cấu trúc Danh sách Liên kết Vòng (Circularly Linked List), Con trỏ tail và Ứng dụng Lập lịch Round-Robin", "Danh sách liên kết vòng đơn (Circularly Linked List) khác gì với Danh sách liên kết đơn thông thường? Tại sao khi tổ chức Circularly Linked List, người ta chỉ cần duy trì duy nhất một con trỏ tham chiếu nút cuối (tail) thay vì con trỏ nút đầu (head), và thao tác xoay vòng (rotate) hỗ trợ thuật toán lập lịch CPU Round-Robin trong thời gian O(1) như thế nào?", "1. Sự khác biệt cấu trúc giữa Circularly Linked List và Singly Linked List:\nTrong Danh sách liên kết đơn thông thường, con trỏ kế tiếp của nút cuối cùng luôn mang giá trị rỗng (null) để đánh dấu ranh giới kết thúc danh sách. Ngược lại, trong Danh sách liên kết vòng đơn, con trỏ kế tiếp của nút cuối cùng trỏ ngược trực tiếp về nút đầu tiên của danh sách, tạo thành một vòng tròn liên kết khép kín không có điểm đứt.\n\n2. Lý do chỉ cần duy trì duy nhất con trỏ `tail` thay vì `head`:\nNếu chỉ lưu giữ con trỏ `head`, ta truy cập nút đầu trong O(1) nhưng muốn tìm nút cuối để chèn thêm phần tử vào đuôi danh sách thì buộc phải duyệt qua toàn bộ n nút tốn O(n). Khi chuyển sang duy trì duy nhất con trỏ `tail`, ta vừa nắm trực tiếp nút cuối tại `tail`, vừa truy cập tức thì nút đầu tiên thông qua liên kết kế tiếp của `tail` trong thời gian hằng số O(1). Nhờ đó, cả ba thao tác chèn đầu, chèn cuối và xóa đầu đều đạt O(1) mà tiết kiệm được biến tham chiếu `head`.\n\n3. Thao tác xoay vòng (`rotate`) trong lập lịch CPU Round-Robin:\nKhi hệ điều hành chia sẻ thời gian CPU theo vòng tròn, tiến trình ở đầu danh sách vừa hết lượt chạy cần được chuyển xuống cuối hàng đợi để nhường CPU cho tiến trình kế tiếp. Trên danh sách liên kết vòng quản lý bằng `tail`, thao tác `rotate` chỉ cần dịch chuyển biến tham chiếu `tail` tiến thêm một bước sang nút kế tiếp của nó (chính là nút đầu cũ). Chỉ với một phép cập nhật tham chiếu trong O(1) mà không cần tháo lắp hay cấp phát lại bất kỳ nút nào, nút đầu cũ lập tức trở thành nút cuối mới và nút thứ hai trở thành đầu hàng đợi.", "[\"Phân biệt cấu trúc liên kết vòng khép kín với Singly Linked List (3.0đ): Trình bày rõ nút cuối trỏ ngược về nút đầu tạo chu trình khép kín thay vì kết thúc bằng tham chiếu null.\", \"Giải thích lý do chỉ giữ con trỏ tail đạt O(1) cho cả hai đầu (3.5đ): Chứng minh từ tail truy cập ngay được cả nút cuối lẫn nút đầu (qua liên kết kế tiếp của tail) trong O(1).\", \"Phân tích cơ chế xoay vòng rotate() O(1) trong Round-Robin (3.5đ): Giải thích việc dịch con trỏ tail sang nút kế tiếp giúp đưa tiến trình đầu xuống cuối danh sách tức thì mà không tháo gắn nút.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, 36),
            CreateExamSeed("00000000-0000-0000-0005-000000000208", CourseCsd201Id, "00000000-0000-0000-0000-000000000562", StructureCsd201Id, RubricCsd201Id, "Cơ chế Hoạt động của Hàng đợi Ưu tiên và Sự Khác biệt với Hàng đợi FIFO", "Trình bày cơ chế hoạt động của Hàng đợi ưu tiên (Priority Queue). Sự khác biệt cốt lõi giữa Hàng đợi ưu tiên và Hàng đợi thông thường (FIFO Queue) là gì? Nêu một tình huống thực tế minh họa rõ nét sự khác biệt này.", "1. Cơ chế hoạt động của Hàng đợi ưu tiên (Priority Queue):\nTrong Hàng đợi ưu tiên, mỗi phần tử khi đưa vào cấu trúc dữ liệu đều đi kèm một khóa xác định mức độ ưu tiên (Priority Key). Khi thực hiện thao tác trích xuất phần tử tiếp theo, hệ thống luôn chọn ra phần tử có độ ưu tiên cao nhất (ví dụ khóa nhỏ nhất trong Min-Priority Queue hoặc khóa lớn nhất trong Max-Priority Queue) để phục vụ trước tiên, bất kể phần tử đó được đưa vào sớm hay muộn.\n\n2. Sự khác biệt cốt lõi với Hàng đợi FIFO thông thường:\n- Hàng đợi FIFO (First-In, First-Out) phục vụ thuần túy theo trình tự thời gian đến: phần tử nào gia nhập hàng đợi trước sẽ được lấy ra trước một cách công bằng tuyệt đối.\n- Hàng đợi ưu tiên phục vụ theo trọng số quan trọng: một phần tử vừa mới chèn vào nhưng mang mức ưu tiên khẩn cấp sẽ lập tức vượt qua toàn bộ các phần tử mức ưu tiên thấp đang chờ sẵn.\n\n3. Tình huống thực tế minh họa:\nTại khoa Cấp cứu bệnh viện, nếu xếp hàng theo cơ chế FIFO thông thường thì bệnh nhân trầy xước nhẹ đến lúc 8 giờ sẽ được khám trước ca chấn thương nguy kịch nhập viện lúc 8 giờ 5 phút. Thực tế bệnh viện vận hành theo mô hình Hàng đợi ưu tiên phân loại cấp độ: bệnh nhân nguy kịch mang mức ưu tiên số 1 được chuyển thẳng vào phòng cấp cứu ngay lập tức, trong khi các ca nhẹ hơn tiếp tục chờ tới lượt.", "[\"Cơ chế trích xuất theo khóa ưu tiên (Priority Key) (3.5đ): Mô tả chính xác nguyên tắc luôn lấy ra phần tử có mức độ ưu tiên cao nhất thay vì thứ tự đến.\", \"So sánh bản chất với FIFO Queue (3.5đ): Phân biệt rõ ràng tiêu chí trình tự thời gian của FIFO so với tiêu chí trọng số ưu tiên của Priority Queue.\", \"Tình huống thực tế minh họa thuyết phục (3.0đ): Đưa ra ví dụ thực tiễn chuẩn xác như phân loại cấp cứu y tế hoặc lập lịch tiến trình hệ điều hành.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, 37),
            CreateExamSeed("00000000-0000-0000-0005-000000000209", CourseCsd201Id, "00000000-0000-0000-0000-000000000565", StructureCsd201Id, RubricCsd201Id, "Thuật toán Hierholzer Tìm Chu trình và Đường đi Euler trong Thời gian Tuyến tính O(V + E)", "Hãy phát biểu điều kiện cần và đủ để một đồ thị liên thông có Chu trình Euler và Đường đi Euler đối với cả đồ thị vô hướng lẫn đồ thị có hướng. Tiếp theo, hãy trình bày nguyên lý Thuật toán Hierholzer sử dụng Ngăn xếp (Stack) để dựng Chu trình Euler trong thời gian tuyến tính O(V + E) và giải thích tại sao thuật toán này hiệu quả hơn thuật toán Fleury?", "1. Điều kiện cần và đủ tồn tại Chu trình Euler và Đường đi Euler:\n- Trên đồ thị vô hướng (các đỉnh có cạnh thuộc cùng một thành phần liên thông): Đồ thị có Chu trình Euler đi qua mọi cạnh đúng một lần rồi quay về đỉnh xuất phát khi và chỉ khi tất cả các đỉnh đều có bậc chẵn. Đồ thị có Đường đi Euler không khép kín khi và chỉ khi có đúng 2 đỉnh bậc lẻ (hai đỉnh này đóng vai trò điểm đầu và điểm cuối).\n- Trên đồ thị có hướng: Đồ thị có Chu trình Euler khi các đỉnh có cạnh liên thông mạnh và tại mọi đỉnh, bán bậc vào luôn bằng bán bậc ra. Đồ thị có Đường đi Euler khi tối đa một đỉnh có bán bậc ra lớn hơn bán bậc vào đúng 1 đơn vị (đỉnh xuất phát), tối đa một đỉnh có bán bậc vào lớn hơn bán bậc ra đúng 1 đơn vị (đỉnh kết thúc), và mọi đỉnh còn lại có bán bậc vào bằng bán bậc ra.\n\n2. Nguyên lý Thuật toán Hierholzer dùng Ngăn xếp đạt thời gian O(V + E):\nĐẩy đỉnh xuất phát vào ngăn xếp hành trình hiện tại. Ở mỗi bước, quan sát đỉnh nằm trên đỉnh ngăn xếp: nếu đỉnh đó vẫn còn cạnh chưa đi qua, ta chọn một cạnh kề bất kỳ, đánh dấu xóa cạnh đó khỏi đồ thị và đẩy đỉnh đích vào ngăn xếp để đi tiếp; ngược lại nếu đỉnh trên cùng đã hết sạch cạnh chưa thăm, ta lấy nó ra khỏi ngăn xếp và ghi nhận vào danh sách kết quả. Sau khi ngăn xếp rỗng, đảo ngược danh sách kết quả sẽ thu được chu trình hoàn chỉnh vì các chu trình nhánh phụ đã tự động được ghép lồng vào đúng điểm rẽ khi quay lui.\n\n3. Ưu thế vượt trội so với Thuật toán Fleury:\nThuật toán Fleury ở mỗi bước chọn cạnh đều phải chạy phép duyệt đồ thị để kiểm tra tránh đi qua cạnh cầu khi vẫn còn lựa chọn khác, khiến chi phí đội lên O(E^2). Trong khi đó, Hierholzer không cần kiểm tra cạnh cầu mà đi thẳng và ghép chu trình con tự nhiên lúc lùi ngăn xếp, nên mỗi cạnh chỉ bị xét một lần duy nhất với tổng thời gian tuyến tính O(V + E).", "[\"Phát biểu đúng điều kiện Chu trình và Đường đi Euler cho đồ thị vô hướng và có hướng (3.5đ): Nêu rõ điều kiện bậc chẵn hoặc 2 đỉnh bậc lẻ trên đồ thị vô hướng, cùng cân bằng bán bậc vào và bán bậc ra trên đồ thị có hướng.\", \"Trình bày chính xác từng bước Thuật toán Hierholzer dùng Stack (3.5đ): Mô tả rõ quy tắc đi tiếp và xóa cạnh khi còn cạnh kề, kết hợp lấy đỉnh ra ghi vào danh sách kết quả khi hết cạnh kề.\", \"Chứng minh độ phức tạp tuyến tính O(V + E) và ưu thế so với thuật toán Fleury (3.0đ): Giải thích vì sao Hierholzer không cần kiểm tra cạnh cầu tốn O(E^2) như Fleury mà tự động lồng chu trình phụ khi quay lui.\"]", QuestionDifficulty.Easy, BloomLevel.Understand, 38),
            CreateExamSeed("00000000-0000-0000-0005-000000000210", CourseCsd201Id, "00000000-0000-0000-0000-000000000561", StructureCsd201Id, RubricCsd201Id, "Ứng dụng Định lý Thợ (Master Theorem) Phân tích Phương trình Truy hồi Đệ quy", "Đối với thuật toán Chia để trị tách bài toán kích thước n thành a bài toán con kích thước n chia b với chi phí chia và tổng hợp là f(n), hãy trình bày ý nghĩa của 3 trường hợp trong Định lý Thợ (Master Theorem) dựa trên việc so sánh f(n) với tốc độ tăng số lượng lá của cây đệ quy. Vận dụng định lý này để giải thích vì sao Tìm kiếm nhị phân có độ phức tạp O(log n) và MergeSort có độ phức tạp O(n log n).", "1. Bản chất 3 trường hợp của Định lý Thợ dựa trên cây đệ quy:\nVới phương trình chia để trị tạo ra a nhánh con kích thước n chia b ở mỗi bước, tổng số lá ở đáy cây đệ quy tăng theo hàm lũy thừa n mũ log cơ số b của a. Định lý Thợ đối chiếu chi phí chia - gộp f(n) tại mỗi nút với đại lượng tới hạn này qua 3 kịch bản:\n- Trường hợp 1 (Chi phí tập trung ở đáy lá): Khi f(n) tăng chậm hơn một bậc đa thức so với n mũ log_b(a), tổng công việc bị chi phối hoàn toàn bởi số lượng lá ở tầng cuối cùng, nên độ phức tạp toàn cục là Theta của n mũ log_b(a).\n- Trường hợp 2 (Chi phí phân bố đồng đều qua các tầng): Khi f(n) tăng cùng bậc tiệm cận với n mũ log_b(a), mỗi tầng trên cây đệ quy tốn xấp xỉ cùng một lượng công việc như nhau; nhân với chiều cao cây log(n) ta thu được độ phức tạp Theta của n mũ log_b(a) nhân log(n).\n- Trường hợp 3 (Chi phí tập trung ngay tại nút gốc): Khi f(n) tăng nhanh hơn một bậc đa thức so với n mũ log_b(a) đồng thời thỏa mãn điều kiện đều đặn (tổng chi phí các con nhỏ hơn một hằng số c < 1 lần nút cha), công việc tại nút gốc áp đảo toàn cây nên độ phức tạp bằng Theta(f(n)).\n\n2. Giải thích Tìm kiếm nhị phân và MergeSort:\n- Tìm kiếm nhị phân: Mỗi bước chỉ đi tiếp vào a = 1 nhánh con kích thước n chia 2 (b = 2) với chi phí so sánh ở giữa là hằng số O(1). Khi đó log cơ số 2 của 1 bằng 0 nên đại lượng tới hạn bằng n mũ 0 tức bằng 1, khớp với f(n) = Theta(1) thuộc Trường hợp 2, suy ra độ phức tạp là Theta(log n).\n- MergeSort: Chia mảng thành a = 2 nửa kích thước n chia 2 (b = 2) và tốn chi phí trộn tuyến tính f(n) = Theta(n). Đại lượng tới hạn là n mũ log_2(2) bằng n, cân bằng đúng với f(n) = Theta(n) ở Trường hợp 2, nên tổng thời gian bằng chi phí mỗi tầng n nhân với log(n) tầng, đạt Theta(n log n).", "[\"Giải thích đúng ý nghĩa đại lượng tới hạn và 3 trường hợp của Định lý Thợ (4.0đ): Phân tích rõ việc so sánh chi phí chia-gộp f(n) với bậc tăng số lá n mũ log_b(a) ở 3 kịch bản lá áp đảo, cân bằng các tầng và gốc áp đảo.\", \"Vận dụng giải thích đúng độ phức tạp O(log n) của Tìm kiếm nhị phân (3.0đ): Xác định đúng a = 1, b = 2, chi phí bước O(1) thuộc Trường hợp 2 cho kết quả Theta(log n).\", \"Vận dụng giải thích đúng độ phức tạp O(n log n) của MergeSort (3.0đ): Xác định đúng a = 2, b = 2, chi phí trộn tuyến tính Theta(n) cân bằng với đại lượng tới hạn ở Trường hợp 2 cho kết quả Theta(n log n).\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 39),
            CreateExamSeed("00000000-0000-0000-0005-000000000211", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", StructureCsd201Id, RubricCsd201Id, "Công thức Tính Hệ số Cân bằng và Điều kiện Cân bằng của Cây AVL", "Hệ số cân bằng (Balance Factor) của một nút trên Cây AVL được tính bằng công thức nào? Điều kiện cân bằng nghiêm ngặt của Cây AVL là gì và tại sao điều kiện này bảo đảm chiều cao của cây luôn duy trì ở mức O(log n)?", "1. Công thức tính Hệ số cân bằng (Balance Factor - BF):\nTại một nút x bất kỳ trên cây tìm kiếm nhị phân, Hệ số cân bằng được định nghĩa bằng hiệu số giữa chiều cao cây con trái và chiều cao cây con phải của nút đó (quy ước chiều cao của nhánh rỗng bằng -1 và chiều cao nút lá bằng 0).\n\n2. Điều kiện cân bằng nghiêm ngặt của Cây AVL:\nMột cây tìm kiếm nhị phân đạt chuẩn AVL khi và chỉ khi tại mọi nút trong cây, trị tuyệt đối của Hệ số cân bằng không vượt quá 1, tức hệ số cân bằng chỉ được phép nhận một trong ba giá trị là -1, 0 hoặc +1. Ngay khi thao tác chèn hoặc xóa làm độ lệch chiều cao tại một nút chạm mức 2, thuật toán lập tức kích hoạt phép quay đơn hoặc phép quay kép để khôi phục cân bằng.\n\n3. Lý do chiều cao cây luôn bị chặn ở mức O(log n):\nXét cây AVL thưa nhất có chiều cao h với số lượng nút ít nhất là N(h). Để đạt chiều cao h mà tốn ít nút nhất, bên cạnh nút gốc ta buộc phải ghép một cây con cao h - 1 và cây con kia cao h - 2 (lệch tối đa 1 đơn vị), dẫn tới hệ thức truy hồi N(h) = 1 + N(h - 1) + N(h - 2). Hệ thức này tăng trưởng theo hàm mũ tương đương dãy số Fibonacci với cơ số tỷ lệ vàng khoảng 1.618 mũ h. Lấy logarit hai vế theo tổng số nút n, ta chứng minh được chiều cao h luôn nhỏ hơn 1.44 lần logarit cơ số 2 của n, đảm bảo mọi thao tác tra cứu, thêm, xóa luôn duy trì O(log n).", "[\"Công thức tính Hệ số cân bằng (Balance Factor) (3.0đ): Nêu đúng công thức hiệu chiều cao giữa cây con trái và cây con phải kèm quy ước chiều cao cây rỗng.\", \"Điều kiện cân bằng trị tuyệt đối BF không vượt quá 1 (3.0đ): Khẳng định điều kiện nghiêm ngặt hệ số cân bằng chỉ nhận giá trị -1, 0 hoặc +1 tại mọi nút trên cây.\", \"Chứng minh trần chiều cao O(log n) qua cây tối thiểu Fibonacci (4.0đ): Lập luận hệ thức số nút tối thiểu N(h) = 1 + N(h-1) + N(h-2) tăng theo hàm mũ để suy ra chiều cao nhỏ hơn 1.44 log2(n).\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 40),
            CreateExamSeed("00000000-0000-0000-0005-000000000212", CourseCsd201Id, "00000000-0000-0000-0000-000000000565", StructureCsd201Id, RubricCsd201Id, "Phân biệt Bản chất Chiến lược Khám phá giữa Duyệt BFS và Duyệt DFS", "Hãy phân biệt chiến lược khám phá đồ thị giữa Thuật toán duyệt theo chiều rộng (BFS) và Thuật toán duyệt theo chiều sâu (DFS). Cấu trúc dữ liệu bổ trợ nào được sử dụng trong mỗi thuật toán và trong bài toán tìm đường đi ngắn nhất không trọng số, tại sao ta bắt buộc phải dùng BFS?", "1. Chiến lược khám phá đồ thị:\n- BFS (Breadth-First Search - Khám phá theo mức/chiều rộng): Xuất phát từ đỉnh nguồn, BFS khám phá đồ thị theo từng vòng sóng đồng tâm. Thuật toán thăm hết toàn bộ các đỉnh kề cách nguồn 1 cạnh, sau đó mới mở rộng sang các đỉnh cách nguồn 2 cạnh, rồi 3 cạnh, tuyệt đối không đi sâu vào một nhánh khi tầng khoảng cách hiện tại chưa xét xong.\n- DFS (Depth-First Search - Khám phá theo chiều sâu): Xuất phát từ đỉnh nguồn, DFS tiến sâu tối đa dọc theo một nhánh đường đi cho đến khi chạm đỉnh cụt không còn đỉnh kề chưa thăm, lúc đó mới quay lui (backtrack) về nút cha gần nhất để thử rẽ sang nhánh khác.\n\n2. Cấu trúc dữ liệu bổ trợ:\n- BFS sử dụng Hàng đợi vào trước ra trước (FIFO Queue) để bảo đảm đỉnh nào được phát hiện ở tầng gần hơn sẽ được mở rộng các đỉnh kề trước.\n- DFS sử dụng Ngăn xếp vào sau ra trước (LIFO Stack) tường minh hoặc tận dụng trực tiếp ngăn xếp lời gọi hàm đệ quy (Call Stack).\n\n3. Lý do tìm đường đi ngắn nhất không trọng số bắt buộc dùng BFS:\nTrên đồ thị không trọng số, độ dài đường đi tính bằng số cạnh đi qua. Vì BFS duyệt tuần tự theo khoảng cách tăng dần từng bước 1, 2, 3 cạnh tính từ nguồn, ngay khoảnh khắc đỉnh đích được chạm tới lần đầu tiên, đường đi đó chắc chắn đi qua ít cạnh nhất. Ngược lại, DFS có thể đi vòng rất xa theo một nhánh sâu và chạm đỉnh đích trên một lộ trình dài trước khi quay lui về nhánh ngắn sát cạnh nguồn.", "[\"Phân biệt chiến lược lan tỏa sóng vs đi sâu quay lui (3.5đ): Mô tả chuẩn xác cơ chế duyệt theo từng tầng khoảng cách của BFS so với tiến sâu tối đa rồi quay lui của DFS.\", \"Cấu trúc dữ liệu bổ trợ Queue vs Stack (3.0đ): Chỉ rõ vai trò của FIFO Queue trong BFS và LIFO Stack hoặc Call Stack đệ quy trong DFS.\", \"Lý do BFS đảm bảo đường đi ngắn nhất không trọng số (3.5đ): Chứng minh tính đơn điệu tăng theo số cạnh của BFS đảm bảo lần chạm đỉnh đích đầu tiên luôn là tối ưu.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 41),
            CreateExamSeed("00000000-0000-0000-0005-000000000213", CourseCsd201Id, "00000000-0000-0000-0000-000000000566", StructureCsd201Id, RubricCsd201Id, "Nguyên lý Hoạt động Thời gian Tuyến tính của Thuật toán Radix Sort", "Thuật toán Radix Sort hoạt động theo nguyên lý nào? Tại sao Radix Sort có thể đạt được độ phức tạp thời gian tuyến tính O(d * (n + k)) mà không bị giới hạn bởi cận dưới toán học Omega(n log n) của các thuật toán sắp xếp dựa trên so sánh?", "1. Nguyên lý hoạt động của Radix Sort:\nRadix Sort là thuật toán sắp xếp không dựa trên phép so sánh trực tiếp giữa hai phần tử. Theo hướng tiếp cận phổ biến từ chữ số có trọng số thấp nhất (LSD - Least Significant Digit), thuật toán tách khóa thành d chữ số theo cơ số k (ví dụ hệ thập phân có k = 10 thùng từ 0 đến 9) và tiến hành phân phối các phần tử qua d lượt liên tiếp: lượt đầu gom theo hàng đơn vị, lượt hai theo hàng chục, tiếp tục tiến dần lên hàng cao nhất. Tại mỗi lượt chữ số, thuật toán bắt buộc dùng một thủ tục phân phối ổn định như Counting Sort để giữ nguyên thứ tự tương đối đã thiết lập từ các chữ số thấp hơn, đạt tổng chi phí O(d * (n + k)).\n\n2. Lý do vượt qua cận dưới toán học Omega(n log n):\nCận dưới Omega(n log n) được chứng minh trên mô hình Cây quyết định nhị phân, áp dụng riêng cho các thuật toán chỉ thu thập thông tin thứ tự thông qua phép so sánh cặp lớn hơn hay nhỏ hơn giữa hai phần tử (cần phân biệt n giai thừa hoán vị nên chiều cao cây tối thiểu cỡ n log n). Radix Sort không hề so sánh hai phần tử với nhau mà dùng trực tiếp giá trị chữ số làm địa chỉ thùng chứa để rẽ nhánh đa hướng thành k thùng trong O(1), qua đó thoát khỏi mô hình cây quyết định nhị phân và đạt thời gian tuyến tính khi d là hằng số nhỏ.", "[\"Nguyên lý phân rã chữ số LSD và vai trò của Counting Sort ổn định (4.0đ): Mô tả đúng quá trình phân phối từ hàng đơn vị lên hàng cao nhất và yêu cầu bắt buộc dùng thuật toán con ổn định.\", \"Giải thích ý nghĩa công thức độ phức tạp O(d*(n+k)) (2.5đ): Nêu rõ vai trò của số chữ số d, số lượng phần tử n và cơ số thùng chứa k.\", \"Chứng minh lý do vượt qua mô hình Cây quyết định Omega(n log n) (3.5đ): Lập luận rõ cận dưới Omega(n log n) chỉ ràng buộc thuật toán so sánh cặp, còn Radix Sort định vị trực tiếp theo giá trị chữ số.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 42),
            CreateExamSeed("00000000-0000-0000-0005-000000000214", CourseCsd201Id, "00000000-0000-0000-0000-000000000568", StructureCsd201Id, RubricCsd201Id, "Nguyên lý Nén Run-Length Encoding (RLE) và Nén Từ điển Động LZW (Lempel-Ziv-Welch)", "Hãy trình bày nguyên lý nén dữ liệu của thuật toán Run-Length Encoding (RLE) và chỉ ra kịch bản dữ liệu khiến RLE làm phình to kích thước tệp. Tiếp theo, giải thích cơ chế hoạt động của thuật toán nén từ điển LZW (Lempel-Ziv-Welch) và tại sao bộ giải nén LZW có thể tự tái tạo lại chính xác từ điển mà không cần bộ nén phải đính kèm bảng từ điển vào tệp đầu ra?", "1. Nguyên lý Run-Length Encoding (RLE) và kịch bản gây phình to dữ liệu:\nRLE thu gọn dữ liệu bằng cách gom một dãy các ký tự giống hệt nhau đứng liên tiếp thành một cặp thông tin gồm số lần lặp đi kèm ký tự đại diện (chẳng hạn sáu chữ A liên tiếp được thu gọn thành cặp 6A, rất hiệu quả cho ảnh bitmap ít màu). Tuy nhiên, khi dữ liệu đầu vào biến thiên liên tục không có ký tự lặp liền kề (như chuỗi ABCDEFGH), RLE phải chèn thêm số đếm 1 trước từng ký tự đơn lẻ, làm dung lượng đầu ra phình gấp đôi kích thước gốc.\n\n2. Cơ chế nén từ điển động LZW và khả năng tự đồng bộ không cần Header:\n- LZW khởi tạo từ điển ban đầu bằng toàn bộ các ký tự đơn lẻ chuẩn (như 256 mã ASCII từ 0 đến 255). Trong khi quét dữ liệu, bộ nén tìm chuỗi tiền tố dài nhất W đang tồn tại trong từ điển, đọc thêm ký tự kế tiếp K ngay sau nó: xuất mã số của W ra luồng nén, đăng ký chuỗi ghép mới W nối K vào từ điển với mã số tiếp theo (từ 256 trở đi), rồi đặt lại W bằng K để lặp tiếp.\n- Khác với Huffman tĩnh phải gửi kèm bảng tần suất ở đầu tệp, cả bộ nén lẫn bộ giải nén LZW đều xuất phát từ cùng bảng 256 ký tự gốc. Mỗi mục từ điển mới W nối K chỉ được tạo sau khi mã của W đã phát đi, còn ký tự K chính là ký tự mở đầu của chuỗi giải mã ở bước kế tiếp, nên bộ giải nén tự suy luận và dựng lại từ điển khớp từng bước 100% với bộ nén mà không tốn dung lượng truyền bảng từ điển.", "[\"Trình bày nguyên lý RLE và kịch bản phình to dữ liệu (3.5đ): Giải thích cách gom cặp số lần lặp - ký tự của RLE và chỉ rõ chuỗi luân phiên không lặp liên tiếp làm phình kích thước.\", \"Giải thích quy trình khớp chuỗi dài nhất W và mở rộng từ điển trong LZW (3.5đ): Mô tả rõ bước khởi tạo bảng ASCII cơ sở, xuất mã của chuỗi khớp dài nhất W và thêm chuỗi ghép W nối K vào từ điển động.\", \"Làm rõ lý do bộ giải nén LZW tự tái tạo từ điển không cần Header (3.0đ): Giải thích sự đồng bộ trạng thái từ bảng gốc chung và quy tắc lấy ký tự đầu của bước giải mã kế tiếp để khôi phục mục từ mới.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 43),
            CreateExamSeed("00000000-0000-0000-0005-000000000215", CourseCsd201Id, "00000000-0000-0000-0000-000000000563", StructureCsd201Id, RubricCsd201Id, "Đệ quy Đảo ngược Singly Linked List và Phân tích Lỗi Đệ quy Vô tận (StackOverflowError)", "Khi thiết kế giải thuật đệ quy đảo ngược một Danh sách liên kết đơn, điều kiện dừng cơ sở gồm những trường hợp nào? Tại sao nếu ở bước gọi đệ quy lập trình viên truyền nhầm lại chính nút hiện tại thay vì nút kế tiếp thì chương trình lập tức bị sập với lỗi tràn ngăn xếp (StackOverflowError)? Hãy giải thích cơ chế quay lui đảo ngược chiều liên kết giữa nút hiện tại với nút kế tiếp và lý do bắt buộc phải ngắt liên kết xuôi cũ của nút hiện tại về null.", "1. Điều kiện dừng cơ sở và nguyên nhân lỗi `StackOverflowError`:\n- Điều kiện dừng chuẩn của giải thuật đệ quy đảo ngược danh sách liên kết đơn gồm hai trường hợp: danh sách rỗng (`head` bằng null) hoặc danh sách chỉ có duy nhất một nút (con trỏ kế tiếp của `head` bằng null); khi đó hàm trả về chính nút đó làm đầu danh sách mới.\n- Nếu lời gọi đệ quy truyền nhầm lại chính nút `head` hiện tại thay vì nút kế tiếp `head.next`, quy mô bài toán không hề thu hẹp qua từng bước gọi nên không bao giờ chạm tới điều kiện dừng. Máy ảo Java liên tục cấp phát thêm khung kích hoạt mới chồng chất lên vùng nhớ Call Stack cho đến khi cạn kiệt dung lượng ngăn xếp của luồng và ném lỗi `StackOverflowError`.\n\n2. Cơ chế đảo chiều liên kết trong pha quay lui (Unwinding Phase):\nSau khi lời gọi đệ quy trên phần đuôi danh sách chạm đáy tại nút cuối cùng và trả về nút cuối đó làm đầu mới, luồng thực thi quay lui từng bậc về các nút phía trước. Tại mỗi nút `head` đang xét, nút kế tiếp ngay sau nó chính là nút cuối của đoạn danh sách con vừa được đảo ngược. Để nối ngược chiều, ta cho con trỏ kế tiếp của nút đứng sau đó trỏ ngược về lại chính `head`, đồng thời bắt buộc gán con trỏ kế tiếp của `head` về null nhằm cắt đứt chiều liên kết xuôi cũ. Nếu quên bước ngắt về null ở nút đầu ban đầu, hai nút cuối cùng của danh sách sau đảo ngược sẽ trỏ vòng qua lại lẫn nhau tạo thành chu trình vô tận.", "[\"Nêu đúng điều kiện dừng và nguyên nhân lỗi StackOverflowError (3.5đ): Chỉ rõ hai ca dừng (danh sách rỗng hoặc còn 1 nút) và giải thích truyền nhầm nút hiện tại làm bài toán không hội tụ gây tràn Call Stack.\", \"Giải thích cơ chế đảo chiều liên kết trong pha quay lui (3.5đ): Mô tả rõ cách giữ lại nút đầu mới từ đáy đệ quy và cập nhật nút đứng liền sau trỏ ngược về nút hiện tại khi quay lui.\", \"Phân tích lý do bắt buộc ngắt liên kết xuôi cũ về null (3.0đ): Chứng minh việc gán con trỏ kế tiếp của nút hiện tại về null giúp triệt tiêu nguy cơ tạo chu trình khép kín ở đuôi danh sách mới.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 44),
            CreateExamSeed("00000000-0000-0000-0005-000000000216", CourseCsd201Id, "00000000-0000-0000-0000-000000000562", StructureCsd201Id, RubricCsd201Id, "Ứng dụng Thuật toán Shunting-Yard Chuyển đổi Biểu thức Infix sang Postfix", "Tại sao máy tính thường chuyển biểu thức toán học từ dạng trung tố (Infix) sang dạng hậu tố (Postfix / Ký pháp Ba Lan ngược) trước khi tính giá trị? Hãy trình bày 4 quy tắc xử lý toán hạng, toán tử và cặp dấu ngoặc trên Ngăn xếp (Stack) của thuật toán Shunting-Yard, đồng thời giải thích cơ chế Stack bảo đảm phép trừ và phép nhân được thực hiện trước phép cộng trong biểu thức A cộng B nhân mở ngoặc C trừ D đóng ngoặc.", "1. Ưu điểm của dạng hậu tố (Postfix) và 4 quy tắc cốt lõi của thuật toán Shunting-Yard:\nBiểu thức trung tố đòi hỏi máy tính phải xét đồng thời mức ưu tiên toán tử và các cặp ngoặc lồng nhau, trong khi biểu thức hậu tố đặt toán tử ngay sau các toán hạng của nó nên hoàn toàn không cần dấu ngoặc và có thể tính giá trị chỉ bằng một lần duyệt tuyến tính từ trái sang phải. Thuật toán Shunting-Yard dùng một Stack tạm giữ toán tử theo 4 quy tắc:\n- Gặp toán hạng: đưa thẳng vào chuỗi kết quả đầu ra vì thứ tự tương đối giữa các toán hạng không đổi.\n- Gặp dấu mở ngoặc đơn: đẩy vào Stack để đánh dấu mốc phạm vi ưu tiên con mới.\n- Gặp toán tử: chừng nào đỉnh Stack là toán tử có độ ưu tiên lớn hơn hoặc bằng toán tử đang xét (với phép toán kết hợp trái), lấy toán tử trên đỉnh Stack đưa ra đầu ra rồi mới đẩy toán tử hiện tại vào Stack.\n- Gặp dấu đóng ngoặc đơn: lấy liên tiếp các toán tử khỏi Stack đưa ra đầu ra cho tới khi chạm dấu mở ngoặc đơn, sau đó hủy bỏ cả cặp ngoặc; cuối cùng khi hết biểu thức thì xả toàn bộ toán tử còn lại trong Stack ra đầu ra.\n\n2. Giải thích thứ tự thực thi trên ví dụ A + B * (C - D):\nKhi quét qua phép cộng rồi đến phép nhân, do phép nhân có độ ưu tiên cao hơn phép cộng nên nó nằm đè lên trên phép cộng trong Stack mà chưa xả phép cộng ra. Tiếp theo, cặp ngoặc bao quanh C trừ D cô lập phép trừ trên đỉnh Stack và ép xả dấu trừ ngay khi gặp dấu đóng ngoặc (tạo cụm C D -). Cuối cùng khi hết biểu thức, cơ chế vào sau ra trước (LIFO) xả phép nhân ra trước phép cộng, bảo đảm kết quả C trừ D được nhân với B rồi mới cộng vào A.", "[\"Giải thích lợi ích của biểu thức Postfix đối với bộ tính toán (2.5đ): Nêu rõ Postfix triệt tiêu hoàn toàn dấu ngoặc và cho phép tính giá trị tuyến tính một lượt không cần xét lại độ ưu tiên.\", \"Trình bày chuẩn xác 4 quy tắc điều phối Stack của Shunting-Yard (4.5đ): Trình bày đủ cách xử lý toán hạng ra thẳng Output, dấu mở ngoặc, dấu đóng ngoặc xả tới mốc và so sánh độ ưu tiên toán tử.\", \"Phân tích đúng cơ chế LIFO bảo toàn thứ tự ưu tiên trên ví dụ (3.0đ): Giải thích rõ cách cặp ngoặc giải phóng phép trừ trước, sau đó phép nhân nằm trên đỉnh Stack được xả trước phép cộng.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 45),
            CreateExamSeed("00000000-0000-0000-0005-000000000217", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", StructureCsd201Id, RubricCsd201Id, "Tính chất Chiều cao Cây Nhị phân và Cơ chế Duyệt Theo Mức (Level-Order Traversal) với Hàng đợi", "Hãy phân biệt chiều cao (Height) và độ sâu (Depth) của một nút trên Cây nhị phân, đồng thời nêu công thức xác định số nút tối đa ở tầng thứ k và trên toàn bộ cây có chiều cao h. Tiếp theo, hãy trình bày quy trình sử dụng cấu trúc Hàng đợi (Queue) để duyệt cây nhị phân theo từng mức từ trên xuống dưới, từ trái sang phải (Level-Order Traversal) và phân tích độ phức tạp thời gian, không gian.", "1. Phân biệt Độ sâu (Depth), Chiều cao (Height) và công thức số lượng nút tối đa:\n- Độ sâu của một nút được đo từ trên xuống, bằng số cạnh trên đường đi đơn từ nút gốc xuống nút đó (nút gốc có độ sâu bằng 0). Ngược lại, chiều cao của một nút được đo từ dưới lên, bằng số cạnh trên đường đi dài nhất từ nút đó xuống một nút lá hậu duệ xa nhất của nó (nút lá có chiều cao bằng 0, và chiều cao của toàn cây chính là chiều cao của nút gốc).\n- Do mỗi nút phân nhánh tối đa thành 2 con, tại tầng độ sâu thứ k (với k bắt đầu từ 0) có tối đa 2 mũ k nút. Cộng dồn cấp số nhân từ tầng 0 đến tầng h, một cây nhị phân có chiều cao h chứa tối đa 2 mũ (h + 1) trừ 1 nút.\n\n2. Quy trình Duyệt theo mức (Level-Order Traversal) bằng Hàng đợi và độ phức tạp:\n- Trước tiên kiểm tra ca biên cây rỗng; nếu cây khác rỗng thì khởi tạo một Hàng đợi FIFO và đưa nút gốc vào hàng đợi.\n- Chừng nào Hàng đợi chưa rỗng, lặp thao tác: lấy nút ở đầu hàng đợi ra để xử lý dữ liệu, sau đó kiểm tra nếu nút con trái tồn tại thì thêm con trái vào cuối hàng đợi, rồi nếu nút con phải tồn tại thì thêm con phải vào cuối hàng đợi. Cơ chế vào trước ra trước đảm bảo mọi nút ở tầng k đều được lấy ra hết trước khi các nút con ở tầng k + 1 của chúng đến lượt xử lý, đồng thời việc đẩy con trái trước con phải giữ đúng thứ tự từ trái sang phải.\n- Mỗi nút chỉ vào và ra khỏi Hàng đợi đúng một lần nên độ phức tạp thời gian là O(n). Dung lượng Hàng đợi lớn nhất tại thời điểm chứa trọn tầng rộng nhất của cây (tối đa khoảng n chia 2 nút lá ở cây nhị phân đầy đủ), do đó độ phức tạp không gian phụ là O(n).", "[\"Phân biệt đúng Depth vs Height và công thức số nút tối đa (3.5đ): Định nghĩa chính xác độ sâu tính từ gốc xuống, chiều cao tính từ nút xuống lá xa nhất, cùng công thức 2 mũ k và 2 mũ (h+1) trừ 1.\", \"Trình bày chuẩn xác quy trình Level-Order Traversal bằng Queue (4.0đ): Mô tả rõ kiểm tra cây rỗng, khởi tạo Queue với nút gốc, vòng lặp lấy đầu hàng đợi và đẩy tuần tự con trái rồi con phải.\", \"Phân tích đúng độ phức tạp thời gian O(n) và không gian O(n) (2.5đ): Giải thích mỗi nút qua Queue đúng 1 lần và bộ nhớ phụ đạt cực đại theo độ rộng tầng lớn nhất của cây.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 46),
            CreateExamSeed("00000000-0000-0000-0005-000000000218", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", StructureCsd201Id, RubricCsd201Id, "Quy trình Xây dựng Max-Heap từ Mảng và Thao tác Xóa Phần tử Lớn nhất", "Hãy trình bày quy trình xây dựng một Max-Heap trực tiếp từ một mảng số nguyên chưa có thứ tự theo phương pháp từ dưới lên (Bottom-up Build-Heap). Tiếp theo, mô tả chi tiết các bước thực hiện thao tác trích xuất và xóa phần tử lớn nhất (extractMax) kết hợp quá trình vun đống xuống (Sift-Down) để khôi phục cả tính chất hình học lẫn tính chất thứ tự của đống.", "1. Quy trình xây dựng Max-Heap từ dưới lên (Bottom-up Build-Heap):\nXem mảng đầu vào gồm n phần tử (đánh chỉ số từ 0 đến n - 1) như một cây nhị phân hoàn chỉnh, trong đó nút tại chỉ số i có con trái tại 2i + 1 và con phải tại 2i + 2. Toàn bộ các phần tử từ chỉ số n/2 đến n - 1 đều là các nút lá không có con nên bản thân mỗi lá đã mặc định là một Max-Heap hợp lệ. Do đó, thuật toán bắt đầu từ nút trong cuối cùng tại chỉ số (n/2) - 1, duyệt ngược từng chỉ số lùi về gốc 0 và gọi thủ tục vun đống xuống (`siftDown`) tại mỗi nút để biến cây con gốc i thành Max-Heap dựa trên hai cây con dưới nó đã thỏa tính chất đống, hoàn tất toàn bộ trong thời gian tuyến tính O(n).\n\n2. Quy trình trích xuất phần tử lớn nhất (`extractMax`) và vun đống xuống (`siftDown`):\n- Bước 1: Lưu lại giá trị phần tử cực đại nằm ở gốc đống (chỉ số 0) để chuẩn bị trả về. Không được xóa trống ô đầu rồi dồn mảng vì sẽ tốn O(n) và làm xáo trộn quan hệ cha - con.\n- Bước 2: Đưa phần tử cuối cùng của đống (tại chỉ số `size - 1`) lên ghi đè vào vị trí gốc 0, sau đó giảm kích thước đống đi 1 đơn vị nhằm bảo toàn ngay lập tức hình dáng Cây nhị phân hoàn chỉnh.\n- Bước 3: Thực hiện `siftDown` từ gốc 0: so sánh nút hiện tại với hai nút con trái và phải của nó; nếu nút hiện tại nhỏ hơn nút con lớn nhất trong hai con thì hoán đổi nó với nút con lớn hơn đó (để phần tử lớn nhất nổi lên làm cha của cả nhánh) rồi tiếp tục lặp xuống vị trí mới cho tới khi nút lớn hơn hoặc bằng cả hai con hoặc chạm tới tầng lá, tốn thời gian O(log n).", "[\"Trình bày đúng quy trình Bottom-up Build-Heap từ nút trong cuối cùng (3.5đ): Giải thích rõ ánh xạ mảng 0-indexed, lý do bỏ qua nửa mảng sau là lá và duyệt lùi từ (n/2) - 1 về 0 gọi siftDown.\", \"Mô tả chính xác thao tác thay thế gốc bằng phần tử cuối trong extractMax (3.0đ): Nêu rõ bước lưu gốc cực đại, chép phần tử cuối lên vị trí 0 và giảm kích thước đống để giữ cấu trúc Complete Binary Tree.\", \"Giải thích đúng cơ chế Sift-Down chọn con lớn hơn và độ phức tạp (3.5đ): Làm rõ nguyên tắc luôn hoán đổi với con lớn nhất trong hai con cho tới khi thỏa bất biến đống với chi phí O(log n).\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 47),
            CreateExamSeed("00000000-0000-0000-0005-000000000219", CourseCsd201Id, "00000000-0000-0000-0000-000000000565", StructureCsd201Id, RubricCsd201Id, "Thuật toán Sắp xếp Tô-pô (Kahn's Topological Sort) trên DAG và Thuật toán Floyd-Warshall Mọi Cặp Đỉnh", "Sắp xếp Tô-pô (Topological Sort) áp dụng cho loại đồ thị nào và giải quyết bài toán thực tế gì? Hãy trình bày từng bước Thuật toán Kahn sử dụng mảng bán bậc vào (in-degree) kết hợp Hàng đợi (Queue) để tìm thứ tự Tô-pô và giải thích làm thế nào thuật toán này phát hiện được đồ thị có chu trình có hướng. Tiếp theo, hãy trình bày nguyên lý quy hoạch động mở rộng dần tập đỉnh trung gian của thuật toán Floyd-Warshall tìm đường đi ngắn nhất giữa mọi cặp đỉnh.", "1. Điều kiện áp dụng và Thuật toán Kahn cho Sắp xếp Tô-pô:\n- Sắp xếp Tô-pô chỉ áp dụng cho Đồ thị có hướng không có chu trình (DAG - Directed Acyclic Graph), dùng để xác định trình tự thực hiện các tác vụ có ràng buộc phụ thuộc như thứ tự học môn tiên quyết hoặc biên dịch gói thư viện.\n- Quy trình Thuật toán Kahn chạy trong thời gian O(V + E): Đầu tiên, thống kê bán bậc vào (số cạnh đi vào) cho tất cả các đỉnh và đưa mọi đỉnh có bán bậc vào bằng 0 (không phụ thuộc tác vụ nào khác) vào Hàng đợi. Lặp cho tới khi Hàng đợi rỗng: lấy một đỉnh u ra đưa vào danh sách kết quả Tô-pô, tăng biến đếm số đỉnh đã xử lý thêm 1, đồng thời duyệt mọi đỉnh kề v của u để giảm bán bậc vào của v đi 1; ngay khi đỉnh v nào giảm bán bậc vào chạm 0 thì đẩy v vào Hàng đợi.\n- Cơ chế phát hiện chu trình: Nếu sau khi Hàng đợi đã cạn mà tổng số đỉnh đã lấy ra nhỏ hơn tổng số đỉnh V của đồ thị, chứng tỏ tồn tại nhóm đỉnh khóa lẫn nhau không bao giờ giảm bán bậc vào về 0, tức đồ thị chứa ít nhất một chu trình có hướng.\n\n2. Nguyên lý Quy hoạch động của Thuật toán Floyd-Warshall:\nFloyd-Warshall giải bài toán đường đi ngắn nhất giữa mọi cặp đỉnh trên ma trận khoảng cách với độ phức tạp O(V^3) bằng cách mở rộng dần tập đỉnh trung gian được phép đi qua từ đỉnh 0 đến đỉnh V - 1. Ở giai đoạn xét đỉnh trung gian k (vòng lặp ngoài cùng), với mọi cặp đỉnh đi từ i đến j, thuật toán kiểm tra xem đường đi vòng từ i qua k rồi từ k sang j (nếu cả hai chặng đều hữu hạn) có tổng trọng số nhỏ hơn khoảng cách tốt nhất hiện tại từ i đến j hay không để cập nhật tối ưu. Nếu sau khi kết thúc tồn tại đỉnh i có khoảng cách tới chính nó mang giá trị âm, đồ thị có chu trình âm.", "[\"Nêu đúng điều kiện đồ thị DAG và các bước Thuật toán Kahn (3.5đ): Trình bày rõ điều kiện đồ thị có hướng không chu trình, cách thống kê bán bậc vào và dùng Queue giải phóng dần các đỉnh có in-degree bằng 0.\", \"Giải thích cơ chế phát hiện chu trình có hướng qua số đỉnh đã duyệt (3.0đ): Chứng minh các đỉnh thuộc chu trình luôn còn phụ thuộc nên không bao giờ về in-degree bằng 0, làm số đỉnh lấy ra nhỏ hơn V.\", \"Trình bày đúng nguyên lý quy hoạch động Floyd-Warshall và nhận diện chu trình âm (3.5đ): Giải thích công thức tối ưu khoảng cách qua đỉnh trung gian k đặt ở vòng lặp ngoài cùng, kiểm tra vô cực và phát hiện chu trình âm trên đường chéo.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 48),
            CreateExamSeed("00000000-0000-0000-0005-000000000220", CourseCsd201Id, "00000000-0000-0000-0000-000000000566", StructureCsd201Id, RubricCsd201Id, "Nguyên lý Sắp xếp Trộn (MergeSort) và Cơ chế Hai Con trỏ Trộn Mảng Con Bảo toàn Tính Ổn định", "Hãy trình bày 3 giai đoạn Chia - Trị - Tổng hợp của thuật toán Sắp xếp Trộn (MergeSort) và mô tả chi tiết quy trình sử dụng kỹ thuật hai con trỏ để trộn hai nửa mảng con đã sắp xếp thành một dãy tăng dần hoàn chỉnh. Tại sao trong bước so sánh hai phần tử đang trỏ ở nửa trái và nửa phải, việc ưu tiên chọn phần tử nửa trái khi hai giá trị bằng nhau lại quyết định trực tiếp đến Tính ổn định (Stability) của MergeSort?", "1. Ba giai đoạn Chia để trị của MergeSort:\n- Chia (Divide): Xác định chỉ số điểm giữa một cách an toàn chống tràn số nguyên bằng công thức lấy chỉ số đầu cộng một nửa hiệu chỉ số cuối trừ chỉ số đầu, chia mảng thành hai nửa con kích thước xấp xỉ bằng nhau.\n- Trị (Conquer): Gọi đệ quy sắp xếp độc lập nửa mảng bên trái và nửa mảng bên phải cho tới điều kiện dừng cơ sở khi đoạn con chỉ còn tối đa 1 phần tử.\n- Tổng hợp (Combine): Trộn hai mảng con đã có thứ tự thành một đoạn được sắp xếp hoàn chỉnh trong thời gian tuyến tính O(n), giúp tổng thời gian toàn thuật toán luôn đạt O(n log n) ở cả trường hợp tốt nhất, trung bình và xấu nhất.\n\n2. Quy trình trộn bằng kỹ thuật hai con trỏ và bảo toàn Tính ổn định:\nTa sao chép dữ liệu hai đoạn con ra hai mảng tạm trái L và phải R, đặt con trỏ i ở đầu mảng L, con trỏ j ở đầu mảng R và con trỏ ghi k ở vị trí bắt đầu đoạn đích. Ở mỗi bước lặp khi cả hai mảng tạm đều còn phần tử, ta so sánh L[i] với R[j] để chép phần tử nhỏ hơn vào vị trí k rồi nhích con trỏ tương ứng lên 1; khi một trong hai mảng tạm cạn trước, ta chép nốt toàn bộ phần tử còn dư của mảng kia vào cuối đoạn đích. Trong phép so sánh, do mọi phần tử thuộc nửa trái L vốn đứng trước mọi phần tử thuộc nửa phải R trong mảng gốc, khi gặp hai phần tử bằng nhau ta bắt buộc ưu tiên lấy phần tử L[i] đưa vào mảng kết quả trước (tương ứng điều kiện nhỏ hơn hoặc bằng). Nếu lấy R[j] trước khi bằng nhau, phần tử đứng sau sẽ vượt lên trước phần tử đứng đầu và làm hỏng tính ổn định của MergeSort.", "[\"Trình bày đúng 3 giai đoạn Chia - Trị - Tổng hợp của MergeSort (3.0đ): Nêu rõ cách tính điểm chia giữa chống tràn số, điều kiện dừng 1 phần tử và độ phức tạp O(n log n) bất biến.\", \"Mô tả chính xác quy trình trộn 2 con trỏ và xử lý phần tử dư (4.0đ): Giải thích rõ vai trò hai mảng tạm trái - phải, bước dịch chuyển hai con trỏ đối chiếu và bước chép vét phần còn lại khi một nửa cạn trước.\", \"Giải thích thuyết phục điều kiện ưu tiên nửa trái bảo toàn Stability (3.0đ): Chứng minh khi hai khóa bằng nhau, chọn phần tử mảng con trái trước giúp giữ nguyên thứ tự xuất hiện ban đầu trong mảng gốc.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 49),
            CreateExamSeed("00000000-0000-0000-0005-000000000221", CourseCsd201Id, "00000000-0000-0000-0000-000000000567", StructureCsd201Id, RubricCsd201Id, "Xử lý Xung đột Bảng băm bằng Dò Bậc Hai (Quadratic Probing) và Băm Kép (Double Hashing)", "Trong bảng băm theo cơ chế Địa chỉ mở (Open Addressing), để khắc phục hiện tượng Cụm chính (Primary Clustering) của phương pháp Dò tuyến tính, hai chiến lược Dò bậc hai (Quadratic Probing) và Băm kép (Double Hashing) xác định chuỗi vị trí dò tiếp theo dựa trên nguyên lý nào? Tại sao Dò bậc hai tuy phá vỡ được Cụm chính nhưng vẫn gặp phải hiện tượng Cụm thứ cấp (Secondary Clustering) và có nguy cơ không tìm được ô trống dù bảng chưa đầy, trong khi Băm kép giải quyết triệt để vấn đề này?", "1. Nguyên lý chuỗi vị trí dò của Dò bậc hai và Băm kép:\n- Trong Dò tuyến tính, bước nhảy tăng đều từng ô liền kề (+1, +2, +3...) khiến các vùng ô đầy sát nhập lại thành những dải liên tiếp ngày càng phình to gọi là Cụm chính.\n- Dò bậc hai (Quadratic Probing) thay khoảng dịch tuyến tính bằng bình phương của số lần thử thứ i (cộng 1, cộng 4, cộng 9... lấy phần dư cho kích thước bảng M), giúp các lần thử nhảy vọt ra xa điểm va chạm ban đầu và phá vỡ sự kết dính của các cụm liền kề.\n- Băm kép (Double Hashing) sử dụng thêm một hàm băm phụ thứ hai độc lập h2(k) để quyết định độ lớn bước nhảy riêng cho từng khóa: ở lần thử thứ i, vị trí dò bằng mã băm chính cộng i nhân bước nhảy h2(k) rồi chia lấy dư cho M.\n\n2. Hạn chế Cụm thứ cấp của Dò bậc hai và cách Băm kép khắc phục triệt để:\n- Trong Dò bậc hai, khoảng nhảy bình phương chỉ phụ thuộc vào số thứ tự lần thử i chứ không phụ thuộc vào bản thân giá trị khóa k. Do đó, mọi khóa vô tình có cùng chỉ số băm ban đầu h1(k) vẫn đi theo một quỹ đạo nhảy trùng khít 100% với nhau, gây nghẽn trên cùng các ô đó — hiện tượng này gọi là Cụm thứ cấp (Secondary Clustering). Ngoài ra, các số chính phương theo modulo M chỉ phủ được khoảng một nửa số ô của bảng (cần chọn M là số nguyên tố và giữ hệ số tải dưới 0.5 mới đảm bảo chèn thành công).\n- Băm kép khắc phục hoàn toàn Cụm thứ cấp vì hai khóa khác nhau dù trùng vị trí băm đầu tiên h1 vẫn sẽ có bước nhảy h2 khác nhau, phân tán chúng theo các quỹ đạo độc lập khắp bảng băm.", "[\"Trình bày đúng nguyên lý bước nhảy của Quadratic Probing và Double Hashing (3.5đ): Phân biệt rõ khoảng nhảy bình phương theo lượt thử i của Dò bậc hai với khoảng nhảy nhân theo hàm băm phụ h2(k) của Băm kép.\", \"Phân tích bản chất Cụm thứ cấp và giới hạn hệ số tải của Dò bậc hai (3.5đ): Giải thích rõ các khóa trùng h1 đi chung một quỹ đạo dò gây Secondary Clustering và giới hạn hệ số tải 0.5 trên bảng kích thước nguyên tố.\", \"Giải thích cơ chế Băm kép phân tán quỹ đạo dò độc lập theo khóa (3.0đ): Chứng minh hàm băm phụ h2 tạo bước nhảy khác nhau cho từng khóa giúp triệt tiêu cả Cụm chính lẫn Cụm thứ cấp.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 50),
            CreateExamSeed("00000000-0000-0000-0005-000000000222", CourseCsd201Id, "00000000-0000-0000-0000-000000000563", StructureCsd201Id, RubricCsd201Id, "Phân tích Ba Phương pháp Tính Số Fibonacci: Đệ quy Ngây thơ, Ghi nhớ và Quy hoạch Động Lặp", "Hãy phân tích và so sánh 3 phương pháp giải bài toán tìm số Fibonacci thứ n gồm: (1) Đệ quy ngây thơ (Naive Recursion), (2) Đệ quy có nhớ từ trên xuống (Top-down Memoization), và (3) Quy hoạch động lặp từ dưới lên (Bottom-up Iterative DP) về độ phức tạp thời gian, độ phức tạp không gian và điểm nghẽn kỹ thuật. Giải thích tại sao phương pháp lặp từ dưới lên có thể thu gọn không gian bộ nhớ phụ từ O(n) xuống O(1).", "1. Đối chiếu chuyên sâu 3 phương pháp tính số Fibonacci thứ n:\n- Phương pháp 1 - Đệ quy ngây thơ (Naive Recursion): Dịch trực tiếp công thức truy hồi bằng hai lời gọi đệ quy cho n - 1 và n - 2. Do hiện tượng bài toán con gối nhau (Overlapping Subproblems), cùng một giá trị trung gian như F(n - 2), F(n - 3) bị tính đi tính lại theo cấp số nhân trên cây nhị phân đệ quy, khiến thời gian bùng nổ theo hàm mũ O(2^n) (chính xác cỡ 1.618^n) trong khi không gian Call Stack tốn O(n).\n- Phương pháp 2 - Đệ quy có nhớ (Top-down Memoization): Bổ sung một mảng hoặc bảng tra cứu lưu kết quả của mỗi trạng thái k ngay lần đầu tính xong; các nhánh gọi trùng sau đó trả về tức thì trong O(1). Nhờ cắt tỉa toàn bộ nhánh lặp thừa, thời gian giảm mạnh xuống tuyến tính O(n), nhưng không gian bộ nhớ vẫn tốn O(n) cho mảng lưu trữ cộng với chiều sâu ngăn xếp đệ quy O(n).\n- Phương pháp 3 - Quy hoạch động lặp (Bottom-up Iterative DP): Khử hoàn toàn đệ quy bằng vòng lặp tính tuần tự từ cơ sở F(0), F(1) tiến dần lên F(n), đạt thời gian O(n) mà không chịu bất kỳ chi phí khung gọi hàm Call Stack nào.\n\n2. Nguyên lý tối ưu hóa không gian bộ nhớ phụ xuống hằng số O(1):\nTheo quan hệ phụ thuộc trạng thái, để xác định giá trị Fibonacci tại bước thứ i hiện tại, ta chỉ cần đúng hai giá trị kề ngay trước nó là bước i - 1 và bước i - 2, còn toàn bộ lịch sử từ bước 0 đến i - 3 không bao giờ dùng lại nữa. Vì vậy, thay vì cấp phát mảng kích thước n, ta chỉ cần duy trì đúng hai biến trượt lưu hai số liền trước và cập nhật cuốn chiếu qua từng vòng lặp, đưa bộ nhớ phụ về O(1) tuyệt đối.", "[\"Phân tích đúng chi phí O(2^n) và điểm nghẽn lặp bài toán con của Đệ quy ngây thơ (3.5đ): Chỉ rõ cây đệ quy nhị phân tính trùng lặp Overlapping Subproblems làm thời gian tăng hàm mũ O(2^n) và tốn O(n) Call Stack.\", \"So sánh chính xác Đệ quy có nhớ (Memoization) với Quy hoạch động lặp (3.5đ): Nêu đúng cả hai cùng đạt thời gian O(n), nhưng Memoization tốn O(n) mảng kèm Call Stack còn Bottom-up khử hoàn toàn đệ quy.\", \"Giải thích cơ chế trượt 2 biến tối ưu không gian phụ xuống O(1) (3.0đ): Lập luận trạng thái thứ i chỉ phụ thuộc đúng 2 trạng thái liền kề trước đó nên chỉ cần giữ 2 biến cuốn chiếu thay cho mảng n phần tử.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 51),
            CreateExamSeed("00000000-0000-0000-0005-000000000223", CourseCsd201Id, "00000000-0000-0000-0000-000000000561", StructureCsd201Id, RubricCsd201Id, "Thiết kế Doubly Linked List với Hai Nút Lính canh (Header/Trailer Sentinels) và Phân tích Bất biến Con trỏ O(1)", "Tại sao trong thiết kế cấu trúc dữ liệu chuẩn công nghiệp (như giáo trình Goodrich & Tamassia), Danh sách liên kết đôi (Doubly Linked List) thường đặt cố định hai nút lính canh giả (Header ở đầu và Trailer ở cuối) không mang dữ liệu nghiệp vụ? Hãy phân tích bất biến cấu trúc mà hai nút lính canh này thiết lập, cách hợp nhất mọi thao tác chèn đầu, chèn cuối về cùng một cơ chế chèn giữa hai nút đã biết và cách xóa nút bất kỳ trong thời gian O(1) mà không cần rẽ nhánh kiểm tra danh sách rỗng.", "1. Vai trò của hai nút lính canh (`Header` & `Trailer` Sentinels) và Bất biến cấu trúc:\nTrong danh sách liên kết đôi không dùng lính canh, mỗi thao tác thêm hoặc xóa đều phải kiểm tra nhiều trường hợp biên rườm rà và dễ phát sinh lỗi `NullPointerException`: danh sách đang rỗng hoàn toàn, thao tác rơi đúng vào nút đầu tiên hay rơi đúng vào nút cuối cùng. Khi bố trí cố định nút giả `Header` chặn ở đầu và nút giả `Trailer` chặn ở cuối (khi danh sách rỗng thì `Header.next` trỏ thẳng sang `Trailer` và `Trailer.prev` trỏ ngược về `Header`), hệ thống thiết lập được một bất biến cấu trúc tuyệt đối: mọi nút chứa dữ liệu thật trong danh sách luôn luôn nằm kẹp nghiêm ngặt ở giữa hai nút láng giềng có thật khác null (nút đứng liền trước `predecessor` và nút đứng liền sau `successor`), đồng thời bản thân hai tham chiếu `Header`, `Trailer` không bao giờ bị thay đổi.\n\n2. Hợp nhất thao tác chèn và xóa trong thời gian hằng số O(1):\n- Cơ chế chèn tổng quát giữa hai nút (`addBetween`): Để chèn phần tử mới vào giữa `predecessor` và `successor`, ta chỉ cần tạo nút mới nối hai chiều tới hai nút đó, rồi cập nhật `predecessor.next` và `successor.prev` trỏ về nút mới. Khi đó, chèn vào đầu danh sách (`addFirst`) đơn giản là chèn vào giữa `Header` và `Header.next`; chèn vào cuối danh sách (`addLast`) đơn giản là chèn vào giữa `Trailer.prev` và `Trailer` mà không cần bất kỳ câu lệnh kiểm tra rỗng nào.\n- Cơ chế xóa nút (`remove`) trong O(1): Để xóa một nút dữ liệu bất kỳ, ta chỉ cần bắc cầu trực tiếp cho nút đứng trước trỏ qua nút đứng sau và nút đứng sau trỏ ngược về nút đứng trước, sau đó xóa trắng các tham chiếu của nút bị gỡ để bộ thu gom rác (Garbage Collector) giải phóng bộ nhớ an toàn.", "[\"Phân tích vai trò của 2 nút lính canh Header/Trailer và bất biến cấu trúc (3.5đ): Giải thích rõ liên kết trạng thái rỗng giữa Header với Trailer và bất biến mọi nút dữ liệu thật luôn có hai nút lân cận khác null.\", \"Giải thích cơ chế hợp nhất addFirst và addLast qua thao tác chèn giữa hai nút (3.5đ): Trình bày rõ 4 mối nối con trỏ khi chèn giữa predecessor - successor và cách quy addFirst, addLast về cùng một cơ chế không cần rẽ nhánh biên.\", \"Trình bày cơ chế xóa nút O(1) và dọn dẹp tham chiếu hỗ trợ thu gom rác (3.0đ): Nêu đúng phép nối bắc cầu hai chiều bỏ qua nút cần xóa trong O(1) kèm việc ngắt tham chiếu trên nút bị xóa hỗ trợ Garbage Collector.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 52),
            CreateExamSeed("00000000-0000-0000-0005-000000000224", CourseCsd201Id, "00000000-0000-0000-0000-000000000564", StructureCsd201Id, RubricCsd201Id, "Phân tích Bất đối xứng Tái cân bằng trên Cây AVL: Phép Chèn (O(1) Phép Quay) vs Phép Xóa (O(log n) Phép Quay)", "Trên Cây tìm kiếm nhị phân tự cân bằng AVL, tại sao sau khi chèn (insert) một khóa mới gây mất cân bằng, ta chỉ cần thực hiện tối đa 1 phép quay (đơn hoặc kép) tại nút mất cân bằng thấp nhất là khôi phục được độ cân bằng của toàn bộ cây, trong khi sau khi xóa (delete) một nút, quá trình tái cân bằng lại có thể lan truyền ngược lên tới tận nút gốc và đòi hỏi tới O(log n) phép quay?", "1. Phân tích sự bất đối xứng về số lượng phép quay giữa Phép Chèn và Phép Xóa trên Cây AVL:\n- Đối với Phép Chèn (tối đa O(1) phép quay): Giả sử trước khi chèn, cây con tại nút mất cân bằng thấp nhất z có chiều cao là h. Việc thêm lá mới làm một nhánh dưới z cao thêm 1 mức, đẩy chiều cao tạm thời của cây con gốc z lên h + 1 và làm độ lệch chạm mức 2. Ngay khi ta thực hiện đúng 1 phép quay đơn (LL hoặc RR) hoặc 1 phép quay kép (LR hoặc RL) tại z, chiều cao của cây con tại vị trí này giảm đi 1 đơn vị, tức quay trở về đúng bằng h như trước lúc chèn. Vì chiều cao nhìn từ bên ngoài không hề thay đổi, hệ số cân bằng của mọi nút tổ tiên phía trên z được giữ nguyên 100% và quá trình sửa cân bằng kết thúc ngay lập tức.\n- Đối với Phép Xóa (có thể lan truyền O(log n) phép quay): Trước khi xóa, giả sử cây con gốc z có chiều cao h; thao tác xóa làm nhánh thấp hơn của z bị hụt thêm 1 mức gây mất cân bằng tại z. Khi thực hiện phép quay khôi phục cân bằng cục bộ tại z, chiều cao của cây con mới tại vị trí đó có thể bị thu ngắn từ h xuống còn h - 1. Sự sụt giảm chiều cao này tiếp tục làm biến đổi hệ số cân bằng của nút cha của z, có thể kích hoạt mất cân bằng dây chuyền ngược lên từng tầng cho tới tận nút gốc với tối đa O(log n) phép quay.\n\n2. Quy tắc chọn phép quay khi xóa nút (giả sử z lệch trái, gọi y là con trái cao hơn của z):\nNếu nhánh con y lệch cùng phía hoặc cân bằng hoàn toàn (hệ số cân bằng của y lớn hơn hoặc bằng 0), ta áp dụng phép quay đơn phải quanh z; riêng trường hợp hệ số cân bằng của y bằng 0 (chỉ xảy ra khi xóa) thì sau quay đơn chiều cao cây con vẫn giữ nguyên là h nên dừng lan truyền. Ngược lại nếu y lệch ngược phía (hệ số cân bằng bằng -1), ta bắt buộc dùng phép quay kép Trái - Phải và tiếp tục kiểm tra lên nút cha.", "[\"Chứng minh Phép Chèn trên AVL chỉ cần tối đa 1 phép quay O(1) (4.0đ): Phân tích rõ sau phép quay tại nút mất cân bằng thấp nhất z, chiều cao cây con trở về đúng mức h ban đầu nên không ảnh hưởng tổ tiên.\", \"Chứng minh Phép Xóa trên AVL có thể lan truyền O(log n) phép quay (3.5đ): Giải thích rõ phép quay sau khi xóa có thể làm chiều cao cây con sụt từ h xuống h - 1, kéo theo mất cân bằng dây chuyền lên nút gốc.\", \"Đặc tả quy tắc chọn phép quay đơn hoặc kép khi xóa (kể cả ca BF(y) bằng 0) (2.5đ): Nêu đúng cách xét dấu hệ số cân bằng của nút con cao hơn y và chỉ ra trường hợp BF(y) bằng 0 dùng quay đơn giữ nguyên chiều cao.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 53),
            CreateExamSeed("00000000-0000-0000-0005-000000000225", CourseCsd201Id, "00000000-0000-0000-0000-000000000566", StructureCsd201Id, RubricCsd201Id, "Phân tích Trường hợp Xấu nhất O(n^2) của QuickSort và Tối ưu Hóa Công nghiệp", "Kịch bản dữ liệu đầu vào nào sẽ khiến thuật toán QuickSort kinh điển (luôn chọn phần tử đầu hoặc phần tử cuối làm chốt Pivot) bị suy thoái hiệu năng về O(n^2)? Hãy phân tích cơ chế làm cây đệ quy bị lệch và trình bày 3 kỹ thuật tối ưu hóa được áp dụng trong các thư viện chuẩn công nghiệp (như Java JDK) để triệt tiêu rủi ro này.", "1. Kịch bản đầu vào gây suy thoái và cơ chế lệch cây đệ quy O(n^2):\nKhi QuickSort cố định chọn phần tử đầu mảng hoặc cuối mảng làm Pivot (hoặc dùng phân hoạch hai vùng thông thường trên mảng toàn phần tử trùng nhau), thuật toán sẽ rơi vào trường hợp xấu nhất khi mảng đầu vào đã được sắp xếp tăng dần sẵn, sắp xếp giảm dần ngược hoàn toàn, hoặc tất cả phần tử có giá trị bằng nhau. Lúc này, Pivot được chọn ở mỗi bước luôn là cực trị nhỏ nhất hoặc lớn nhất của đoạn đang xét, khiến phép phân hoạch chia mảng cực kỳ mất cân đối thành một đoạn rỗng 0 phần tử và một đoạn chứa n - 1 phần tử còn lại. Cây đệ quy bị thoái hóa thành chuỗi tuyến tính sâu n tầng; tổng số phép so sánh cộng dồn từ n - 1 xuống 1 bằng n*(n - 1)/2 tức O(n^2), đồng thời Call Stack phình lên O(n) dễ gây tràn ngăn xếp.\n\n2. Ba kỹ thuật tối ưu hóa trong thư viện công nghiệp:\n- Chọn chốt Trung vị của ba phần tử (Median-of-Three) hoặc chọn Pivot ngẫu nhiên: Lấy giá trị trung vị giữa phần tử đầu, giữa và cuối mảng làm Pivot giúp loại bỏ hoàn toàn bẫy suy thoái trên dữ liệu đã có thứ tự tăng hoặc giảm.\n- Phân hoạch ba vùng hoặc Hai chốt (3-Way Partitioning / Dual-Pivot QuickSort của Java JDK): Gom riêng các phần tử bằng Pivot vào vùng giữa không gọi đệ quy lại giúp xử lý mảng nhiều khóa trùng trong O(n), đồng thời chia 3 đoạn bằng 2 chốt giúp tối ưu hóa số lần đọc bộ nhớ đệm CPU Cache.\n- Ngắt sang Insertion Sort trên đoạn con nhỏ: Khi kích thước mảng con giảm xuống dưới ngưỡng nhỏ (khoảng 16 đến 47 phần tử), chuyển sang Insertion Sort để triệt tiêu chi phí gọi hàm đệ quy.", "[\"Xác định đúng các kịch bản dữ liệu gây suy thoái (3.0đ): Chỉ ra mảng đã sắp xếp tăng dần, giảm dần hoặc toàn phần tử bằng nhau khi chọn Pivot cố định ở đầu hoặc cuối.\", \"Phân tích cơ chế phân hoạch lệch 0 vs n-1 và cây đệ quy sâu n tầng (3.5đ): Chứng minh tổng số phép so sánh cộng dồn cấp số cộng lên O(n^2) và nguy cơ tràn Call Stack O(n).\", \"Trình bày thuyết phục 3 kỹ thuật tối ưu hóa công nghiệp (3.5đ): Mô tả rõ Median-of-Three (hoặc ngẫu nhiên hóa), phân hoạch 3 vùng / Dual-Pivot xử lý khóa trùng và chuyển sang Insertion Sort trên mảng nhỏ.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 54),
            CreateExamSeed("00000000-0000-0000-0005-000000000226", CourseCsd201Id, "00000000-0000-0000-0000-000000000568", StructureCsd201Id, RubricCsd201Id, "Phân tích Mảng Tiền tố - Hậu tố (LPS) trong Thuật toán KMP và Chứng minh Tuyến tính O(n + m)", "Trong thuật toán đối sánh chuỗi Knuth-Morris-Pratt (KMP), mảng tiền tố thất bại (còn gọi là mảng LPS — Longest Proper Prefix which is also Suffix) lưu trữ thông tin gì tại mỗi vị trí của chuỗi mẫu P (hãy minh họa ngắn gọn ý nghĩa trên mẫu ngắn như ABAB)? Giải thích cơ chế KMP tận dụng mảng LPS khi xảy ra lệch ký tự và chứng minh vì sao con trỏ duyệt trên văn bản chính T không bao giờ phải lùi lại, giúp thuật toán đạt độ phức tạp thời gian tuyến tính O(n + m).", "1. Bản chất thông tin lưu trong mảng LPS (Failure Function):\nTại mỗi chỉ số k của chuỗi mẫu P độ dài m, phần tử `LPS[k]` lưu độ dài của tiền tố thực sự dài nhất của chuỗi con `P[0..k]` (không tính toàn bộ chuỗi con đó) mà đồng thời trùng khớp chính xác với hậu tố kết thúc tại vị trí k của nó. Chẳng hạn với mẫu ngắn `\"ABAB\"`: tại ký tự đầu `'A'` giá trị bằng 0; tại `\"AB\"` bằng 0; tại `\"ABA\"` có tiền tố `'A'` trùng hậu tố `'A'` nên bằng 1; tại `\"ABAB\"` có tiền tố `\"AB\"` trùng hậu tố `\"AB\"` nên bằng 2.\n\n2. Cơ chế trượt mẫu không lùi con trỏ văn bản và chứng minh độ phức tạp O(n + m):\n- Giả sử thuật toán đã khớp thành công j ký tự đầu của mẫu P nhưng bị lệch tại ký tự `P[j]` với ký tự văn bản `T[i]`. Thay vì lùi con trỏ văn bản `i` quay ngược lại như thuật toán vét cạn, KMP biết rằng đoạn hậu tố ngay trước điểm lệch trên văn bản vừa khớp với `P[0..j-1]`, nên đoạn hậu tố dài `LPS[j - 1]` của nó chính là tiền tố đầu mẫu P đã khớp sẵn! Do đó, KMP giữ nguyên con trỏ văn bản `i` đứng yên và chỉ dịch con trỏ mẫu `j` lùi về `LPS[j - 1]` để so sánh tiếp ngay mà không cần đọc lại bất kỳ ký tự nào trên văn bản T.\n- Về độ phức tạp: bước tiền xử lý tự đối sánh mẫu P với chính nó để tính mảng LPS tốn O(m). Trong pha tìm kiếm trên văn bản độ dài n, con trỏ `i` chỉ tiến đơn điệu từ 0 đến n (tối đa n lần tăng); mỗi lần con trỏ `j` tăng tối đa 1 đơn vị khi `i` tăng, nên tổng số lần `j` bị giảm qua bảng LPS trong suốt toàn bộ quá trình tìm kiếm cũng không thể vượt quá n lần. Cộng hai giai đoạn, tổng số phép so sánh bị chặn chặt bởi O(n + m).", "[\"Định nghĩa chuẩn xác ý nghĩa mảng LPS và minh họa trên mẫu ngắn (3.5đ): Giải thích rõ khái niệm độ dài tiền tố thực sự dài nhất đồng thời là hậu tố của đoạn mẫu và minh họa đúng trên ví dụ như ABAB.\", \"Giải thích cơ chế nhảy con trỏ mẫu qua LPS mà không lùi con trỏ văn bản (3.5đ): Làm rõ cách tận dụng phần hậu tố đã khớp trùng tiền tố mẫu để dịch j về LPS[j - 1] trong khi giữ con trỏ văn bản i không bao giờ lùi.\", \"Chứng minh chặt chẽ độ phức tạp tuyến tính O(n + m) bằng phân tích khấu hao (3.0đ): Lập luận số lần giảm j bị chặn bởi tổng số lần tăng j (tối đa n lần theo bước tiến đơn điệu của i), cộng pha dựng LPS O(m) đạt O(n + m).\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 55),
            // =========================================================================
            // 3. DBI202 — 26 CÂU HỎI KHO THI THẬT (6 Remember, 8 Understand, 7 Apply, 5 Analyze)
            // =========================================================================
            CreateExamSeed("00000000-0000-0000-0006-000000000201", CourseDbi202Id, "00000000-0000-0000-0000-000000000661", StructureDbi202Id, RubricDbi202Id, "Các giai đoạn Tiến hóa của Hệ CSDL và 5 Nhược điểm Cốt lõi của Hệ thống Quản lý Tệp phẳng (CQ1.1)", "Theo nội dung tiến hóa của các hệ cơ sở dữ liệu (Constructive Question CQ1.1), hãy trình bày các giai đoạn phát triển chính từ Hệ thống quản lý tệp truyền thống (File-based Systems) đến Hệ quản trị CSDL quan hệ (RDBMS) và hiện đại. Phân tích 5 nhược điểm nghiêm trọng của việc lưu trữ dữ liệu nghiệp vụ trên các tệp phẳng độc lập khiến doanh nghiệp bắt buộc phải sử dụng DBMS.", "Lịch sử tiến hóa của hệ cơ sở dữ liệu trải qua bốn giai đoạn chính: (1) Hệ thống quản lý tệp phẳng trước thập niên 1960 lưu dữ liệu rời rạc trong các tệp riêng của từng phòng ban; (2) Hệ CSDL Phân cấp và Mạng thập niên 1960-1970 (như IBM IMS, CODASYL) truy xuất nhanh nhưng lập trình viên phải điều hướng con trỏ vật lý cứng nhắc; (3) Hệ quản trị CSDL Quan hệ (RDBMS) do E.F. Codd đề xuất từ năm 1970 trừu tượng hóa dữ liệu thành bảng hai chiều dựa trên lý thuyết tập hợp và ngôn ngữ phi thủ tục SQL, tách rời hoàn toàn mức logic khỏi mức vật lý; (4) Hệ CSDL Quan hệ - Đối tượng, NoSQL và NewSQL từ thập niên 1990 đến nay mở rộng cho dữ liệu bán cấu trúc và phân tán đám mây. Doanh nghiệp buộc phải rời bỏ hệ thống tệp phẳng vì năm nhược điểm cốt lõi: (a) Dư thừa và mất nhất quán dữ liệu khi thông tin bị sao chép ở nhiều tệp gây lệch lạc khi cập nhật; (b) Phụ thuộc chặt giữa chương trình và dữ liệu khiến mỗi lần đổi cấu trúc trường đều phải sửa mã nguồn ứng dụng; (c) Cô lập dữ liệu gây khó khăn khi tổng hợp báo cáo liên phòng ban do thiếu ngôn ngữ truy vấn chuẩn; (d) Vi phạm tính nguyên tố khi sập nguồn giữa giao dịch do không có nhật ký khôi phục tự động; (e) Dị thường tương tranh gây ghi đè mất dữ liệu và không thể phân quyền chi tiết đến từng dòng, cột.", "[\"Trình bày đúng 4 giai đoạn tiến hóa của hệ CSDL (CQ1.1) (3.5đ): Nêu rõ tiến trình từ File-based sang Hierarchical/Network, đến Relational DBMS (E.F. Codd, SQL) và NoSQL/NewSQL.\", \"Phân tích rõ sự dư thừa/bất nhất và phụ thuộc chương trình - dữ liệu (3.5đ): Giải thích cụ thể nguyên nhân gây mâu thuẫn dữ liệu và việc phải sửa code ứng dụng khi đổi cấu trúc tệp phẳng.\", \"Phân tích 3 nhược điểm về Atomicity, Concurrency và Bảo mật/Cô lập dữ liệu (3.0đ): Chỉ rõ rủi ro mất toàn vẹn khi crash giữa chừng, xung đột ghi đè đồng thời và thiếu ngôn ngữ truy vấn chuẩn.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 60),
            CreateExamSeed("00000000-0000-0000-0006-000000000202", CourseDbi202Id, "00000000-0000-0000-0000-000000000662", StructureDbi202Id, RubricDbi202Id, "Bản chất và Nguyên lý Kết hợp của 5 Phép toán Nguyên thủy trong Đại số Quan hệ", "Hãy nêu tên gọi và giải thích bản chất xử lý dữ liệu của 5 phép toán nguyên thủy (Primitive Operations) tạo nên nền tảng của Đại số quan hệ. Phép kết nối tự nhiên (Natural Join) có phải là phép toán nguyên thủy không và vì sao?", "Năm phép toán nguyên thủy tạo nên nền tảng tối thiểu của Đại số quan hệ (không phép nào có thể suy ra từ các phép còn lại) bao gồm: (1) Phép chọn (Selection): lọc theo chiều ngang để giữ lại các dòng thỏa mãn điều kiện logic chỉ định; (2) Phép chiếu (Projection): trích xuất theo chiều dọc một tập con các cột thuộc tính và tự động loại bỏ các bộ trùng lặp; (3) Phép tích Descartes (Cartesian Product): ghép mọi dòng của quan hệ thứ nhất với tất cả các dòng của quan hệ thứ hai, tạo ra quan hệ mới có số cột bằng tổng số cột hai bên; (4) Phép hợp (Union): gộp tất cả các dòng thuộc quan hệ thứ nhất hoặc thuộc quan hệ thứ hai; (5) Phép hiệu tập hợp (Set Difference): giữ lại các dòng thuộc quan hệ thứ nhất nhưng không xuất hiện trong quan hệ thứ hai, trong đó cả Phép hợp và Phép hiệu đều bắt buộc hai quan hệ phải khả hợp (cùng số lượng cột và tương thích miền giá trị từng cặp cột). Phép kết nối tự nhiên (Natural Join) không phải là phép toán nguyên thủy mà là phép toán phái sinh để viết gọn truy vấn, được cấu thành qua ba bước tuần tự: lấy Tích Descartes hai bảng, dùng Phép chọn lọc các dòng có giá trị bằng nhau trên mọi cột trùng tên, rồi dùng Phép chiếu giữ lại một bản duy nhất của các cột chung; tương tự, Phép giao giữa R và S được tính bằng R trừ đi hiệu của R với S.", "[\"Nêu đủ tên gọi của 5 phép toán nguyên thủy trong Đại số quan hệ (4.0đ): Liệt kê chính xác Phép chọn (Selection), Phép chiếu (Projection), Tích Descartes, Phép hợp (Union) và Phép hiệu (Set Difference).\", \"Giải thích bản chất xử lý và điều kiện khả hợp (Union-compatible) (3.5đ): Phân tích rõ cơ chế lọc dòng, trích cột, ghép tích và điều kiện cùng bậc, tương thích miền giá trị đối với phép hợp và phép hiệu.\", \"Lý giải bản chất phái sinh và cách cấu thành Natural Join (2.5đ): Khẳng định Natural Join là phép phái sinh được tổ hợp tuần tự từ Tích Descartes, Phép chọn trên cột chung và Phép chiếu khử cột lặp.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 61),
            CreateExamSeed("00000000-0000-0000-0006-000000000203", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", StructureDbi202Id, RubricDbi202Id, "Hệ tiên đề Armstrong cho Phụ thuộc hàm", "Hệ tiên đề Armstrong trong lý thuyết thiết kế cơ sở dữ liệu là gì? Hãy nêu tên gọi và giải thích bằng lời bản chất của 3 tiên đề cơ bản của Armstrong cùng 2 quy tắc suy dẫn bổ trợ phổ biến. Giải thích ý nghĩa tính Đúng đắn (Soundness) và tính Đầy đủ (Completeness) của hệ tiên đề này.", "Hệ tiên đề Armstrong là bộ quy tắc suy diễn hình thức dùng để tìm ra toàn bộ các phụ thuộc hàm logic được suy dẫn từ một tập phụ thuộc hàm ban đầu. Ba tiên đề cơ bản gồm: (1) Tiên đề Phản xạ (Reflexivity): nếu tập thuộc tính Y là tập con của tập thuộc tính X thì X luôn xác định hàm được Y (phụ thuộc hàm tầm thường); (2) Tiên đề Tăng trưởng (Augmentation): nếu X xác định Y thì khi ghép thêm cùng một tập thuộc tính Z vào cả hai vế, hợp của X và Z sẽ xác định hợp của Y và Z; (3) Tiên đề Bắc cầu (Transitivity): nếu X xác định Y và Y tiếp tục xác định Z thì X xác định được Z. Từ ba tiên đề gốc này, ta suy ra hai quy tắc bổ trợ rất hữu ích là Quy tắc Hợp (Union: nếu X xác định Y và X xác định Z thì X xác định cả hợp của Y và Z, suy ra bằng cách tăng trưởng X vào X xác định Y được X xác định XY, tăng trưởng Y vào X xác định Z được XY xác định YZ, rồi bắc cầu) và Quy tắc Phân rã vế phải (Decomposition: nếu X xác định hợp của Y và Z thì X xác định riêng Y và X xác định riêng Z; lưu ý tuyệt đối cấm phân rã ở vế trái). Hệ tiên đề có tính Đúng đắn vì mọi phụ thuộc hàm suy ra đều đúng trên mọi thể hiện dữ liệu hợp lệ, và có tính Đầy đủ vì mọi phụ thuộc hàm đúng về mặt ngữ nghĩa đều chứng minh được bằng ba tiên đề này.", "[\"Trình bày chính xác 3 tiên đề cơ bản của Armstrong (4.0đ): Nêu đúng tên gọi và giải thích rõ bản chất của Tiên đề Phản xạ, Tiên đề Tăng trưởng và Tiên đề Bắc cầu.\", \"Nêu đúng các quy tắc suy dẫn bổ trợ (3.0đ): Giải thích chính xác Quy tắc Hợp (Union) và Quy tắc Phân rã vế phải (Decomposition).\", \"Giải thích tính Đúng đắn (Sound) và Đầy đủ (Complete) (3.0đ): Làm rõ ý nghĩa không sinh ra phụ thuộc sai (Soundness) và vét cạn được mọi phụ thuộc hàm hợp lệ (Completeness).\"]", QuestionDifficulty.Medium, BloomLevel.Remember, 62),
            CreateExamSeed("00000000-0000-0000-0006-000000000204", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", StructureDbi202Id, RubricDbi202Id, "Định nghĩa Khóa chính, Siêu khóa và Khóa ứng viên trong lý thuyết CSDL", "Trong lý thuyết cơ sở dữ liệu quan hệ, hãy định nghĩa chính xác các khái niệm: Siêu khóa (Superkey), Khóa ứng viên (Candidate Key) và Khóa chính (Primary Key). Mối quan hệ tập hợp giữa 3 khái niệm này là gì?", "Trên một lược đồ quan hệ R: (1) Siêu khóa (Superkey) là một tập hợp gồm một hoặc nhiều thuộc tính sao cho bao đóng của nó bao phủ toàn bộ các thuộc tính của lược đồ R; giá trị của siêu khóa bảo đảm phân biệt duy nhất mọi bản ghi trong bảng, không thể tồn tại hai dòng khác nhau mang cùng bộ giá trị trên siêu khóa. (2) Khóa ứng viên (Candidate Key) là một Siêu khóa tối tiểu (Minimal Superkey), nghĩa là bản thân nó là một siêu khóa nhưng không chứa bất kỳ tập con thực sự nào bên trong nó cũng có khả năng làm siêu khóa; chỉ cần loại bỏ bớt dù chỉ một thuộc tính ra khỏi khóa ứng viên thì tập còn lại sẽ lập tức mất tính định danh duy nhất. Một bảng có thể đồng thời tồn tại nhiều khóa ứng viên khác nhau (chẳng hạn bảng Sinh viên có Mã sinh viên, Số căn cước công dân và Email trường cấp đều là các khóa ứng viên). (3) Khóa chính (Primary Key) là duy nhất một Khóa ứng viên được người thiết kế lựa chọn chính thức để định danh các bộ dữ liệu và làm đích tham chiếu cho khóa ngoại, bắt buộc duy nhất và cấm tuyệt đối giá trị NULL. Xét về quan hệ bao hàm tập hợp, Khóa chính là một phần tử được chọn từ tập các Khóa ứng viên, còn tập tất cả các Khóa ứng viên là một tập con nằm trong tập hợp các Siêu khóa.", "[\"Định nghĩa Siêu khóa (Superkey) (3.0đ): Nêu đúng tính chất bao đóng phủ toàn bộ các thuộc tính của lược đồ và khả năng định danh duy nhất bản ghi.\", \"Định nghĩa Khóa ứng viên (Candidate Key) (3.5đ): Khẳng định bản chất siêu khóa tối tiểu, không có bất kỳ tập con thực sự nào bên trong nó cũng là siêu khóa.\", \"Định nghĩa Khóa chính & Mối quan hệ bao hàm (3.5đ): Nêu đúng Khóa chính là một Khóa ứng viên được chọn (cấm NULL) và chỉ rõ quan hệ tập Khóa ứng viên là tập con của tập Siêu khóa.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 63),
            CreateExamSeed("00000000-0000-0000-0006-000000000205", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", StructureDbi202Id, RubricDbi202Id, "Danh mục Ràng buộc Toàn vẹn Dữ liệu chuẩn trong SQL DDL", "Hãy liệt kê 6 ràng buộc toàn vẹn dữ liệu (Constraints) được hỗ trợ chuẩn trong ngôn ngữ định nghĩa dữ liệu SQL DDL và nêu mục đích nghiệp vụ của từng ràng buộc. Phân tích cách phối hợp đồng thời các ràng buộc này trên một bảng thực tế (ví dụ bảng Nhân viên hoặc bảng Đơn hàng) để bảo vệ toàn vẹn dữ liệu ngay tại tầng cơ sở dữ liệu.", "Sáu ràng buộc toàn vẹn chuẩn trong SQL DDL bao gồm: (1) NOT NULL bắt buộc cột luôn phải có giá trị xác định, cấm để trống; (2) UNIQUE bảo đảm các giá trị trên cột hoặc tổ hợp cột không bị trùng lặp giữa các dòng (lưu ý đặc thù trong MS SQL Server, ràng buộc UNIQUE truyền thống chỉ cho phép tối đa một dòng mang giá trị NULL, muốn cho phép nhiều NULL thì dùng Filtered Unique Index lọc điều kiện IS NOT NULL); (3) PRIMARY KEY định danh duy nhất mỗi bản ghi trong bảng, kết hợp ngầm định cả tính duy nhất và cấm NULL; (4) FOREIGN KEY bảo vệ toàn vẹn tham chiếu, bắt buộc giá trị cột khóa ngoại phải khớp với một khóa hiện có ở bảng cha hoặc mang giá trị NULL; (5) CHECK kiểm soát miền giá trị hợp lệ thông qua biểu thức điều kiện logic trên dòng; (6) DEFAULT tự động điền giá trị mặc định khi thao tác thêm mới không truyền dữ liệu cho cột đó. Minh họa phối hợp trên bảng Nhân viên: cột Mã nhân viên đặt làm PRIMARY KEY; cột Số căn cước công dân gắn đồng thời NOT NULL và UNIQUE; cột Lương cơ bản gắn CHECK bắt buộc lớn hơn 0; cột Mã phòng ban gắn FOREIGN KEY tham chiếu về bảng Phòng ban; và cột Trạng thái làm việc gắn DEFAULT mặc định là đang hoạt động, tạo thành chốt chặn bảo vệ dữ liệu độc lập hoàn toàn với lỗi tầng ứng dụng.", "[\"Liệt kê và nêu đúng mục đích 6 ràng buộc toàn vẹn chuẩn (4.0đ): Nêu đầy đủ và giải thích đúng vai trò của NOT NULL, UNIQUE, PRIMARY KEY, FOREIGN KEY, CHECK và DEFAULT.\", \"Phân tích phối hợp các ràng buộc trên bảng thực tế (3.5đ): Trình bày hợp lý cách gắn kết đồng thời ít nhất 4 ràng buộc trên các cột nghiệp vụ của bảng Nhân viên hoặc Đơn hàng.\", \"Giải thích ý nghĩa bảo vệ toàn vẹn dữ liệu tại tầng CSDL (2.5đ): Làm rõ vai trò của từng ràng buộc trong ví dụ thực tế nhằm ngăn chặn dữ liệu rác ngay tại động cơ lưu trữ.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 64),
            CreateExamSeed("00000000-0000-0000-0006-000000000206", CourseDbi202Id, "00000000-0000-0000-0000-000000000666", StructureDbi202Id, RubricDbi202Id, "Định nghĩa và Phân loại 2 dạng DML Triggers chính trong MS SQL Server", "Trigger trong hệ quản trị cơ sở dữ liệu là gì? Trong MS SQL Server, DML Triggers được phân thành 2 dạng chính nào? Nêu sự khác nhau cơ bản về thời điểm thực thi giữa hai loại trigger này đối với thao tác DML.", "Trigger là một dạng thủ tục lưu trữ đặc biệt (Special Stored Procedure) được lưu trong CSDL và tự động thực thi (kích hoạt) khi xảy ra một sự kiện xác định (sự kiện DML: INSERT, UPDATE, DELETE; hoặc sự kiện DDL: CREATE, ALTER, DROP). Trong MS SQL Server, DML Trigger được chia thành 2 loại chính: (1) AFTER Trigger (còn gọi là FOR Trigger): Được kích hoạt và thực thi SAU KHI câu lệnh DML gốc đã thực hiện xong các thao tác ghi dữ liệu vào bảng tạm và vượt qua toàn bộ các ràng buộc toàn vẹn cơ bản (Constraints). Nếu trong AFTER Trigger phát hiện vi phạm nghiệp vụ, lập trình viên phải gọi lệnh ROLLBACK TRANSACTION để hủy bỏ thay đổi. AFTER Trigger chỉ có thể được gắn trên Bảng vật lý (Tables), không gắn được trên Views chuẩn. (2) INSTEAD OF Trigger: Được kích hoạt THAY THẾ HOÀN TOÀN cho câu lệnh DML gốc; câu lệnh DML kích hoạt sẽ không thực thi trên bảng cơ sở mà nhường toàn bộ quyền điều khiển cho thân mã của trigger. INSTEAD OF Trigger có thể được gắn trên cả Bảng vật lý và Khung nhìn (Views), chuyên dùng để hỗ trợ cập nhật dữ liệu qua các View phức tạp.", "[\"Định nghĩa chính xác Trigger (3.0đ): Nêu đúng Trigger là thủ tục tự động kích hoạt bởi sự kiện CSDL (DML/DDL).\", \"Phân loại và cơ chế của AFTER Trigger (3.5đ): Giải thích rõ AFTER Trigger chạy sau DML và constraint, chỉ gắn trên bảng vật lý.\", \"Phân loại và cơ chế của INSTEAD OF Trigger (3.5đ): Giải thích rõ INSTEAD OF thay thế DML gốc, gắn được trên cả View và Bảng.\"]", QuestionDifficulty.Easy, BloomLevel.Remember, 65),
            CreateExamSeed("00000000-0000-0000-0006-000000000207", CourseDbi202Id, "00000000-0000-0000-0000-000000000664", StructureDbi202Id, RubricDbi202Id, "Cơ chế ánh xạ mối kết hợp Một - Một (1:1) từ ERD sang Lược đồ quan hệ", "Khi chuyển đổi một mối kết hợp Một - Một (1:1) từ sơ đồ ERD sang mô hình cơ sở dữ liệu quan hệ, chúng ta có những phương án thiết kế nào? Việc lựa chọn phương án phụ thuộc vào ràng buộc tham gia (Total / Partial Participation) của các thực thể như thế nào?", "Khi ánh xạ mối kết hợp 1:1 giữa thực thể A và B, có 3 phương án thiết kế: (Phương án 1 - Gộp thành 1 bảng duy nhất): Tạo một bảng duy nhất chứa toàn bộ thuộc tính của A và B. Phương án này tối ưu nhất khi CẢ HAI BÊN ĐỀU CÓ RÀNG BUỘC THAM GIA TOÀN PHẦN (Total - Total Participation); giúp loại bỏ hoàn toàn phép JOIN và không sinh ra giá trị NULL dư thừa. (Phương án 2 - Giữ 2 bảng, đưa Khóa ngoại sang một bên kèm ràng buộc UNIQUE): Đưa khóa chính của bảng này sang làm khóa ngoại của bảng kia, và BẮT BUỘC gán ràng buộc UNIQUE trên cột khóa ngoại đó để bảo đảm tỷ số 1:1. Nguyên tắc vàng: Nên đưa khóa ngoại sang phía thực thể có Ràng buộc tham gia Toàn phần (Total Participation) để cột khóa ngoại đó có thể đặt thêm ràng buộc NOT NULL, tránh triệt để việc xuất hiện các giá trị NULL dư thừa. (Phương án 3 - Dùng bảng trung gian): Tạo bảng thứ 3 lưu cặp khóa; phương án này chỉ nên dùng khi cả hai bên đều tham gia một phần (Partial - Partial) và tần suất liên kết rất hiếm, nhằm bảo vệ cả 2 bảng gốc không bị rác giá trị NULL.", "[\"Phương án gộp bảng (Merged Table) (3.0đ): Giải thích rõ việc gộp bảng tối ưu khi cả hai bên cùng tham gia toàn phần (Total-Total).\", \"Phương án Khóa ngoại kèm ràng buộc UNIQUE (4.0đ): Phân tích quy tắc đặt khóa ngoại về bên Total Participation để áp dụng NOT NULL.\", \"Phương án Bảng trung gian & Tối ưu hóa NULL (3.0đ): Chỉ ra trường hợp Partial-Partial dùng bảng riêng để tránh lãng phí bộ nhớ lưu NULL.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 66),
            CreateExamSeed("00000000-0000-0000-0006-000000000208", CourseDbi202Id, "00000000-0000-0000-0000-000000000662", StructureDbi202Id, RubricDbi202Id, "Biểu diễn Ràng buộc Toàn vẹn trên Lược đồ Quan hệ bằng Đại số Quan hệ (CQ3.2 & CQ3.3)", "Trong lý thuyết Mô hình Quan hệ (Constructive Questions CQ3.2 và CQ3.3), mọi ràng buộc toàn vẹn dữ liệu đều có thể được đặc tả dựa trên hai nguyên lý tương đương trong Đại số quan hệ là điều kiện Tập hợp vi phạm bằng rỗng và quan hệ Bao hàm tập hợp. Hãy giải thích bản chất tương đương của hai nguyên lý này, sau đó trình bày bằng lời cách vận dụng các phép toán Đại số quan hệ để kiểm tra: (1) Ràng buộc khóa ngoại từ cột Mã phòng ban của bảng Nhân viên tham chiếu sang cột Mã phòng ban của bảng Phòng ban, và (2) Ràng buộc miền giá trị bắt buộc Lương của mọi nhân viên phải từ 500 trở lên.", "Trong Đại số quan hệ, hai nguyên lý đặc tả ràng buộc toàn vẹn hoàn toàn tương đương nhau về mặt tập hợp: (1) Nguyên lý Tập hợp vi phạm bằng rỗng xây dựng một chuỗi phép toán để lọc ra tất cả các dòng dữ liệu làm trái quy tắc nghiệp vụ, rồi đặt điều kiện tập kết quả đó phải là tập rỗng (không tồn tại dòng vi phạm nào); (2) Nguyên lý Bao hàm tập hợp yêu cầu tập kết quả truy xuất ở vế thứ nhất phải là tập con nằm trọn trong tập hợp các giá trị hợp lệ ở vế thứ hai. Hai dạng này tương đương chặt chẽ vì tập A là tập con của tập B khi và chỉ khi phép hiệu tập hợp lấy A trừ đi B cho kết quả bằng tập rỗng. Vận dụng cho bài toán thứ nhất về Ràng buộc khóa ngoại giữa bảng Nhân viên và bảng Phòng ban: theo hướng bao hàm tập hợp, ta dùng Phép chiếu lấy cột Mã phòng ban khác NULL từ bảng Nhân viên và yêu cầu nó phải là tập con của Phép chiếu cột Mã phòng ban từ bảng Phòng ban; hoặc theo hướng tập rỗng, lấy hiệu tập hợp của Mã phòng ban bên Nhân viên trừ đi Mã phòng ban bên Phòng ban bắt buộc phải bằng rỗng. Với bài toán thứ hai về Ràng buộc miền giá trị lương: theo hướng tập rỗng, ta dùng Phép chọn lọc trên bảng Nhân viên với điều kiện Lương nhỏ hơn 500 và yêu cầu tập kết quả phải bằng rỗng; hoặc theo hướng bao hàm, toàn bộ bảng Nhân viên phải là tập con của Phép chọn những nhân viên có Lương lớn hơn hoặc bằng 500.", "[\"Giải thích bản chất tương đương giữa Bao hàm tập hợp và Hiệu tập hợp bằng rỗng (3.0đ): Phân tích rõ hai hướng tiếp cận kiểm tra ràng buộc và lý giải tập A là tập con của B tương đương A trừ B bằng tập rỗng.\", \"Trình bày đúng cách kiểm tra Ràng buộc Khóa ngoại bằng Phép chiếu và Phép hiệu (3.5đ): Giải thích rõ việc chiếu cột Mã phòng ban ở hai bảng rồi kiểm tra quan hệ tập con hoặc lấy phép hiệu bằng tập rỗng.\", \"Trình bày đúng cách kiểm tra Ràng buộc Miền giá trị bằng Phép chọn (3.5đ): Giải thích rõ việc dùng Phép chọn lọc các bản ghi có Lương nhỏ hơn 500 yêu cầu bằng tập rỗng và dạng bao hàm tương đương.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 67),
            CreateExamSeed("00000000-0000-0000-0006-000000000209", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", StructureDbi202Id, RubricDbi202Id, "Khái niệm Phủ tối tiểu (Minimal Cover / Canonical Cover) và Quy trình 3 Bước Thu gọn Tập Phụ thuộc Hàm", "Trong lý thuyết thiết kế cơ sở dữ liệu quan hệ, khi nào hai tập phụ thuộc hàm được gọi là tương đương nhau, và một tập phụ thuộc hàm cần thỏa mãn đồng thời 3 điều kiện chuẩn mực nào để trở thành Phủ tối tiểu (Minimal Cover / Canonical Cover)? Tại sao việc tìm Phủ tối tiểu luôn là bước khởi đầu bắt buộc trong Thuật toán tổng hợp chuẩn 3NF của Bernstein?", "Hai tập phụ thuộc hàm F và G trên cùng một lược đồ được gọi là tương đương nhau khi bao đóng phụ thuộc hàm của chúng hoàn toàn trùng khớp, nghĩa là mọi phụ thuộc hàm suy dẫn được từ F đều suy dẫn được từ G và ngược lại. Một tập phụ thuộc hàm tương đương với F được gọi là Phủ tối tiểu khi thỏa mãn đồng thời ba điều kiện: (1) Vế phải đơn thuộc tính: mọi phụ thuộc hàm trong tập chỉ chứa đúng một thuộc tính duy nhất ở vế phải (tách bằng quy tắc phân rã); (2) Không có thuộc tính dư thừa ở vế trái: đối với mọi phụ thuộc hàm có vế trái gồm nhiều thuộc tính, không thể bỏ bớt bất kỳ thuộc tính nào ở vế trái mà tập phụ thuộc hàm vẫn giữ nguyên tính tương đương; (3) Không có phụ thuộc hàm dư thừa: không thể xóa bỏ bất kỳ phụ thuộc hàm nào khỏi tập mà bao đóng các phụ thuộc còn lại vẫn suy dẫn lại được phụ thuộc vừa xóa. Trong quy trình 3 bước, việc rút gọn vế trái bắt buộc làm trước vì sau khi lược bỏ thuộc tính thừa ở vế trái, hai phụ thuộc hàm vốn nhìn khác nhau có thể biến thành trùng nhau hoặc bắc cầu dư thừa để bước 3 dọn sạch. Phủ tối tiểu là bước mở đầu sống còn của thuật toán tổng hợp 3NF vì nếu vế trái còn thừa thuộc tính thì bảng con sinh ra sẽ vi phạm ngay chuẩn 2NF, còn nếu còn phụ thuộc bắc cầu dư thừa thì thuật toán sẽ đẻ thêm bảng phụ không cần thiết.", "[\"Định nghĩa đúng hai tập phụ thuộc hàm tương đương (2.5đ): Nêu rõ khái niệm bao đóng tập phụ thuộc hàm bằng nhau và khả năng suy dẫn hai chiều giữa hai tập F và G.\", \"Trình bày chính xác 3 điều kiện của Phủ tối tiểu (4.5đ): Nêu đủ: vế phải đơn thuộc tính, vế trái không chứa thuộc tính dư thừa và tập không chứa phụ thuộc hàm dư thừa.\", \"Giải thích vai trò của Phủ tối tiểu trong tổng hợp 3NF và thứ tự rút gọn (3.0đ): Chỉ rõ rút gọn vế trái trước giúp lộ diện phụ thuộc thừa, ngăn ngừa sinh bảng con vi phạm 2NF hoặc bảng dư thừa.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 68),
            CreateExamSeed("00000000-0000-0000-0006-000000000210", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", StructureDbi202Id, RubricDbi202Id, "Thứ tự Thực thi Logic của các mệnh đề trong Câu truy vấn SQL", "Trình bày thứ tự thực thi logic đầy đủ gồm 6 giai đoạn chính của một câu truy vấn SQL chuẩn (FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY). Dựa vào thứ tự này, hãy giải thích tại sao ta không thể dùng bí danh cột (Alias) đặt ở SELECT trong mệnh đề WHERE, nhưng lại CÓ THỂ dùng bí danh đó trong mệnh đề ORDER BY?", "Khác với thứ tự viết câu lệnh bắt đầu bằng từ khóa SELECT, trình tự thực thi logic chuẩn bên trong bộ xử lý truy vấn của SQL Server diễn ra qua 6 giai đoạn tuần tự: (1) FROM và JOIN xác định các bảng nguồn và kết nối tạo tập dữ liệu đầu vào; (2) WHERE đánh giá điều kiện lọc trên từng dòng đơn lẻ để loại bỏ dòng không hợp lệ; (3) GROUP BY gom các dòng vượt qua bước lọc thành từng nhóm theo cột chỉ định; (4) HAVING lọc giữ lại các nhóm thỏa mãn điều kiện hàm tổng hợp; (5) SELECT tính toán các biểu thức, hàm cửa sổ OVER, gán bí danh cột (Alias) và khử trùng lặp DISTINCT; (6) ORDER BY sắp xếp tập kết quả cuối cùng (kèm TOP hoặc OFFSET - FETCH nếu có). Từ trình tự trên, mệnh đề WHERE thực thi ở giai đoạn 2, tức xảy ra trước giai đoạn 5 của SELECT nên tại thời điểm WHERE kiểm tra điều kiện thì bí danh cột hoàn toàn chưa được khởi tạo trong ngữ cảnh, dẫn tới lỗi không nhận diện được tên cột (muốn lọc theo bí danh hoặc hàm cửa sổ, ta phải bọc truy vấn vào CTE hoặc bảng dẫn xuất Derived Table). Ngược lại, mệnh đề ORDER BY chạy ở giai đoạn 6 sau khi SELECT đã hoàn tất việc gắn nhãn cột nên sử dụng được mọi bí danh của SELECT.", "[\"Trình bày chính xác thứ tự thực thi 6 giai đoạn (4.0đ): Nêu đúng trình tự tuần tự từ FROM/JOIN, WHERE, GROUP BY, HAVING, SELECT đến ORDER BY.\", \"Giải thích lý do WHERE không dùng được Alias (3.0đ): Lập luận chính xác do WHERE chạy ở bước 2 trước khi SELECT định nghĩa bí danh ở bước 5.\", \"Giải thích lý do ORDER BY dùng được Alias (3.0đ): Lập luận chính xác do ORDER BY chạy ở bước cuối cùng sau khi SELECT đã gắn nhãn cột hoàn tất.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 69),
            CreateExamSeed("00000000-0000-0000-0006-000000000211", CourseDbi202Id, "00000000-0000-0000-0000-000000000667", StructureDbi202Id, RubricDbi202Id, "Cơ chế hoạt động của Cây B-Tree trong Clustered Index và Tìm kiếm Bản ghi", "Hãy giải thích cấu trúc phân tầng của cây B-Tree (gốc Root, nhánh Intermediate, lá Leaf Level) trong Clustered Index của MS SQL Server. Quá trình tìm kiếm một bản ghi theo khóa chính diễn ra như thế nào và tại sao nó lại có độ phức tạp thời gian là O(log N)?", "Cấu trúc B-Tree trong Clustered Index thực chất là biến thể B+Tree cân bằng hoàn hảo, gồm 3 tầng trang dữ liệu (8KB mỗi trang): (1) Nút gốc (Root Node): Trang đầu vào duy nhất chứa các giá trị khóa phân định và con trỏ trỏ tới các trang mức trung gian. (2) Các nút trung gian (Intermediate Nodes): Các trang chỉ mục điều hướng tiếp tục chia nhỏ dải giá trị khóa thành các khoảng hẹp hơn. (3) Các nút lá (Leaf Level): Đối với Clustered Index, tầng lá CHÍNH LÀ CÁC TRANG DỮ LIỆU THỰC TẾ (Data Pages) của bảng, được tổ chức thành một danh sách liên kết kép (Doubly-linked list) và sắp xếp vật lý tăng dần theo khóa chỉ mục. Quá trình tìm kiếm (Index Seek): Bắt đầu từ Root, bộ máy đối chiếu giá trị khóa cần tìm với các mốc phân vùng để chọn nhánh con phù hợp; tiếp tục duyệt qua tầng Intermediate cho đến khi chạm tới đúng Trang dữ liệu ở mức Lá; sau đó quét nhị phân trong trang để lấy ra dòng dữ liệu hoàn chỉnh. Độ phức tạp là O(log N) vì cây B-Tree có bậc (Fanout) rất lớn (hàng trăm nhánh trên 1 trang 8KB); với bảng 10 triệu bản ghi, chiều cao của cây thường chỉ từ 3 đến 4 tầng; do đó hệ thống chỉ tốn 3-4 thao tác I/O đọc trang để định vị bản ghi chính xác.", "[\"Cấu trúc 3 tầng phân cấp của cây B-Tree (3.5đ): Mô tả chính xác Root, Intermediate và Leaf level là data pages trong Clustered Index.\", \"Quy trình điều hướng Index Seek từ gốc tới lá (3.5đ): Giải thích rõ việc so sánh mốc phân vùng qua các trang chỉ mục để tới trang đích.\", \"Giải thích độ phức tạp O(log N) và Fanout (3.0đ): Chứng minh chiều cao cây thấp (3-4 cấp) nhờ Fanout lớn giúp giảm thiểu chi phí I/O.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 70),
            CreateExamSeed("00000000-0000-0000-0006-000000000212", CourseDbi202Id, "00000000-0000-0000-0000-000000000667", StructureDbi202Id, RubricDbi202Id, "Bảo đảm Tính Nguyên tố (Atomicity) và Bền vững (Durability) qua Write-Ahead Logging (WAL)", "Hệ quản trị cơ sở dữ liệu làm thế nào để đảm bảo được hai thuộc tính Atomicity và Durability khi có sự cố sập nguồn (Crash)? Giải thích nguyên lý cốt lõi của kỹ thuật Write-Ahead Logging (WAL) và vai trò của hai tiến trình Undo và Redo.", "DBMS đảm bảo Atomicity và Durability thông qua Nhật ký giao dịch (Transaction Log file) kết hợp kỹ thuật Ghi nhật ký trước khi ghi dữ liệu (Write-Ahead Logging - WAL). Nguyên lý bất biến của WAL: Mọi thay đổi dữ liệu trên trang bộ nhớ đệm (Buffer Pool) BẮT BUỘC phải được ghi chi tiết vào Transaction Log trên đĩa cứng TRƯỚC KHI trang dữ liệu vật lý (Data Page) được ghi xuống đĩa, và một giao dịch chỉ được coi là đã COMMIT thành công khi bản ghi log commit đã được ghi an toàn xuống đĩa (Flush to disk). Khi máy chủ bị mất điện đột ngột và khởi động lại, tiểu trình Crash Recovery sẽ kích hoạt cơ chế ARIES gồm 2 giai đoạn: (1) Tiến trình REDO (Roll Forward): Quét nhật ký giao dịch từ điểm kiểm tra (Checkpoint) gần nhất, thực hiện lại toàn bộ các thao tác của tất cả các giao dịch ĐÃ COMMIT nhưng dữ liệu trên trang bộ nhớ chưa kịp ghi xuống đĩa, bảo đảm trọn vẹn thuộc tính Durability. (2) Tiến trình UNDO (Roll Back): Quét ngược lại nhật ký, hoàn tác và khôi phục lại trạng thái cũ của toàn bộ các giao dịch ĐANG CHẠY DỞ DANG (chưa Commit) tại thời điểm mất điện, bảo đảm tính nguyên lý 'Tất cả hoặc không có gì' của thuộc tính Atomicity.", "[\"Nguyên lý bất biến của Write-Ahead Logging (WAL) (3.5đ): Nêu đúng quy tắc ghi log xuống đĩa trước khi ghi data page và flush log khi commit.\", \"Vai trò của tiến trình REDO và tính Bền vững (Durability) (3.5đ): Giải thích rõ việc làm lại các thay đổi của transaction đã commit để bảo vệ dữ liệu.\", \"Vai trò của tiến trình UNDO và tính Nguyên tố (Atomicity) (3.0đ): Giải thích rõ việc hoàn tác các transaction chưa commit để chống trạng thái dở dang.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 71),
            CreateExamSeed("00000000-0000-0000-0006-000000000213", CourseDbi202Id, "00000000-0000-0000-0000-000000000666", StructureDbi202Id, RubricDbi202Id, "Điều kiện Khung nhìn Có thể Cập nhật (Updatable Views), WITH CHECK OPTION và WITH SCHEMABINDING (CQ7.3)", "Trong MS SQL Server (Constructive Question CQ7.3), một Khung nhìn (View) cần thỏa mãn những điều kiện nào để trở thành Khung nhìn có thể cập nhật trực tiếp (Updatable View) thông qua các thao tác INSERT, UPDATE, DELETE? Hãy giải thích vai trò của hai tùy chọn nâng cao khi định nghĩa View là WITH CHECK OPTION và WITH SCHEMABINDING.", "Để một View cho phép cập nhật dữ liệu trực tiếp xuống bảng vật lý mà không cần gắn INSTEAD OF Trigger, View đó phải thỏa mãn ba điều kiện: (1) Mỗi thao tác INSERT, UPDATE hoặc DELETE tại một thời điểm chỉ được tác động lên các cột thuộc về duy nhất một bảng cơ sở (nếu sửa đồng thời cột của hai bảng trong View có JOIN sẽ bị từ chối ngay); (2) Các cột được sửa đổi phải ánh xạ trực tiếp tới cột vật lý của bảng gốc, không phải cột tính toán từ biểu thức số học hay hàm tổng hợp; (3) Định nghĩa View không chứa các mệnh đề làm mất ánh xạ một - một tới dòng gốc như GROUP BY, HAVING, DISTINCT hoặc các phép toán tập hợp UNION, INTERSECT, EXCEPT. Về hai tùy chọn nâng cao: tùy chọn WITH CHECK OPTION ngăn chặn hiện tượng dòng dữ liệu biến mất khỏi phạm vi nhìn thấy của View sau khi cập nhật, bắt buộc mọi dòng thêm mới hoặc chỉnh sửa qua View vẫn phải thỏa mãn điều kiện lọc WHERE của chính View đó (chẳng hạn View lọc nhân viên đang hoạt động sẽ chặn thao tác đổi trạng thái sang nghỉ việc qua View). Trong khi đó, WITH SCHEMABINDING khóa chặt cấu trúc các bảng cơ sở được View tham chiếu (chặn lệnh xóa bảng hoặc sửa kiểu cột đang dùng), bắt buộc định danh bảng gồm hai phần kèm tên lược đồ, liệt kê tường minh tên cột và là điều kiện tiên quyết để tạo Indexed View.", "[\"Nêu đúng các điều kiện của Updatable View (1 bảng đích, không GROUP BY/DISTINCT/Aggregate) (4.0đ): Trình bày đầy đủ điều kiện chỉ tác động 1 bảng cơ sở mỗi lệnh và các mệnh đề gom nhóm, khử trùng làm View chỉ đọc.\", \"Giải thích chính xác cơ chế kiểm soát của WITH CHECK OPTION (3.0đ): Giải thích rõ WITH CHECK OPTION bắt buộc mọi dữ liệu INSERT/UPDATE qua View phải tiếp tục thỏa mãn mệnh đề WHERE của View.\", \"Giải thích vai trò khóa cấu trúc và điều kiện tạo Indexed View của WITH SCHEMABINDING (3.0đ): Nêu rõ tác dụng chống ALTER/DROP cột bảng gốc, quy tắc định danh bảng kèm tên schema và điều kiện tiên quyết tạo Indexed View.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 72),
            CreateExamSeed("00000000-0000-0000-0006-000000000214", CourseDbi202Id, "00000000-0000-0000-0000-000000000666", StructureDbi202Id, RubricDbi202Id, "Cơ chế Tái sử dụng Kế hoạch Thực thi (Execution Plan Cache) của Stored Procedure", "Tại sao việc thực thi một Stored Procedure thường nhanh hơn đáng kể so với việc gửi trực tiếp các câu lệnh SQL Ad-hoc thô từ ứng dụng? Hãy giải thích cơ chế phân tích cú pháp, tối ưu hóa và lưu bộ nhớ đệm Kế hoạch thực thi (Execution Plan Cache) của Stored Procedure trong SQL Server.", "Khi một câu lệnh SQL Ad-hoc thô được gửi lên máy chủ, SQL Server bắt buộc phải trải qua 4 công đoạn tuần tự: (1) Parsing: Phân tích cú pháp; (2) Binding/Resolving: Kiểm tra tính hợp lệ của các đối tượng bảng/cột và phân quyền; (3) Optimization: Bộ tối ưu hóa chi phí (Cost-Based Optimizer) đánh giá các giải thuật Join, Scan, Seek để tạo ra Kế hoạch thực thi (Execution Plan) tối ưu; (4) Execution: Thực thi kế hoạch. Công đoạn Optimization tiêu tốn rất nhiều tài nguyên CPU và thời gian. Ngược lại, Stored Procedure mang lại hiệu năng vượt trội nhờ cơ chế Tái sử dụng Kế hoạch thực thi (Execution Plan Cache): Trong lần gọi đầu tiên, SQL Server biên dịch, tối ưu và lưu Kế hoạch thực thi vào vùng nhớ RAM Plan Cache. Trong các lần gọi tiếp theo, khi nhận lệnh EXEC với cùng mã SP, hệ thống lập tức lấy ngay Kế hoạch thực thi đã có sẵn trong bộ nhớ đệm để chạy ngay mà không cần tốn chi phí phân tích và tối ưu hóa lại. Ngoài ra, SP còn giảm thiểu tối đa băng thông đường truyền mạng (chỉ truyền tên SP và tham số thay vì cả đoạn văn bản SQL dài) và loại bỏ hoàn toàn nguy cơ tấn công SQL Injection nhờ cơ chế tham số hóa tự động.", "[\"4 giai đoạn xử lý truy vấn SQL thô (Ad-hoc) (3.0đ): Liệt kê đúng Parsing, Binding, Optimization và Execution cùng chi phí CPU.\", \"Cơ chế lưu và tái sử dụng Plan Cache của SP (4.0đ): Giải thích rõ việc biên dịch lần đầu và tái sử dụng trực tiếp kế hoạch trong RAM các lần sau.\", \"Lợi ích bổ trợ về Network Bandwidth và SQL Injection (3.0đ): Chỉ rõ lợi thế giảm lưu lượng mạng và an ninh tham số hóa chống SQL Injection.\"]", QuestionDifficulty.Medium, BloomLevel.Understand, 73),
            CreateExamSeed("00000000-0000-0000-0006-000000000215", CourseDbi202Id, "00000000-0000-0000-0000-000000000664", StructureDbi202Id, RubricDbi202Id, "Ánh xạ Thực thể Kết hợp (Associative Entity), Mối kết hợp Bậc 3 (Ternary) và Thuộc tính Đa trị từ ERD sang Lược đồ Quan hệ", "Trong bài toán Quản lý Khám chữa bệnh tại bệnh viện, mô hình ERD gồm ba thực thể mạnh là Bác sĩ (có Mã bác sĩ, Họ tên và thuộc tính đa trị Chuyên khoa vì một bác sĩ có thể có nhiều chuyên khoa), Bệnh nhân (có Mã bệnh nhân, Họ tên, Ngày sinh) và Thuốc (có Mã thuốc, Tên thuốc, Đơn giá). Giữa Bác sĩ, Bệnh nhân và Thuốc có mối kết hợp bậc ba Kê đơn mang thuộc tính Ngày kê đơn và Liều lượng, trong đó một bác sĩ có thể kê nhiều loại thuốc cho cùng một bệnh nhân vào các ngày khác nhau. Hãy trình bày bằng lời cách thiết kế các bảng quan hệ chuẩn 3NF và xác định rõ Khóa chính, Khóa ngoại của từng bảng.", "Áp dụng quy tắc ánh xạ từ sơ đồ ERD sang Lược đồ Quan hệ chuẩn 3NF, hệ thống được tổ chức thành 5 bảng độc lập: (1) Ba thực thể mạnh được chuyển thành ba bảng cơ sở gồm bảng Bác sĩ lưu Mã bác sĩ làm khóa chính và Họ tên; bảng Bệnh nhân lưu Mã bệnh nhân làm khóa chính, Họ tên và Ngày sinh; bảng Thuốc lưu Mã thuốc làm khóa chính, Tên thuốc và Đơn giá. (2) Đối với thuộc tính đa trị Chuyên khoa của Bác sĩ, để bảo toàn Dạng chuẩn 1 (tuyệt đối không nhồi danh sách chuyên khoa ngăn cách bằng dấu phẩy vào một cột), ta bắt buộc tách thành bảng Chuyên khoa Bác sĩ gồm hai cột là Mã bác sĩ (khóa ngoại tham chiếu về bảng Bác sĩ kèm tùy chọn xóa dây chuyền) và Tên chuyên khoa, trong đó khóa chính phức hợp là sự kết hợp của cả hai cột này. (3) Đối với mối kết hợp bậc ba Kê đơn giữa Bác sĩ, Bệnh nhân và Thuốc, ta tạo bảng trung gian Đơn kê thuốc gom khóa ngoại tham chiếu tới khóa chính của cả ba thực thể mạnh kèm thuộc tính Ngày kê đơn và Liều lượng; vì cùng một bác sĩ có thể kê lại cùng một loại thuốc cho một bệnh nhân vào các ngày khác nhau nên khóa chính phức hợp của bảng này gồm bốn cột là Mã bác sĩ, Mã bệnh nhân, Mã thuốc và Ngày kê đơn.", "[\"Ánh xạ đúng 3 bảng Thực thể mạnh (Bác sĩ, Bệnh nhân, Thuốc) (2.5đ): Xác định đúng cấu trúc cột và khóa chính đơn cho cả ba thực thể mạnh độc lập.\", \"Tách bảng riêng cho Thuộc tính đa trị Chuyên khoa bảo toàn 1NF (3.5đ): Thiết kế bảng phụ gồm khóa ngoại Mã bác sĩ ghép với Tên chuyên khoa tạo thành khóa chính phức hợp hai cột.\", \"Ánh xạ đúng Mối kết hợp bậc 3 Kê đơn với Khóa chính phức hợp và 3 Khóa ngoại (4.0đ): Thiết kế bảng trung gian chứa đủ 3 khóa ngoại tham chiếu 3 thực thể, thuộc tính Liều lượng và khóa chính phức hợp gồm cả Ngày kê đơn.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 74),
            CreateExamSeed("00000000-0000-0000-0006-000000000216", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", StructureDbi202Id, RubricDbi202Id, "Phương pháp Phân loại Thuộc tính và Xác định Khóa ứng viên (Candidate Keys) của Quan hệ", "Khi xác định tất cả các Khóa ứng viên (Candidate Keys) của một lược đồ quan hệ có nhiều thuộc tính, việc thử bao đóng cho mọi tập con là không khả thi. Hãy trình bày phương pháp phân loại thuộc tính thành 4 nhóm dựa theo vị trí xuất hiện trong tập phụ thuộc hàm (chỉ xuất hiện ở vế trái, chỉ xuất hiện ở vế phải, xuất hiện ở cả hai vế và không xuất hiện ở vế nào) để xác định thuộc tính nào bắt buộc phải có mặt trong mọi khóa, thuộc tính nào chắc chắn bị loại trừ, và minh họa bằng lời trên một ví dụ thực tế đơn giản.", "Phương pháp phân loại thuộc tính giúp cắt giảm đột biến không gian tìm kiếm Khóa ứng viên thông qua bốn nhóm: (1) Nhóm nguồn thuần túy (chỉ xuất hiện ở vế trái) và (2) Nhóm cô lập (không xuất hiện ở bất kỳ phụ thuộc hàm nào): vì không có phụ thuộc hàm nào có thể suy dẫn ra các thuộc tính thuộc hai nhóm này nên chúng BẮT BUỘC phải có mặt trong mọi Khóa ứng viên của quan hệ, hợp lại thành Tập hạt nhân (Core). (3) Nhóm đích thuần túy (chỉ xuất hiện ở vế phải): vì chúng luôn suy ra được từ thuộc tính khác nhưng bản thân lại không giúp suy dẫn thêm thuộc tính nào mới, nên theo tính chất tối tiểu của khóa ứng viên, nhóm này TUYỆT ĐỐI KHÔNG BAO GIỜ xuất hiện trong bất kỳ Khóa ứng viên nào. (4) Nhóm trung gian (xuất hiện ở cả vế trái và vế phải): chỉ khi nào bao đóng của Tập hạt nhân chưa phủ hết toàn bộ lược đồ, ta mới lần lượt ghép thử từng thuộc tính trung gian vào Tập hạt nhân theo kích thước tăng dần để tìm các khóa ứng viên. Minh họa trên bảng Phân công Lớp học gồm Mã lớp học phần, Phòng học, Sức chứa phòng và Ghi chú: Mã lớp xác định Phòng học, còn Phòng học xác định Sức chứa; khi đó Mã lớp (chỉ ở vế trái) và Ghi chú (không xuất hiện) tạo thành hạt nhân bắt buộc, Sức chứa (chỉ ở vế phải) bị loại ngay, và bao đóng của cặp Mã lớp - Ghi chú đã phủ trọn cả bốn cột nên đó là Khóa ứng viên duy nhất.", "[\"Phân tích đúng vai trò Tập hạt nhân bắt buộc (chỉ ở vế trái và không xuất hiện) (3.5đ): Giải thích rõ lý do các thuộc tính không bao giờ nằm ở vế phải không thể được suy dẫn từ thuộc tính khác nên bắt buộc thuộc mọi khóa ứng viên.\", \"Phân tích đúng nhóm bị loại trừ (chỉ ở vế phải) và nhóm trung gian (cả hai vế) (3.5đ): Lý giải vì sao thuộc tính chỉ ở vế phải vi phạm tính tối tiểu nếu đưa vào khóa và cách ghép thử nhóm trung gian khi hạt nhân chưa đủ.\", \"Minh họa mạch lạc bằng lời trên ví dụ thực tế (3.0đ): Đưa ra ví dụ bảng thực tế trực quan, phân nhóm thuộc tính chính xác và kết luận đúng Khóa ứng viên.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 75),
            CreateExamSeed("00000000-0000-0000-0006-000000000217", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", StructureDbi202Id, RubricDbi202Id, "Nhận diện Vi phạm 2NF/3NF và Thuật toán Tổng hợp Lược đồ Chuẩn 3NF (Bernstein)", "Trong chuẩn hóa cơ sở dữ liệu, hãy phân tích dấu hiệu nhận biết một lược đồ đã đạt 1NF nhưng vi phạm Dạng chuẩn 2 (2NF) so với trường hợp đã đạt 2NF nhưng vi phạm Dạng chuẩn 3 (3NF). Để chuẩn hóa một lược đồ lớn về 3NF, hãy trình bày chi tiết quy trình 3 bước của Thuật toán tổng hợp 3NF (Bernstein) giúp vừa khử dư thừa dữ liệu, vừa bảo đảm đồng thời cả tính Bảo toàn phụ thuộc hàm lẫn tính Kết nối không mất thông tin (Lossless Join).", "Dấu hiệu chẩn đoán vi phạm chuẩn hóa dựa trên mối quan hệ giữa thuộc tính không khóa và khóa ứng viên: một bảng 1NF vi phạm 2NF khi xuất hiện Phụ thuộc hàm bộ phận, tức một thuộc tính không khóa chỉ phụ thuộc vào một phần tập con thực sự của khóa ứng viên phức hợp (ví dụ Tên mặt hàng chỉ phụ thuộc Mã mặt hàng trong bảng Chi tiết hóa đơn có khóa gồm Mã hóa đơn và Mã mặt hàng). Trong khi đó, một bảng đã đạt 2NF nhưng vi phạm 3NF khi xuất hiện Phụ thuộc hàm bắc cầu, tức một thuộc tính không khóa phụ thuộc vào một thuộc tính không khóa khác không phải siêu khóa (ví dụ Tên phòng ban phụ thuộc Mã phòng ban trong bảng Nhân viên). Quy trình 3 bước của Thuật toán tổng hợp 3NF (Bernstein) giải quyết trọn vẹn bài toán chuẩn hóa: Bước 1 thu gọn tập phụ thuộc hàm ban đầu về Phủ tối tiểu để loại bỏ mọi thuộc tính thừa ở vế trái và các phụ thuộc bắc cầu dư thừa; Bước 2 gom tất cả các phụ thuộc hàm trong phủ tối tiểu có cùng vế trái lại với nhau để tạo thành một lược đồ bảng con tương ứng với vế trái làm Khóa chính (loại bỏ bảng con nếu tập thuộc tính của nó bị chứa trọn trong bảng con khác), nhờ đó bảo toàn 100% phụ thuộc hàm; Bước 3 kiểm tra tính Lossless Join, nếu chưa có bảng con nào chứa trọn vẹn một Khóa ứng viên của lược đồ gốc thì bắt buộc tạo thêm một bảng mới gồm các thuộc tính của một Khóa ứng viên bất kỳ.", "[\"Phân biệt rõ dấu hiệu vi phạm 2NF (phụ thuộc bộ phận) và 3NF (phụ thuộc bắc cầu) (3.0đ): Chỉ rõ vi phạm 2NF do thuộc tính không khóa phụ thuộc một phần khóa phức hợp, còn vi phạm 3NF do phụ thuộc bắc cầu qua thuộc tính không khóa.\", \"Trình bày đúng Bước 1 (Phủ tối tiểu) và Bước 2 (Gom bảng theo vế trái) (4.0đ): Giải thích rõ việc tìm Phủ tối tiểu trước rồi gom các phụ thuộc cùng vế trái thành bảng con giúp bảo toàn toàn bộ phụ thuộc hàm.\", \"Giải thích đúng Bước 3 bổ sung bảng chứa Khóa ứng viên gốc cho Lossless Join (3.0đ): Khẳng định điều kiện kiểm tra và bổ sung bảng chứa một Khóa ứng viên của lược đồ ban đầu để chống mất thông tin khi JOIN.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, 76),
            CreateExamSeed("00000000-0000-0000-0006-000000000218", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", StructureDbi202Id, RubricDbi202Id, "Giải pháp Truy vấn và Xếp hạng Khách hàng Chi tiêu Cao nhất theo Từng Thành phố", "Trong hệ thống quản lý bán hàng gồm bảng Khách hàng (lưu Mã khách hàng, Tên khách hàng, Thành phố) và bảng Đơn hàng (lưu Mã đơn hàng, Mã khách hàng, Ngày đặt và Tổng tiền đơn hàng), bài toán đặt ra là tìm thông tin Khách hàng có tổng giá trị mua hàng cao nhất tại từng Thành phố và hiển thị đầy đủ tất cả nếu có nhiều khách hàng đồng hạng nhất. Hãy phân tích chiến lược truy vấn nhiều bước kết hợp gom nhóm, Biểu thức bảng chung (CTE) và hàm xếp hạng cửa sổ để giải quyết chính xác bài toán này.", "Vì SQL không cho phép lồng trực tiếp hàm cửa sổ xếp hạng bên ngoài hàm tổng hợp rồi lọc ngay trong cùng một mệnh đề WHERE, chiến lược chuẩn mực và dễ bảo trì nhất là chia bài toán thành ba bước nối tiếp thông qua Biểu thức bảng chung (CTE): Bước 1 xây dựng CTE thứ nhất thực hiện kết nối nội INNER JOIN giữa bảng Khách hàng và bảng Đơn hàng qua Mã khách hàng, sau đó gom nhóm GROUP BY theo Mã khách hàng, Tên khách hàng và Thành phố để tính tổng chi tiêu bằng hàm SUM trên cột Tổng tiền đơn hàng. Bước 2 xây dựng CTE thứ hai đọc từ kết quả bước 1 và áp dụng hàm xếp hạng cửa sổ DENSE_RANK (hoặc RANK) đi kèm mệnh đề OVER, trong đó dùng PARTITION BY theo cột Thành phố để chia không gian xếp hạng độc lập cho từng địa phương và ORDER BY tổng chi tiêu giảm dần để người chi tiêu lớn nhất nhận hạng 1. Bước 3 tại câu lệnh SELECT ngoài cùng, ta chỉ cần lọc giữ lại các dòng có cột thứ hạng bằng 1. Việc chọn DENSE_RANK hoặc RANK thay vì ROW_NUMBER là bắt buộc vì ROW_NUMBER luôn đánh số tăng dần phân biệt nên sẽ bỏ sót các khách hàng đồng hạng nhất; riêng khi bài toán mở rộng lên lấy Top 3 mức chi tiêu cao nhất thì DENSE_RANK ưu việt hơn RANK do không nhảy cóc bỏ trống bậc hạng kế tiếp sau các vị trí đồng hạng.", "[\"Phân tích bước gom nhóm tính Tổng chi tiêu từng khách hàng (3.0đ): Trình bày đúng bước kết nối bảng Khách hàng với Đơn hàng và gom nhóm GROUP BY theo khách hàng, thành phố để tính tổng tiền SUM.\", \"Chiến lược tổ chức CTE kết hợp hàm cửa sổ phân vùng theo thành phố (4.0đ): Giải thích rõ việc dùng CTE trung gian kết hợp PARTITION BY theo Thành phố và sắp xếp tổng chi tiêu giảm dần trong mệnh đề OVER.\", \"Xử lý triệt để trường hợp đồng hạng nhất bằng DENSE_RANK / RANK (3.0đ): Lý giải chính xác việc lọc hạng bằng 1 với DENSE_RANK hoặc RANK để không làm rơi khách hàng có mức chi tiêu cao nhất bằng nhau.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, 77),
            CreateExamSeed("00000000-0000-0000-0006-000000000219", CourseDbi202Id, "00000000-0000-0000-0000-000000000665", StructureDbi202Id, RubricDbi202Id, "Thiết kế Ràng buộc Toàn vẹn Khóa chính Phức hợp, Khóa ngoại và CHECK trên Bảng Đăng ký Học", "Khi thiết kế bảng Đăng ký môn học (CourseEnrollments) lưu mối quan hệ giữa Sinh viên và Môn học kèm các thông tin Ngày đăng ký, Điểm tổng kết (thang điểm từ 0 đến 10, cho phép để trống NULL khi sinh viên đang học) và Trạng thái học tập, hãy phân tích cách thiết lập hệ thống ràng buộc toàn vẹn gồm: Khóa chính phức hợp, lựa chọn hành vi xóa cho hai Khóa ngoại tham chiếu về bảng Sinh viên và bảng Môn học (giữa CASCADE và NO ACTION), giá trị mặc định DEFAULT và ràng buộc miền giá trị CHECK xử lý an toàn với NULL.", "Thiết kế hệ thống ràng buộc toàn vẹn chuẩn mực cho bảng Đăng ký môn học cần phối hợp chặt chẽ bốn lớp bảo vệ: (1) Khóa chính phức hợp kết hợp hai cột Mã sinh viên và Mã môn học (cả hai bắt buộc NOT NULL), ngăn chặn tuyệt đối việc một sinh viên đăng ký trùng lặp hai lần vào cùng một môn học trong kỳ. (2) Hai ràng buộc Khóa ngoại có hành vi xóa bất đối xứng tùy theo ngữ nghĩa bảo toàn dữ liệu: khóa ngoại Mã môn học tham chiếu bảng Môn học bắt buộc đặt ON DELETE NO ACTION để chặn việc xóa nhầm một môn học đã có lịch sử sinh viên theo học; trong khi khóa ngoại Mã sinh viên tham chiếu bảng Sinh viên có thể cấu hình ON DELETE CASCADE nếu nghiệp vụ yêu cầu tự động dọn sạch hồ sơ đăng ký phụ thuộc khi xóa bản ghi sinh viên (hoặc NO ACTION trong hệ thống lưu trữ học bạ lâu dài). (3) Ràng buộc DEFAULT tự động gán ngày hệ thống hiện tại cho Ngày đăng ký và trạng thái mặc định là đang theo học cho cột Trạng thái, đi kèm ràng buộc CHECK giới hạn cột Trạng thái chỉ nằm trong tập danh mục hợp lệ như Đang học, Hoàn thành, Rút môn hoặc Học lại. (4) Ràng buộc CHECK trên cột Điểm kiểm tra khoảng từ 0 đến 10: điểm đặc biệt trong SQL là khác với WHERE (chỉ nhận TRUE), ràng buộc CHECK chỉ từ chối khi biểu thức ra FALSE và cho phép đi qua cả khi ra TRUE lẫn UNKNOWN (khi Điểm là NULL), tuy nhiên kiểm tra tường minh IS NULL hoặc nằm trong đoạn 0 đến 10 giúp ý đồ thiết kế rõ ràng tuyệt đối.", "[\"Thiết kế Khóa chính phức hợp chống đăng ký trùng và quy định tính Nullable (2.5đ): Giải thích rõ việc ghép Mã sinh viên với Mã môn học (NOT NULL) làm khóa chính phức hợp và cho phép cột Điểm nhận NULL khi đang học.\", \"Phân tích lựa chọn hành vi Khóa ngoại CASCADE so với NO ACTION (3.5đ): Lý giải hợp lý sự khác biệt ngữ nghĩa giữa xóa dây chuyền bản ghi phụ thuộc (CASCADE) và chặn xóa danh mục môn học đang có dữ liệu (NO ACTION).\", \"Thiết kế ràng buộc DEFAULT, miền giá trị CHECK và hành vi với NULL (4.0đ): Trình bày đầy đủ DEFAULT ngày hiện tại, CHECK tập trạng thái hợp lệ, khoảng điểm 0-10 và giải thích đúng hành vi chấp nhận UNKNOWN của CHECK.\"]", QuestionDifficulty.Medium, BloomLevel.Apply, 78),
            CreateExamSeed("00000000-0000-0000-0006-000000000220", CourseDbi202Id, "00000000-0000-0000-0000-000000000666", StructureDbi202Id, RubricDbi202Id, "Cơ chế Kiểm soát Tồn kho và Hủy Giao dịch Tự động bằng DML AFTER Trigger", "Trong hệ thống quản lý bán hàng gồm bảng Sản phẩm (lưu số lượng tồn kho hiện tại) và bảng Chi tiết đơn hàng (lưu mã sản phẩm và số lượng đặt mua), giả sử ta gắn một AFTER INSERT Trigger trên bảng Chi tiết đơn hàng để tự động kiểm soát kho. Hãy phân tích luồng xử lý chuẩn mực theo tư duy tập hợp (Set-based) sử dụng bảng ảo inserted nhằm: kiểm tra tình trạng thiếu hàng khi một câu lệnh chèn đồng thời nhiều dòng chi tiết đơn hàng, phát lỗi hủy giao dịch khi vượt tồn kho và trừ tồn kho chính xác kể cả khi một mã sản phẩm xuất hiện nhiều lần trong đợt chèn.", "Trong MS SQL Server, một DML Trigger không kích hoạt lặp lại cho từng dòng mà chỉ kích hoạt duy nhất một lần cho mỗi câu lệnh INSERT, do đó bảng ảo inserted có thể chứa hàng chục dòng chi tiết đơn hàng cùng lúc, thậm chí cùng một mã sản phẩm có thể xuất hiện ở nhiều dòng trong cùng đợt chèn. Luồng xử lý chuẩn mực theo tư duy tập hợp gồm ba bước chặt chẽ: Bước 1 gom nhóm bảng ảo inserted theo cột Mã sản phẩm và tính tổng số lượng đặt mua SUM của từng mặt hàng, sau đó kết nối INNER JOIN tập gom nhóm này với bảng Sản phẩm bên trong điều kiện kiểm tra sự tồn tại EXISTS xem có bất kỳ mặt hàng nào mà tổng số lượng đặt vượt quá số lượng tồn kho hiện có hay không. Bước 2 nếu phát hiện dù chỉ một mặt hàng thiếu tồn kho, Trigger lập tức phát thông báo lỗi nghiệp vụ tường minh bằng THROW hoặc RAISERROR và gọi lệnh ROLLBACK TRANSACTION để hoàn tác nguyên tố toàn bộ câu lệnh chèn Chi tiết đơn hàng trước đó rồi thoát khỏi Trigger. Bước 3 nếu tất cả các mặt hàng đều đủ tồn kho, Trigger thực hiện một câu lệnh UPDATE tập hợp duy nhất trên bảng Sản phẩm kết nối với truy vấn con đã gom nhóm tổng lượng đặt từ bảng inserted để trừ chính xác số lượng tồn kho tương ứng, khắc phục triệt để lỗi gán biến vô hướng vốn làm bỏ sót 19 trên 20 mặt hàng khi chèn theo lô.", "[\"Kiểm tra điều kiện thiếu hàng theo tập hợp qua bảng ảo inserted (3.5đ): Giải thích rõ cơ chế gom nhóm tổng lượng đặt trên bảng inserted rồi kết nối với bảng Sản phẩm qua EXISTS để phát hiện vượt tồn kho đa dòng.\", \"Cơ chế phát lỗi nghiệp vụ và hoàn tác giao dịch nguyên tố (3.0đ): Trình bày đúng quy trình phát thông báo lỗi (RAISERROR/THROW) đi kèm ROLLBACK TRANSACTION để hủy bỏ toàn bộ thao tác chèn không hợp lệ.\", \"Phân tích cập nhật trừ tồn kho theo tập hợp (Set-based) (3.5đ): Lý giải chuẩn xác việc cập nhật bảng Sản phẩm dựa trên tập gom nhóm theo Mã sản phẩm của bảng inserted thay vì dùng biến vô hướng hay con trỏ.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, 79),
            CreateExamSeed("00000000-0000-0000-0006-000000000221", CourseDbi202Id, "00000000-0000-0000-0000-000000000666", StructureDbi202Id, RubricDbi202Id, "Quy trình Quản trị Giao dịch Chuyển khoản An toàn và Phòng chống Deadlock trong Stored Procedure", "Khi thiết kế một Stored Procedure thực hiện giao dịch chuyển tiền giữa hai tài khoản ngân hàng, hãy phân tích kiến trúc quản trị giao dịch an toàn qua từng bước: kiểm tra điều kiện nghiệp vụ đầu vào trước khi mở giao dịch, vai trò của cấu hình XACT_ABORT kết hợp khối bắt lỗi TRY...CATCH để đảm bảo tính Nguyên tố (Atomicity), và nguyên tắc đặt khóa cập nhật trên hai dòng tài khoản để vừa chống ghi đè mất số dư vừa phòng chống triệt để Deadlock.", "Kiến trúc một Stored Procedure chuyển khoản chuẩn công nghiệp cần tuân thủ bốn chốt chặn an toàn: (1) Tiền kiểm tra ngoài giao dịch và bật XACT_ABORT ON: kiểm tra ngay từ đầu số tiền chuyển phải lớn hơn 0 và mã tài khoản nguồn phải khác tài khoản đích trước khi gọi BEGIN TRANSACTION nhằm rút ngắn tối đa thời gian giữ khóa, đồng thời bật chế độ SET XACT_ABORT ON để mọi lỗi runtime nghiêm trọng hoặc hết thời gian chờ đều buộc giao dịch tự động hủy bỏ sạch sẽ. (2) Đặt khóa cập nhật theo thứ tự định danh tăng dần chống Deadlock: bên trong khối TRY và giao dịch, nếu khóa tài khoản nguồn trước rồi khóa tài khoản đích sau sẽ sinh ra chờ đợi vòng tròn khi A chuyển cho B đồng thời B chuyển cho A; do đó thủ tục phải so sánh hai mã tài khoản và luôn đọc kiểm tra kèm gợi ý khóa mức dòng UPDLOCK, ROWLOCK đối với tài khoản có ID nhỏ hơn trước, tài khoản có ID lớn hơn sau, qua đó phá vỡ hoàn toàn chu trình Deadlock đồng thời ngăn giao dịch khác đọc chèn gây mất cập nhật số dư. (3) Xác thực trạng thái tài khoản đang hoạt động và số dư tài khoản nguồn đủ chi trả. (4) Thực hiện trừ tiền tài khoản nguồn, cộng tiền tài khoản đích rồi COMMIT TRANSACTION; nếu bất kỳ bước nào ném lỗi nhảy sang khối CATCH, thủ tục kiểm tra trạng thái giao dịch đang mở (qua XACT_STATE hoặc TRANCOUNT lớn hơn 0) để thực thi ROLLBACK TRANSACTION hoàn trả nguyên trạng số dư hai bên.", "[\"Kiểm tra điều kiện biên ngoài giao dịch và vai trò của XACT_ABORT ON (2.5đ): Nêu rõ việc kiểm tra số tiền dương, hai tài khoản khác nhau trước khi mở Transaction và bật XACT_ABORT ON chống giao dịch treo khi lỗi runtime.\", \"Nguyên tắc khóa UPDLOCK mức dòng theo thứ tự ID tăng dần chống Deadlock (4.0đ): Phân tích rõ cơ chế luôn khóa tài khoản có ID nhỏ trước, ID lớn sau để phá vỡ chu trình chờ vòng tròn và kiểm tra tồn tại, số dư an toàn.\", \"Đảm bảo tính Nguyên tố với COMMIT và ROLLBACK trong khối TRY...CATCH (3.5đ): Trình bày chuẩn xác luồng trừ/cộng tiền đồng bộ, COMMIT khi hoàn tất và kiểm tra trạng thái giao dịch để ROLLBACK an toàn trong khối CATCH.\"]", QuestionDifficulty.Hard, BloomLevel.Apply, 80),
            CreateExamSeed("00000000-0000-0000-0006-000000000222", CourseDbi202Id, "00000000-0000-0000-0000-000000000663", StructureDbi202Id, RubricDbi202Id, "Bản chất Phép phân rã Kết nối Không Mất Thông tin (Lossless Join) và Nguyên lý Kiểm định", "Trong thiết kế cơ sở dữ liệu quan hệ, hãy phân biệt bản chất của Phép phân rã kết nối không mất thông tin (Lossless Join Decomposition) với Phép phân rã mất thông tin (Lossy Join Decomposition) và giải thích hiện tượng sinh ra các bản ghi giả mạo (Spurious Tuples) khi kết nối tự nhiên các bảng con. Trình bày điều kiện cần và đủ bằng phụ thuộc hàm trên phần giao thuộc tính để kiểm tra nhanh tính Lossless Join khi tách một bảng thành hai bảng con, đồng thời nêu nguyên lý cốt lõi của phương pháp Bảng kiểm tra Chase (Chase Test) khi phân rã thành nhiều bảng con.", "Một phép phân rã lược đồ R thành các bảng con được gọi là Kết nối không mất thông tin (Lossless Join) nếu với mọi thể hiện dữ liệu hợp lệ thỏa mãn tập phụ thuộc hàm F, khi thực hiện phép kết nối tự nhiên (Natural Join) các bảng con lại với nhau ta luôn khôi phục đúng chính xác tập bản ghi ban đầu của R. Trái với cách hiểu nhầm phổ biến, phân rã mất thông tin (Lossy Join) không hề làm rơi mất dòng dữ liệu gốc nào, mà khi JOIN ngược các bảng con lại theo thuộc tính chung không duy nhất, phép ghép chéo sẽ đẻ thêm các bản ghi tổ hợp sai sự thật gọi là Bản ghi giả mạo (Spurious Tuples), làm hệ thống mất khả năng phân biệt đâu là dữ liệu thật, đâu là dữ liệu nhiễu. Đối với trường hợp phân rã nhị phân từ R thành hai bảng con R1 và R2, điều kiện cần và đủ để đạt Lossless Join là tập các thuộc tính phần giao chung giữa R1 và R2 phải đóng vai trò là một Siêu khóa của R1 HOẶC là một Siêu khóa của R2 (tức bao đóng của phần giao chứa trọn R1 hoặc chứa trọn R2, thể hiện vật lý thành liên kết Khóa chính - Khóa ngoại). Khi phân rã thành từ ba bảng con trở lên, ta dùng thuật toán Bảng kiểm tra Chase: khởi tạo ma trận mỗi dòng ứng với một bảng con (đánh dấu ký hiệu phân biệt cho thuộc tính có mặt), lặp áp dụng các phụ thuộc hàm để đồng nhất ký hiệu; phép phân rã đạt Lossless Join khi và chỉ khi xuất hiện ít nhất một dòng gồm toàn bộ ký hiệu phân biệt đại diện cho bản ghi gốc được tái tạo trọn vẹn.", "[\"Phân biệt bản chất Lossless Join với Lossy Join & Hiện tượng Spurious Tuples (3.5đ): Giải thích rõ Lossy Join không làm hụt dòng mà phát sinh thêm các bản ghi giả mạo (Spurious Tuples) khi Natural Join các bảng con.\", \"Điều kiện cần và đủ trên phần giao của phép phân rã hai bảng con (3.5đ): Nêu chính xác điều kiện tập thuộc tính giao giữa hai bảng con phải là Siêu khóa của ít nhất một trong hai bảng con đó.\", \"Giải thích đúng nguyên lý và điều kiện dừng của Bảng kiểm tra Chase (3.0đ): Mô tả rõ cơ chế đồng nhất ký hiệu theo các phụ thuộc hàm và ý nghĩa dòng chứa toàn ký hiệu phân biệt bảo đảm tái tạo đúng quan hệ gốc.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 81),
            CreateExamSeed("00000000-0000-0000-0006-000000000223", CourseDbi202Id, "00000000-0000-0000-0000-000000000667", StructureDbi202Id, RubricDbi202Id, "Phân tích Tranh chấp Dữ liệu giữa Hai Giao dịch và Đề xuất Mức Cô lập Tối ưu", "Cho kịch bản hệ thống đặt vé máy bay:\n- Giao dịch T1 (Khách hàng): Đọc số ghế trống chuyến bay VN123 (thấy còn 1 ghế); sau đó hệ thống chờ khách xác nhận thanh toán thẻ (khoảng 30 giây); rồi thực hiện UPDATE giảm số ghế trống về 0 và COMMIT.\n- Giao dịch T2 (Khách hàng khác): Bắt đầu 5 giây sau T1, cũng đọc số ghế trống của chuyến bay VN123 (vẫn thấy còn 1 ghế); khách thanh toán nhanh (trong 10 giây); thực hiện UPDATE số ghế trống về 0 và COMMIT thành công TRƯỚC KHI T1 hoàn tất.\nHãy phân tích: Hiện tượng tranh chấp dữ liệu này được gọi là gì? Nếu hệ thống đang chạy ở mức cô lập mặc định Read Committed thì hậu quả gì sẽ xảy ra cho T1? Đề xuất 2 giải pháp kỹ thuật (mức cô lập hoặc cơ chế khóa) để ngăn chặn hoàn toàn lỗi nghiệp vụ bán vé vượt số lượng (Overbooking) này.", "Hiện tượng tranh chấp này được gọi là Dị thường Ghi đè Mất mát (Lost Update Anomaly): cả hai giao dịch T1 và T2 cùng đọc thấy số ghế trống là 1; giao dịch T2 thanh toán nhanh và COMMIT trước làm số ghế thực tế giảm về 0. Ở mức cô lập mặc định Read Committed, khóa chia sẻ đọc dữ liệu của T1 đã bị giải phóng ngay khi câu lệnh SELECT đầu tiên vừa kết thúc, nên T1 không hề hay biết dữ liệu đã thay đổi, tiếp tục cập nhật và dẫn tới lỗi nghiệp vụ bán trùng một ghế duy nhất cho hai hành khách (Overbooking). Hai giải pháp kỹ thuật khắc phục triệt để gồm: (1) Khóa bi quan (Pessimistic Locking): ngay tại bước đọc kiểm tra số ghế trống ban đầu của T1, gắn gợi ý khóa cập nhật mức dòng UPDLOCK, ROWLOCK trên bản ghi chuyến bay đó; khóa UPDLOCK lập tức buộc giao dịch T2 phải xếp hàng chờ cho tới khi T1 hoàn tất thanh toán hoặc hủy bỏ rồi T2 mới đọc được số ghế mới bằng 0 và báo hết vé. (2) Kiểm soát tương tranh lạc quan (Optimistic Concurrency Control): bổ sung cột phiên bản dòng RowVersion (hoặc Version kiểu số nguyên) vào bảng Chuyến bay; khi T1 thực hiện lệnh UPDATE trừ ghế, điều kiện lọc kiểm tra kèm giá trị Version ban đầu lúc đọc, nếu T2 đã commit trước làm Version thay đổi thì số dòng cập nhật của T1 bằng 0, ứng dụng nhận biết xung đột ngay lập tức để hoàn tác và thông báo hết chỗ.", "[\"Chẩn đoán chính xác hiện tượng Lost Update / Overbooking (3.5đ): Chỉ rõ việc giải phóng Shared Lock sớm ở mức Read Committed dẫn đến ghi đè mất mát dữ liệu và bán vượt số ghế.\", \"Giải pháp Khóa bi quan (Pessimistic UPDLOCK) (3.5đ): Trình bày đúng cơ chế đặt gợi ý khóa cập nhật UPDLOCK mức dòng ngay từ bước đọc đầu tiên để buộc giao dịch T2 phải chờ.\", \"Giải pháp Khóa lạc quan (Optimistic Versioning) (3.0đ): Giải thích chuẩn mực cơ chế dùng cột RowVersion/Version đối chiếu lúc cập nhật và kiểm tra số dòng bị tác động để phát hiện xung đột.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 82),
            CreateExamSeed("00000000-0000-0000-0006-000000000224", CourseDbi202Id, "00000000-0000-0000-0000-000000000667", StructureDbi202Id, RubricDbi202Id, "Phân tích Kế hoạch Thực thi, Phát hiện Table Scan và Thiết kế Composite Index theo ESR", "Giả sử một truy vấn báo cáo chạy thường xuyên trên bảng Đơn hàng (Orders) có 5 triệu dòng để lấy ba cột Mã khách hàng, Ngày đặt hàng và Tổng tiền, với điều kiện lọc cột Trạng thái bằng Completed, lọc khoảng Ngày đặt hàng nằm trong sáu tháng đầu năm 2024 và sắp xếp kết quả tăng dần theo Mã khách hàng. Khi kiểm tra Execution Plan, quản trị viên phát hiện hệ thống đang thực hiện Clustered Index Scan chiếm 92% chi phí kèm một toán tử Sort chiếm 8% chi phí. Hãy phân tích nguyên nhân gây nghẽn và vận dụng Nguyên tắc vàng ESR (Equality - Sort - Range) kết hợp cột INCLUDE để đề xuất cấu trúc Chỉ mục phức hợp (Composite Non-Clustered Index) tối ưu nhất.", "Phân tích điểm nghẽn trên Execution Plan hiện tại: (1) Thao tác Clustered Index Scan xuất hiện do bảng Orders chưa có chỉ mục nào khớp với tổ hợp điều kiện lọc, buộc SQL Server phải đọc tuần tự toàn bộ các trang dữ liệu của 5 triệu dòng gây tốn kém I/O đĩa nặng nề; (2) Toán tử Sort phát sinh do tập dòng sau khi lọc chưa có thứ tự theo Mã khách hàng, buộc hệ thống phải xin cấp phát vùng nhớ RAM (Memory Grant) để sắp xếp lại và dễ bị tràn xuống tempdb (TempDB Spill) khi tải cao. Vận dụng Nguyên tắc vàng ESR để định hình thứ tự các cột khóa trong Composite Non-Clustered Index: vị trí đầu tiên (Equality) đặt cột Trạng thái vì dùng phép so sánh bằng tuyệt đối, giúp cây B-Tree định vị thẳng tới phân vùng các đơn hàng Completed; vị trí thứ hai (Sort) đặt cột Mã khách hàng đứng ngay sau cột so sánh bằng để toàn bộ các bản ghi trong nhánh Completed đã nằm sẵn theo đúng thứ tự Mã khách hàng tăng dần, nhờ đó loại bỏ hoàn toàn 100% toán tử Sort; vị trí thứ ba (Range) đặt cột Ngày đặt hàng để lọc phạm vi ngày trong từng nhóm khách hàng (nếu đặt Range trước Sort thì thứ tự cột sau sẽ bị đứt gãy). Cuối cùng, đưa cột Tổng tiền vào phần mở rộng INCLUDE ở tầng lá để tạo thành Chỉ mục bao phủ (Covering Index), chuyển toàn bộ truy vấn thành một thao tác Index Seek duy nhất mà không phát sinh Key Lookup về bảng gốc.", "[\"Phân tích nguyên nhân Clustered Index Scan & Toán tử Sort (3.0đ): Chỉ rõ chi phí đọc tuần tự 5 triệu dòng do thiếu chỉ mục phù hợp và rủi ro tốn RAM, tràn tempdb của toán tử Sort.\", \"Áp dụng chính xác quy tắc vàng ESR sắp xếp thứ tự cột khóa (4.0đ): Lập luận đúng thứ tự khóa chỉ mục gồm Trạng thái (Equality), đến Mã khách hàng (Sort), rồi đến Ngày đặt hàng (Range).\", \"Thiết kế Covering Index với cột INCLUDE chống Key Lookup (3.0đ): Xác định đúng việc đưa cột Tổng tiền vào danh sách INCLUDE ở nút lá để bao phủ trọn vẹn truy vấn và triệt tiêu Key Lookup.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 83),
            CreateExamSeed("00000000-0000-0000-0006-000000000225", CourseDbi202Id, "00000000-0000-0000-0000-000000000667", StructureDbi202Id, RubricDbi202Id, "Phân tích Độ mịn của Khóa (Lock Granularity), Hiện tượng Leo thang Khóa (Lock Escalation) và Cơ chế RCSI trong SQL Server", "Trong MS SQL Server, hãy phân tích sự đánh đổi giữa các cấp độ mịn của khóa (Lock Granularity gồm khóa dòng, khóa trang và khóa bảng) cùng vai trò của Khóa Ý định (Intent Locks như IS, IX). Hiện tượng Leo thang khóa (Lock Escalation) kích hoạt khi nào và tại sao một thao tác DELETE hoặc UPDATE hàng chục ngàn dòng trong giờ cao điểm lại có thể làm treo đứng toàn bộ các truy vấn đọc SELECT khác trên bảng? Hãy đề xuất 2 giải pháp kỹ thuật (chia nhỏ lô cập nhật và bật cơ chế RCSI) để xử lý triệt để.", "Quản lý độ mịn của khóa là bài toán đánh đổi giữa độ tương tranh và chi phí bộ nhớ: khóa mức dòng (Row Lock) cho độ tương tranh cao nhất vì các giao dịch khác vẫn thao tác được trên dòng lân cận, nhưng mỗi cấu trúc khóa tiêu tốn khoảng 96 bytes RAM; ngược lại khóa mức bảng (Table Lock) cực kỳ tiết kiệm RAM nhưng triệt tiêu khả năng chạy đồng thời. Để phối hợp đa cấp, SQL Server dùng Khóa Ý định (Intent Shared IS, Intent Exclusive IX): trước khi khóa độc quyền X một dòng, giao dịch đặt cờ IX ở mức Bảng và Trang, giúp giao dịch khác muốn khóa toàn bảng phát hiện ngay xung đột ở đỉnh Bảng mà không phải quét kiểm tra hàng triệu dòng con. Hiện tượng Leo thang khóa (Lock Escalation) xảy ra khi một câu lệnh đơn lẻ tích lũy vượt ngưỡng khoảng 5,000 khóa mức dòng hoặc trang trên một bảng, buộc SQL Server thu hồi các khóa nhỏ và nâng thẳng lên Khóa độc quyền toàn bảng (Table X-Lock, không leo từ dòng lên trang) để bảo vệ RAM; ở chế độ Read Committed bi quan mặc định, khóa bảng này chặn đứng toàn bộ truy vấn SELECT xin khóa đọc. Hai giải pháp triệt để gồm: (1) Chia nhỏ lô cập nhật (Batching) dưới 2,000 đến 4,000 dòng mỗi đợt giao dịch ngắn để không bao giờ chạm ngưỡng 5,000 khóa; (2) Bật READ_COMMITTED_SNAPSHOT (RCSI) lưu bản chụp dòng cũ trong tempdb để đọc không bị chặn bởi ghi.", "[\"Phân tích đúng đánh đổi giữa Row/Page/Table Lock và vai trò của Intent Locks (IS, IX) (3.5đ): Giải thích rõ sự đánh đổi Concurrency so với chi phí RAM và cách Intent Lock giúp phát hiện xung đột nhanh ở mức bảng.\", \"Giải thích cơ chế Lock Escalation (ngưỡng ~5,000 khóa) từ Row/Page lên Table Lock (3.5đ): Mô tả chính xác nguyên nhân leo thang khóa thẳng lên mức Table gây chặn toàn bộ truy vấn đọc/ghi khác.\", \"Đề xuất đúng 2 giải pháp: Chia lô Batching và bật READ_COMMITTED_SNAPSHOT (RCSI) (3.0đ): Trình bày rõ kỹ thuật chia lô dưới 5,000 dòng mỗi đợt và cơ chế Row Versioning trong tempdb giúp Đọc không bị chặn bởi Ghi.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 84),
            CreateExamSeed("00000000-0000-0000-0006-000000000226", CourseDbi202Id, "00000000-0000-0000-0000-000000000666", StructureDbi202Id, RubricDbi202Id, "So sánh Toàn diện giữa INSTEAD OF Trigger trên View Phức tạp và Stored Procedure", "Để cho phép các ứng dụng bên ngoài thực hiện cập nhật dữ liệu vào một cấu trúc gồm nhiều bảng có quan hệ phức tạp, các kiến trúc sư có hai phương án tiếp cận: (Phương án A) Tạo một View phức hợp (JOIN nhiều bảng) và gắn một INSTEAD OF Trigger trên View đó; (Phương án B) Xây dựng một Stored Procedure nhận tham số và trực tiếp thực thi cập nhật các bảng. Hãy so sánh toàn diện hai phương án này về: tính trong suốt đối với ứng dụng (Transparency), khả năng tái sử dụng với các ORM (như EF Core), độ phức tạp bảo trì và hiệu năng xử lý.", "So sánh toàn diện hai phương án kiến trúc trên bốn khía cạnh: (1) Tính trong suốt (Transparency): View gắn INSTEAD OF Trigger mang lại lớp trừu tượng trong suốt tuyệt đối vì ứng dụng bên ngoài nhìn nhận View như một bảng chuẩn và chỉ việc gửi lệnh INSERT, UPDATE, DELETE quen thuộc; ngược lại Stored Procedure có giao diện tường minh, buộc ứng dụng phải biết rõ tên thủ tục và danh sách tham số để gọi bằng lệnh EXEC. (2) Khả năng tích hợp ORM (như Entity Framework Core): View kèm Trigger tương thích tự nhiên với cơ chế Change Tracker và Unit of Work của ORM mà không cần cấu hình ánh xạ hàm thủ công phức tạp như Stored Procedure. (3) Bảo trì và gỡ lỗi (Maintainability & Debugging): INSTEAD OF Trigger chứa logic ngầm ẩn (Hidden Side Effects) khiến lập trình viên rất khó lần vết khi lệnh cập nhật bị chuyển hướng âm thầm; trái lại Stored Procedure gom toàn bộ kiểm tra nghiệp vụ, giao dịch và xử lý lỗi TRY...CATCH vào một luồng tường minh rất dễ kiểm thử và bảo trì. (4) Hiệu năng và xử lý theo lô: Trigger dễ suy giảm hiệu năng nếu xử lý tập hợp bảng ảo inserted/deleted chưa khéo, trong khi Stored Procedure tối ưu mạnh nhờ Plan Cache và hỗ trợ truyền tham số kiểu bảng (Table-Valued Parameters) cho các nghiệp vụ lõi tải cao. Do đó, chọn View kèm Trigger khi cần giữ tương thích giao diện bảng cho hệ thống cũ hoặc ORM, và ưu tiên Stored Procedure cho các giao dịch nghiệp vụ trọng yếu.", "[\"So sánh Tính trong suốt & Tương thích ORM (3.5đ): Phân tích rõ ưu thế giao diện bảng chuẩn của View đối với ORM so với tính tường minh của SP.\", \"So sánh Độ phức tạp bảo trì và Gỡ lỗi (Debugging) (3.5đ): Chỉ ra cạm bẫy logic ẩn ngầm của Trigger so với khả năng kiểm soát luồng rõ ràng của SP.\", \"So sánh Hiệu năng xử lý theo lô và Kết luận kiến trúc (3.0đ): Đánh giá TVP, Plan Cache của SP và đưa ra tiêu chí lựa chọn cho từng ngữ cảnh thực tế.\"]", QuestionDifficulty.Hard, BloomLevel.Analyze, 85),
        };

        foreach (var eq in examQuestions)
        {
            if (!existingById.TryGetValue(eq.Id, out var existingEq))
            {
                context.ExamQuestions.Add(eq);
            }
            else
            {
                existingEq.CloId = eq.CloId;
                existingEq.StructureId = eq.StructureId;
                existingEq.RubricId = eq.RubricId;
                existingEq.Title = eq.Title;
                existingEq.Content = eq.Content;
                existingEq.SampleAnswer = eq.SampleAnswer;
                existingEq.KeyPoints = eq.KeyPoints;
                existingEq.Difficulty = eq.Difficulty;
                existingEq.BloomLevel = eq.BloomLevel;
                existingEq.ApprovalStatus = ApprovalStatus.Approved;
                existingEq.ApprovedBy = DepartmentHeadUserId;
                existingEq.SubmittedBy = LecturerUserId;
                existingEq.IsActive = true;
            }
        }

        await context.SaveChangesAsync(cancellationToken);

        var existingSetQuestions = await context.ExamSetQuestions
            .Select(sq => new { sq.ExamSetId, sq.ExamQuestionId })
            .ToListAsync(cancellationToken);
        var existingPairs = existingSetQuestions.Select(sq => (sq.ExamSetId, sq.ExamQuestionId)).ToHashSet();

        var setMappings = new List<(Guid SetId, Guid QuestionId, int OrderIndex)>
        {
            (ExamSetPrf192Id, Guid.Parse("00000000-0000-0000-0004-000000000201"), 1),
            (ExamSetPrf192Id, Guid.Parse("00000000-0000-0000-0004-000000000207"), 2),
            (ExamSetPrf192Id, Guid.Parse("00000000-0000-0000-0004-000000000215"), 3),
            (ExamSetPrf192Id, Guid.Parse("00000000-0000-0000-0004-000000000219"), 4),
            (ExamSetPrf192Id, Guid.Parse("00000000-0000-0000-0004-000000000222"), 5),

            (ExamSetCsd201Id, Guid.Parse("00000000-0000-0000-0005-000000000201"), 1),
            (ExamSetCsd201Id, Guid.Parse("00000000-0000-0000-0005-000000000207"), 2),
            (ExamSetCsd201Id, Guid.Parse("00000000-0000-0000-0005-000000000215"), 3),
            (ExamSetCsd201Id, Guid.Parse("00000000-0000-0000-0005-000000000218"), 4),
            (ExamSetCsd201Id, Guid.Parse("00000000-0000-0000-0005-000000000223"), 5),

            (ExamSetDbi202Id, Guid.Parse("00000000-0000-0000-0006-000000000201"), 1),
            (ExamSetDbi202Id, Guid.Parse("00000000-0000-0000-0006-000000000207"), 2),
            (ExamSetDbi202Id, Guid.Parse("00000000-0000-0000-0006-000000000215"), 3),
            (ExamSetDbi202Id, Guid.Parse("00000000-0000-0000-0006-000000000219"), 4),
            (ExamSetDbi202Id, Guid.Parse("00000000-0000-0000-0006-000000000222"), 5),
        };

        foreach (var (setId, questionId, orderIndex) in setMappings)
        {
            if (!existingPairs.Contains((setId, questionId)))
            {
                context.ExamSetQuestions.Add(new ExamSetQuestion
                {
                    Id = Guid.NewGuid(),
                    ExamSetId = setId,
                    ExamQuestionId = questionId,
                    OrderIndex = orderIndex
                });
                existingPairs.Add((setId, questionId));
            }
        }

        await context.SaveChangesAsync(cancellationToken);
    }

    private static async Task EnsureAdditionalClassesAndEnrollmentsAsync(OralExamDbContext context, CancellationToken cancellationToken)
    {
        var existingClasses = await context.Classes.ToListAsync(cancellationToken);
        var semester = await context.Semesters.FirstOrDefaultAsync(cancellationToken);
        var semesterId = semester?.Id ?? Guid.Parse("00000000-0000-0000-0000-000000000001");

        var classes = new List<Class>
        {
            new()
            {
                Id = ClassPrf192Id,
                CourseId = CoursePrf192Id,
                Code = "SE1804-PRF",
                Name = "Lớp SE1804-PRF",
                JoinCode = "SE1804PRF",
                SemesterId = semesterId,
                LecturerId = LecturerUserId,
                MaxStudents = 40,
                IsActive = true,
                CreatedAt = SeedTimestampUtc
            },
            new()
            {
                Id = ClassCsd201Id,
                CourseId = CourseCsd201Id,
                Code = "SE1805-CSD",
                Name = "Lớp SE1805-CSD",
                JoinCode = "SE1805CSD",
                SemesterId = semesterId,
                LecturerId = LecturerUserId,
                MaxStudents = 40,
                IsActive = true,
                CreatedAt = SeedTimestampUtc
            },
            new()
            {
                Id = ClassDbi202Id,
                CourseId = CourseDbi202Id,
                Code = "SE1806-DBI",
                Name = "Lớp SE1806-DBI",
                JoinCode = "SE1806DBI",
                SemesterId = semesterId,
                LecturerId = LecturerUserId,
                MaxStudents = 40,
                IsActive = true,
                CreatedAt = SeedTimestampUtc
            }
        };

        foreach (var cls in classes)
        {
            cls.Name = $"Lớp {cls.Code}";
            cls.JoinCode = cls.Code.Replace("-", "").ToUpperInvariant();

            var existing = existingClasses.FirstOrDefault(c => c.Id == cls.Id || c.Code == cls.Code);
            if (existing == null)
            {
                context.Classes.Add(cls);
            }
            else
            {
                existing.IsActive = true;
                if (string.IsNullOrWhiteSpace(existing.JoinCode))
                {
                    existing.JoinCode = cls.JoinCode;
                }
                if (string.IsNullOrWhiteSpace(existing.Name))
                {
                    existing.Name = cls.Name;
                }
            }
        }
        await context.SaveChangesAsync(cancellationToken);

        var existingEnrollments = (await context.ClassEnrollments.Select(e => e.Id).ToListAsync(cancellationToken)).ToHashSet();

        var enrollments = new List<ClassEnrollment>
        {
            new() { Id = Guid.Parse("00000000-0000-0000-0003-000000000401"), ClassId = ClassPrf192Id, StudentId = StudentHoangId, EnrolledAt = SeedTimestampUtc, Status = "enrolled" },
            new() { Id = Guid.Parse("00000000-0000-0000-0003-000000000402"), ClassId = ClassPrf192Id, StudentId = StudentMaiId, EnrolledAt = SeedTimestampUtc, Status = "enrolled" },
            new() { Id = Guid.Parse("00000000-0000-0000-0003-000000000403"), ClassId = ClassPrf192Id, StudentId = StudentThanhId, EnrolledAt = SeedTimestampUtc, Status = "enrolled" },

            new() { Id = Guid.Parse("00000000-0000-0000-0003-000000000411"), ClassId = ClassCsd201Id, StudentId = StudentHoangId, EnrolledAt = SeedTimestampUtc, Status = "enrolled" },
            new() { Id = Guid.Parse("00000000-0000-0000-0003-000000000412"), ClassId = ClassCsd201Id, StudentId = StudentMaiId, EnrolledAt = SeedTimestampUtc, Status = "enrolled" },
            new() { Id = Guid.Parse("00000000-0000-0000-0003-000000000413"), ClassId = ClassCsd201Id, StudentId = StudentThanhId, EnrolledAt = SeedTimestampUtc, Status = "enrolled" },

            new() { Id = Guid.Parse("00000000-0000-0000-0003-000000000421"), ClassId = ClassDbi202Id, StudentId = StudentHoangId, EnrolledAt = SeedTimestampUtc, Status = "enrolled" },
            new() { Id = Guid.Parse("00000000-0000-0000-0003-000000000422"), ClassId = ClassDbi202Id, StudentId = StudentMaiId, EnrolledAt = SeedTimestampUtc, Status = "enrolled" },
            new() { Id = Guid.Parse("00000000-0000-0000-0003-000000000423"), ClassId = ClassDbi202Id, StudentId = StudentThanhId, EnrolledAt = SeedTimestampUtc, Status = "enrolled" }
        };

        foreach (var enr in enrollments)
        {
            if (!existingEnrollments.Contains(enr.Id))
            {
                context.ClassEnrollments.Add(enr);
            }
        }

        await context.SaveChangesAsync(cancellationToken);
    }
